INSERT INTO `sys_sjgl_dzd` VALUES ('016A2FCDDFE94015942997C5B840FBA0', 'DEFAULT.getdata', 99999, 'SYS_SJGL_APPCONFIG', 'select #{globalUse(\"util.expDate14\")} curr_date #{globalUse(\"util.expDefaultFrom\")}', '获取数据默认sql', 'SELECT #{GLOBALUSE(\"UTIL.EXPDATE14\")} CURR_DATE #{GLOBALUSE(\"UTIL.EXPDEFAULTFROM\")}', 'SELECT #{GLOBALUSE(\"UTIL.EXPDATE14\")} CURR_DATE #{GLOBALUSE(\"UTIL.EXPDEFAULTFROM\")}', NULL, '20190315200219', '20231027001132', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('02B4D1B14BE940008C8D5A411E90ACA8', 'zd.SYS_COMMON_TABLES.mysql', 99999, 'SYS_SJGL_APPCONFIG', 'select t.table_name dm,CONCAT_WS(\'\',t.table_comment,\'[\',t.table_name,\']\') as mc,\'\' upnode,\'\' px,\'\' as search_key from information_schema.tables t \n-- @where(){\n-- @ if(isNotEmpty(yobj.owner)){\nand table_schema=\'${yobj.owner}\'\n-- @}else if(isNotEmpty(sjzt.dxgs)){\nand table_schema = \'${sjzt.dxgs}\'\n-- @}\n-- @}', NULL, 'SELECT T.TABLE_NAME DM,CONCAT_WS(\'\',T.TABLE_COMMENT,\'[\',T.TABLE_NAME,\']\') AS MC,\'\' UPNODE,\'\' PX,\'\' AS SEARCH_KEY FROM INFORMATION_SCHEMA.TABLES T \n-- @WHERE(){\n-- @ IF(ISNOTEMPTY(YOBJ.OWNER)){\nAND TABLE_SCHEMA=\'${YOBJ.OWNER}\'\n-- @}ELSE IF(ISNOTEMPTY(SJZT.DXGS)){\nAND TABLE_SCHEMA = \'${SJZT.DXGS}\'\n-- @}\n-- @}', 'SELECT T.TABLE_NAME DM,CONCAT_WS(\'\',T.TABLE_COMMENT,\'[\',T.TABLE_NAME,\']\') AS MC,\'\' UPNODE,\'\' PX,\'\' AS SEARCH_KEY FROM INFORMATION_SCHEMA.TABLES T \n-- @WHERE(){\n-- @ IF(ISNOTEMPTY(YOBJ.OWNER)){\nAND TABLE_SCHEMA=\'${YOBJ.OWNER}\'\n-- @}ELSE IF(ISNOTEMPTY(SJZT.DXGS)){\nAND TABLE_SCHEMA = \'${SJZT.DXGS}\'\n-- @}\n-- @}', NULL, '20230604020406', '20230604024132', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('057E5B051E4A402DB4D162D8D06D66B3', 'DEFAULT.dis.oracle', 99999, 'SYS_SJGL_APPCONFIG', 'select a.column_name as zddm,\n       a.comments    as zdms,\n       c.data_type   as zdlx,\n       (case when c.data_type=\'VARCHAR2\' then c.data_length else null end)as zdcd,\n       f_xzmrz(\'select t.DATA_DEFAULT from all_tab_columns t where t.OWNER=\'\'\'||c.OWNER\n       ||\'\'\' and t.TABLE_NAME=\'\'\'||c.TABLE_NAME||\'\'\' and t.COLUMN_NAME=\'\'\'||c.COLUMN_NAME||\'\'\'\') xzmrz\n  from all_col_comments a\n  left join all_tab_columns c\n    on a.table_name = c.table_name\n   and a.owner = c.owner\n   and a.column_name = c.column_name\n   and a.owner = c.owner\n where a.table_name = upper(\'${yobj.jtdx}\')\n      /* if(!isEmpty(yobj.dxgs)){*/\n   and a.owner = upper(\'${yobj.dxgs}\')\n/* }else  if(!isEmpty(yobj.sjztObj.dxgs)){*/\n   and a.owner = upper(\'${yobj.sjztObj.dxgs}\')\n/* }else  if(!isEmpty(yobj.sjztObj.yhm)){*/\n   and a.owner = upper(\'${yobj.sjztObj.yhm}\')\n/* }*/', '数据对象-默认导入sql-oracle', NULL, NULL, NULL, '20181210165142', '20220825105040', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('0593292106D94252A1ADD7C31F514946', 'yzgz.cdjy', 99999, 'SYS_COMMON_YBMB', '${su.length(sys.value)<=sys.gzObj.maxLength}', '长度校验', NULL, '${SU.LENGTH(SYS.VALUE)<=SYS.GZOBJ.MAXLENGTH}', NULL, '20221118101202', '20221118111324', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('0A2ACB8F9FC44E5AA2496062008B8D95', 'DEFAULT.dis.postgresql', 99999, 'SYS_SJGL_APPCONFIG', 'select T.col_name AS zddm,\n       z.zdms AS zdms,\n       T.col_type AS zdlx,\n       CASE\n         WHEN T.col_len IS NOT NULL THEN\n          T.col_len\n         ELSE\n          T.col_prec\n       END AS zdcd\n  FROM (SELECT aa.*, bb.zdms\n          FROM (SELECT A.ordinal_position         AS col_num,\n                       A                          . COLUMN_NAME AS col_name,\n                       A.data_type                AS col_type,\n                       A.character_maximum_length AS col_len,\n                       A.numeric_precision        AS col_prec\n                  FROM information_schema. COLUMNS A\n                 WHERE A . TABLE_NAME = LOWER(\'${tableName}\')\n                      /* if(!isEmpty(yobj.dxgs)){*/\n                   AND table_schema = \'${yobj.dxgs}\'\n                      /* }else  if(!isEmpty(owner)){*/\n                   AND table_schema = \'${owner}\'\n                /* }*/\n                ) AS aa\n          LEFT JOIN (SELECT objsubid, description AS zdms\n                      FROM pg_description\n                     WHERE objoid = (SELECT relid\n                                       FROM pg_stat_all_tables\n                                      WHERE relname = LOWER(\'${tableName}\')\n                                           /* if(!isEmpty(yobj.dxgs)){*/\n                                        AND table_schema = \'${yobj.dxgs}\'\n                                           /* }else  if(!isEmpty(owner)){*/\n                                        AND schemaname = \'${owner}\'\n                                     /* }*/\n                                     )) AS bb\n            ON aa.col_num = bb.objsubid\n         ORDER BY aa.col_num) T\n  LEFT JOIN (SELECT attr.attname AS zddm,\n                    col_description(attr.attrelid, attr.attnum) AS zdms\n               FROM pg_attribute attr\n               LEFT JOIN pg_class clazz\n                 ON attr.attrelid = clazz.oid\n               LEFT JOIN pg_type C\n                 ON attr.attrelid = C.oid\n              WHERE clazz.relname = LOWER(\'${tableName}\')\n                AND attr.attnum > 0) z\n    ON T.col_name = z.zddm\n', NULL, NULL, NULL, NULL, '20181210170248', '20200617160750', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('0AB3BB835030411792FB893F5ADEC99B', 'zd.SYS_COMMON_TABLES.vertica', 99999, 'SYS_SJGL_APPCONFIG', 'SELECT table_name dm,\nCASE when remarks is null \nthen table_name else remarks || \'[\' || table_name || \']\'\nend mc,\'\' upnode,\'\' px,\'\' as search_key\nFROM v_catalog.all_tables t \n-- @where(){\n-- @ if(isNotEmpty(yobj.owner)){\nand schema_name = \'${yobj.owner}\'\n-- @}else if(isNotEmpty(sjzt.dxgs)){\nand schema_name = \'${sjzt.dxgs}\'\n-- @}\n-- @}', NULL, 'SELECT TABLE_NAME DM,\nCASE WHEN REMARKS IS NULL \nTHEN TABLE_NAME ELSE REMARKS || \'[\' || TABLE_NAME || \']\'\nEND MC,\'\' UPNODE,\'\' PX,\'\' AS SEARCH_KEY\nFROM V_CATALOG.ALL_TABLES T \n-- @WHERE(){\n-- @ IF(ISNOTEMPTY(YOBJ.OWNER)){\nAND SCHEMA_NAME = \'${YOBJ.OWNER}\'\n-- @}ELSE IF(ISNOTEMPTY(SJZT.DXGS)){\nAND SCHEMA_NAME = \'${SJZT.DXGS}\'\n-- @}\n-- @}', 'SELECT TABLE_NAME DM,\nCASE WHEN REMARKS IS NULL \nTHEN TABLE_NAME ELSE REMARKS || \'[\' || TABLE_NAME || \']\'\nEND MC,\'\' UPNODE,\'\' PX,\'\' AS SEARCH_KEY\nFROM V_CATALOG.ALL_TABLES T \n-- @WHERE(){\n-- @ IF(ISNOTEMPTY(YOBJ.OWNER)){\nAND SCHEMA_NAME = \'${YOBJ.OWNER}\'\n-- @}ELSE IF(ISNOTEMPTY(SJZT.DXGS)){\nAND SCHEMA_NAME = \'${SJZT.DXGS}\'\n-- @}\n-- @}', NULL, '20230604020507', '20230604024103', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('12F7CFC3234146D5ACF95A06B43BF61B', 'SYS_PLBD_HM.hqcxx', 99999, 'SYS_SJGL_APPCONFIG', 'select zd.* from sys_sjgl_sjzd zd\nwhere zd.cxzs=\'1\' and zd.yxx=\'1\' and zd.sjdx=#{yobj.sjdx};ds=default', NULL, 'SELECT ZD.* FROM SYS_SJGL_SJZD ZD\nWHERE ZD.CXZS=\'1\' AND ZD.YXX=\'1\' AND ZD.SJDX=#YOBJ.SJDX#;DS=DEFAULT', 'SELECT ZD.* FROM SYS_SJGL_SJZD ZD\nWHERE ZD.CXZS=\'1\' AND ZD.YXX=\'1\' AND ZD.SJDX=#YOBJ.SJDX#;DS=DEFAULT', NULL, '20200610111705', '20200617115130', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('1778634CC9FD4D7F938AEB61F012C7CE', 'KETTLE_GLPT_ZYGL.kzxx', 99999, 'SYS_SJGL_APPCONFIG', '{\n	\"fields\":{\n		\"myLbcz\":{\n			\"kzxxObj\":{\n				\"kjkz\": {\n					//最大按钮数，列表操作中默认最大显示3个按钮\n					\"zdans\": 5,\n					\"btns\": {\n						\"update\": {\n							\"type\": \"text\",\n							\"content\": \"编辑\",\n							\"status\": \"primary\",\n							\"buttonOptions\": {\n								\"clfs\": \"tcck\",\n								\"dxjcxx\": {\n									\"sys\": {\n										\"cllx\": \"update\"\n									},\n									\"sjdx\":{\n										\"dxdm\":\"KETTLE_GLPT_ZYGL\"\n									}\n								},\n								\"jcxxqqcskz\": {\n									\"yobj.idJob\": \"dxjcxx.obj.idJob\",\n									\"yobj.zyk\": \"dxjcxx.obj.zyk\"\n								}\n							}\n						},\n						\"dxjcxx\": {\n							\"type\": \"text\",\n							\"content\": \"详情\",\n							\"status\": \"primary\",\n							\"buttonOptions\": {\n								\"clfs\": \"tcck\",\n								\"dxjcxx\": {\n									\"sys\": {\n										\"cllx\": \"dxjcxx\"\n									},\n									\"sjdx\":{\n										\"dxdm\":\"KETTLE_GLPT_ZYGL\"\n									}\n								},\n								\"jcxxqqcskz\": {\n									\"yobj.idJob\": \"dxjcxx.obj.idJob\",\n									\"yobj.zyk\": \"dxjcxx.obj.zyk\"\n								}\n							}\n						},\n						\"rz\": {\n							\"px\":10,\n							\"type\": \"text\",\n							\"status\": \"primary\",\n							\"content\": \"日志\",\n							\"buttonOptions\": {\n								\"clfs\": \"tcck\",\n								\"tcqp\": true,\n								\"dxjcxx\": {\n									\"sys\": {\n										\"cllx\": \"rz\"\n									},\n									\"sjdx\":{\n										\"dxdm\":\"KETTLE_GLPT_ZYGL\"\n									}\n								},\n								\"jcxxkz\": {\n									\"obj.idJob\": \"dxjcxx.obj.zykJob\"\n								}\n							}\n						},\n						\"qd\": {\n							\"px\":12,\n							\"type\": \"text\",\n							\"status\": \"primary\",\n							\"content\": \"启动\",\n							\"buttonOptions\": {\n								\"htqqts\": false,\n								\"jcxxkz\":{\n									\"sys.ctapp\":\"dxjcxx.obj.ddjd\"\n								}\n							}\n						},\n						\"tz\": {\n							\"px\":14,\n							\"type\": \"text\",\n							\"status\": \"primary\",\n							\"content\": \"停止\",\n							\"buttonOptions\": {\n								\"htqqts\": false,\n								\"jcxxkz\":{\n									\"sys.ctapp\":\"dxjcxx.obj.ddjd\"\n								}\n							}\n						},\n						\"dssz\": {\n							\"px\":20,\n							\"type\": \"text\",\n							\"status\": \"primary\",\n							\"content\": \"定时设置\",\n							\"buttonOptions\": {\n								\"clfs\": \"tcck\",\n								\"tcqp\": false,\n								\"tckz\":{\n									\"width\":500,\n									\"height\":450\n								},\n								\"dxjcxx\": {\n									\"sys\": {\n										\"cllx\": \"update\"\n									},\n									\"sjdx\":{\n										\"dxdm\":\"KETTLE_GLPT_ZYGL_DSSZ\"\n									}\n								},\n								\"jcxxqqcskz\": {\n									\"yobj.idJob\": \"dxjcxx.obj.idJob\",\n									\"yobj.zyk\": \"dxjcxx.obj.zyk\"\n								}\n							}\n						},\n						\"cssz\": {\n							\"px\":30,\n							\"type\": \"text\",\n							\"status\": \"primary\",\n							\"content\": \"参数设置\",\n							\"buttonOptions\": {\n								\"clfs\": \"tcck\",\n								\"tcqp\": true,\n								\"dxjcxx\": {\n									\"sys\": {\n										\"cllx\": \"select\"\n									},\n									\"sjdx\":{\n										\"dxdm\":\"KETTLE_GLPT_CSSZ\"\n									}\n								},\n								\"jcxxkz\": {\n									\"fields.idJob.cxmrz\": \"dxjcxx.obj.idJob\",\n									\"fields.zyk.cxmrz\": \"dxjcxx.obj.zyk\"\n								}\n							}\n						},\n						\"fzjl\": {\n							\"px\":40,\n							\"type\": \"text\",\n							\"status\": \"primary\",\n							\"content\": \"复制\",\n							\"buttonOptions\": {\n								\"clfs\": \"tcck\",\n								\"tcqp\": true,\n								\"dxjcxx\": {\n									\"sys\": {\n										\"cllx\": \"fzjl\"\n									},\n									\"sjdx\":{\n										\"dxdm\":\"KETTLE_GLPT_ZYGL\"\n									}\n								},\n								\"jcxxqqcskz\": {\n									\"yobj.idJob\": \"dxjcxx.obj.idJob\",\n									\"yobj.zyk\": \"dxjcxx.obj.zyk\"\n								}\n							}\n						},\n						\"ml\": {\n							\"type\": \"text\",\n							\"status\": \"primary\",\n							\"content\": \"目录\",\n							\"buttonOptions\": {\n								\"htqqts\": false\n							}\n						},\n						\"zyt\": {\n							\"type\": \"text\",\n							\"status\": \"primary\",\n							\"content\": \"作业图\",\n							\"buttonOptions\": {\n								\"clfs\": \"tcck\",\n								\"tcqp\": true,\n								\"dxjcxx\": {\n									\"sys\": {\n										\"cllx\": \"zyt\"\n									},\n									\"sjdx\":{\n										\"dxdm\":\"KETTLE_GLPT_ZYGL\"\n									},\n									\"yobj\":{\n										\"zyt\":true\n									}\n								},\n								\"jcxxqqcskz\": {\n									\"yobj.idJob\": \"dxjcxx.obj.idJob\",\n									\"yobj.zyk\": \"dxjcxx.obj.zyk\"\n								}\n							}\n						},\n						\"cz\": {\n							\"type\": \"text\",\n							\"status\": \"primary\",\n							\"content\": \"重置\",\n							\"buttonOptions\": {\n								\"htqqts\": true,\n								\"jcxxkz\":{\n									\"sys.ctapp\":\"dxjcxx.obj.ddjd\"\n								}\n							}\n						},\n						\"js\": {\n							\"type\": \"text\",\n							\"status\": \"primary\",\n							\"content\": \"结束\",\n							\"buttonOptions\": {\n								\"htqqts\": true,\n								\"jcxxkz\":{\n									\"sys.ctapp\":\"dxjcxx.obj.ddjd\"\n								}\n							}\n						}\n					}\n				}\n			}\n		}\n	}\n}', '作业管理扩展信息', '{\n	\"FIELDS\":{\n		\"MYLBCZ\":{\n			\"KZXXOBJ\":{\n				\"KJKZ\": {\n					//ZDANS，LBCZZMRZDXS3GAN\n					\"ZDANS\": 5,\n					\"BTNS\": {\n						\"UPDATE\": {\n							\"TYPE\": \"TEXT\",\n							\"CONTENT\": \"BJ\",\n							\"STATUS\": \"PRIMARY\",\n							\"BUTTONOPTIONS\": {\n								\"CLFS\": \"TCCK\",\n								\"DXJCXX\": {\n									\"SYS\": {\n										\"CLLX\": \"UPDATE\"\n									},\n									\"SJDX\":{\n										\"DXDM\":\"KETTLE_GLPT_ZYGL\"\n							', '{\n	\"FIELDS\":{\n		\"MYLBCZ\":{\n			\"KZXXOBJ\":{\n				\"KJKZ\": {\n					//ZUIDAANNIUSHU，LIEBIAOCAOZUOZHONGMORENZUIDAXIANSHI3GEANNIU\n					\"ZDANS\": 5,\n					\"BTNS\": {\n						\"UPDATE\": {\n							\"TYPE\": \"TEXT\",\n							\"CONTENT\": \"BIANJI\",\n							\"STATUS\": \"PRIMARY\",\n							\"BUTTONOPTIONS\": {\n								\"CLFS\": \"TCCK\",\n								\"DXJCXX\": {\n									\"SYS\": {\n										\"CLLX\": \"UPDATE\"\n									},\n									\"SJDX\":{\n			', NULL, '20230601221105', '20240523142726', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('1970D0303A8F4DF1BBA2A9E4B01DF632', 'SYS_QX_JGXX.getTreeCN', 99999, 'SYS_SJGL_APPCONFIG', 'select jgmc  name,\n       t.id dm,\n       (select count(1)\n          from SYS_QX_JGXX t1\n         where t1.yxx = \'1\'\n           and t1.sjjg = t.id\n        ) parent\n  from SYS_QX_JGXX t\n where t.yxx = \'1\'\n      /*if(!isEmpty(sjdx.sjjg)){*/\n   and t.sjjg = #{sjdx.sjjg}\n      /*}else if(!isEmpty(sjdx.treeRoot)){*/\n   and t.sjjg = #{sjdx.treeRoot}\n      /*}else{*/\n   and t.sjjg is null\n      /*}*/\n order by px asc,jgdm \n', NULL, NULL, NULL, NULL, '20190419231545', '20190419235716', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('1C0AD44E750C4C4FB7D7631392CE6C25', 'DEFAULT.select.greenplum', 99999, 'SYS_SJGL_APPCONFIG', '/*\nvar selectField = \"\";\nvar whereStr = \"\";\nvar sszdlb = null;\n//简拼全拼支持\nif(!isEmpty(kzxx.fields.sszzd)&&!isEmpty(yobj[kzxx.fields.sszzd.zddm])){\n   var value = yobj[kzxx.fields.sszzd.zddm];\n   //if(su.endsWith(value, \"%\")&&su.startsWith(value, \"%\")){\n     sszdlb = kzxx.fields.sszzd.zddm;\n     if(!isEmpty(kzxx.fields.pyjp)){\n          sszdlb = sszdlb+\"||\"+kzxx.fields.pyjp.zddm;\n     }\n     if(!isEmpty(kzxx.fields.pyqp)){\n          sszdlb = sszdlb+\"||\"+kzxx.fields.pyqp.zddm;\n     }\n     if(!isEmpty(kzxx.fields.sszdlb)){\n          sszdlb = sszdlb+\"||\"+kzxx.fields.sszdlb.zddm;\n     }\n     whereStr = whereStr + \" and upper(\"+sszdlb+\") like \'%\'||upper(#{yobj.\"+kzxx.fields.sszzd.zddm+\"})||\'%\'\";\n   //}\n}\n//循环生成字段\nfor(field in fieldList){\n   if(\"99\"==field.zdywlb){\n        //虚拟字段\n        continue;\n   }\n   selectField = selectField + \",\" + field.zddm;\n   if((sszdlb!=null&&kzxx.fields.sszzd.zddm==field.zddm)||isEmpty(yobj[field.zddm])){\n        //搜索主字段或该字段值为空\n        continue;\n   }\n   if(\"dict\"==field.kjlx&&field.zddx==\'1\'){\n        //字典多选支持\n       var arr = su.split(yobj[field.zddm], \",\");\n       var idx=0;\n       for(var a in arr){\n           if(idx==0){\n             if(a==\'my-null\'){\n               whereStr = whereStr + \" and (\"+field.zddm+\" is null \";\n             }else{\n               whereStr = whereStr + \" and (\"+field.zddm+\" = \'\"+a+\"\' \";\n             }\n           }else{\n             if(a==\'my-null\'){\n               whereStr = whereStr + \" or \"+field.zddm+\"  is null\";\n             }else{\n               whereStr = whereStr + \" or \"+field.zddm+\" = \'\"+a+\"\' \";\n             }\n           }\n           idx=idx+1;\n       }\n       whereStr = whereStr + \")\";\n   }else if(yobj[field.zddm]==\'my-null\'){\n         whereStr = whereStr + \" and \"+field.zddm+\" is null\";\n   }else if(\"dict\"==field.kjlx){\n         whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm]);\n   }else if((\"check\"+\"box\")==field.kjlx){\n         whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm]);\n   }else if(\"suggest\"==field.kjlx){\n         mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm+\"_text\"]+\"%\");\n         whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n   }else if(\"time\"==field.kjlx){\n         whereStr = whereStr + su.addEqDate(field,yobj);\n         if(field.hdgs==\'date\'){\n                  //支持date类型的时间\n                  if(!isEmpty(yobj[field.zddm+\"_start\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" >=to_date(\'\"+yobj[field.zddm+\"_start\"]+\"\',\'YYYYMMDDHH24MISS\')\";\n                  }\n                  if(!isEmpty(yobj[field.zddm+\"_end\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" <=to_date(\'\"+yobj[field.zddm+\"_end\"]+\"\',\'YYYYMMDDHH24MISS\')\";\n                  }\n         }else{\n                  if(!isEmpty(yobj[field.zddm+\"_start\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" >=\'\"+yobj[field.zddm+\"_start\"]+\"\'\";\n                  }\n                  if(!isEmpty(yobj[field.zddm+\"_end\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" <=\'\"+yobj[field.zddm+\"_end\"]+\"\'\";\n                  }\n         }\n   }else if(\"number\"==field.kjlx){\n         whereStr = whereStr + su.addEqNumber(field.zddm,yobj);\n   }else{\n        //默认处理方式\n       if(!isEmpty(yobj[field.zddm])){\n           if(su.indexOf(yobj[field.zddm], \"%\")>-1){\n              //用户输入有%，则按用户输入进行模糊即可\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",yobj[field.zddm]);\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else if(field.cxms==\'1\'){\n              //模糊搜索\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm]+\"%\");\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else if(field.cxms==\'2\'){\n              //右模糊搜索\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",yobj[field.zddm]+\"%\");\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else if(field.cxms==\'3\'){\n              //左模糊搜索\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm]);\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else{\n              //精确搜索\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm]);\n           }\n        }\n   }\n}\n//权限过滤条件\nvar authWhere = \"\";\nif(user==null){\n    //用户为空，初进系统\n}else if(user.qxMap[\'KFZFW_GLY\']!=null){\n    //管理员，不能查看系统管理员(sys)创建的数据。\n    if(!isEmpty(kzxx.fields.cjrdm)){\n        authWhere = \" and \"+kzxx.fields.cjrdm.zddm+\"<>\'BC5D77315CA84C6C807988E3CD17E70D\'\";\n    }\n}else if(user.qxMap[\'KFZFW_DWGLY\']!=null){\n    //单位管理员，只能管理本单位\n    if(!isEmpty(kzxx.fields.cjrdwdm)&&has(user)){\n        authWhere = \" and \"+kzxx.fields.cjrdwdm.zddm+\"=\'\"+user.jgxx.id+\"\'\";\n    }\n    if(user.qxMap[\'KFZFW_GLZDW\']!=null){\n        //管理子单位\n    \n    }\n}else if(user.qxMap[\'KFZFW_GLZDW\']!=null){\n    //管理子单位\n    \n}\n\nif(user==null){\n    //用户为空，初进系统\n}else if(user.qxMap[\'KFZFW_SYS\']!=null){\n    //系统管理员，无权限过滤\n    authWhere = \"\";\n}else if(isEmpty(authWhere)){\n    //普通用户,或上述权限没有生效只能查看本人数据\n    if(!isEmpty(kzxx.fields.cjrdm)&&has(user)&&user!=null){\n        authWhere = \" and \"+kzxx.fields.cjrdm.zddm+\"=\'\"+user.id+\"\'\";\n    }\n}\nselectField = su.substring(selectField,1);\n//排序\nvar orderBy = su.addPxField(sjdx.mrpx,yobj);\n//设置变量，备用\nmu.safeAddToMap(obj,\"selectField\",selectField);\nmu.safeAddToMap(obj,\"whereStr\",whereStr);\nmu.safeAddToMap(obj,\"authWhere\",authWhere);\nmu.safeAddToMap(obj,\"orderBy\",orderBy);\n*/\nselect  ${selectField} from ${owner}.${tableName} t where 1 = 1 ${whereStr} ${authWhere} ${orderBy}', NULL, NULL, NULL, NULL, '20181223155356', '20220916223709', NULL, NULL, '0', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('1EEAD220F0F44955A4CC1766FD5D6208', 'SYS_YXJK_JKRW_FK.update', 99999, 'SYS_SJGL_APPCONFIG', '/*\n //入消息表\nif(!isEmpty(yobj.clfk)){\n      mydb.update(mydb.use(),\"insert into SYS_YXJK_XX(xxlx,xxdj,jkrw,xxnr) values(\'3\',\'2\',?,?)\",yobj.id,obj.rwmc+\"在\"+du.getDateTimeStr()+\"反馈：\"+yobj.clfk);\n}\n*/\n${defaultSql}', NULL, NULL, NULL, NULL, '20190114130226', '20211202224303', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('21562EC4C9D84820A2356ED4985FA2A0', 'SYS_PLBD_HM_QYZS.getTreeCN', 99999, 'SYS_SJGL_APPCONFIG', 'select mc  name,\n       t.dm dm,\n       (select count(1)\n          from SYS_BDHC_ZY t1\n         where t1.yxx = \'1\'\n           and t1.sjzy = t.dm\n        ) parent,\n        t.sjdx\n  from SYS_BDHC_ZY t\n where t.yxx = \'1\' and t.qyhc=\'1\'\n      /*if(!isEmpty(sjdx.sjzy)){*/\n   and t.sjzy = #{sjdx.sjzy}\n      /*}else if(!isEmpty(sjdx.treeRoot)){*/\n   and t.sjzy = #{sjdx.treeRoot}\n      /*}else{*/\n   and t.sjzy is null\n      /*}*/\n order by px asc,t.gxsj desc', NULL, NULL, NULL, NULL, '20200616094127', '20210222153408', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('2164F87311014CC699A85B4A28594B15', 'DEFAULT.select', 99999, 'SYS_SJGL_APPCONFIG', '/*\r\n//查询字段列表\r\nvar selectField = \"\";\r\n//查询条件\r\nvar whereStr = \"\";\r\n//搜索字段列表\r\nvar sszdlb = null;\r\n//设置查询的字段列表\r\nfor(e in fields){\r\n   var field = e.value;\r\n   if(!su.contains(field.zdywlb,\"99\")&&(field.xqzs==\"1\"||field.lbzs==\"1\"||field.zddm==sjdx.zjzd)){\r\n	 		if(field.zdlx==\'DATE\'){\r\n       	selectField = selectField + \",#{globalUse(\'util.expDateToStr14\',{\'dateObj\':\'t.\"+field.yszddm+\"\'\\\\})} as \"+field.yszddm;\r\n			}else{\r\n       	selectField = selectField + \",t.#{globalUse(\'util.expField\',{\'field\':\'\"+field.yszddm+\"\'\\\\})}\";\r\n			}\r\n   }\r\n}\r\n//树形结构处理\r\nif(null!=cllxkz[\'select\'].tree.hasChild!){\r\n   var tree = cllxkz[\'select\'].tree;\r\n   //查询该节点是否有子节点\r\n   selectField = selectField + \",(select (case when count(1)>0 then \'true\' else \'false\' end) from \"+sql.from+\" tree where tree.\"+tree.parentField+\"=t.\"+tree.rowField+\")\" + tree.hasChild;\r\n}\r\n\r\nif(!su.isBlank(sql.qczd)){\r\n    //去重查询\r\n    whereStr = \" and (\";\r\n		for(var i=0;i<sql.qcList.~size;i++){\r\n    	whereStr += \" t.\"+sql.qczd+\" in (#{join(sql.qcList[\"+i+\"])}) or\";\r\n		}\r\n		whereStr = su.substring(whereStr,0,su.length(whereStr)-3)+\")\";\r\n}else if(!su.isBlank(sjdx.zjzd)&&!su.isBlank(yobj[sjdx.zjzd])){\r\n   //主键存在，则只查询主键\r\n   whereStr = \" and t.\"+sjdx.zjzd+\" =#{yobj.\"+sjdx.zjzd+\"}\";\r\n}else if(!su.isBlank(sys.ids)){\r\n    //id列表场景：不再处理其他查询条件\r\n    whereStr = \" and t.\"+sjdx.zjzd+\" in (#{join(sys.ids)})\";\r\n}else{\r\n  if(null!=cllxkz[\'select\'].tree.hasChild!){\r\n     //树形结构查询场景\r\n     var tree = cllxkz[\'select\'].tree;\r\n      //是否树形结构查询条件\r\n      var sfsxjgField = tree.sfsxjgField!;\r\n     if(su.isBlank(yobj[tree.parentField])&&(sfsxjgField==null||!(yobj[sfsxjgField]==\'0\'))){\r\n         //若是没有传父节点，且没有要求不按树形结构查询，则默认查所有根节点\r\n         whereStr = \" and (t.\"+tree.parentField+\"  is null or t.\"+tree.parentField+\" =\'\')\";\r\n     }\r\n  }\r\n  //简拼全拼支持\r\n  if(!su.isBlank(sys.fields.sszzd!)){\r\n     var value = yobj[sys.fields.sszzd.zddm];\r\n     if(su.isBlank(value)){\r\n         value = sys.searchKey;\r\n         //mu.safeAddToMap(yobj,sys.fields.sszzd.zddm,value);\r\n				 classUtil.setVal(sys.fields.sszzd.zddm,value,yobj,null);\r\n     }\r\n     if(!su.isBlank(value)){\r\n       sszdlb = \"\'t.\"+sys.fields.sszzd.zddm+\"\'\";\r\n       if(!su.isBlank(sys.fields.pyjp)){\r\n            sszdlb = sszdlb+\",\'t.\"+sys.fields.pyjp.zddm+\"\'\";\r\n       }\r\n       if(!su.isBlank(sys.fields.pyqp)){\r\n            sszdlb = sszdlb+\",\'t.\"+sys.fields.pyqp.zddm+\"\'\";\r\n       }\r\n       if(!su.isBlank(sys.fields.sszdlb)){\r\n            sszdlb = sszdlb+\",\'t.\"+sys.fields.sszdlb.zddm+\"\'\";\r\n       }\r\n       whereStr = whereStr + \" and upper(#{globalUse(\'util.expConcatWs\',{\'list\':[\"+sszdlb+\"]\\\\})}) like upper(#{\'%\'+yobj.\"+sys.fields.sszzd.zddm+\"+\'%\'})\";\r\n     }\r\n  }\r\n  //循环生成字段\r\n  for(e in fields){\r\n   var field = e.value;\r\n     if(su.contains(field.zdywlb,\"99\")||su.contains(field.zdywlb,\"98\")){\r\n          //虚拟字段 或 查询自定义\r\n          continue;\r\n     }\r\n     if((sszdlb!=null&&sys.fields.sszzd.zddm==field.zddm)||su.isBlank(yobj[field.zddm])){\r\n          //搜索主字段或该字段值为空\r\n          continue;\r\n     }\r\n     if(yobj[field.zddm]==\'my-null\'){\r\n           whereStr = whereStr + \" and t.\"+field.yszddm+\" is null\";\r\n     }else if(yobj[field.zddm]==\'my-not-null\'){\r\n           whereStr = whereStr + \" and t.\"+field.yszddm+\" is not null\";\r\n     }else if(\"$select\"==field.kjlx||\"$checkbox\"==field.kjlx||\"$radio\"==field.kjlx){\r\n          //字典多选支持\r\n         var arr = su.split(yobj[field.zddm]+\"\", \",\");\r\n         //mu.safeAddToMap(yobj,field.zddm+\"_arr\",arr);\r\n				 classUtil.setVal(field.zddm+\"_arr\",arr,sql.kzcs,null);\r\n         for(var a=0;a<arr.~size;a++){\r\n             if(a==0){\r\n	     whereStr = whereStr + \" and (\";\r\n             }else{\r\n	     whereStr = whereStr + \" or \";\r\n             }\r\n               if(a==\'my-null\'){\r\n                 whereStr = whereStr + \" t.\"+field.yszddm+\" is null \";\r\n               }else if(field.zddx==\'1\'||\"$checkbox\"==field.kjlx){\r\n                 whereStr = whereStr + \" t.\"+field.yszddm+\" like #{\'%\'+sql.kzcs.\"+field.zddm+\"_arr[\"+a+\"]+\'%\'} \";\r\n               }else{\r\n                 whereStr = whereStr + \" t.\"+field.yszddm+\" = #{sql.kzcs.\"+field.zddm+\"_arr[\"+a+\"]} \";\r\n							 }\r\n         }\r\n         whereStr = whereStr + \")\";\r\n     }else if(\"$select\"==field.kjlx||\"$radio\"==field.kjlx||\"ElCascader\"==field.kjlx\r\n		 		||\"$switch\"==field.kjlx){\r\n           whereStr = whereStr + \" and t.\"+field.yszddm+ su.addInput(field.zddm,yobj[field.zddm]);\r\n     }else if(\"suggest\"==field.kjlx){\r\n           //mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm+\"_text\"]+\"%\");\r\n				   classUtil.setVal(field.zddm+\"_like\",\"%\"+yobj[field.zddm+\"_text\"]+\"%\",sql.kzcs,null);\r\n           whereStr = whereStr + \" and t.\"+field.yszddm+ su.addInput(field.zddm,sql.kzcs[field.zddm+\"_like\"]);\r\n     }else if(\"ElDatePicker\"==field.kjlx){\r\n           su.clEqDate(field,yobj);\r\n           if(field.zdlx==\'DATE\'){\r\n                    //支持date类型的时间\r\n                    if(!su.isBlank(yobj[field.zddm+\"_start\"])){\r\n                      whereStr = whereStr + \" and t.\"+field.yszddm+\" >=#{globalUse(\'util.expStr14ToDate\',{\'dateStr\':\'\"+yobj[field.zddm+\"_start\"]+\"\'\\\\})}\";\r\n                    }\r\n                    if(!su.isBlank(yobj[field.zddm+\"_end\"])){\r\n                      whereStr = whereStr + \" and t.\"+field.yszddm+\" <=#{globalUse(\'util.expStr14ToDate\',{\'dateStr\':\'\"+yobj[field.zddm+\"_end\"]+\"\'\\\\})}\";\r\n                    }\r\n           }else{\r\n                    if(!su.isBlank(yobj[field.zddm+\"_start\"])){\r\n                      whereStr = whereStr + \" and t.\"+field.yszddm+\" >=#{yobj.\"+field.zddm+\"_start}\";\r\n                    }\r\n                    if(!su.isBlank(yobj[field.zddm+\"_end\"])){\r\n                      whereStr = whereStr + \" and t.\"+field.yszddm+\" <=#{yobj.\"+field.zddm+\"_end}\";\r\n                    }\r\n           }\r\n     }else if(\"ElInputNumber\"==field.kjlx){\r\n					if(yobj[field.zddm].~size>0&&!su.isBlank(yobj[field.zddm][0])){\r\n						whereStr = whereStr + \" and t.\"+field.yszddm+\" >=#{\"+yobj[field.zddm][0]+\"}\";\r\n					}\r\n					if(yobj[field.zddm].~size>1&&!su.isBlank(yobj[field.zddm][1])){\r\n						whereStr = whereStr + \" and t.\"+field.yszddm+\" <=#{\"+yobj[field.zddm][1]+\"}\";\r\n					}\r\n     }else{\r\n		     whereStr = whereStr + \" and t.#{globalUse(\'util.expField\',{\'field\':\'\"+field.yszddm+\"\'\\\\})}\";\r\n          //默认处理方式\r\n         if(!su.isBlank(yobj[field.zddm])){\r\n             if(su.indexOf(yobj[field.zddm]+\"\", \"%\")>-1){\r\n                //用户输入有%，则按用户输入进行模糊即可\r\n                //mu.safeAddToMap(yobj,field.zddm+\"_like\",yobj[field.zddm]);\r\n				   			classUtil.setVal(field.zddm+\"_like\",yobj[field.zddm],sql.kzcs,null);\r\n                whereStr = whereStr + su.addInput(field.zddm,sql.kzcs[field.zddm+\"_like\"]);\r\n             }else if(field.cxms==\'1\'){\r\n                //模糊搜索\r\n                //mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm]+\"%\");\r\n				   			classUtil.setVal(field.zddm+\"_like\",\"%\"+yobj[field.zddm]+\"%\",sql.kzcs,null);\r\n                whereStr = whereStr + su.addInput(field.zddm,sql.kzcs[field.zddm+\"_like\"]);\r\n             }else if(field.cxms==\'2\'){\r\n                //右模糊搜索\r\n                //mu.safeAddToMap(yobj,field.zddm+\"_like\",yobj[field.zddm]+\"%\");\r\n				   			classUtil.setVal(field.zddm+\"_like\",yobj[field.zddm]+\"%\",sql.kzcs,null);\r\n                whereStr = whereStr + su.addInput(field.zddm,sql.kzcs[field.zddm+\"_like\"]);\r\n             }else if(field.cxms==\'3\'){\r\n                //左模糊搜索\r\n                //mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm]);\r\n				   			classUtil.setVal(field.zddm+\"_like\",\"%\"+yobj[field.zddm],sql.kzcs,null);\r\n                whereStr = whereStr + su.addInput(field.zddm,sql.kzcs[field.zddm+\"_like\"]);\r\n             }else{\r\n                //精确搜索\r\n                whereStr = whereStr + \" =#{yobj[\'\"+field.zddm+\"\']}\";\r\n             }\r\n          }\r\n     }\r\n  }\r\n}\r\n\r\n//权限过滤条件\r\nvar authWhere = \"\";\r\nif(!has(user)){\r\n    //用户为空，初进系统\r\n}else if(user.qxMap[\'KFZFW_GLY\']!=null){\r\n    //管理员，不能查看系统管理员(sys)创建的数据。\r\n    if(!su.isBlank(sys.fields.cjrdm!)){\r\n        authWhere = \" and t.\"+sys.fields.cjrdm.zddm+\"<>\'BC5D77315CA84C6C807988E3CD17E70D\'\";\r\n    }\r\n}else if(user.qxMap[\'KFZFW_DWGLY\']!=null){\r\n    //单位管理员，只能管理本单位\r\n    if(!su.isBlank(sys.fields.cjrdwdm!)&&has(user)){\r\n        authWhere = \" and t.\"+sys.fields.cjrdwdm.zddm+\"=\'\"+user.jgxx.id+\"\'\";\r\n    }\r\n    if(user.qxMap[\'KFZFW_GLZDW\']!=null){\r\n        //管理子单位\r\n    \r\n    }\r\n}else if(user.qxMap[\'KFZFW_GLZDW\']!=null){\r\n    //管理子单位\r\n    \r\n}\r\n\r\nif(!has(user)){\r\n    //用户为空，初进系统\r\n}else if(user.qxMap[\'KFZFW_SYS\']!=null){\r\n    //系统管理员，无权限过滤\r\n    authWhere = \"\";\r\n}else if(su.isBlank(authWhere)){\r\n    //普通用户,或上述权限没有生效只能查看本人数据\r\n    if(!su.isBlank(sys.fields.cjrdm!)&&has(user)&&user!=null){\r\n        authWhere = \" and t.\"+sys.fields.cjrdm.zddm+\"=\'\"+user.id+\"\'\";\r\n    }\r\n}\r\n\r\n//处理排序\r\nvar orderBy = page.orderBy;\r\nif(su.isBlank(orderBy)){\r\n    orderBy = sjdx.mrpx;\r\n}\r\nif(!su.isBlank(orderBy)){\r\n    orderBy = \"order by \"+orderBy;\r\n}\r\n\r\nselectField = su.substring(selectField,1);\r\n\r\n//设置变量，备用\r\n//mu.safeAddToMap(sql,\"selectField\",selectField);\r\n//mu.safeAddToMap(sql,\"whereStr\",whereStr);\r\n//mu.safeAddToMap(sql,\"authWhere\",authWhere);\r\n//mu.safeAddToMap(sql,\"orderBy\",orderBy);\r\nclassUtil.setVal(\"selectField\",selectField,sql,null);\r\nclassUtil.setVal(\"whereStr\",whereStr,sql,null);\r\nclassUtil.setVal(\"authWhere\",authWhere,sql,null);\r\nclassUtil.setVal(\"orderBy\",orderBy,sql,null);\r\n//要上天，逆天的操作\r\n//mydb.update(mydb.use(),\"insert into test_sjgl_1(xm) select to_char(sysdate,\'yyyymmddhh24miss\') from dual\",null);\r\n*/\r\nselect\r\n-- @pageTag(){\r\n ${sql.selectField}\r\n-- @}\r\n  from ${sql.from} t\r\n-- @where(){\r\n        ${sql.whereStr}\r\n-- @}\r\n-- @pageIgnoreTag(){\r\n	${sql.orderBy}\r\n-- @}', NULL, '/*\n//CXZDLB\nVAR SELECTFIELD = \"\";\n//CXTJ\nVAR WHERESTR = \"\";\n//SSZDLB\nVAR SSZDLB = NULL;\n//SZCXDZDLB\nFOR(E IN FIELDS){\n   VAR FIELD = E.VALUE;\n   IF(!SU.CONTAINS(FIELD.ZDYWLB,\"99\")&&(FIELD.XQZS==\"1\"||FIELD.LBZS==\"1\"||FIELD.ZDDM==SJDX.ZJZD)){\n	 		IF(FIELD.ZDLX==\'DATE\'){\n       	SELECTFIELD = SELECTFIELD + \",#{GLOBALUSE(\'UTIL.EXPDATETOSTR14\',{\'DATEOBJ\':\'T.\"+FIELD.YSZDDM+\"\'\\\\})} AS \"+FIELD.YSZDDM;\n	', '/*\n//CHAXUNZIDUANLIEBIAO\nVAR SELECTFIELD = \"\";\n//CHAXUNTIAOJIAN\nVAR WHERESTR = \"\";\n//SOUSUOZIDUANLIEBIAO\nVAR SSZDLB = NULL;\n//SHEZHICHAXUNDEZIDUANLIEBIAO\nFOR(E IN FIELDS){\n   VAR FIELD = E.VALUE;\n   IF(!SU.CONTAINS(FIELD.ZDYWLB,\"99\")&&(FIELD.XQZS==\"1\"||FIELD.LBZS==\"1\"||FIELD.ZDDM==SJDX.ZJZD)){\n	 		IF(FIELD.ZDLX==\'DATE\'){\n       	SELECTFIELD = SELECTFIELD + \",#{GLOBALUSE(\'UTIL.EXPDATETOSTR14\',{\'D', NULL, '20200226155926', '20240614222233', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('26B7F6F2363B48A8A1B5561DAD94351C', 'sjkxsjzt', 99999, 'SYS_SJGL_APPCONFIG', 'oracle,mysql,postgresql,hwmpp,greenplum,h2', '数据库型数据载体，应用中会采用Db工具类处理', 'ORACLE,MYSQL,POSTGRESQL,HWMPP,GREENPLUM,H2', 'ORACLE,MYSQL,POSTGRESQL,HWMPP,GREENPLUM,H2', NULL, '20190917164913', '20190917185503', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('27DABC08028441B1A5ED4F6FC2A36236', 'SHRMYY_HLB_ZLJCX.update', 99999, 'SYS_SJGL_APPCONFIG', '/*\nvar setf = \"\";\nif(su.isNotBlank(sjdx.zlzd)){\n    setf = setf+\",\"+sjdx.zlzd+\"=#{globalUse(\"util.expDate14\")}\";\n}\nvar whereStr = sjdx.zjzd+\"=#{yobj.\"+sjdx.zjzd+\"}\";\n//循环生成字段\nfor(field in fieldList){\n     if(yobj[field.zddm]!=null&&field.zddm!=sjdx.zjzd&&!su.contains(field.zdywlb,\"99\")){\n          if(field.kjlx==\'password\'){\n             setf = setf+\",\"+field.zddm+\"=\'\"+su.desEnByField(yobj[field.zddm],field)+\"\'\";\n          }else{\n             setf = setf+\",\"+field.zddm+\"=#{yobj.\"+field.zddm+\"}\";\n          }\n     }\n }\n if(!isEmpty(kzxx.fields.sszzd)&&!isEmpty(yobj[kzxx.fields.sszzd.zddm])){\n     //设置简拼和全拼\n     if(!isEmpty(kzxx.fields.pyjp)&&su.length(yobj[kzxx.fields.sszzd.zddm])<200){\n          setf = setf+\",\"+kzxx.fields.pyjp.zddm+\"=#{yobj.pyjp}\";\n          mu.safeAddToMap(yobj,\"pyjp\",su.getSimpleSpell(yobj[kzxx.fields.sszzd.zddm]));\n     }\n     if(!isEmpty(kzxx.fields.pyqp)&&su.length(yobj[kzxx.fields.sszzd.zddm])<200){\n          setf = setf+\",\"+kzxx.fields.pyqp.zddm+\"=#{yobj.pyqp}\";\n          mu.safeAddToMap(yobj,\"pyqp\",su.getFullSpell(yobj[kzxx.fields.sszzd.zddm]));\n     }\n }\n setf = su.substring(setf, 1);\n\n//新增\nvar insertf = \"\";\nvar values = \"\";\n//循环生成字段\nfor(field in fieldList){\n     if(!isEmpty(yobj[field.zddm])&&!su.contains(field.zdywlb,\"99\")&&field.zddm!=\'z_id\'){\n          insertf = insertf+\",\"+field.zddm;\n          if(field.kjlx==\'password\'){\n             values = values+\",\'\"+su.desEnByField(yobj[field.zddm],field)+\"\'\";\n          }else{\n             values = values+\",#{yobj.\"+field.zddm+\"}\";\n          }\n     }\n}\nif(!isEmpty(kzxx.fields.sszzd)&&!isEmpty(yobj[kzxx.fields.sszzd.zddm])){\n     //设置简拼和全拼\n     if(!isEmpty(kzxx.fields.pyjp)&&su.length(yobj[kzxx.fields.sszzd.zddm])<200){\n          insertf = insertf+\",\"+kzxx.field