{\n     IF(YOBJ[FIELD.ZDDM]!=NULL&&FIELD.ZDDM!=SJDX.ZJZD&&!SU.CONTAINS(FIELD.ZDYWLB,\"99\")){\n          IF(FIELD.KJLX==\'PASSWORD\'){\n             SETF = SETF+\",\"+FIELD.ZDDM+\"=\'\"+SU.DESENBYF', NULL, '20210330194204', '20230302113149', NULL, NULL, '0', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('299BBFA078D04557B6FBA69A81AFF8EA', 'KETTLE_GLPT_ZYYJ.getfile', 99999, 'SYS_SJGL_APPCONFIG', 'select job_name||\'-\'||to_char(sysdate,\'yyyymmddhh24miss\')||\'.txt\' wjm,\'txt\' wjlx,\'true\' xzms,\'bdwjjl\' sjxs,log_file data from job_warning jw where jw.oid=#{yobj.oid}', NULL, 'SELECT JOB_NAME||\'-\'||TO_CHAR(SYSDATE,\'YYYYMMDDHH24MISS\')||\'.TXT\' WJM,\'TXT\' WJLX,\'TRUE\' XZMS,\'BDWJJL\' SJXS,LOG_FILE DATA FROM JOB_WARNING JW WHERE JW.OID=#YOBJ.OID#', 'SELECT JOB_NAME||\'-\'||TO_CHAR(SYSDATE,\'YYYYMMDDHH24MISS\')||\'.TXT\' WJM,\'TXT\' WJLX,\'TRUE\' XZMS,\'BDWJJL\' SJXS,LOG_FILE DATA FROM JOB_WARNING JW WHERE JW.OID=#YOBJ.OID#', NULL, '20191017203616', '20191120234359', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('2BD8DAA2BD8449C4A29B100554F24B30', 'KETTLE_GLPT_JCRZ.getfile', 99999, 'SYS_SJGL_APPCONFIG', 'select job_name||\'-\'||to_char(sysdate,\'yyyymmddhh24miss\')||\'.txt\' wjm,\'txt\' wjlx,\'true\' xzms,\'bdwjjl\' sjxs,log_file data from job_log jl where jl.oid=#{yobj.oid}', 'wjm：文件名，wjlx：文件类型，xzms：下载模式，sjxs：数据形式（bdwjjl：本地文件记录，bolb），data：具体数据', 'SELECT JOB_NAME||\'-\'||TO_CHAR(SYSDATE,\'YYYYMMDDHH24MISS\')||\'.TXT\' WJM,\'TXT\' WJLX,\'TRUE\' XZMS,\'BDWJJL\' SJXS,LOG_FILE DATA FROM JOB_LOG JL WHERE JL.OID=#YOBJ.OID#', 'SELECT JOB_NAME||\'-\'||TO_CHAR(SYSDATE,\'YYYYMMDDHH24MISS\')||\'.TXT\' WJM,\'TXT\' WJLX,\'TRUE\' XZMS,\'BDWJJL\' SJXS,LOG_FILE DATA FROM JOB_LOG JL WHERE JL.OID=#YOBJ.OID#', NULL, '20191017201441', '20191120234350', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('2DE0A38C02494647A7C86972A20303FA', 'DEFAULT.qqmrcs', 99999, 'SYS_SJGL_APPCONFIG', '默认-请求默认参数', NULL, 'MR-QQMRCS', 'MOREN-QINGQIUMORENCANSHU', NULL, '20210830110102', '20210830110102', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\"sjdx\":{},\"yobj\":{},\"obj\":{},\"fsxx\":{}}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('2FB64714B3DB4447BFD33D031FA14C22', 'SYS_SJGL_GRBJ_ZS.getTreeCN', 99999, 'SYS_SJGL_APPCONFIG', 'select bt  name,\n       t.id dm,\n       t.cjrdwdm,\n       t.cjrdm,\n       (select count(1)\n          from SYS_SJGL_GRBJ t1\n         where t1.yxx = \'1\'\n           and t1.sjbj = t.id\n        ) parent,\n        t.zt,t.kjx,t.tb icon\n  from SYS_SJGL_GRBJ t\n where t.yxx = \'1\'\n      /*if(!isEmpty(sjdx.sjbj)){*/\n   and t.sjbj = #{sjdx.sjbj}\n      /*}else if(!isEmpty(sjdx.treeRoot)){*/\n   and t.sjbj = #{sjdx.treeRoot}\n      /*}else{*/\n   and t.sjbj is null\n      /*}*/\n order by px asc,t.gxsj desc', NULL, NULL, NULL, NULL, '20200701114458', '20200828231658', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('2FFBF44CF8554C0F93347FB990CB9D13', 'SYS_SJGL_BHSC.nextVal', 99999, 'SYS_SJGL_APPCONFIG', '/*\nmydb.update(mydb.use(),\"update sys_sjgl_bhsc t set t.dqz=(dqz+dzl) where t.id=? and t.yxx=\'1\'\",sys.ids[0]);\n*/\nselect dqz\n  from sys_sjgl_bhsc t\n where t.id = #{sys.ids[0]}\n   and t.yxx = \'1\'\n', NULL, '/*\nMYDB.UPDATE(MYDB.USE(),\"UPDATE SYS_SJGL_BHSC T SET T.DQZ=(DQZ+DZL) WHERE T.ID=? AND T.YXX=\'1\'\",SYS.IDS[0]);\n*/\nSELECT DQZ\n  FROM SYS_SJGL_BHSC T\n WHERE T.ID = #{SYS.IDS[0]}\n   AND T.YXX = \'1\'\n', '/*\nMYDB.UPDATE(MYDB.USE(),\"UPDATE SYS_SJGL_BHSC T SET T.DQZ=(DQZ+DZL) WHERE T.ID=? AND T.YXX=\'1\'\",SYS.IDS[0]);\n*/\nSELECT DQZ\n  FROM SYS_SJGL_BHSC T\n WHERE T.ID = #{SYS.IDS[0]}\n   AND T.YXX = \'1\'\n', NULL, '20191210225612', '20211202224247', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('3321fc38023911ee8ef3000c29f304ac', 'zd.SYS_COMMON_TABLES.oracle', 99999, 'SYS_SJGL_APPCONFIG', 'select t.TABLE_NAME dm,t.TABLE_NAME||\'[\'||t.COMMENTS||\']\' as mc,\'\' upnode,\'\' px,\'\' as search_key from  all_tab_comments t \n-- @where(){\n-- @ if(isNotEmpty(yobj.owner)){\nand t.owner=\'${su.upperCase(yobj.owner)}\'\n-- @}else if(isNotEmpty(sjzt.dxgs)){\nand t.owner=\'${su.upperCase(sjzt.dxgs)}\'\n-- @}\n-- @}', NULL, 'SELECT T.TABLE_NAME DM,T.TABLE_NAME||\'[\'||T.COMMENTS||\']\' AS MC,\'\' UPNODE,\'\' PX,\'\' AS SEARCH_KEY FROM  ALL_TAB_COMMENTS T \n-- @WHERE(){\n-- @ IF(ISNOTEMPTY(YOBJ.OWNER)){\nAND T.OWNER=\'${SU.UPPERCASE(YOBJ.OWNER)}\'\n-- @}ELSE IF(ISNOTEMPTY(SJZT.DXGS)){\nAND T.OWNER=\'${SU.UPPERCASE(SJZT.DXGS)}\'\n-- @}\n-- @}', 'SELECT T.TABLE_NAME DM,T.TABLE_NAME||\'[\'||T.COMMENTS||\']\' AS MC,\'\' UPNODE,\'\' PX,\'\' AS SEARCH_KEY FROM  ALL_TAB_COMMENTS T \n-- @WHERE(){\n-- @ IF(ISNOTEMPTY(YOBJ.OWNER)){\nAND T.OWNER=\'${SU.UPPERCASE(YOBJ.OWNER)}\'\n-- @}ELSE IF(ISNOTEMPTY(SJZT.DXGS)){\nAND T.OWNER=\'${SU.UPPERCASE(SJZT.DXGS)}\'\n-- @}\n-- @}', NULL, '20230604020518', '20230604032106', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('35B3F6CA65D74C22ACA641F04329C533', 'DEFAULT.dis.vertica', 99999, 'SYS_SJGL_APPCONFIG', 'SELECT column_name zddm,column_name zdms,split_part(data_type,\'(\',1) zdlx,data_type_length zdcd\nFROM v_catalog.columns c\nwhere  table_name = \'${yobj.jtdx}\'\n/* if(!isEmpty(yobj.dxgs)){*/\n   and c.table_schema = \'${yobj.dxgs}\'\n/* }else  if(!isEmpty(yobj.sjztObj.dxgs)){*/\n   and c.table_schema = \'${yobj.sjztObj.dxgs}\'\n/* }else  if(!isEmpty(yobj.sjztObj.yhm)){*/\n   and c.table_schema = \'${yobj.sjztObj.yhm}\'\n/* }*/\nunion all \nSELECT column_name zddm,column_name zdms,split_part(data_type,\'(\',1) zdlx,data_type_length zdcd\nFROM v_catalog.view_columns c\nwhere  table_name =  \'${yobj.jtdx}\'\n/* if(!isEmpty(yobj.dxgs)){*/\n   and c.table_schema = \'${yobj.dxgs}\'\n/* }else  if(!isEmpty(yobj.sjztObj.dxgs)){*/\n   and c.table_schema = \'${yobj.sjztObj.dxgs}\'\n/* }else  if(!isEmpty(yobj.sjztObj.yhm)){*/\n   and c.table_schema = \'${yobj.sjztObj.yhm}\'\n/* }*/', NULL, NULL, 'SELECT COLUMN_NAME ZDDM,COLUMN_NAME ZDMS,SPLIT_PART(DATA_TYPE,\'(\',1) ZDLX,DATA_TYPE_LENGTH ZDCD\nFROM V_CATALOG.COLUMNS C\nWHERE  TABLE_NAME = \'${YOBJ.JTDX}\'\n/* IF(!ISEMPTY(YOBJ.DXGS)){*/\n   AND C.TABLE_SCHEMA = \'${YOBJ.DXGS}\'\n/* }ELSE  IF(!ISEMPTY(YOBJ.SJZTOBJ.DXGS)){*/\n   AND C.TABLE_SCHEMA = \'${YOBJ.SJZTOBJ.DXGS}\'\n/* }ELSE  IF(!ISEMPTY(YOBJ.SJZTOBJ.YHM)){*/\n   AND C.TABLE_SCHEMA = \'${YOBJ.SJZTOBJ', NULL, '20220923105851', '20220923105851', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('3863E2D45E864E32BB98FB4A5EA547AD', 'DEFAULT.fzzd', 99999, 'SYS_SJGL_APPCONFIG', '/*\nvar zdIn = \"\";\nif(!isEmpty(yobj.xjdx)&&yobj.xjdx){\nzdIn = \"\'myLbcz\'\";\nfor(field in yobj.newSjzd){\n	zdIn = zdIn + \",\'\"+su.lowerCase(field.zddm)+\"\'\";\n}\n}\nvar fzdx = \'21C74221753145F6A3B690042E0B563A\';\nif(!isEmpty(yobj.oldSjdxId)){\nfzdx = yobj.oldSjdxId;\n}\n*/\ninsert into sys_sjgl_sjzd\n  (yxx,\n   px,\n   kzxx,\n   sjdx,\n   zddm,\n   zdmc,\n   zdms,\n   zdjp,\n   zdqp,\n   zdlx,\n   zdcd,\n   zdkd,\n   cxmrz,\n   xzmrz,\n   kjlx,\n   zddx,\n   zdfy,\n   yxpx,\n   lbzs,\n   cxzs,\n   xzzs,\n   mbzs,\n   bjzs,\n   xqzs,\n   cxbt,\n   bjbt,\n   yxbj,\n   zdzdlb,\n   zdywlb,\n   zdts,\n   qcbh,\n   bzzd,\n   zydj,\n	 yszddm)\n  select yxx,\n         px,\n         kzxx,\n         \'${yobj.newSjdx.id}\' as sjdx,\n         zddm,\n         zdmc,\n         zdms,\n         zdjp,\n         zdqp,\n         zdlx,\n         zdcd,\n         zdkd,\n         cxmrz,\n         xzmrz,\n         kjlx,\n         zddx,\n         zdfy,\n         yxpx,\n         lbzs,\n         cxzs,\n         xzzs,\n         mbzs,\n         bjzs,\n         xqzs,\n         cxbt,\n         bjbt,\n         yxbj,\n         zdzdlb,\n         zdywlb,\n         zdts,\n         qcbh,\n         bzzd,\n         zydj,\n				 yszddm\n    from sys_sjgl_sjzd t\n   where t.sjdx = \'${fzdx}\' and t.yxx=\'1\'\n        /*if(zdIn!=\'\'){*/\n     and yszddm in (${zdIn})\n  /*}*/', '复制字段', '/*\nVAR ZDIN = \"\";\nIF(!ISEMPTY(YOBJ.XJDX)&&YOBJ.XJDX){\nZDIN = \"\'MYLBCZ\'\";\nFOR(FIELD IN YOBJ.NEWSJZD){\n	ZDIN = ZDIN + \",\'\"+SU.LOWERCASE(FIELD.ZDDM)+\"\'\";\n}\n}\nVAR FZDX = \'21C74221753145F6A3B690042E0B563A\';\nIF(!ISEMPTY(YOBJ.OLDSJDXID)){\nFZDX = YOBJ.OLDSJDXID;\n}\n*/\nINSERT INTO SYS_SJGL_SJZD\n  (YXX,\n   PX,\n   KZXX,\n   SJDX,\n   ZDDM,\n   ZDMC,\n   ZDMS,\n   ZDJP,\n   ZDQP,\n   ZDLX,\n   ZDCD,\n   ZDKD,\n   CXMRZ,', '/*\nVAR ZDIN = \"\";\nIF(!ISEMPTY(YOBJ.XJDX)&&YOBJ.XJDX){\nZDIN = \"\'MYLBCZ\'\";\nFOR(FIELD IN YOBJ.NEWSJZD){\n	ZDIN = ZDIN + \",\'\"+SU.LOWERCASE(FIELD.ZDDM)+\"\'\";\n}\n}\nVAR FZDX = \'21C74221753145F6A3B690042E0B563A\';\nIF(!ISEMPTY(YOBJ.OLDSJDXID)){\nFZDX = YOBJ.OLDSJDXID;\n}\n*/\nINSERT INTO SYS_SJGL_SJZD\n  (YXX,\n   PX,\n   KZXX,\n   SJDX,\n   ZDDM,\n   ZDMC,\n   ZDMS,\n   ZDJP,\n   ZDQP,\n   ZDLX,\n   ZDCD,\n   ZDKD,\n   CXMRZ,', NULL, '20181218130733', '20231030223745', 'jingma', NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('411610D73836471C9400C0064890F2EF', 'DEFAULT.getFields', 99999, 'SYS_SJGL_APPCONFIG', 'select * from sys_sjgl_sjzd t \nwhere t.yxx=\'1\' and t.sjdx=#{sjdx.id} \n-- @if(isNotEmpty(user)){\nand t.zydj>=#{user.yhdj}\n-- @}\norder by px asc;ds=default', '获取对象的字段信息', 'SELECT * FROM SYS_SJGL_SJZD T \nWHERE T.YXX=\'1\' AND T.SJDX=#{SJDX.ID} \n-- @IF(ISNOTEMPTY(USER)){\nAND T.ZYDJ>=#{USER.YHDJ}\n-- @}\nORDER BY PX ASC;DS=DEFAULT', 'SELECT * FROM SYS_SJGL_SJZD T \nWHERE T.YXX=\'1\' AND T.SJDX=#{SJDX.ID} \n-- @IF(ISNOTEMPTY(USER)){\nAND T.ZYDJ>=#{USER.YHDJ}\n-- @}\nORDER BY PX ASC;DS=DEFAULT', NULL, '20200904005043', '20211027151439', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('45D72CEFD09A4B729B24A7A56B2D4930', 'SYS_PLBD_HM_QYMP.getTreeCN', 99999, 'SYS_SJGL_APPCONFIG', 'select mc  name,\n       t.dm dm,\n       (select count(1)\n          from SYS_BDHC_ZY t1\n         where t1.yxx = \'1\'\n           and t1.sjzy = t.dm\n        ) parent,\n        t.sjdx\n  from SYS_BDHC_ZY t\n where t.yxx = \'1\' and t.qyhc=\'1\'\n      /*if(!isEmpty(sjdx.sjzy)){*/\n   and t.sjzy = #{sjdx.sjzy}\n      /*}else if(!isEmpty(sjdx.treeRoot)){*/\n   and t.sjzy = #{sjdx.treeRoot}\n      /*}else{*/\n   and t.sjzy is null\n      /*}*/\n order by px asc,t.gxsj desc', NULL, NULL, NULL, NULL, '20200616000228', '20210222153741', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('462ABCC3F0ED4359AA2F8349248B32B2', 'DEFAULT.plbd', 99999, 'SYS_SJGL_APPCONFIG', '/*\nvar selectField = \"\";\nvar whereStr = \"\";\nvar sszdlb = null;\n//循环生成字段\nfor(field in fieldList){\n   if(su.contains(field.zdywlb,\"99\")){\n        //虚拟字段\n        continue;\n   }\n   selectField = selectField + \",\" + field.zddm;\n     if(su.contains(field.zdywlb,\"zjhm\")){\n          //设置证件号码字段\n           mu.safeAddToMap(sjdx.map,\'ZJHMZD\',field.zddm);\n          //证件类型为该字段\n          whereStr = whereStr + \" and \"+field.zddm+qyzstj.zjhmIn;\n          continue;\n     }\n     //具体资源没有输入该条件，且公用条件输入了该条件\n     if(isEmpty(yobj[field.zddm])){\n     if(!isEmpty(qyzstj[field.zdywlb])){\n          yobj[field.zddm]=qyzstj[field.zdywlb];\n     }\n     }\n   if((sszdlb!=null&&kzxx.fields.sszzd.zddm==field.zddm)||isEmpty(yobj[field.zddm])){\n        //搜索主字段或该字段值为空\n        continue;\n   }\n   if(\"dict\"==field.kjlx&&field.zddx==\'1\'){\n        //字典多选支持\n       var arr = su.split(yobj[field.zddm], \",\");\n       var idx=0;\n       for(var a in arr){\n           if(idx==0){\n             if(a==\'my-null\'){\n               whereStr = whereStr + \" and (\"+field.zddm+\" is null \";\n             }else{\n               whereStr = whereStr + \" and (\"+field.zddm+\" = \'\"+a+\"\' \";\n             }\n           }else{\n             if(a==\'my-null\'){\n               whereStr = whereStr + \" or \"+field.zddm+\"  is null\";\n             }else{\n               whereStr = whereStr + \" or \"+field.zddm+\" = \'\"+a+\"\' \";\n             }\n           }\n           idx=idx+1;\n       }\n       whereStr = whereStr + \")\";\n   }else if(yobj[field.zddm]==\'my-null\'){\n         whereStr = whereStr + \" and \"+field.zddm+\" is null\";\n   }else if(\"dict\"==field.kjlx){\n         whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm]);\n   }else if((\"check\"+\"box\")==field.kjlx){\n         whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm]);\n   }else if(\"suggest\"==field.kjlx){\n         mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm+\"_text\"]+\"%\");\n         whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n   }else if(\"time\"==field.kjlx){\n         whereStr = whereStr + su.addEqDate(field,yobj);\n         if(field.hdgs==\'date\'){\n                  //支持date类型的时间\n                  if(!isEmpty(yobj[field.zddm+\"_start\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" >=to_date(\'\"+yobj[field.zddm+\"_start\"]+\"\',\'YYYYMMDDHH24MISS\')\";\n                  }\n                  if(!isEmpty(yobj[field.zddm+\"_end\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" <=to_date(\'\"+yobj[field.zddm+\"_end\"]+\"\',\'YYYYMMDDHH24MISS\')\";\n                  }\n         }else{\n                  if(!isEmpty(yobj[field.zddm+\"_start\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" >=\'\"+yobj[field.zddm+\"_start\"]+\"\'\";\n                  }\n                  if(!isEmpty(yobj[field.zddm+\"_end\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" <=\'\"+yobj[field.zddm+\"_end\"]+\"\'\";\n                  }\n         }\n   }else if(\"number\"==field.kjlx){\n         whereStr = whereStr + su.addEqNumber(field.zddm,yobj);\n   }else{\n        //默认处理方式\n       if(!isEmpty(yobj[field.zddm])){\n           if(su.indexOf(yobj[field.zddm], \"%\")>-1){\n              //用户输入有%，则按用户输入进行模糊即可\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",yobj[field.zddm]);\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else if(field.cxms==\'1\'){\n              //模糊搜索\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm]+\"%\");\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else if(field.cxms==\'2\'){\n              //右模糊搜索\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",yobj[field.zddm]+\"%\");\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else if(field.cxms==\'3\'){\n              //左模糊搜索\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm]);\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else{\n              //精确搜索\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm]);\n           }\n        }\n   }\n}\n//权限过滤条件\nvar authWhere = \"\";\nif(user==null){\n    //用户为空，初进系统\n}else if(user.qxMap[\'KFZFW_GLY\']!=null){\n    //管理员，不能查看系统管理员(sys)创建的数据。\n    if(!isEmpty(kzxx.fields.cjrdm)){\n        authWhere = \" and \"+kzxx.fields.cjrdm.zddm+\"<>\'BC5D77315CA84C6C807988E3CD17E70D\'\";\n    }\n}else if(user.qxMap[\'KFZFW_DWGLY\']!=null){\n    //单位管理员，只能管理本单位\n    if(!isEmpty(kzxx.fields.cjrdwdm)&&has(user)){\n        authWhere = \" and \"+kzxx.fields.cjrdwdm.zddm+\"=\'\"+user.jgxx.id+\"\'\";\n    }\n    if(user.qxMap[\'KFZFW_GLZDW\']!=null){\n        //管理子单位\n    \n    }\n}else if(user.qxMap[\'KFZFW_GLZDW\']!=null){\n    //管理子单位\n    \n}\n\nif(user==null){\n    //用户为空，初进系统\n}else if(user.qxMap[\'KFZFW_SYS\']!=null){\n    //系统管理员，无权限过滤\n    authWhere = \"\";\n}else if(isEmpty(authWhere)){\n    //普通用户,或上述权限没有生效只能查看本人数据\n    if(!isEmpty(kzxx.fields.cjrdm)&&has(user)&&user!=null){\n        authWhere = \" and \"+kzxx.fields.cjrdm.zddm+\"=\'\"+user.id+\"\'\";\n    }\n}\nselectField = su.substring(selectField,1);\n//排序\nvar orderBy = su.addPxField(sjdx.mrpx,yobj);\n//设置变量，备用\nmu.safeAddToMap(obj,\"selectField\",selectField);\nmu.safeAddToMap(obj,\"whereStr\",whereStr);\nmu.safeAddToMap(obj,\"authWhere\",authWhere);\nmu.safeAddToMap(obj,\"orderBy\",orderBy);\n*/\n/*if(!isEmpty(sjdx.map.ZJHMZD)){*/\nselect  ${selectField} from ${owner}.${tableName} t where 1 = 1 ${whereStr} ${authWhere} ${orderBy}\n/*}else{*/\nerror:${sjdx.dxmc}没配置有证件号码\n/*}*/', '通用批量比对', '/*\nVAR SELECTFIELD = \"\";\nVAR WHERESTR = \"\";\nVAR SSZDLB = NULL;\n//XHSCZD\nFOR(FIELD IN FIELDLIST){\n   IF(SU.CONTAINS(FIELD.ZDYWLB,\"99\")){\n        //XNZD\n        CONTINUE;\n   }\n   SELECTFIELD = SELECTFIELD + \",\" + FIELD.ZDDM;\n     IF(SU.CONTAINS(FIELD.ZDYWLB,\"ZJHM\")){\n          //SZZJHMZD\n           MU.SAFEADDTOMAP(SJDX.MAP,\'ZJHMZD\',FIELD.ZDDM);\n          //ZJLXWGZD\n          WHERESTR = WHERESTR + ', '/*\nVAR SELECTFIELD = \"\";\nVAR WHERESTR = \"\";\nVAR SSZDLB = NULL;\n//XUNHUANSHENGCHENGZIDUAN\nFOR(FIELD IN FIELDLIST){\n   IF(SU.CONTAINS(FIELD.ZDYWLB,\"99\")){\n        //XUNIZIDUAN\n        CONTINUE;\n   }\n   SELECTFIELD = SELECTFIELD + \",\" + FIELD.ZDDM;\n     IF(SU.CONTAINS(FIELD.ZDYWLB,\"ZJHM\")){\n          //SHEZHIZHENGJIANHAOMAZIDUAN\n           MU.SAFEADDTOMAP(SJDX.MAP,\'ZJHMZD\',FIELD.ZDDM);\n          //', NULL, '20200616010331', '20221117212138', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('46DE4F0796344CDEA15128B9B9019502', 'SYS_BDHC_FK.insert', 99999, 'SYS_SJGL_APPCONFIG', '/*\nif(!isEmpty(yobj.bkjg)){\n      mydb.update(mydb.use(),\"update SYS_BDHC_JG t set t.zlzt=\'9\',t.gxsj=to_char(sysdate,\'YYYYMMDDHH24MISS\') where t.zlzt=\'1\' and t.id=?\",yobj.bkjg);\n}\n*/\n${defaultSql}', NULL, '/*\nIF(!ISEMPTY(YOBJ.BKJG)){\n      MYDB.UPDATE(MYDB.USE(),\"UPDATE SYS_BDHC_JG T SET T.ZLZT=\'9\',T.GXSJ=TO_CHAR(SYSDATE,\'YYYYMMDDHH24MISS\') WHERE T.ZLZT=\'1\' AND T.ID=?\",YOBJ.BKJG);\n}\n*/\n${DEFAULTSQL}', '/*\nIF(!ISEMPTY(YOBJ.BKJG)){\n      MYDB.UPDATE(MYDB.USE(),\"UPDATE SYS_BDHC_JG T SET T.ZLZT=\'9\',T.GXSJ=TO_CHAR(SYSDATE,\'YYYYMMDDHH24MISS\') WHERE T.ZLZT=\'1\' AND T.ID=?\",YOBJ.BKJG);\n}\n*/\n${DEFAULTSQL}', NULL, '20210805100340', '20211202224227', NULL, NULL, '1', '系统管理员', 'sys', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('476A5E446D7E41E293CF7F401D1D4F65', 'SYS_QX_QXXX.sczqx', 99999, 'SYS_SJGL_APPCONFIG', 'insert into sys_qx_qxxx\n  (px,\n   cjrxm,\n   cjrdm,\n   cjrdwmc,\n   cjrdwdm,\n   mc,\n   dm,\n   ms,\n   lx,\n   ssyy,\n   bz,\n   fqx,\n   dzlx,\n   dkfs)\n  select px,\n   cjrxm,\n   cjrdm,\n   cjrdwmc,\n   cjrdwdm,\n   mc,\n   replace(dm,\'KFZFW_PTGL_SJDX\',#{yobj.dm!obj.dm}),\n   ms,\n   lx,\n   ssyy,\n   bz,\n   #{yobj.id},\n   dzlx,\n   dkfs\n    from sys_qx_qxxx t\n   where t.fqx=\'E84DA3F236C246BF81FE07783D821C86\'and t.px<500', '生成数据对象子权限sql', 'INSERT INTO SYS_QX_QXXX\n  (PX,\n   CJRXM,\n   CJRDM,\n   CJRDWMC,\n   CJRDWDM,\n   MC,\n   DM,\n   MS,\n   LX,\n   SSYY,\n   BZ,\n   FQX,\n   DZLX,\n   DKFS)\n  SELECT PX,\n   CJRXM,\n   CJRDM,\n   CJRDWMC,\n   CJRDWDM,\n   MC,\n   REPLACE(DM,\'KFZFW_PTGL_SJDX\',#{YOBJ.DM!OBJ.DM}),\n   MS,\n   LX,\n   SSYY,\n   BZ,\n   #{YOBJ.ID},\n   DZLX,\n   DKFS\n    FROM SYS_QX_QXXX T\n   WHERE T.FQX=\'E84DA3F236C246BF81FE07783D821C86\'AND T', 'INSERT INTO SYS_QX_QXXX\n  (PX,\n   CJRXM,\n   CJRDM,\n   CJRDWMC,\n   CJRDWDM,\n   MC,\n   DM,\n   MS,\n   LX,\n   SSYY,\n   BZ,\n   FQX,\n   DZLX,\n   DKFS)\n  SELECT PX,\n   CJRXM,\n   CJRDM,\n   CJRDWMC,\n   CJRDWDM,\n   MC,\n   REPLACE(DM,\'KFZFW_PTGL_SJDX\',#{YOBJ.DM!OBJ.DM}),\n   MS,\n   LX,\n   SSYY,\n   BZ,\n   #{YOBJ.ID},\n   DZLX,\n   DKFS\n    FROM SYS_QX_QXXX T\n   WHERE T.FQX=\'E84DA3F236C246BF81FE07783D821C86\'AND T', NULL, '20190416172342', '20221030224628', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('4D72695EC6C244728F99DAFEA4033A54', 'DEFAULT.cqsql', 99999, 'SYS_SJGL_APPCONFIG', 'select  t.* \n/*if(gdpz.lzmb==\'zlmb\'){*/\n        ,${sjdx.zlzd} as zlcqzd  \n/*}*/\nfrom ${owner}.${tableName}  t\n/*if(gdpz.lzmb==\'zlmb\'){*/\n        where ${sjdx.zlzd}<${globalUse(\"util.expDate14\")}\n        and ${sjdx.zlzd} >\'\\${ZLSJC}\'\n/*}*/\n', '抽取sql模板', NULL, NULL, NULL, '20191021115001', '20211203001017', 'jingma', NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('4ECB7B2A821342739EF1892901EBF6E2', 'SYS_QX_APP.scjkrw', 99999, 'SYS_SJGL_APPCONFIG', 'select id jtrw,dm rwdm,mc rwmc,\'2\' rwlx,\'99\' rwlb,\'1\' rwdj \n   from sys_qx_app t \n   where 1=1 \n   /*if (!isEmpty(sys.ids)){*/\n   	and t.id in (#{join(sys.ids)})\n   /*}*/', NULL, 'SELECT ID JTRW,DM RWDM,MC RWMC,\'2\' RWLX,\'99\' RWLB,\'1\' RWDJ \n   FROM SYS_QX_APP T \n   WHERE 1=1 \n   /*IF (!ISEMPTY(SYS.IDS)){*/\n   	AND T.ID IN (#{JOIN(SYS.IDS)})\n   /*}*/', 'SELECT ID JTRW,DM RWDM,MC RWMC,\'2\' RWLX,\'99\' RWLB,\'1\' RWDJ \n   FROM SYS_QX_APP T \n   WHERE 1=1 \n   /*IF (!ISEMPTY(SYS.IDS)){*/\n   	AND T.ID IN (#{JOIN(SYS.IDS)})\n   /*}*/', NULL, '20190925183224', '20211205140407', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('4F1E241053E04714B435EA23FA9D8BA8', 'DEFAULT.gxqczd', 99999, 'SYS_SJGL_APPCONFIG', '/*\nvar whereStr = \"\";\nif(su.isNotBlank(sjdx.yxxzd)){\n    whereStr = \"t.\"+sjdx.yxxzd+\"=\'1\'\";\n}\n//循环生成字段\nvar sszdlb = \"\";\nfor(ent in qcFields){\n	sszdlb = sszdlb+\",\'\"+ent.key+\"\',\\\"\'_\'\\\"\";\n}\nvar setf = \"t.\"+sjdx.qczd+\"=upper(md5(#{globalUse(\'util.expConcatWs\',{\'list\':[\"+su.substring(sszdlb, 1)+\"]\\\\})}))\";\n mu.safeAddToMap(sql,\"setf\",setf);\n mu.safeAddToMap(sql,\"whereStr\",whereStr);\n*/\nupdate ${sql.from} t\n   set ${sql.setf}\n where ${sql.whereStr}', '更新去重字段', '/*\nVAR WHERESTR = \"\";\nIF(SU.ISNOTBLANK(SJDX.YXXZD)){\n    WHERESTR = \"T.\"+SJDX.YXXZD+\"=\'1\'\";\n}\n//XHSCZD\nVAR SSZDLB = \"\";\nFOR(ENT IN QCFIELDS){\n	SSZDLB = SSZDLB+\",\'\"+ENT.KEY+\"\',\\\"\'_\'\\\"\";\n}\nVAR SETF = \"T.\"+SJDX.QCZD+\"=UPPER(MD5(#{GLOBALUSE(\'UTIL.EXPCONCATWS\',{\'LIST\':[\"+SU.SUBSTRING(SSZDLB, 1)+\"]\\\\})}))\";\n MU.SAFEADDTOMAP(SQL,\"SETF\",SETF);\n MU.SAFEADDTOMAP(SQL,\"WHERESTR\",WHERESTR);\n*/\nUPDATE ${SQL.FRO', '/*\nVAR WHERESTR = \"\";\nIF(SU.ISNOTBLANK(SJDX.YXXZD)){\n    WHERESTR = \"T.\"+SJDX.YXXZD+\"=\'1\'\";\n}\n//XUNHUANSHENGCHENGZIDUAN\nVAR SSZDLB = \"\";\nFOR(ENT IN QCFIELDS){\n	SSZDLB = SSZDLB+\",\'\"+ENT.KEY+\"\',\\\"\'_\'\\\"\";\n}\nVAR SETF = \"T.\"+SJDX.QCZD+\"=UPPER(MD5(#{GLOBALUSE(\'UTIL.EXPCONCATWS\',{\'LIST\':[\"+SU.SUBSTRING(SSZDLB, 1)+\"]\\\\})}))\";\n MU.SAFEADDTOMAP(SQL,\"SETF\",SETF);\n MU.SAFEADDTOMAP(SQL,\"WHERESTR\",WHERESTR);\n*/', NULL, '20221119170106', '20221119181008', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('5070849DD06E4BEDAF9DF55A5F14CF03', 'SYS_QX_QTQX.getQtxt', 99999, 'SYS_SJGL_APPCONFIG', 'select mc  name,\n       tb  icon,\n       t.*\n  from SYS_QX_QXXX t\n where t.yxx = \'1\'\n   and t.fqx is null and t.dm not in (\'QTQX\')\n   and exists (select jq1.qx\n          from sys_qx_jsqxgl jq1\n         inner join sys_qx_yhjsgl yj1\n            on jq1.js = yj1.js\n         inner join sys_qx_jsxx js1\n            on js1.dm = yj1.js\n         where (yj1.yh = #{user.id} or js1.dm=\'ADMIN_DLYH_LSYH\'\n			 /*if(user.yhdm!=\'lsyh\'){*/\n				or js1.dm=\'ADMIN_DLYH\'\n			 /*}*/\n		 )\n           and js1.yxx = \'1\'\n           and yj1.yxx = \'1\'\n           and jq1.yxx = \'1\'\n           and jq1.qx = t.dm)\n order by px asc', '根据用户获取其有权限的其他系统', NULL, NULL, NULL, '20200908232359', '20220908150905', NULL, NULL, '0', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('5082AE52FF604A1594FA92EFD824D3CD', 'sjdx.jcxx1', 99999, 'SYS_SJGL_APPCONFIG', '//本默认配置优先级最低，用户端传参可以覆盖本配置\n{\n  //原对象，一般是前端的表单数据，与对应表字段对应\n  //\"yobj\": {\n  //},\n  //系统参数\n  \"sys\": {\n    //执行操作;设置执行什么操作，默认getData，可选项：getData获取数据，plcl执行新增修改操作\n    \"zxcz\": \"getdata\",\n		//终端类别\n		\"zdlb\":\"PC\",\n    //请求时清除缓存，默认false，重新加载对象、字段等信息\n    \"clearCache\": false,\n    //事务提交量，主要用于批量上传时，多少条数据提交一次事务，默认5000\n    \"swtjl\": 5000,\n    //数据是否使用缓存，部分功能数据存在缓存会用到，默认true\n    \"dataCache\": true,\n    //物理删除，默认false，配置该数据对象是否允许物理删除\n    \"wlsc\": false\n  },\n  \"cllxkz\": {\n		\"insert\":{\n			//弹窗关闭提示\n			\"tcgbts\":true,\n			//获取基础信息时是否进行根据主键查询库中的记录\n			\"putobj\":true\n		},\n		\"update\":{\n			//弹窗关闭提示\n			\"tcgbts\":true,\n			\"putobj\":true\n		},\n		\"dxjcxx\":{\n			\"tcgbts\":false,\n			\"putobj\":true\n		},\n		\"save\":{\n			\"putobj\":true\n		},\n    \"select\": {\n			//展示查询项数量\n			\"zscxxsl\":6,\n      //饿了么的的按钮\n      \"qxpz\": {\n        //批量处理左侧最大按钮数\n        \"plclLeftZdans\": 7,\n        //批量处理右侧最大按钮数\n        \"plclRightZdans\": 2,\n        \"plclLeft\": {\n          \"bjms\": {\n            \"type\": \"primary\",\n            \"content\": \"编辑模式\",\n            \"buttonOptions\": {\n						  bjqx:true,\n              \"clfs\": \"ymcsth\",\n              \"htqqts\": false,\n              //是否需要选择记录\n              sfxyxzjl: false,\n              \"isshow\": true,\n              \"params\": {\n                \"editCofnig\": {\n                  \"enabled\": true\n                },\n                \"dxjcxx\": {\n                  \"cllxkz\": {\n                    \"select\": {\n                      \"qxpz\": {\n                        \"plclLeft\": {\n//                          \"plbc\": {\n//                            \"buttonOptions\": {\n//                              \"isshow\": true\n//                            }\n//                          },\n                          \"qxbj\": {\n                            \"buttonOptions\": {\n                              \"isshow\": true\n                            }\n                          },\n                          \"bjms\": {\n                            \"buttonOptions\": {\n                              \"isshow\": false\n                            }\n                          }\n                        }\n                      }\n                    }\n                  }\n                }\n              }\n            }\n          },\n          \"qxbj\": {\n            \"type\": \"primary\",\n            \"content\": \"取消编辑\",\n            \"buttonOptions\": {\n						  bjqx:true,\n              \"clfs\": \"ymcsth\",\n              \"htqqts\": false,\n              //是否需要选择记录\n              sfxyxzjl: false,\n              \"isshow\": false,\n              \"params\": {\n                \"editCofnig\": {\n                  \"enabled\": false\n                },\n                \"dxjcxx\": {\n                  \"cllxkz\": {\n                    \"select\": {\n                      \"qxpz\": {\n                        \"plclLeft\": {\n//                          \"plbc\": {\n//                            \"buttonOptions\": {\n//                              \"isshow\": false\n//                            }\n//                          },\n                          \"qxbj\": {\n                            \"buttonOptions\": {\n                              \"isshow\": false\n                            }\n                          },\n                          \"bjms\": {\n                            \"buttonOptions\": {\n                              \"isshow\": true\n                            }\n                          }\n                        }\n                      }\n                    }\n                  }\n                }\n              }\n            }\n          },\n          //            \"plbc\": {\n          //              \"type\": \"primary\",\n          //              \"content\": \"保存\",\n          //              \"buttonOptions\": {\n          //                \"clfs\": \"plbc\",\n          //                \"htqqts\": true,\n          //                //是否需要选择记录\n          //                sfxyxzjl: false,\n          //                \"isshow\": false\n          //              }\n          //            },\n          \"insert\": {\n            \"type\": \"primary\",\n            \"content\": \"新建\",\n            \"buttonOptions\": {\n						  bjqx:true,\n              \"clfs\": \"tcck\",\n              //是否需要选择记录\n              sfxyxzjl: false\n            }\n          },\n          \"plsc\": {\n            \"type\": \"primary\",\n            \"content\": \"批量删除\",\n            \"buttonOptions\": {\n						  bjqx:true,\n              \"clfs\": \"htqq\",\n              \"htqqts\": true,\n              \"params\": {\n                \"sys\": {\n                  \"zxcz\": \"plcl\"\n                }\n              }\n            }\n          },\n          \"dcmb\": {\n            \"type\": \"primary\",\n            \"content\": \"导出模板\",\n            \"buttonOptions\": {\n						  bjqx:true,\n              \"clfs\": \"download\",\n              \"htqqts\": false,\n              //是否需要选择记录\n              sfxyxzjl: false,\n							sfsxym:false\n            }\n          },\n          \"sjplsc\": {\n            \"type\": \"primary\",\n            \"content\": \"批量上传\",\n            \"buttonOptions\": {\n						  bjqx:true,\n              \"clfs\": \"upload\",\n              \"htqqts\": false,\n              //是否需要选择记录\n              sfxyxzjl: false,\n							//上传后请求\n							schqq: true\n            }\n          },\n          \"fzjl\": {\n            \"type\": \"primary\",\n            \"content\": \"复制\",\n            \"buttonOptions\": {\n						  bjqx:true,\n              \"clfs\": \"htqq\",\n              \"htqqts\": true,\n              \"params\": {\n                \"sys\": {\n                  \"zxcz\": \"plcl\"\n                }\n              }\n            }\n          },\n          \"pzdx\": {\n            \"type\": \"primary\",\n            \"content\": \"对象配置\",\n            \"buttonOptions\": {\n              \"clfs\": \"tcck\",\n              \"tcqp\": true,\n              //是否需要选择记录\n              sfxyxzjl: false,\n              \"dxjcxx\": {\n                \"sjdx\": {\n                  \"dxdm\": \"SYS_SJGL_SJDX\"\n                },\n                \"sys\": {\n                  \"cllx\": \"update\"\n                }\n              },\n              //基础信息扩展，可以把当前页面参数取出来设置到dxjcxx中\n              \"jcxxkz\": {\n                //<设置到obj中的key，从myData中取的只路径>\n                \"obj\": \"dxjcxx.sjdx\"\n              }\n            }\n          },\n          \"pzzd\": {\n            \"type\": \"primary\",\n            \"content\": \"字段配置\",\n            \"buttonOptions\": {\n              \"clfs\": \"tcck\",\n              //是否需要选择记录\n              sfxyxzjl: false,\n              tcqp: true,\n              \"dxjcxx\": {\n                \"sjdx\": {\n                  \"dxdm\": \"SYS_SJGL_SJZD\"\n                },\n                \"sys\": {\n                  \"cllx\": \"select\"\n                }\n              },\n              //基础信息扩展，可以把当前页面参数取出来设置到dxjcxx中\n              \"jcxxkz\": {\n                //<设置到obj中的key，从myData中取的只路径>\n                \"fields.sjdx.cxmrz\": \"dxjcxx.sjdx.id\"\n              }\n            }\n          }\n        },\n        \"plclRight\": {\n          \"dcdqysj\": {\n            \"content\": \"导出当前页\",\n            \"buttonOptions\": {\n              \"clfs\": \"download\",\n              sfxyxzjl: false,\n							sfsxym:false\n            }\n          },\n          \"dcsj\": {\n            \"content\": \"导出全部\",\n            \"buttonOptions\": {\n              \"clfs\": \"download\",\n              sfxyxzjl: false,\n							sfsxym:false,\n							//允许分页导出全部，否则只允许导出第一页\n							\"yxfydc\": false,\n              \"params\": {\n                \"page\": {\n                  //默认导出50000条记录\n                  \"pageSize\": 5000,\n                  //导出全部默认只允许导出第一页\n                  \"pageNumber\": 1\n                }\n              }\n            }\n          }\n        }\n      }\n    }\n  },\n  //分页对象\n  \"page\": {\n    //是否进行总数统计\n    \"totalRequired\": true,\n    //是否进行列表查询\n    \"listRequired\": true,\n    //查询页号\n    \"pageNumber\": 1,\n    //页大小\n    \"pageSize\": 10\n  },\n  //对象的字段信息，可以在对象中配置字段，但一般不这么做，专门的字段配置优先级最高，全局配置文件中可以配置所有对象的通用字段\n  \"fields\": {\n		\"myPlcz\":{\n			\"zdmc\":\"批量操作\",\n			\"zdywlb\":\"plcz,99\",\n			\"dcmrbtys\":\"RED\",\n			\"tails\":{\n				\"xxxx\":\"xxxx\"\n			}\n		},\n    //查询列表\n    \"myList\": {\n      \"zddm\": \"myList\",\n      \"px\": 1,\n      \"zdywlb\": \"99\",\n      \"kjlx\": \"MySelectGrid\",\n			yxbj:\"1\",\n      \"kzxxObj\": {\n        \"cllxkz\": {\n          \"select\": {\n            \"show\": true,\n            \"zdkd\": 12424,\n	    csbjzt: false\n          }\n        },\n        \"kjkz\":{\n          \"title\":\"\"\n        }\n      }\n    },\n    //列表选择\n    \"myLbxz\": {\n      \"zddm\": \"myLbxz\",\n      \"px\": 2,\n      \"zdkd\": 50,\n      \"zdywlb\": \"99\",\n      \"kjlx\": \"checkbox\",\n      \"lbzs\": \"1\",\n      \"kzxxObj\": {\n        \"kjkz\": {\n          \"title\":\"\"\n        }\n      }\n    },\n    //列表序号\n    \"myLbxh\": {\n      \"zddm\": \"myLbxh\",\n      \"px\": 3,\n      \"zdkd\": 60,\n      \"zdmc\": \"序号\",\n      \"zdywlb\": \"99\",\n      \"kjlx\": \"seq\",\n      \"lbzs\": \"1\",\n      \"kzxxObj\": {\n        \"kjkz\": {\n          \"treeNode\": false\n        }\n      }\n    },\n    //列表操作\n    \"myLbcz\": {\n      \"zddm\": \"myLbcz\",\n      \"px\": 5000,\n      \"zdkd\": 165,\n      \"zdmc\": \"操作\",\n      \"zdywlb\": \"99\",\n      \"kjlx\": \"$buttons\",\n      \"lbzs\": \"1\",\n      \"kzxxObj\": {\n			  \"cllxkz\":{\n				  \"update\":{\n					  \"disabled\": true\n					}\n				},\n        \"kjkz\": {\n          \"fixed\": \"right\",\n          \"zdans\": 3,\n          //vxe的按钮\n          \"btns\": {\n            \"update\": {\n              \"type\": \"text\",\n              \"content\": \"编辑\",\n              \"status\": \"primary\",\n              \"buttonOptions\": {\n						  	bjqx:true,\n                \"clfs\": \"tcck\"\n              }\n            },\n            \"delete\": {\n              \"type\": \"text\",\n              \"content\": \"删除\",\n              \"status\": \"primary\",\n              \"buttonOptions\": {\n						  	bjqx:true,\n                \"clfs\": \"htqq\",\n                \"htqqts\": true\n              }\n            },\n            \"dxjcxx\": {\n              \"type\": \"text\",\n              \"content\": \"详情\",\n              \"status\": \"primary\",\n              \"buttonOptions\": {\n                \"clfs\": \"tcck\"\n              }\n            },\n            \"fzjl\": {\n							\"px\":9999,\n              \"type\": \"text\",\n              \"status\": \"primary\",\n              \"content\": \"复制\",\n              \"buttonOptions\": {\n						  	bjqx:true,\n                \"clfs\": \"htqq\",\n                \"htqqts\": true,\n                \"params\": {\n                  \"sys\": {\n                    \"zxcz\": \"plcl\"\n                  }\n                }\n              }\n            }\n          }\n        }\n      }\n    },\n    //查询按钮字段\n    \"myCxan\": {\n      \"zddm\": \"myCxan\",\n      \"px\": 50000,\n      \"zdywlb\": \"99\",\n      \"cxzs\": \"1\",\n      \"kjlx\": \"$buttons\",\n      \"kzxxObj\": {\n        \"cllxkz\": {\n        },\n        \"kjkz\": {\n          \"title\":\"\",\n          \"align\": \"right\",\n          \"span\": 24,\n					\"collapseNode\": true,\n          //vxe的按钮\n          \"btns\": {\n            \"cxan\": {\n              \"type\": \"submit\",\n              \"content\": \"查询\",\n              \"status\": \"primary\",\n              \"buttonOptions\": {\n\n              }\n            }\n          }\n        }\n      }\n    },\n    //新建按钮字段\n    \"myXjan\": {\n      \"zddm\": \"myXjan\",\n      \"px\": 50000,\n      \"zdywlb\": \"99\",\n      \"kjlx\": \"$buttons\",\n      \"kzxxObj\": {\n        \"cllxkz\": {\n          \"insert\": {\n            \"show\": true\n          }\n        },\n        \"kjkz\": {\n				  //操作按钮沾在下方\n          \"className\":\"modalStickyBottom\",\n          \"title\":\"\",\n          \"align\": \"center\",\n          \"span\": 24,\n          //vxe的按钮\n          \"btns\": {\n            \"insert\": {\n              \"type\": \"button\",\n              \"content\": \"提交\",\n              \"status\": \"primary\",\n              \"buttonOptions\": {\n                \"htqqts\": false,\n                \"sfgbtc\": true\n              }\n            },\n            \"gb\": {\n              \"type\": \"button\",\n              \"content\": \"关闭\",\n              \"buttonOptions\": {\n                \"clfs\": \"gbtc\",\n                \"sfjybd\": false,\n                \"sfsxym\": false,\n								\"htqqts\":true\n              }\n            }\n          }\n        }\n      }\n    },\n    //编辑按钮字段\n    \"myBjan\": {\n      \"zddm\": \"myBjan\",\n      \"px\": 50000,\n      \"zdywlb\": \"99\",\n      \"kjlx\": \"$buttons\",\n      \"kzxxObj\": {\n        \"cllxkz\": {\n          \"update\": {\n            \"show\": true\n          }\n        },\n        \"kjkz\": {\n				  //操作按钮沾在下发\n          \"className\":\"modalStickyBottom\",\n          \"title\":\"\",\n          \"align\": \"center\",\n          \"span\": 24,\n          //vxe的按钮\n          \"btns\": {\n            \"update\": {\n              \"type\": \"button\",\n              \"content\": \"提交\",\n              \"status\": \"primary\",\n              \"buttonOptions\": {\n                \"htqqts\": false,\n                \"sfgbtc\": true\n              }\n            },\n            \"gb\": {\n              \"type\": \"button\",\n              \"content\": \"关闭\",\n              \"buttonOptions\": {\n                \"clfs\": \"gbtc\",\n                \"sfjybd\": false,\n                \"sfsxym\": false,\n								\"htqqts\":true\n              }\n            }\n          }\n        }\n      }\n    },\n    //详情按钮字段\n    \"myXqan\": {\n      \"zddm\": \"myXqan\",\n      \"px\": 50000,\n      \"zdywlb\": \"99\",\n      \"kjlx\": \"$buttons\",\n      \"kzxxObj\": {\n        \"cllxkz\": {\n          \"dxjcxx\": {\n            \"show\": true\n          }\n        },\n        \"kjkz\": {\n				  //操作按钮沾在下发\n          \"className\":\"modalStickyBottom\",\n          \"title\":\"\",\n          \"align\": \"center\",\n          \"span\": 24,\n          //vxe的按钮\n          \"btns\": {\n            \"gb\": {\n              \"type\": \"button\",\n              \"content\": \"关闭\",\n              \"buttonOptions\": {\n                \"clfs\": \"gbtc\",\n                \"sfjybd\": false,\n                \"sfsxym\": false\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n}', '数据对象的基础信息1，优先级最低', '//BMRPZYXJZD，YHDCCKYFGBPZ\n{\n  //YDX，YBSQDDBDSJ，YDYBZDDY\n  //\"YOBJ\": {\n  //},\n  //XTCS\n  \"SYS\": {\n    //ZXCZ;SZZXSMCZ，MRGETDATA，KXX：GETDATAHQSJ，PLCLZXXZXGCZ\n    \"ZXCZ\": \"GETDATA\",\n		//ZDLB\n		\"ZDLB\":\"PC\",\n    //QQSQCHC，MRFALSE，CXJZDX、ZDDXX\n    \"CLEARCACHE\": FALSE,\n    //SWTJL，ZYYYPLSCS，DSTSJTJYCSW，MR5000\n    \"SWTJL\": 5000,\n    //SJSFSYHC，BFGNSJCZHCHYD，MRTRUE\n    \"DATACA', '//BENMORENPEIZHIYOUXIANJIZUIDI，YONGHUDUANCHUANCANKEYIFUGAIBENPEIZHI\n{\n  //YUANDUIXIANG，YIBANSHIQIANDUANDEBIAODANSHUJU，YUDUIYINGBIAOZIDUANDUIYING\n  //\"YOBJ\": {\n  //},\n  //XITONGCANSHU\n  \"SYS\": {\n    //ZHIXINGCAOZUO;SHEZHIZHIXINGSHENMECAOZUO，MORENGETDATA，KEXUANXIANG：GETDATAHUOQUSHUJU，PLCLZHIXINGXINZENGXIUGAICAOZUO\n    \"ZXCZ\": \"GETDATA\",\n		//ZHONGDUANLEIBIE\n		\"ZDLB\":\"PC\",\n    //QINGQIUS', NULL, '20220108190716', '20240131150850', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('5587192DE15E494B9FD43962AC7D1F7D', 'SHRMYY_HLB_ZLJCX.update', 99999, 'SYS_SJGL_APPCONFIG', '/*\nvar setf = ;\nif(su.isNotBlank(sjdx.zlzd)){\n    setf = setf+,+sjdx.zlzd+=to_char(sysdate,\'yyyymmddhh24miss\');\n}\nvar whereStr = sjdx.zjzd+\"=#{yobj.\"+sjdx.zddmZjzd+\"}\";\n//循环生成字段\nfor(field in fieldList){\n     if(yobj[field.zddm]!=null&&field.zddm!=sjdx.zjzd&&99!=field.zdywlb){\n          if(field.kjlx==\'password\'){\n             setf = setf+,+field.zddm+=\'+su.desEnByField(yobj[field.zddm],field)+\';\n          }else{\n             setf = setf+,+field.zddm+=#yobj.+field.zddm+#;\n          }\n     }\n }\n if(!isEmpty(kzxx.fields.sszzd)&&!isEmpty(yobj[kzxx.fields.sszzd.zddm])){\n     //设置简拼和全拼\n     if(!isEmpty(kzxx.fields.pyjp)&&su.length(yobj[kzxx.fields.sszzd.zddm])<200){\n          setf = setf+,+kzxx.fields.pyjp.zddm+=#yobj.pyjp#;\n          mu.safeAddToMap(yobj,pyjp,su.getSimpleSpell(yobj[kzxx.fields.sszzd.zddm]));\n     }\n     if(!isEmpty(kzxx.fields.pyqp)&&su.length(yobj[kzxx.fields.sszzd.zddm])<200){\n          setf = setf+,+kzxx.fields.pyqp.zddm+=#yobj.pyqp#;\n          mu.safeAddToMap(yobj,pyqp,su.getFullSpell(yobj[kzxx.fields.sszzd.zddm]));\n     }\n }\n setf = su.substring(setf, 1);\n\n//新增\nvar insertf = ;\nvar values = ;\n//循环生成字段\nfor(field in fieldList){\n     if(!isEmpty(yobj[field.zddm])&&99!=field.zdywlb&&field.zddm!=\'z_id\'){\n          insertf = insertf+,+field.zddm;\n          if(field.kjlx==\'password\'){\n             values = values+,\'+su.desEnByField(yobj[field.zddm],field)+\';\n          }else{\n             values = values+,#yobj.+field.zddm+#;\n          }\n     }\n}\nif(!isEmpty(kzxx.fields.sszzd)&&!isEmpty(yobj[kzxx.fields.sszzd.zddm])){\n     //设置简拼和全拼\n     if(!isEmpty(kzxx.fields.pyjp)&&su.length(yobj[kzxx.fields.sszzd.zddm])<200){\n          insertf = insertf+,+kzxx.fields.pyjp.zddm;\n          values = values+,#yobj.pyjp#;\n          mu.safeAddToMap(yobj,pyjp,su.getSimpleSpell(yobj[kzxx.fields.sszzd.zddm]));\n     }\n     if(!isEmpty(kzxx.fields.pyqp)&&su.length(yobj[kzxx.fields.sszzd.zddm])<200){\n          insertf = insertf+,+kzxx.fields.pyqp.zddm;\n          values = values+,#yobj.pyqp#;\n          mu.safeAddToMap(yobj,pyqp,su.getFullSpell(yobj[kzxx.fields.sszzd.zddm]));\n     }\n}\nif(!isEmpty(kzxx.fields.cjrdm)){\n    insertf = insertf+,+kzxx.fields.cjrdm.zddm;\n    values = values+,#user.id#;\n}\nif(!isEmpty(kzxx.fields.cjrxm)){\n    insertf = insertf+,+kzxx.fields.cjrxm.zddm;\n    values = values+,#user.yhxm#;\n}\nif(!isEmpty(kzxx.fields.cjrdwdm)){\n    insertf = insertf+,+kzxx.fields.cjrdwdm.zddm;\n    values = values+,#user.jgxx.id#;\n}\nif(!isEmpty(kzxx.fields.cjrdwmc)){\n    insertf = insertf+,+kzxx.fields.cjrdwmc.zddm;\n    values = values+,#user.jgxx.jgmc#;\n}\ninsertf = su.substring(insertf, 1);\nvalues = su.substring(values, 1);\n mu.safeAddToMap(obj,insertf,insertf);\n mu.safeAddToMap(obj,values,values);\n*/\n/*if(isEmpty(obj.cjsj)){*/\ninsert into \nSHRMYY_HLB_ZLJCX\n  (${insertf})\nvalues\n  (${values})\n/*}else{*/\nupdate SHRMYY_HLB_ZLJCX\n   set ${setf}\n where id=#yobj.id#\n/*}*/', NULL, '/*\nVAR SETF = ;\nIF(SU.ISNOTBLANK(SJDX.ZLZD)){\n    SETF = SETF+,+SJDX.ZLZD+=TO_CHAR(SYSDATE,\'YYYYMMDDHH24MISS\');\n}\nVAR WHERESTR = SJDX.ZJZD+\"=#{YOBJ.\"+SJDX.ZDDMZJZD+\"}\";\n//XHSCZD\nFOR(FIELD IN FIELDLIST){\n     IF(YOBJ[FIELD.ZDDM]!=NULL&&FIELD.ZDDM!=SJDX.ZJZD&&99!=FIELD.ZDYWLB){\n          IF(FIELD.KJLX==\'PASSWORD\'){\n             SETF = SETF+,+FIELD.ZDDM+=\'+SU.DESENBYFIELD(YOBJ[FIELD.ZDDM],FIELD)+\';\n ', '/*\nVAR SETF = ;\nIF(SU.ISNOTBLANK(SJDX.ZLZD)){\n    SETF = SETF+,+SJDX.ZLZD+=TO_CHAR(SYSDATE,\'YYYYMMDDHH24MISS\');\n}\nVAR WHERESTR = SJDX.ZJZD+\"=#{YOBJ.\"+SJDX.ZDDMZJZD+\"}\";\n//XUNHUANSHENGCHENGZIDUAN\nFOR(FIELD IN FIELDLIST){\n     IF(YOBJ[FIELD.ZDDM]!=NULL&&FIELD.ZDDM!=SJDX.ZJZD&&99!=FIELD.ZDYWLB){\n          IF(FIELD.KJLX==\'PASSWORD\'){\n             SETF = SETF+,+FIELD.ZDDM+=\'+SU.DESENBYFIELD(YOBJ[FIELD.', NULL, '20210330172518', '20240523154226', NULL, NULL, '1', '系统管理员', 'sys', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '3');
INSERT INTO `sys_sjgl_dzd` VALUES ('566999ab568d11ed841e000c29f304ac', 'SYS_PTGL_XTXX.swyd', 99999, 'SYS_SJGL_APPCONFIG', 'update ${sql.from} t set ydzt=\'1\'\n/*if(su.isNotBlank(sjdx.zlzd)){*/\n    ,t.${sjdx.zlzd}=#{globalUse(\"util.expDate14\")}\n/*}*/\n-- @ where(){\n/*if(!isEmpty(sys.ids)){*/\nand t.${sjdx.zjzd} in (#{join(sys.ids)})\n/*}else if(!isEmpty(sql.whereStr)){*/\n${sql.whereStr} ${sql.authWhere} \n/*}else{*/\nand 1=2\n/*}*/\n-- @ }', '系统消息-设为已读', 'UPDATE ${SQL.FROM} T SET YDZT=\'1\'\n/*IF(SU.ISNOTBLANK(SJDX.ZLZD)){*/\n    ,T.${SJDX.ZLZD}=#{GLOBALUSE(\"UTIL.EXPDATE14\")}\n/*}*/\n-- @ WHERE(){\n/*IF(!ISEMPTY(SYS.IDS)){*/\nAND T.${SJDX.ZJZD} IN (#{JOIN(SYS.IDS)})\n/*}ELSE IF(!ISEMPTY(SQL.WHERESTR)){*/\n${SQL.WHERESTR} ${SQL.AUTHWHERE} \n/*}ELSE{*/\nAND 1=2\n/*}*/\n-- @ }', 'UPDATE ${SQL.FROM} T SET YDZT=\'1\'\n/*IF(SU.ISNOTBLANK(SJDX.ZLZD)){*/\n    ,T.${SJDX.ZLZD}=#{GLOBALUSE(\"UTIL.EXPDATE14\")}\n/*}*/\n-- @ WHERE(){\n/*IF(!ISEMPTY(SYS.IDS)){*/\nAND T.${SJDX.ZJZD} IN (#{JOIN(SYS.IDS)})\n/*}ELSE IF(!ISEMPTY(SQL.WHERESTR)){*/\n${SQL.WHERESTR} ${SQL.AUTHWHERE} \n/*}ELSE{*/\nAND 1=2\n/*}*/\n-- @ }', NULL, '20221028145415', '20221028151438', NULL, NULL, '1', '系统管理员', 'sys', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('56868B56D9FA4BF5B3774C7EA3AD9D3F', 'SYS_PLBD_HM_QYMP.hqcxx', 99999, 'SYS_SJGL_APPCONFIG', 'select zd.* from sys_sjgl_sjzd zd\nwhere zd.cxzs=\'1\' and zd.yxx=\'1\' and zd.sjdx=#{yobj.sjdx};ds=default', NULL, 'SELECT ZD.* FROM SYS_SJGL_SJZD ZD\nWHERE ZD.CXZS=\'1\' AND ZD.YXX=\'1\' AND ZD.SJDX=#YOBJ.SJDX#;DS=DEFAULT', 'SELECT ZD.* FROM SYS_SJGL_SJZD ZD\nWHERE ZD.CXZS=\'1\' AND ZD.YXX=\'1\' AND ZD.SJDX=#YOBJ.SJDX#;DS=DEFAULT', NULL, '20200616103555', '20200617115120', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('62E2E7F180A14F2D8E5BA66E30637138', 'SYS_ZNBK_JG.plqs', 99999, 'SYS_SJGL_APPCONFIG', 'update SYS_BDHC_JG set qssj=to_char(sysdate,\'yyyymmddhh24miss\') ,zlzt=\'1\',\nqsrxm = #{user.yhxm},qsrdm=#{user.id},qsrdwdm=#{user.jgxx.id},qsrdwmc=#{user.jgxx.jgmc},\n${sjdx.zlzd}=to_char(sysdate,\'yyyymmddhh24miss\') where ${sjdx.zjzd} ${idsIn} and zlzt=\'0\'', NULL, NULL, NULL, NULL, '20210723102411', '20210723103210', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('6426671615C948A7B8E81738A09A9242', 'DEFAULT.dis.mysql', 99999, 'SYS_SJGL_APPCONFIG', 'select a.COLUMN_NAME zddm,\na.COLUMN_COMMENT zdms,\na.TABLE_NAME,\na.DATA_TYPE zdlx,\nCASE \n	WHEN a.DATA_TYPE=\'varchar\' THEN\n		a.CHARACTER_MAXIMUM_LENGTH\n	ELSE\n		null\nEND zdcd,\nCASE \n	WHEN a.COLUMN_DEFAULT=\'date_format(now(),_utf8mb4\\\\\\\'%Y%m%d%H%i%S\\\\\\\')\' THEN\n		\'to_char(sysdate,\\\'yyyymmddhh24miss\\\')\'\n	WHEN a.COLUMN_DEFAULT=\'replace(uuid(),_utf8mb4\\\\\\\'-\\\\\\\',_utf8mb4\\\\\\\'\\\\\\\')\' THEN\n		\'sys_guid() \'\n	WHEN a.COLUMN_DEFAULT is not null THEN\n		a.COLUMN_DEFAULT\n	ELSE\n		null\nEND xzmrz\n  from information_schema.COLUMNS a\n where a.table_name = \'${yobj.jtdx}\'\n      /* if(!isEmpty(yobj.dxgs)){*/\n   and a.TABLE_SCHEMA = \'${yobj.dxgs}\'\n/* }else  if(!isEmpty(yobj.sjztObj.dxgs)){*/\n   and a.TABLE_SCHEMA = \'${yobj.sjztObj.dxgs}\'\n/* }*/', '数据对象-默认导入sql-mysql', 'SELECT A.COLUMN_NAME ZDDM,\nA.COLUMN_COMMENT ZDMS,\nA.TABLE_NAME,\nA.DATA_TYPE ZDLX,\nCASE \n	WHEN A.DATA_TYPE=\'VARCHAR\' THEN\n		A.CHARACTER_MAXIMUM_LENGTH\n	ELSE\n		NULL\nEND ZDCD,\nCASE \n	WHEN A.COLUMN_DEFAULT=\'DATE_FORMAT(NOW(),_UTF8MB4\\\\\\\'%Y%M%D%H%I%S\\\\\\\')\' THEN\n		\'TO_CHAR(SYSDATE,\\\'YYYYMMDDHH24MISS\\\')\'\n	WHEN A.COLUMN_DEFAULT=\'REPLACE(UUID(),_UTF8MB4\\\\\\\'-\\\\\\\',_UTF8MB4\\\\\\\'\\\\\\\')\' THEN\n		\'SYS_GUID() \'\n	WHE', 'SELECT A.COLUMN_NAME ZDDM,\nA.COLUMN_COMMENT ZDMS,\nA.TABLE_NAME,\nA.DATA_TYPE ZDLX,\nCASE \n	WHEN A.DATA_TYPE=\'VARCHAR\' THEN\n		A.CHARACTER_MAXIMUM_LENGTH\n	ELSE\n		NULL\nEND ZDCD,\nCASE \n	WHEN A.COLUMN_DEFAULT=\'DATE_FORMAT(NOW(),_UTF8MB4\\\\\\\'%Y%M%D%H%I%S\\\\\\\')\' THEN\n		\'TO_CHAR(SYSDATE,\\\'YYYYMMDDHH24MISS\\\')\'\n	WHEN A.COLUMN_DEFAULT=\'REPLACE(UUID(),_UTF8MB4\\\\\\\'-\\\\\\\',_UTF8MB4\\\\\\\'\\\\\\\')\' THEN\n		\'SYS_GUID() \'\n	WHE', NULL, '20200223114805', '20221005155932', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('6474db01029111ee8ef3000c29f304ac', 'SYS_QX_QXXX.cds.mysql', 99999, 'SYS_SJGL_APPCONFIG', 'SELECT\n  t.id,\n	t.mc NAME,\n	t.tb icon,\n	t.tptb,\n	t.mc,\n	t.dm,\n	t.ms,\n	t.DZLX,\n	t.DKFS,\n	t.FQX,\n	t.KZXX,\n	t.LX,\n	( CASE  WHEN t.dzlx=\'05\' THEN  #{globalUse(\'util.expConcatWs\',{\"list\":[\"app.dz\",\"t.dz\"]\\})} ELSE t.dz END) dz,\n/*if(!isEmpty(yobj.dqjs)){*/\n	(\n	SELECT\n		count( 1 ) \n	FROM\n		sys_qx_jsqxgl jq\n		INNER JOIN sys_qx_jsxx js ON js.id = jq.js \n	WHERE\n		js.id = #{yobj.dqjs}\n		\n		AND js.yxx = \'1\' \n		AND jq.yxx = \'1\' \n		AND jq.qx = t.id \n	) checked,\n/*}*/\n	(\n	SELECT\n		count( 1 ) \n	FROM\n		SYS_QX_QXXX t1 \n	WHERE\n		t1.yxx = \'1\' \n		AND t1.fqx = t.id \n		/*if(yobj.treeModel==\'cds\'){*/\n		AND t1.lx != \'03\' \n		/*}*/\n		\n	) parent ,\n  dx.dxdm\nFROM\n	SYS_QX_QXXX t\n	LEFT JOIN sys_qx_app app ON app.dm = t.SSYY \n	left join sys_sjgl_sjdx dx on dx.id = t.sjdx\nWHERE\n	t.yxx = \'1\' \n	-- @if(sys.zdlb!=\"PC\"){\n	  and t.zcsjd = \'1\'\n	-- @}\n	/*if(!isEmpty(yobj.fqx)){*/\n	AND (t.dm LIKE #{yobj.fqx+\"\\\\_%\"} or t.dm = #{yobj.fqx})\n/*}else if(!isEmpty(yobj.treeRoot)){*/\n	AND (t.dm LIKE #{yobj.treeRoot+\"\\\\_%\"} or t.dm = #{yobj.treeRoot})\n/*}else{*/\n			AND t.fqx IS NULL \n			/*}*/\n/*if(yobj.treeModel==\'cds\'){*/\n			AND (t.lx != \'03\' or t.dz is not null)\n/*}*/\n/*if(yobj.treeModel==\'cds\'){*/\n			AND EXISTS (\n			SELECT\n				qx.dm \n			FROM\n				sys_qx_qxxx qx\n				INNER JOIN sys_qx_jsqxgl jq ON qx.id = jq.qx \n				AND jq.yxx = \'1\'\n				INNER JOIN sys_qx_jsxx js ON js.id = jq.js \n				AND js.yxx = \'1\' \n			WHERE\n				qx.yxx = \'1\' \n				AND ( js.dm IN ( \'ADMIN_DLYH_LSYH\' \n-- @if(user.yhdm != \'lsyh\') {\n						, \'ADMIN_DLYH\' \n-- @}\n						) \n-- @for(e in user.jsMap) {\n					OR js.dm LIKE #{e.key+\"%\"}\n-- @}\n				) \n			AND qx.id = t.id \n	) \n/*}*/\n order by t.px asc', '获取菜单树的全部数据，然后代码中组建为树形结构', 'SELECT\n  T.ID,\n	T.MC NAME,\n	T.TB ICON,\n	T.TPTB,\n	T.MC,\n	T.DM,\n	T.MS,\n	T.DZLX,\n	T.DKFS,\n	T.FQX,\n	T.KZXX,\n	T.LX,\n	( CASE  WHEN T.DZLX=\'05\' THEN  #{GLOBALUSE(\'UTIL.EXPCONCATWS\',{\"LIST\":[\"APP.DZ\",\"T.DZ\"]\\})} ELSE T.DZ END) DZ,\n/*IF(!ISEMPTY(YOBJ.DQJS)){*/\n	(\n	SELECT\n		COUNT( 1 ) \n	FROM\n		SYS_QX_JSQXGL JQ\n		INNER JOIN SYS_QX_JSXX JS ON JS.ID = JQ.JS \n	WHERE\n		JS.ID = #{YOBJ.DQJS}\n		\n		AND JS.YXX = \'1\' ', 'SELECT\n  T.ID,\n	T.MC NAME,\n	T.TB ICON,\n	T.TPTB,\n	T.MC,\n	T.DM,\n	T.MS,\n	T.DZLX,\n	T.DKFS,\n	T.FQX,\n	T.KZXX,\n	T.LX,\n	( CASE  WHEN T.DZLX=\'05\' THEN  #{GLOBALUSE(\'UTIL.EXPCONCATWS\',{\"LIST\":[\"APP.DZ\",\"T.DZ\"]\\})} ELSE T.DZ END) DZ,\n/*IF(!ISEMPTY(YOBJ.DQJS)){*/\n	(\n	SELECT\n		COUNT( 1 ) \n	FROM\n		SYS_QX_JSQXGL JQ\n		INNER JOIN SYS_QX_JSXX JS ON JS.ID = JQ.JS \n	WHERE\n		JS.ID = #{YOBJ.DQJS}\n		\n		AND JS.YXX = \'1\' ', NULL, '20230604123637', '20231009153528', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('6B1549046CF442729ED5ACFA2CB5B39F', 'SYS_SJGL_FILE.wjsc', 99999, 'SYS_COMMON_APPCONFIG', 'error:上传成功', NULL, 'ERROR:SCCG', 'ERROR:SHANGCHUANCHENGGONG', NULL, '20211205153113', '20211205153354', NULL, NULL, '0', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('6C8A1E7F58E7447CA324E6BF5C45F307', 'zd.KETTLE_DEFAULT_JOB.mysql', 99999, 'SYS_SJGL_APPCONFIG', 'select id_job dm,\n       #{globalUse(\'util.expConcatWs\',{\'list\':[\'name\',\"\'[\'\",\'t.description\',\"\']\'\"]\\})} as mc,\n       id_job px,\n       t.extended_description as search_key\n  from r_job t;ds=kettle_default', NULL, NULL, 'SELECT ID_JOB DM,\n       #{GLOBALUSE(\'UTIL.EXPCONCATWS\',{\'LIST\':[\'NAME\',\"\'[\'\",\'T.DESCRIPTION\',\"\']\'\"]\\})} AS MC,\n       ID_JOB PX,\n       T.EXTENDED_DESCRIPTION AS SEARCH_KEY\n  FROM R_JOB T;DS=KETTLE_DEFAULT', NULL, '20230520181931', '20230520181948', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('6ca316e523dc11ef9bde000c29f304ac', 'zd.SYS_YXJK_JKRW.mysql', 99999, 'SYS_SJGL_APPCONFIG', 'select id dm,\n       CONCAT((case\n         when rwlx = \'3\' then\n          CONCAT((select dxmc\n             from sys_sjgl_sjdx tt\n            where substr(jtrw, 1, instr(jtrw, \'#\') - 1) = tt.dxdm), \'-\')\n         else\n          \'\'\n       end), rw.rwmc) as mc,\n       px,\n       \'\' as search_key\n  from sys_yxjk_jkrw rw\n where rw.yxx = \'1\'', NULL, 'SELECT ID DM,\n       CONCAT((CASE\n         WHEN RWLX = \'3\' THEN\n          CONCAT((SELECT DXMC\n             FROM SYS_SJGL_SJDX TT\n            WHERE SUBSTR(JTRW, 1, INSTR(JTRW, \'#\') - 1) = TT.DXDM), \'-\')\n         ELSE\n          \'\'\n       END), RW.RWMC) AS MC,\n       PX,\n       \'\' AS SEARCH_KEY\n  FROM SYS_YXJK_JKRW RW\n WHERE RW.YXX = \'1\'', 'SELECT ID DM,\n       CONCAT((CASE\n         WHEN RWLX = \'3\' THEN\n          CONCAT((SELECT DXMC\n             FROM SYS_SJGL_SJDX TT\n            WHERE SUBSTR(JTRW, 1, INSTR(JTRW, \'#\') - 1) = TT.DXDM), \'-\')\n         ELSE\n          \'\'\n       END), RW.RWMC) AS MC,\n       PX,\n       \'\' AS SEARCH_KEY\n  FROM SYS_YXJK_JKRW RW\n WHERE RW.YXX = \'1\'', NULL, '20240606161149', '20240606161321', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('6E3B2146A76B40CD95509CA63AC7FEB3', 'SYS_SJGL_SJZT.scjkrw', 99999, 'SYS_SJGL_APPCONFIG', 'select id jtrw,dm rwdm,mc rwmc,\'1\' rwlx,\'99\' rwlb,\'1\' rwdj \n   from sys_sjgl_sjzt t \n   where 1=1 \n   /*if (!isEmpty(sys.ids)){*/\n   	and t.id in (#{join(sys.ids)})\n   /*}*/', NULL, 'SELECT ID JTRW,DM RWDM,MC RWMC,\'1\' RWLX,\'99\' RWLB,\'1\' RWDJ \n   FROM SYS_SJGL_SJZT T \n   WHERE 1=1 \n   /*IF (!ISEMPTY(SYS.IDS)){*/\n   	AND T.ID IN (#{JOIN(SYS.IDS)})\n   /*}*/', 'SELECT ID JTRW,DM RWDM,MC RWMC,\'1\' RWLX,\'99\' RWLB,\'1\' RWDJ \n   FROM SYS_SJGL_SJZT T \n   WHERE 1=1 \n   /*IF (!ISEMPTY(SYS.IDS)){*/\n   	AND T.ID IN (#{JOIN(SYS.IDS)})\n   /*}*/', NULL, '20190925180744', '20211205140426', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('7424B94C94E7410988BB77B241C8F679', 'DEFAULT.swwx', 99999, 'SYS_SJGL_APPCONFIG', 'update ${sql.from} t set ${sjdx.yxxzd}=\'0\'\n/*if(su.isNotBlank(sjdx.zlzd)){*/\n    ,t.${sjdx.zlzd}=#{globalUse(\"util.expDate14\")}\n/*}*/\n-- @ where(){\n/*if(!isEmpty(sys.ids)){*/\nand t.${sjdx.zjzd} in (#{join(sys.ids)})\n/*}else if(!isEmpty(sql.whereStr)){*/\n${sql.whereStr} ${sql.authWhere} \n/*}else{*/\nand 1=2\n/*}*/\n-- @ }', NULL, 'UPDATE ${SQL.FROM} T SET ${SJDX.YXXZD}=\'0\'\n/*IF(SU.ISNOTBLANK(SJDX.ZLZD)){*/\n    ,T.${SJDX.ZLZD}=#{GLOBALUSE(\"UTIL.EXPDATE14\")}\n/*}*/\n-- @ WHERE(){\n/*IF(!ISEMPTY(SYS.IDS)){*/\nAND T.${SJDX.ZJZD} IN (#{JOIN(SYS.IDS)})\n/*}ELSE IF(!ISEMPTY(SQL.WHERESTR)){*/\n${SQL.WHERESTR} ${SQL.AUTHWHERE} \n/*}ELSE{*/\nAND 1=2\n/*}*/\n-- @ }', 'UPDATE ${SQL.FROM} T SET ${SJDX.YXXZD}=\'0\'\n/*IF(SU.ISNOTBLANK(SJDX.ZLZD)){*/\n    ,T.${SJDX.ZLZD}=#{GLOBALUSE(\"UTIL.EXPDATE14\")}\n/*}*/\n-- @ WHERE(){\n/*IF(!ISEMPTY(SYS.IDS)){*/\nAND T.${SJDX.ZJZD} IN (#{JOIN(SYS.IDS)})\n/*}ELSE IF(!ISEMPTY(SQL.WHERESTR)){*/\n${SQL.WHERESTR} ${SQL.AUTHWHERE} \n/*}ELSE{*/\nAND 1=2\n/*}*/\n-- @ }', NULL, '20190116120115', '20240131151241', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('784FBF69A6F14AE588B41B9993316F15', 'V_XMGL_GZTJ.update', 99999, 'SYS_SJGL_APPCONFIG', '/*\n//更新子系统\nif(isNotEmpty(yobj.zxt)){\n	if(isEmpty(obj.piId)){\n		mydb.update(mydb.use(sjdx.dxzt),\"insert into gitea.project_issue(issue_id,project_id) values(?,?)\",obj.issueId,yobj.zxt);\n	}else if(yobj.zxt!=obj.zxt){\n		mydb.update(mydb.use(sjdx.dxzt),\"update gitea.project_issue t set t.project_id=? where t.id=?\",yobj.zxt,obj.piId);\n	}\n}\n//更新类型\nif(isNotEmpty(yobj.lx)){\n	if(isEmpty(obj.ilId)){\n		mydb.update(mydb.use(sjdx.dxzt),\"insert into gitea.issue_label(issue_id,label_id) values(?,?)\",obj.issueId,yobj.lx);\n	}else if(yobj.lx!=obj.lx){\n		mydb.update(mydb.use(sjdx.dxzt),\"update gitea.issue_label t set t.label_id=? where t.id=?\",yobj.lx,obj.ilId);\n	}\n}\n//更新处理人\nif(isNotEmpty(yobj.clrxm)){\n	if(isEmpty(obj.iaId)){\n		mydb.update(mydb.use(sjdx.dxzt),\"insert into gitea.issue_assignees(issue_id,assignee_id) values(?,?)\",obj.issueId,yobj.clrxm);\n	}else if(yobj.clrxm!=obj.clrxm){\n		mydb.update(mydb.use(sjdx.dxzt),\"update gitea.issue_assignees t set t.assignee_id=? where t.id=?\",yobj.clrxm,obj.iaId);\n	}\n}\n*/\nupdate gitea.issue t set\n/*if(isNotEmpty(yobj.lcb)){*/\nt.milestone_id=#{yobj.lcb} ,\n/*}*/\n/*if(isNotEmpty(yobj.isClosed)){*/\nt.is_closed=#{yobj.is_closed},\n/*}*/\n/*if(isNotEmpty(yobj.js)){*/\nt.name=#{yobj.js},\n/*}*/\n/*if(isNotEmpty(yobj.nr)){*/\nt.content=#{yobj.nr},\n/*}*/\n/*if(isNotEmpty(yobj.dqsj)){*/\nt.deadline_unix=UNIX_TIMESTAMP(str_to_date(#{yobj.dqsj}, \'%Y%m%d%H%i%S\')),\n/*}*/\nt.updated_unix=unix_timestamp()\n where t.id=#{obj.issueId}', '更新工作计划', '/*\n//GXZXT\nIF(ISNOTEMPTY(YOBJ.ZXT)){\n	IF(ISEMPTY(OBJ.PIID)){\n		MYDB.UPDATE(MYDB.USE(SJDX.DXZT),\"INSERT INTO GITEA.PROJECT_ISSUE(ISSUE_ID,PROJECT_ID) VALUES(?,?)\",OBJ.ISSUEID,YOBJ.ZXT);\n	}ELSE IF(YOBJ.ZXT!=OBJ.ZXT){\n		MYDB.UPDATE(MYDB.USE(SJDX.DXZT),\"UPDATE GITEA.PROJECT_ISSUE T SET T.PROJECT_ID=? WHERE T.ID=?\",YOBJ.ZXT,OBJ.PIID);\n	}\n}\n//GXLX\nIF(ISNOTEMPTY(YOBJ.LX)){\n	IF(ISEMPTY(OBJ.ILID)){\n		MYDB.', '/*\n//GENGXINZIXITONG\nIF(ISNOTEMPTY(YOBJ.ZXT)){\n	IF(ISEMPTY(OBJ.PIID)){\n		MYDB.UPDATE(MYDB.USE(SJDX.DXZT),\"INSERT INTO GITEA.PROJECT_ISSUE(ISSUE_ID,PROJECT_ID) VALUES(?,?)\",OBJ.ISSUEID,YOBJ.ZXT);\n	}ELSE IF(YOBJ.ZXT!=OBJ.ZXT){\n		MYDB.UPDATE(MYDB.USE(SJDX.DXZT),\"UPDATE GITEA.PROJECT_ISSUE T SET T.PROJECT_ID=? WHERE T.ID=?\",YOBJ.ZXT,OBJ.PIID);\n	}\n}\n//GENGXINLEIXING\nIF(ISNOTEMPTY(YOBJ.LX)){\n	IF(ISEMPTY', NULL, '20220826023721', '20231212163732', NULL, NULL, '1', '系统管理员1', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('7CB041607B874A99B7ADCB56271E81A8', 'SYS_QX_YHJSGL.yhmydjs', 99999, 'SYS_SJGL_APPCONFIG', 'select t.id js,t.mc js_mc,t.bz from sys_qx_jsxx t \nwhere not EXISTS (\nselect yj.js from sys_qx_yhjsgl yj where yj.yh = #{yobj.yh} and yj.js=t.id and yj.yxx=\'1\'\n) and t.yxx=\'1\'', '用户没有的角色', 'SELECT T.ID JS,T.MC JS_MC,T.BZ FROM SYS_QX_JSXX T \nWHERE NOT EXISTS (\nSELECT YJ.JS FROM SYS_QX_YHJSGL YJ WHERE YJ.YH = #{YOBJ.YH} AND YJ.JS=T.ID AND YJ.YXX=\'1\'\n) AND T.YXX=\'1\'', 'SELECT T.ID JS,T.MC JS_MC,T.BZ FROM SYS_QX_JSXX T \nWHERE NOT EXISTS (\nSELECT YJ.JS FROM SYS_QX_YHJSGL YJ WHERE YJ.YH = #{YOBJ.YH} AND YJ.JS=T.ID AND YJ.YXX=\'1\'\n) AND T.YXX=\'1\'', NULL, '20221114210122', '20221114215859', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('7CF3074FC1C649858F6EB0590EB35B1B', 'DEFAULT.update.mysql1', 99999, 'SYS_SJGL_APPCONFIG', '/*\nvar setf = \"\";\nif(su.isNotBlank(sjdx.zlzd)){\n    setf = setf+\",\"+sjdx.zlzd+\"=DATE_FORMAT(NOW(),\'%Y%m%d%H%i%s\')\";\n}\nvar whereStr = sjdx.zjzd+\"=#{yobj.\"+sjdx.zjzd+\"}\";\n//循环生成字段\nfor(ent in fields){\n     var field = ent.value;\n     //属性存在、不是主键、不是虚拟字段、允许编辑\n     if(@yobj.containsKey(field.zddm)&&field.zddm!=sjdx.zjzd&&\"99\"!=field.zdywlb&&field.yxbj==\'1\'){\n          if(field.kjlx==\'password\'){\n             setf = setf+\",\"+field.zddm+\"=\'\"+su.desEnByField(yobj[field.zddm],field)+\"\'\";\n          }else if(su.isBlank(yobj[field.zddm])){\n             setf = setf+\",\"+field.zddm+\"= null\";\n          }else{\n             setf = setf+\",\"+field.zddm+\"=#{yobj.\"+field.zddm+\"}\";\n          }\n     }\n }\n if(!isEmpty(sys.fields.sszzd)&&!isEmpty(yobj[sys.fields.sszzd.zddm])){\n     //设置简拼和全拼\n     if(!isEmpty(sys.fields.pyjp)&&su.length(yobj[sys.fields.sszzd.zddm])<200){\n          setf = setf+\",\"+sys.fields.pyjp.zddm+\"=#{yobj.pyjp}\";\n          mu.safeAddToMap(yobj,\"pyjp\",su.getSimpleSpell(yobj[sys.fields.sszzd.zddm]));\n     }\n     if(!isEmpty(sys.fields.pyqp)&&su.length(yobj[sys.fields.sszzd.zddm])<200){\n          setf = setf+\",\"+sys.fields.pyqp.zddm+\"=#{yobj.pyqp}\";\n          mu.safeAddToMap(yobj,\"pyqp\",su.getFullSpell(yobj[sys.fields.sszzd.zddm]));\n     }\n }\n setf = su.substring(setf, 1);\n mu.safeAddToMap(sql,\"setf\",setf);\n mu.safeAddToMap(sql,\"whereStr\",whereStr);\n*/\n/*if(!sys.yzdjl){*/\nerror:没有找到要修改的记录\n/*}else if(isEmpty(setf)){*/\nerror:没有要修改的信息\n/*}else{*/\nupdate ${sql.from}\n   set ${sql.setf}\n where ${sql.whereStr}\n/*}*/', NULL, NULL, NULL, NULL, '20220403122443', '20220825160908', NULL, NULL, '0', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('7DBEE02B1E5A4E8490F9F795EDC5B031', 'DEFAULT.qymp', 99999, 'SYS_SJGL_APPCONFIG', '/*\nvar selectField = \"\";\nvar whereStr = \"\";\nvar sszdlb = null;\n//循环生成字段\nfor(field in fieldList){\n   if(su.contains(field.zdywlb,\"99\")){\n        //虚拟字段\n        continue;\n   }\n   selectField = selectField + \",\" + field.zddm;\n     if(\'zjhm\'==field.zdywlb){\n          //设置证件号码字段\n           mu.safeAddToMap(sjdx.map,\'ZJHMZD\',field.zddm);\n     }\n     //具体资源没有输入该条件，且公用条件输入了该条件\n     if(isEmpty(yobj[field.zddm])){\n	     if(!isEmpty(qyzstj[field.zdywlb])){\n		  yobj[field.zddm]=qyzstj[field.zdywlb];\n	     }else if(!isEmpty(field.zdywlb)&&qyzstj[\'zjlx\']==field.zdywlb&&!isEmpty(qyzstj[\'zjhm\'])){\n		  //证件类型为该字段，且证件号码不为空\n		  yobj[field.zddm]=qyzstj[\'zjhm\'];\n	     }\n     }\n   if((sszdlb!=null&&kzxx.fields.sszzd.zddm==field.zddm)||isEmpty(yobj[field.zddm])){\n        //搜索主字段或该字段值为空\n        continue;\n   }\n   if(\"dict\"==field.kjlx&&field.zddx==\'1\'){\n        //字典多选支持\n       var arr = su.split(yobj[field.zddm], \",\");\n       var idx=0;\n       for(var a in arr){\n           if(idx==0){\n             if(a==\'my-null\'){\n               whereStr = whereStr + \" and (\"+field.zddm+\" is null \";\n             }else{\n               whereStr = whereStr + \" and (\"+field.zddm+\" = \'\"+a+\"\' \";\n             }\n           }else{\n             if(a==\'my-null\'){\n               whereStr = whereStr + \" or \"+field.zddm+\"  is null\";\n             }else{\n               whereStr = whereStr + \" or \"+field.zddm+\" = \'\"+a+\"\' \";\n             }\n           }\n           idx=idx+1;\n       }\n       whereStr = whereStr + \")\";\n   }else if(yobj[field.zddm]==\'my-null\'){\n         whereStr = whereStr + \" and \"+field.zddm+\" is null\";\n   }else if(\"dict\"==field.kjlx){\n         whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm]);\n   }else if((\"check\"+\"box\")==field.kjlx){\n         whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm]);\n   }else if(\"suggest\"==field.kjlx){\n         mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm+\"_text\"]+\"%\");\n         whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n   }else if(\"time\"==field.kjlx){\n         whereStr = whereStr + su.addEqDate(field,yobj);\n         if(field.hdgs==\'date\'){\n                  //支持date类型的时间\n                  if(!isEmpty(yobj[field.zddm+\"_start\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" >=to_date(\'\"+yobj[field.zddm+\"_start\"]+\"\',\'YYYYMMDDHH24MISS\')\";\n                  }\n                  if(!isEmpty(yobj[field.zddm+\"_end\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" <=to_date(\'\"+yobj[field.zddm+\"_end\"]+\"\',\'YYYYMMDDHH24MISS\')\";\n                  }\n         }else{\n                  if(!isEmpty(yobj[field.zddm+\"_start\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" >=\'\"+yobj[field.zddm+\"_start\"]+\"\'\";\n                  }\n                  if(!isEmpty(yobj[field.zddm+\"_end\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" <=\'\"+yobj[field.zddm+\"_end\"]+\"\'\";\n                  }\n         }\n   }else if(\"number\"==field.kjlx){\n         whereStr = whereStr + su.addEqNumber(field.zddm,yobj);\n   }else{\n        //默认处理方式\n       if(!isEmpty(yobj[field.zddm])){\n           if(su.indexOf(yobj[field.zddm], \"%\")>-1){\n              //用户输入有%，则按用户输入进行模糊即可\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",yobj[field.zddm]);\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else if(field.cxms==\'1\'){\n              //模糊搜索\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm]+\"%\");\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else if(field.cxms==\'2\'){\n              //右模糊搜索\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",yobj[field.zddm]+\"%\");\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else if(field.cxms==\'3\'){\n              //左模糊搜索\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm]);\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else{\n              //精确搜索\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm]);\n           }\n        }\n   }\n}\n//权限过滤条件\nvar authWhere = \"\";\nif(user==null){\n    //用户为空，初进系统\n}else if(user.qxMap[\'KFZFW_GLY\']!=null){\n    //管理员，不能查看系统管理员(sys)创建的数据。\n    if(!isEmpty(kzxx.fields.cjrdm)){\n        authWhere = \" and \"+kzxx.fields.cjrdm.zddm+\"<>\'BC5D77315CA84C6C807988E3CD17E70D\'\";\n    }\n}else if(user.qxMap[\'KFZFW_DWGLY\']!=null){\n    //单位管理员，只能管理本单位\n    if(!isEmpty(kzxx.fields.cjrdwdm)&&has(user)){\n        authWhere = \" and \"+kzxx.fields.cjrdwdm.zddm+\"=\'\"+user.jgxx.id+\"\'\";\n    }\n    if(user.qxMap[\'KFZFW_GLZDW\']!=null){\n        //管理子单位\n    \n    }\n}else if(user.qxMap[\'KFZFW_GLZDW\']!=null){\n    //管理子单位\n    \n}\n\nif(user==null){\n    //用户为空，初进系统\n}else if(user.qxMap[\'KFZFW_SYS\']!=null){\n    //系统管理员，无权限过滤\n    authWhere = \"\";\n}else if(isEmpty(authWhere)){\n    //普通用户,或上述权限没有生效只能查看本人数据\n    if(!isEmpty(kzxx.fields.cjrdm)&&has(user)&&user!=null){\n        authWhere = \" and \"+kzxx.fields.cjrdm.zddm+\"=\'\"+user.id+\"\'\";\n    }\n}\nselectField = su.substring(selectField,1);\n//排序\nvar orderBy = su.addPxField(sjdx.mrpx,yobj);\n//设置变量，备用\nmu.safeAddToMap(obj,\"selectField\",selectField);\nmu.safeAddToMap(obj,\"whereStr\",whereStr);\nmu.safeAddToMap(obj,\"authWhere\",authWhere);\nmu.safeAddToMap(obj,\"orderBy\",orderBy);\n*/\n/*if(!isEmpty(sjdx.map.ZJHMZD)){*/\nselect  ${selectField} from ${owner}.${tableName} t where 1 = 1 ${whereStr} ${authWhere} ${orderBy}\n/*}else{*/\nerror:${sjdx.dxmc}没配置有证件号码\n/*}*/', '通用全域摸排查询', '/*\nVAR SELECTFIELD = \"\";\nVAR WHERESTR = \"\";\nVAR SSZDLB = NULL;\n//XHSCZD\nFOR(FIELD IN FIELDLIST){\n   IF(SU.CONTAINS(FIELD.ZDYWLB,\"99\")){\n        //XNZD\n        CONTINUE;\n   }\n   SELECTFIELD = SELECTFIELD + \",\" + FIELD.ZDDM;\n     IF(\'ZJHM\'==FIELD.ZDYWLB){\n          //SZZJHMZD\n           MU.SAFEADDTOMAP(SJDX.MAP,\'ZJHMZD\',FIELD.ZDDM);\n     }\n     //JTZYMYSRGTJ，QGYTJSRLGTJ\n     IF(ISEMPTY(YOBJ[FIELD.', '/*\nVAR SELECTFIELD = \"\";\nVAR WHERESTR = \"\";\nVAR SSZDLB = NULL;\n//XUNHUANSHENGCHENGZIDUAN\nFOR(FIELD IN FIELDLIST){\n   IF(SU.CONTAINS(FIELD.ZDYWLB,\"99\")){\n        //XUNIZIDUAN\n        CONTINUE;\n   }\n   SELECTFIELD = SELECTFIELD + \",\" + FIELD.ZDDM;\n     IF(\'ZJHM\'==FIELD.ZDYWLB){\n          //SHEZHIZHENGJIANHAOMAZIDUAN\n           MU.SAFEADDTOMAP(SJDX.MAP,\'ZJHMZD\',FIELD.ZDDM);\n     }\n     //JUTIZIYUAN', NULL, '20200616104857', '20221117211940', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('81DBD9C55BE549C18DAAFB2F41004013', 'SYS_QX_QXXX.cds.mysql', 99999, 'SYS_SJGL_APPCONFIG', 'SELECT\r\n	t.mc NAME,\r\n	t.tb icon,\r\n	t.mc,\r\n	t.dm,\r\n	t.ms,\r\n	t.DZLX,\r\n	t.DKFS,\r\n	t.FQX,\r\n	t.KZXX,\r\n	t.LX,\r\n	t.component,\r\n	t.redirect,\r\n	( CASE  WHEN t.dzlx=\'05\' THEN CONCAT_WS(\'\',app.dz, t.dz) ELSE t.dz END) dz,\r\n/*if(!isEmpty(yobj.dqjs)){*/\r\n	(\r\n	SELECT\r\n		count( 1 ) \r\n	FROM\r\n		sys_qx_jsqxgl jq\r\n		INNER JOIN sys_qx_jsxx js ON js.dm = jq.js \r\n	WHERE\r\n		js.dm = #{yobj.dqjs}\r\n		\r\n		AND js.yxx = \'1\' \r\n		AND jq.yxx = \'1\' \r\n		AND jq.qx = t.dm \r\n	) checked,\r\n/*}*/\r\n	(\r\n	SELECT\r\n		count( 1 ) \r\n	FROM\r\n		SYS_QX_QXXX t1 \r\n	WHERE\r\n		t1.yxx = \'1\' \r\n		AND t1.fqx = t.dm \r\n		/*if(yobj.treeModel==\'cds\'){*/\r\n		AND t1.lx != \'03\' \r\n		/*}*/\r\n		\r\n	) parent \r\nFROM\r\n	SYS_QX_QXXX t\r\n	LEFT JOIN sys_qx_app app ON app.dm = t.SSYY \r\nWHERE\r\n	t.yxx = \'1\' \r\n	/*if(!isEmpty(yobj.fqx)){*/\r\n	AND (\r\n		t.fqx LIKE #{yobj.fqx+\"%\"} or t.dm = #{yobj.fqx})\r\n/*}else if(!isEmpty(yobj.treeRoot)){*/\r\n		AND (\r\n			t.fqx LIKE #{yobj.treeRoot+\"%\"} or t.dm = #{yobj.treeRoot})\r\n/*}else{*/\r\n			AND t.fqx IS NULL \r\n			/*}*/\r\n/*if(yobj.treeModel==\'cds\'){*/\r\n			AND t.lx != \'03\' /*}*/\r\n/*if(yobj.treeModel==\'cds\'){*/\r\n			AND EXISTS (\r\n			SELECT\r\n				qx.dm \r\n			FROM\r\n				sys_qx_qxxx qx\r\n				INNER JOIN sys_qx_jsqxgl jq ON qx.dm = jq.qx \r\n				AND jq.yxx = \'1\'\r\n				INNER JOIN sys_qx_jsxx js ON js.dm = jq.js \r\n				AND js.yxx = \'1\' \r\n			WHERE\r\n				qx.yxx = \'1\' \r\n				AND ( js.dm IN ( \'ADMIN_DLYH_LSYH\' \r\n-- @if(user.yhdm != \'lsyh\') {\r\n						, \'ADMIN_DLYH\' \r\n-- @}\r\n						) \r\n-- @for(e in user.jsMap) {\r\n					OR js.dm LIKE #{e.key+\"%\"}\r\n-- @}\r\n				) \r\n			AND qx.dm = t.dm \r\n	) \r\n/*}*/\r\n order by t.px asc', '获取菜单树的全部数据，然后代码中组建为树形结构', NULL, NULL, NULL, '20190403103234', '20220618012354', NULL, NULL, '0', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('8202CBA9C66043708FCDA21EACDF7831', 'DEFAULT.scjkrw', 99999, 'SYS_SJGL_APPCONFIG', 'select \'${sjdx.dxdm}\\#\'||id_job jtrw,name rwdm,\n	nvl(to_char(description),name) rwmc,\'3\' rwlx,\'99\' rwlb,\'1\' rwdj \n   from ${sql.from} t \n   where 1=1 \n   /*if (!isEmpty(sys.ids)){*/\n   	and t.id_job in (#{join(sys.ids)})\n   /*}*/', '生成监控任务', 'SELECT ‘${SJDX.DXDM}#’||ID_JOB JTRW,NAME RWDM,NVL(TO_CHAR(DESCRIPTION),NAME) RWMC\n   FROM ${OWNER}.${TABLENAME} T \n   WHERE 1=1 \n   /*IF (HAS(IDSIN)){*/\n   AND T.ID_JOB ${IDSIN}\n   /*}*/', 'SELECT ‘${SJDX.DXDM}#’||ID_JOB JTRW,NAME RWDM,NVL(TO_CHAR(DESCRIPTION),NAME) RWMC\n   FROM ${OWNER}.${TABLENAME} T \n   WHERE 1=1 \n   /*IF (HAS(IDSIN)){*/\n   AND T.ID_JOB ${IDSIN}\n   /*}*/', NULL, '20190919152120', '20211205140306', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('8ABC38B5161E487BBE12E85890948FB0', 'DEFAULT.select.mysql1', 99999, 'SYS_SJGL_APPCONFIG', '/*\n//查询字段列表\nvar selectField = \"\";\n//查询条件\nvar whereStr = \"\";\n//搜索字段列表\nvar sszdlb = null;\n//设置查询的字段列表\nfor(e in fields){\n   var field = e.value;\n   if(\"99\"!=field.zdywlb&&(field.xqzs==\"1\"||field.bjzs==\"1\"||field.lbzs==\"1\"||field.zddm==sjdx.zjzd)){\n       selectField = selectField + \",t.\" + field.zddm;\n   }\n}\n//树形结构处理\nif(null!=cllxkz[\'select\'].tree.hasChild!){\n   var tree = cllxkz[\'select\'].tree;\n   //查询该节点是否有子节点\n   selectField = selectField + \",(select (case when count(1)>0 then \'true\' else \'false\' end) from \"+sql.from+\" tree where tree.\"+tree.parentField+\"=t.\"+tree.rowField+\")\" + tree.hasChild;\n}\nif(!isEmpty(sys.ids)){\n    //id列表场景：不再处理其他查询条件\n    whereStr = \" and t.\"+sjdx.zjzd+\" in (#{join(sys.ids)})\";\n}else if(!isEmpty(sjdx.zjzd)&&!isEmpty(yobj[sjdx.zjzd])){\n   //主键存在，则只查询主键\n   whereStr = \" and t.\"+sjdx.zjzd+\" =#{yobj.\"+sjdx.zjzd+\"}\";\n}else{\n  if(null!=cllxkz[\'select\'].tree.hasChild!){\n     //树形结构查询场景\n     var tree = cllxkz[\'select\'].tree;\n      //是否树形结构查询条件\n      var sfsxjgField = tree.sfsxjgField!;\n     if(isEmpty(yobj[tree.parentField])&&(sfsxjgField==null||!(yobj[sfsxjgField]==\'0\'))){\n         //若是没有传父节点，且没有要求不按树形结构查询，则默认查所有根节点\n         whereStr = \" and t.\"+tree.parentField+\"  is null\";\n     }\n  }\n  //简拼全拼支持\n  if(!isEmpty(sys.fields.sszzd)){\n     var value = yobj[sys.fields.sszzd.zddm];\n     if(isEmpty(value)){\n         value = sys.searchKey;\n         mu.safeAddToMap(yobj,sys.fields.sszzd.zddm,value);\n     }\n     if(!isEmpty(value)){\n       sszdlb = sys.fields.sszzd.zddm;\n       if(!isEmpty(sys.fields.pyjp)){\n            sszdlb = sszdlb+\",t.\"+sys.fields.pyjp.zddm;\n       }\n       if(!isEmpty(sys.fields.pyqp)){\n            sszdlb = sszdlb+\",t.\"+sys.fields.pyqp.zddm;\n       }\n       if(!isEmpty(sys.fields.sszdlb)){\n            sszdlb = sszdlb+\",t.\"+sys.fields.sszdlb.zddm;\n       }\n       whereStr = whereStr + \" and upper(CONCAT_WS(\'\',\"+sszdlb+\")) like CONCAT_WS(\'\',\'%\',upper(#{yobj.\"+sys.fields.sszzd.zddm+\"}),\'%\')\";\n     }\n  }\n  //循环生成字段\n  for(e in fields){\n   var field = e.value;\n     if(\"99\"==field.zdywlb){\n          //虚拟字段\n          continue;\n     }\n     if((sszdlb!=null&&sys.fields.sszzd.zddm==field.zddm)||isEmpty(yobj[field.zddm])){\n          //搜索主字段或该字段值为空\n          continue;\n     }\n     if((\"$select\"==field.kjlx&&field.zddx==\'1\')||\"$checkbox\"==field.kjlx){\n          //字典多选支持\n         var arr = su.split(yobj[field.zddm], \",\");\n         var idx=0;\n         for(var a in arr){\n             if(idx==0){\n               if(a==\'my-null\'){\n                 whereStr = whereStr + \" and (t.\"+field.zddm+\" is null \";\n               }else{\n                 whereStr = whereStr + \" and (t.\"+field.zddm+\" like \'%\"+a+\"%\' \";\n               }\n             }else{\n               if(a==\'my-null\'){\n                 whereStr = whereStr + \" or t.\"+field.zddm+\"  is null\";\n               }else{\n                 whereStr = whereStr + \" or t.\"+field.zddm+\" like \'%\"+a+\"%\' \";\n               }\n             }\n             idx=idx+1;\n         }\n         whereStr = whereStr + \")\";\n     }else if(yobj[field.zddm]==\'my-null\'){\n           whereStr = whereStr + \" and t.\"+field.zddm+\" is null\";\n     }else if(\"$select\"==field.kjlx||\"$radio\"==field.kjlx||\"ElCascader\"==field.kjlx\n		 		||\"$switch\"==field.kjlx){\n           whereStr = whereStr +\" and t.\"+field.zddm+ su.addInput(field.zddm,yobj[field.zddm]);\n     }else if(\"suggest\"==field.kjlx){\n           mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm+\"_text\"]+\"%\");\n           whereStr = whereStr +\" and t.\"+field.zddm+ su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n     }else if(\"ElDatePicker\"==field.kjlx){\n           su.clEqDate(field,yobj);\n           if(field.hdgs==\'date\'){\n                    //支持date类型的时间\n                    if(!isEmpty(yobj[field.zddm+\"_start\"])){\n                      whereStr = whereStr + \" and t.\"+field.zddm+\" >=str_to_date(\'\"+yobj[field.zddm+\"_start\"]+\"\',\'%Y%m%d%H%I%S\')\";\n                    }\n                    if(!isEmpty(yobj[field.zddm+\"_end\"])){\n                      whereStr = whereStr + \" and t.\"+field.zddm+\" <=str_to_date(\'\"+yobj[field.zddm+\"_end\"]+\"\',\'%Y%m%d%H%I%S\')\";\n                    }\n           }else{\n                    if(!isEmpty(yobj[field.zddm+\"_start\"])){\n                      whereStr = whereStr + \" and t.\"+field.zddm+\" >=\'\"+yobj[field.zddm+\"_start\"]+\"\'\";\n                    }\n                    if(!isEmpty(yobj[field.zddm+\"_end\"])){\n                      whereStr = whereStr + \" and t.\"+field.zddm+\" <=\'\"+yobj[field.zddm+\"_end\"]+\"\'\";\n                    }\n           }\n     }else if(\"ElInputNumber\"==field.kjlx){\n					if(yobj[field.zddm].~size>0&&!isEmpty(yobj[field.zddm][0])){\n						whereStr = whereStr + \" and t.\"+field.zddm+\" >=#{\"+yobj[field.zddm][0]+\"}\";\n					}\n					if(yobj[field.zddm].~size>1&&!isEmpty(yobj[field.zddm][1])){\n						whereStr = whereStr + \" and t.\"+field.zddm+\" <=#{\"+yobj[field.zddm][1]+\"}\";\n					}\n     }else{\n		     whereStr = whereStr + \" and t.\"+field.zddm;\n          //默认处理方式\n         if(!isEmpty(yobj[field.zddm])){\n             if(su.indexOf(yobj[field.zddm]+\"\", \"%\")>-1){\n                //用户输入有%，则按用户输入进行模糊即可\n                mu.safeAddToMap(yobj,field.zddm+\"_like\",yobj[field.zddm]);\n                whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n             }else if(field.cxms==\'1\'){\n                //模糊搜索\n                mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm]+\"%\");\n                whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n             }else if(field.cxms==\'2\'){\n                //右模糊搜索\n                mu.safeAddToMap(yobj,field.zddm+\"_like\",yobj[field.zddm]+\"%\");\n                whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n             }else if(field.cxms==\'3\'){\n                //左模糊搜索\n                mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm]);\n                whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n             }else{\n                //精确搜索\n                whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm]);\n             }\n          }\n     }\n  }\n}\n\n//权限过滤条件\nvar authWhere = \"\";\nif(user==null){\n    //用户为空，初进系统\n}else if(user.qxMap[\'KFZFW_GLY\']!=null){\n    //管理员，不能查看系统管理员(sys)创建的数据。\n    if(!isEmpty(sys.fields.cjrdm)){\n        authWhere = \" and t.\"+sys.fields.cjrdm.zddm+\"<>\'BC5D77315CA84C6C807988E3CD17E70D\'\";\n    }\n}else if(user.qxMap[\'KFZFW_DWGLY\']!=null){\n    //单位管理员，只能管理本单位\n    if(!isEmpty(sys.fields.cjrdwdm)&&has(user)){\n        authWhere = \" and t.\"+sys.fields.cjrdwdm.zddm+\"=\'\"+user.jgxx.id+\"\'\";\n    }\n    if(user.qxMap[\'KFZFW_GLZDW\']!=null){\n        //管理子单位\n    \n    }\n}else if(user.qxMap[\'KFZFW_GLZDW\']!=null){\n    //管理子单位\n    \n}\n\nif(user==null){\n    //用户为空，初进系统\n}else if(user.qxMap[\'KFZFW_SYS\']!=null){\n    //系统管理员，无权限过滤\n    authWhere = \"\";\n}else if(isEmpty(authWhere)){\n    //普通用户,或上述权限没有生效只能查看本人数据\n    if(!isEmpty(sys.fields.cjrdm)&&has(user)&&user!=null){\n        authWhere = \" and t.\"+sys.fields.cjrdm.zddm+\"=\'\"+user.id+\"\'\";\n    }\n}\n//处理排序\nvar orderBy = page.orderBy;\nif(isEmpty(orderBy)){\n    orderBy = sjdx.mrpx;\n}\nif(!isEmpty(orderBy)){\n    orderBy = \"order by \"+orderBy;\n}\n\nselectField = su.substring(selectField,1);\n\n//设置变量，备用\nmu.safeAddToMap(sql,\"selectField\",selectField);\nmu.safeAddToMap(sql,\"whereStr\",whereStr);\nmu.safeAddToMap(sql,\"authWhere\",authWhere);\nmu.safeAddToMap(sql,\"orderBy\",orderBy);\n//要上天，逆天的操作\n//mydb.update(mydb.use(),\"insert into test_sjgl_1(xm) select to_char(sysdate,\'yyyymmddhh24miss\') from dual\",null);\n*/\nselect\n-- @pageTag(){\n ${sql.selectField}\n-- @}\n  from ${sql.from} t\n-- @where(){\n        ${sql.whereStr} ${sql.authWhere}\n-- @}\n-- @pageIgnoreTag(){\n	${sql.orderBy}\n-- @}', 'mysql的通用查询', NULL, NULL, NULL, '20181216190150', '20220901112353', NULL, NULL, '0', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('90AC340B1B6747C2A33D85449D7DBF07', 'SYS_QX_QTQX.getTreeCN', 99999, 'SYS_SJGL_APPCONFIG', 'select t.mc  name,\r\n       t.tb  icon,\r\n       t.*,\r\n       /*if(!isEmpty(yobj.dqjs)){*/\r\n       (select count(1)\r\n          from sys_qx_jsqxgl jq\r\n         inner join sys_qx_jsxx js\r\n            on js.id = jq.js\r\n         where js.id = #{yobj.dqjs}\r\n           and js.yxx = \'1\'\r\n           and jq.yxx = \'1\'\r\n           and jq.qx = t.id) checked,\r\n       /*}*/\r\n       (select count(1)\r\n          from SYS_QX_QXXX t1\r\n         where t1.yxx = \'1\'\r\n           and t1.fqx = t.id\r\n              /*if(yobj.treeModel==\'cds\'){*/\r\n           and t1.lx != \'03\'\r\n        /*}*/\r\n        ) parent\r\n				/*if(isEmpty(yobj.treeRoot))*/\r\n				,a.dz ssyydz\r\n				/**/\r\n  from SYS_QX_QXXX t\r\n	left join sys_qx_app a on a.dm=t.ssyy and a.yxx=\'1\'\r\n where t.yxx = \'1\'\r\n      /*if(!isEmpty(yobj.fqx)){*/\r\n   and t.fqx = (select t1.id from sys_qx_qxxx t1 where t1.dm=#{yobj.fqx} and t1.yxx=\'1\')\r\n      /*}else if(!isEmpty(yobj.fjd)){*/\r\n   and t.fqx = (select t1.id from sys_qx_qxxx t1 where t1.dm=#{yobj.fjd} and t1.yxx=\'1\')\r\n      /*}else if(!isEmpty(yobj.treeRoot)){*/\r\n   and t.fqx = (select t1.id from sys_qx_qxxx t1 where t1.dm=#{yobj.treeRoot} and t1.yxx=\'1\')\r\n      /*}else{*/\r\n   and t.fqx is null\r\n      /*}*/\r\n      /*if(yobj.treeModel==\'cds\'){*/\r\n   and t.lx != \'03\'\r\n   and exists\r\n (select qx.dm\r\n          from sys_qx_qxxx qx\r\n         inner join sys_qx_jsqxgl jq\r\n            on qx.id = jq.qx\r\n           and jq.yxx = \'1\'\r\n         inner join sys_qx_jsxx js\r\n            on js.id = jq.js\r\n           and js.yxx = \'1\'\r\n         where qx.yxx = \'1\'\r\n           and (\r\n               js.dm in (\'ADMIN_DLYH_LSYH\' \r\n               -- @if(user.yhdm != \'lsyh\') {\r\n                   , \'ADMIN_DLYH\' \r\n               -- @}\r\n               )\r\n              -- @for(e in user.jsMap) { \r\n                  or js.dm like #{e.key+\'%\'} \r\n              -- @}\r\n           )\r\n           and qx.id = t.id\r\n        )\r\n/*}*/\r\n order by t.px asc', '按加载菜单数据', 'SELECT T.MC  NAME,\n       T.TB  ICON,\n       T.*,\n       /*IF(!ISEMPTY(YOBJ.DQJS)){*/\n       (SELECT COUNT(1)\n          FROM SYS_QX_JSQXGL JQ\n         INNER JOIN SYS_QX_JSXX JS\n            ON JS.ID = JQ.JS\n         WHERE JS.ID = #{YOBJ.DQJS}\n           AND JS.YXX = \'1\'\n           AND JQ.YXX = \'1\'\n           AND JQ.QX = T.ID) CHECKED,\n       /*}*/\n       (SELECT COUNT(1)\n          FROM SYS_QX_QXXX ', 'SELECT T.MC  NAME,\n       T.TB  ICON,\n       T.*,\n       /*IF(!ISEMPTY(YOBJ.DQJS)){*/\n       (SELECT COUNT(1)\n          FROM SYS_QX_JSQXGL JQ\n         INNER JOIN SYS_QX_JSXX JS\n            ON JS.ID = JQ.JS\n         WHERE JS.ID = #{YOBJ.DQJS}\n           AND JS.YXX = \'1\'\n           AND JQ.YXX = \'1\'\n           AND JQ.QX = T.ID) CHECKED,\n       /*}*/\n       (SELECT COUNT(1)\n          FROM SYS_QX_QXXX ', NULL, '20190414175022', '20240527115312', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('94C2BA555DDE4F738C102592962B0166', 'DEFAULT.plsc', 99999, 'SYS_SJGL_APPCONFIG', '/*if(su.isBlank(sjdx.yxxzd)){*/\ndelete from ${sql.from} t\n-- @ where(){\n/*if(!su.isBlank(sys.ids)){*/\nand t.${sjdx.zjzd} in (#{join(sys.ids)})\n/*}else if(!su.isBlank(sql.whereStr)){*/\n${sql.whereStr} ${sql.authWhere} \n/*}else{*/\nand 1=2\n/*}*/\n-- @ }\n/*}else{*/\nupdate ${sql.from} t set t.${sjdx.yxxzd}=\'0\' \n/*if(su.isNotBlank(sjdx.zlzd)){*/\n    ,t.${sjdx.zlzd}=#{globalUse(\"util.expDate14\")}\n/*}*/\n/*if(su.isNotBlank(sjdx.qczd)){*/\n    ,t.${sjdx.qczd}=\'\'\n/*}*/\nwhere   t.${sjdx.yxxzd}=\'1\' \n/*if(!su.isBlank(sys.ids)){*/\nand t.${sjdx.zjzd} in (#{join(sys.ids)})\n/*}else if(!su.isBlank(sql.whereStr)){*/\n${sql.whereStr} ${sql.authWhere} \n/*}else{*/\nand 1=2\n/*}*/\n/*}*/', '支持逻辑删除，没有设置有效性字段则直接删除，否则更新有效性字段', '/*IF(SU.ISBLANK(SJDX.YXXZD)){*/\nDELETE FROM ${SQL.FROM} T\n-- @ WHERE(){\n/*IF(!SU.ISBLANK(SYS.IDS)){*/\nAND T.${SJDX.ZJZD} IN (#{JOIN(SYS.IDS)})\n/*}ELSE IF(!SU.ISBLANK(SQL.WHERESTR)){*/\n${SQL.WHERESTR} ${SQL.AUTHWHERE} \n/*}ELSE{*/\nAND 1=2\n/*}*/\n-- @ }\n/*}ELSE{*/\nUPDATE ${SQL.FROM} T SET T.${SJDX.YXXZD}=\'0\' \n/*IF(SU.ISNOTBLANK(SJDX.ZLZD)){*/\n    ,T.${SJDX.ZLZD}=#{GLOBALUSE(\"UTIL.EXPDATE14\")}\n/*}*/\n/*', '/*IF(SU.ISBLANK(SJDX.YXXZD)){*/\nDELETE FROM ${SQL.FROM} T\n-- @ WHERE(){\n/*IF(!SU.ISBLANK(SYS.IDS)){*/\nAND T.${SJDX.ZJZD} IN (#{JOIN(SYS.IDS)})\n/*}ELSE IF(!SU.ISBLANK(SQL.WHERESTR)){*/\n${SQL.WHERESTR} ${SQL.AUTHWHERE} \n/*}ELSE{*/\nAND 1=2\n/*}*/\n-- @ }\n/*}ELSE{*/\nUPDATE ${SQL.FROM} T SET T.${SJDX.YXXZD}=\'0\' \n/*IF(SU.ISNOTBLANK(SJDX.ZLZD)){*/\n    ,T.${SJDX.ZLZD}=#{GLOBALUSE(\"UTIL.EXPDATE14\")}\n/*}*/\n/*', NULL, '20210823174835', '20231115232409', NULL, NULL, '1', '系统管理员', 'sys', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('992C83721FEB4EE883CA5B213B607997', 'SYS_PLBD_HM_QYZS.hqcxx', 99999, 'SYS_SJGL_APPCONFIG', 'select zd.* from sys_sjgl_sjzd zd\nwhere zd.cxzs=\'1\' and zd.yxx=\'1\' and zd.sjdx=#{yobj.sjdx};ds=default', NULL, 'SELECT ZD.* FROM SYS_SJGL_SJZD ZD\nWHERE ZD.CXZS=\'1\' AND ZD.YXX=\'1\' AND ZD.SJDX=#YOBJ.SJDX#;DS=DEFAULT', 'SELECT ZD.* FROM SYS_SJGL_SJZD ZD\nWHERE ZD.CXZS=\'1\' AND ZD.YXX=\'1\' AND ZD.SJDX=#YOBJ.SJDX#;DS=DEFAULT', NULL, '20200616103550', '20200617115113', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('9997612C474B4849B96FD87AFE412A58', 'DEFAULT.qyzs', 99999, 'SYS_SJGL_APPCONFIG', '/*\nvar selectField = \"\";\nvar whereStr = \"\";\nvar sszdlb = null;\n//循环生成字段\nfor(field in fieldList){\n   if(su.contains(field.zdywlb,\"99\")){\n        //虚拟字段\n        continue;\n   }\n   selectField = selectField + \",\" + field.zddm;\n     //具体资源没有输入该条件，且公用条件输入了该条件\n     if(isEmpty(yobj[field.zddm])){\n	     if(!isEmpty(qyzstj[field.zdywlb])){\n		  yobj[field.zddm]=qyzstj[field.zdywlb];\n	     }else if(!isEmpty(field.zdywlb)&&qyzstj[\'zjlx\']==field.zdywlb&&!isEmpty(qyzstj[\'zjhm\'])){\n		  //证件类型为该字段，且证件号码不为空\n		  yobj[field.zddm]=qyzstj[\'zjhm\'];\n	     }\n     }\n   if((sszdlb!=null&&kzxx.fields.sszzd.zddm==field.zddm)||isEmpty(yobj[field.zddm])){\n        //搜索主字段或该字段值为空\n        continue;\n   }\n   if(\"dict\"==field.kjlx&&field.zddx==\'1\'){\n        //字典多选支持\n       var arr = su.split(yobj[field.zddm], \",\");\n       var idx=0;\n       for(var a in arr){\n           if(idx==0){\n             if(a==\'my-null\'){\n               whereStr = whereStr + \" and (\"+field.zddm+\" is null \";\n             }else{\n               whereStr = whereStr + \" and (\"+field.zddm+\" = \'\"+a+\"\' \";\n             }\n           }else{\n             if(a==\'my-null\'){\n               whereStr = whereStr + \" or \"+field.zddm+\"  is null\";\n             }else{\n               whereStr = whereStr + \" or \"+field.zddm+\" = \'\"+a+\"\' \";\n             }\n           }\n           idx=idx+1;\n       }\n       whereStr = whereStr + \")\";\n   }else if(yobj[field.zddm]==\'my-null\'){\n         whereStr = whereStr + \" and \"+field.zddm+\" is null\";\n   }else if(\"dict\"==field.kjlx){\n         whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm]);\n   }else if((\"check\"+\"box\")==field.kjlx){\n         whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm]);\n   }else if(\"suggest\"==field.kjlx){\n         mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm+\"_text\"]+\"%\");\n         whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n   }else if(\"time\"==field.kjlx){\n         whereStr = whereStr + su.addEqDate(field,yobj);\n         if(field.hdgs==\'date\'){\n                  //支持date类型的时间\n                  if(!isEmpty(yobj[field.zddm+\"_start\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" >=to_date(\'\"+yobj[field.zddm+\"_start\"]+\"\',\'YYYYMMDDHH24MISS\')\";\n                  }\n                  if(!isEmpty(yobj[field.zddm+\"_end\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" <=to_date(\'\"+yobj[field.zddm+\"_end\"]+\"\',\'YYYYMMDDHH24MISS\')\";\n                  }\n         }else{\n                  if(!isEmpty(yobj[field.zddm+\"_start\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" >=\'\"+yobj[field.zddm+\"_start\"]+\"\'\";\n                  }\n                  if(!isEmpty(yobj[field.zddm+\"_end\"])){\n                    whereStr = whereStr + \" and \"+field.zddm+\" <=\'\"+yobj[field.zddm+\"_end\"]+\"\'\";\n                  }\n         }\n   }else if(\"number\"==field.kjlx){\n         whereStr = whereStr + su.addEqNumber(field.zddm,yobj);\n   }else{\n        //默认处理方式\n       if(!isEmpty(yobj[field.zddm])){\n           if(su.indexOf(yobj[field.zddm], \"%\")>-1){\n              //用户输入有%，则按用户输入进行模糊即可\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",yobj[field.zddm]);\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else if(field.cxms==\'1\'){\n              //模糊搜索\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm]+\"%\");\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else if(field.cxms==\'2\'){\n              //右模糊搜索\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",yobj[field.zddm]+\"%\");\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else if(field.cxms==\'3\'){\n              //左模糊搜索\n              mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm]);\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n           }else{\n              //精确搜索\n              whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm]);\n           }\n        }\n   }\n}\n//权限过滤条件\nvar authWhere = \"\";\nif(user==null){\n    //用户为空，初进系统\n}else if(user.qxMap[\'KFZFW_GLY\']!=null){\n    //管理员，不能查看系统管理员(sys)创建的数据。\n    if(!isEmpty(kzxx.fields.cjrdm)){\n        authWhere = \" and \"+kzxx.fields.cjrdm.zddm+\"<>\'BC5D77315CA84C6C807988E3CD17E70D\'\";\n    }\n}else if(user.qxMap[\'KFZFW_DWGLY\']!=null){\n    //单位管理员，只能管理本单位\n    if(!isEmpty(kzxx.fields.cjrdwdm)&&has(user)){\n        authWhere = \" and \"+kzxx.fields.cjrdwdm.zddm+\"=\'\"+user.jgxx.id+\"\'\";\n    }\n    if(user.qxMap[\'KFZFW_GLZDW\']!=null){\n        //管理子单位\n    \n    }\n}else if(user.qxMap[\'KFZFW_GLZDW\']!=null){\n    //管理子单位\n    \n}\n\nif(user==null){\n    //用户为空，初进系统\n}else if(user.qxMap[\'KFZFW_SYS\']!=null){\n    //系统管理员，无权限过滤\n    authWhere = \"\";\n}else if(isEmpty(authWhere)){\n    //普通用户,或上述权限没有生效只能查看本人数据\n    if(!isEmpty(kzxx.fields.cjrdm)&&has(user)&&user!=null){\n        authWhere = \" and \"+kzxx.fields.cjrdm.zddm+\"=\'\"+user.id+\"\'\";\n    }\n}\nselectField = su.substring(selectField,1);\n//排序\nvar orderBy = su.addPxField(sjdx.mrpx,yobj);\n//设置变量，备用\nmu.safeAddToMap(obj,\"selectField\",selectField);\nmu.safeAddToMap(obj,\"whereStr\",whereStr);\nmu.safeAddToMap(obj,\"authWhere\",authWhere);\nmu.safeAddToMap(obj,\"orderBy\",orderBy);\n*/\nselect  ${selectField} from ${owner}.${tableName} t where 1 = 1 ${whereStr} ${authWhere} ${orderBy}', '通用全域智搜查询', '/*\nVAR SELECTFIELD = \"\";\nVAR WHERESTR = \"\";\nVAR SSZDLB = NULL;\n//XHSCZD\nFOR(FIELD IN FIELDLIST){\n   IF(SU.CONTAINS(FIELD.ZDYWLB,\"99\")){\n        //XNZD\n        CONTINUE;\n   }\n   SELECTFIELD = SELECTFIELD + \",\" + FIELD.ZDDM;\n     //JTZYMYSRGTJ，QGYTJSRLGTJ\n     IF(ISEMPTY(YOBJ[FIELD.ZDDM])){\n	     IF(!ISEMPTY(QYZSTJ[FIELD.ZDYWLB])){\n		  YOBJ[FIELD.ZDDM]=QYZSTJ[FIELD.ZDYWLB];\n	     }ELSE IF(!ISEMPTY', '/*\nVAR SELECTFIELD = \"\";\nVAR WHERESTR = \"\";\nVAR SSZDLB = NULL;\n//XUNHUANSHENGCHENGZIDUAN\nFOR(FIELD IN FIELDLIST){\n   IF(SU.CONTAINS(FIELD.ZDYWLB,\"99\")){\n        //XUNIZIDUAN\n        CONTINUE;\n   }\n   SELECTFIELD = SELECTFIELD + \",\" + FIELD.ZDDM;\n     //JUTIZIYUANMEIYOUSHURUGAITIAOJIAN，QIEGONGYONGTIAOJIANSHURULEGAITIAOJIAN\n     IF(ISEMPTY(YOBJ[FIELD.ZDDM])){\n	     IF(!ISEMPTY(QYZSTJ[FIELD.ZDYWLB]', NULL, '20200614194802', '20221117211921', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('9DEA14AD5344423D9373A945965E687B', 'SYS_SJGL_GRBJ.getTreeCN', 99999, 'SYS_SJGL_APPCONFIG', 'select bt  name,\n       t.id dm,\n       (select count(1)\n          from SYS_SJGL_GRBJ t1\n         where t1.yxx = \'1\'\n           and t1.sjbj = t.id\n        ) parent,\n        t.zt,t.kjx\n  from SYS_SJGL_GRBJ t\n where t.yxx = \'1\'\n      /*if(!isEmpty(sjdx.sjbj)){*/\n   and t.sjbj = #{sjdx.sjbj}\n      /*}else if(!isEmpty(sjdx.treeRoot)){*/\n   and t.sjbj = #{sjdx.treeRoot}\n      /*}else{*/\n   and t.sjbj is null\n      /*}*/\n order by px asc,t.gxsj desc', NULL, NULL, NULL, NULL, '20200624095319', '20200629171535', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('9F88EB93AB5B4455BB32584EB4DC508A', 'SHRMYY_HLB_ZLJCX.select', 99999, 'SYS_SJGL_APPCONFIG', '/*\nvar whereStr = \"\";\nvar whereStr1 = \"\";\n//默认处理方式\nif(!isEmpty(yobj.ssjl)){\n    whereStr = whereStr + \" and x.ssjl= #{yobj.ssjl} \";\n}\nif(!isEmpty(yobj.id)){\n    whereStr1 = whereStr1 + \" and x.id = #{yobj.id} \";\n}\n//排序\nvar orderBy = su.addPxField(sjdx.mrpx,yobj);\n//设置变量，备用\nmu.safeAddToMap(obj,\"whereStr\",whereStr);\nmu.safeAddToMap(obj,\"authWhere\",\"\");\nmu.safeAddToMap(obj,\"orderBy\",orderBy);\n*/\nselect z.ssdl, z.ssxl, z.zblb, z.zbmc, z.zbms,z.id z_id, x.*\n  from SHRMYY_HLB_ZLJCZB z\n  left join SHRMYY_HLB_ZLJCX x\n    on z.id = x.sszb  ${obj.whereStr}\nwhere 1 = 1 ${whereStr1} ${obj.orderBy } ', NULL, NULL, NULL, NULL, '20210330194228', '20230302113149', NULL, NULL, '0', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('A4341768CF494521A42F040092BE653B', 'SYS_PLBD_HM.getTreeCN', 99999, 'SYS_SJGL_APPCONFIG', 'select mc  name,\n       t.dm dm,\n       (select count(1)\n          from SYS_BDHC_ZY t1\n         where t1.yxx = \'1\'\n           and t1.sjzy = t.dm\n        ) parent,\n        t.sjdx\n  from SYS_BDHC_ZY t\n where t.yxx = \'1\' and t.qyhc=\'1\'\n      /*if(!isEmpty(sjdx.sjzy)){*/\n   and t.sjzy = #{sjdx.sjzy}\n      /*}else if(!isEmpty(sjdx.treeRoot)){*/\n   and t.sjzy = #{sjdx.treeRoot}\n      /*}else{*/\n   and t.sjzy is null\n      /*}*/\n order by px asc,t.gxsj desc', NULL, NULL, NULL, NULL, '20200610004214', '20210222153804', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('A4619F3A6921465C9ADF789B8E87E8CE', 'SYS_YXJK_ZDYSQL.scjkrw', 99999, 'SYS_SJGL_APPCONFIG', 'select id jtrw,dm rwdm,mc rwmc,\'5\' rwlx,\'99\' rwlb,\'1\' rwdj \n   from SYS_YXJK_ZDYSQL t \n   where 1=1 \n   /*if (!isEmpty(sys.ids)){*/\n   	and t.id in (#{join(sys.ids)})\n   /*}*/', NULL, 'SELECT ID JTRW,DM RWDM,MC RWMC,\'5\' RWLX,\'99\' RWLB,\'1\' RWDJ \n   FROM SYS_YXJK_ZDYSQL T \n   WHERE 1=1 \n   /*IF (!ISEMPTY(SYS.IDS)){*/\n   	AND T.ID IN (#{JOIN(SYS.IDS)})\n   /*}*/', 'SELECT ID JTRW,DM RWDM,MC RWMC,\'5\' RWLX,\'99\' RWLB,\'1\' RWDJ \n   FROM SYS_YXJK_ZDYSQL T \n   WHERE 1=1 \n   /*IF (!ISEMPTY(SYS.IDS)){*/\n   	AND T.ID IN (#{JOIN(SYS.IDS)})\n   /*}*/', NULL, '20190925190216', '20211205140433', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('A5194F03AAEA494BABB9784BD08F3316', 'SYS_ZNBK_HM.wlplsc', 99999, 'SYS_SJGL_APPCONFIG', 'update SYS_BDHC_HM set gxsj=#{globalUse(\"util.expDate14\")} where 1=2', '支持逻辑删除，没有设置有效性字段则直接删除，否则更新有效性字段', 'UPDATE SYS_BDHC_HM SET GXSJ=#{GLOBALUSE(\"UTIL.EXPDATE14\")} WHERE 1=2', 'UPDATE SYS_BDHC_HM SET GXSJ=#{GLOBALUSE(\"UTIL.EXPDATE14\")} WHERE 1=2', NULL, '20181216195738', '20211203000636', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('AAD97546CDCD4EA7A2FB5FF461EB3B08', 'DEFAULT.update', 99999, 'SYS_SJGL_APPCONFIG', '/*\nvar setf = \"\";\nif(su.isNotBlank(sjdx.zlzd)){\n    setf = setf+\",t.\"+sjdx.zlzd+\'=#{globalUse(\"util.expDate14\")}\';\n}\nvar whereStr = \"t.\"+sjdx.zjzd+\"=#{yobj.\"+sjdx.zddmZjzd+\"}\";\n//循环生成字段\nfor(ent in fields){\n     var field = ent.value;\n     //属性存在、不是主键、不是虚拟字段、允许编辑\n     if(@yobj.containsKey(field.zddm)&&field.zddm!=sjdx.zjzd&&field.zddm!=sjdx.zlzd&&!su.contains(field.zdywlb,\"99\")&&field.yxbj==\'1\'){\n          if(sys.sjyz==\'0\'){\n             setf = setf+\",t.#{globalUse(\'util.expField\',{\'field\':\'\"+field.yszddm+\"\'\\\\})}=#{yobj.\"+field.zddm+\"}\";\n          }else if(field.kjlx==\'password\'){\n             setf = setf+\",t.#{globalUse(\'util.expField\',{\'field\':\'\"+field.yszddm+\"\'\\\\})}=\'\"+su.desEnByField(yobj[field.zddm],field)+\"\'\";\n          }else if(field.zdlx==\'DATE\'){\n             setf = setf+\",t.#{globalUse(\'util.expField\',{\'field\':\'\"+field.yszddm+\"\'\\\\})}=#{globalUse(\'util.expStr14ToDate\',{\'dateStr\':\'\"+yobj[field.zddm]+\"\'\\\\})}\";\n          }else if(isEmpty(yobj[field.zddm])){\n             setf = setf+\",t.#{globalUse(\'util.expField\',{\'field\':\'\"+field.yszddm+\"\'\\\\})}=null\";\n          }else{\n             setf = setf+\",t.#{globalUse(\'util.expField\',{\'field\':\'\"+field.yszddm+\"\'\\\\})}=#{yobj.\"+field.zddm+\"}\";\n          }\n     }\n }\n if(@yobj.containsKey(sys.fields.sszzd.zddm!)&&!isEmpty(yobj[sys.fields.sszzd.zddm!])){\n     //设置简拼和全拼\n     if(!isEmpty(sys.fields.pyjp.zddm!)){\n          setf = setf+\",t.\"+sys.fields.pyjp.zddm+\"=#{yobj[sys.fields.pyjp.zddm]}\";\n					classUtil.setVal(sys.fields.pyjp.zddm,su.substrByByte(su.getSimpleSpell(yobj[sys.fields.sszzd.zddm]),fields[sys.fields.pyjp.zddm].zdcd),yobj,null);\n     }\n     if(!isEmpty(sys.fields.pyqp.zddm!)){\n          setf = setf+\",t.\"+sys.fields.pyqp.zddm+\"=#{yobj[sys.fields.pyqp.zddm]}\";\n					classUtil.setVal(sys.fields.pyqp.zddm,su.substrByByte(su.getFullSpell(yobj[sys.fields.sszzd.zddm]),fields[sys.fields.pyqp.zddm].zdcd),yobj,null);\n     }\n }\n setf = su.substring(setf, 1);\n//mu.safeAddToMap(sql,\"setf\",setf);\n//mu.safeAddToMap(sql,\"whereStr\",whereStr);\nclassUtil.setVal(\"setf\",setf,sql,null);\nclassUtil.setVal(\"whereStr\",whereStr,sql,null);\n*/\n/*if(!sys.yzdjl!true){*/\nerror:没有找到要修改的记录\n/*}else if(isEmpty(setf)){*/\nerror:没有要修改的信息\n/*}else{*/\nupdate ${sql.from} t\n   set ${sql.setf}\n where ${sql.whereStr}\n/*}*/', '默认更新语句生成逻辑1', '/*\nVAR SETF = \"\";\nIF(SU.ISNOTBLANK(SJDX.ZLZD)){\n    SETF = SETF+\",T.\"+SJDX.ZLZD+\'=#{GLOBALUSE(\"UTIL.EXPDATE14\")}\';\n}\nVAR WHERESTR = \"T.\"+SJDX.ZJZD+\"=#{YOBJ.\"+SJDX.ZDDMZJZD+\"}\";\n//XHSCZD\nFOR(ENT IN FIELDS){\n     VAR FIELD = ENT.VALUE;\n     //SXCZ、BSZJ、BSXNZD、YXBJ\n     IF(@YOBJ.CONTAINSKEY(FIELD.ZDDM)&&FIELD.ZDDM!=SJDX.ZJZD&&FIELD.ZDDM!=SJDX.ZLZD&&!SU.CONTAINS(FIELD.ZDYWLB,\"99\")&&FIELD.YXBJ==\'', '/*\nVAR SETF = \"\";\nIF(SU.ISNOTBLANK(SJDX.ZLZD)){\n    SETF = SETF+\",T.\"+SJDX.ZLZD+\'=#{GLOBALUSE(\"UTIL.EXPDATE14\")}\';\n}\nVAR WHERESTR = \"T.\"+SJDX.ZJZD+\"=#{YOBJ.\"+SJDX.ZDDMZJZD+\"}\";\n//XUNHUANSHENGCHENGZIDUAN\nFOR(ENT IN FIELDS){\n     VAR FIELD = ENT.VALUE;\n     //SHUXINGCUNZAI、BUSHIZHUJIAN、BUSHIXUNIZIDUAN、YUNXUBIANJI\n     IF(@YOBJ.CONTAINSKEY(FIELD.ZDDM)&&FIELD.ZDDM!=SJDX.ZJZD&&FIELD.ZDDM!=SJDX.ZL', NULL, '20181213201559', '20240527114429', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('AB6F4F51B09749FE821B19F9C2F5C642', 'DEFAULT.getObjByIds', 99999, 'SYS_SJGL_APPCONFIG', 'select * from ${sql.from} where ${sjdx.zjzd} in #{join(sys.ids)}', '根据对象id集合获取多条记录', 'SELECT * FROM ${SQL.FROM} WHERE ${SJDX.ZJZD} IN #{JOIN(SYS.IDS)}', 'SELECT * FROM ${SQL.FROM} WHERE ${SJDX.ZJZD} IN #{JOIN(SYS.IDS)}', NULL, '20191023160103', '20230601175426', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('B032ED4ACE934482A20686CAF0302F9F', 'zd.SYS_COMMON_ORG.oracle', 99999, 'SYS_SJGL_APPCONFIG', 'select id dm,jgmc as mc,sjjg upnode,px,\njgjc||jgdm||jgbm||jcjp as search_key \nfrom  sys_qx_jgxx org where org.yxx=\'1\'', NULL, 'SELECT ID DM,JGMC AS MC,SJJG UPNODE,PX,\nJGJC||JGDM||JGBM||JCJP AS SEARCH_KEY \nFROM  SYS_QX_JGXX ORG WHERE ORG.YXX=\'1\'', 'SELECT ID DM,JGMC AS MC,SJJG UPNODE,PX,\nJGJC||JGDM||JGBM||JCJP AS SEARCH_KEY \nFROM  SYS_QX_JGXX ORG WHERE ORG.YXX=\'1\'', NULL, '20220313173108', '20220912205501', NULL, NULL, '0', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('B557B3D068E14C4290565F55CD95ED98', 'SYS_QX_JSXX.getTreeCN', 99999, 'SYS_SJGL_APPCONFIG', 'select mc  name,\n       \'\'  icon,\n       t.*,\n       (select count(1)\n          from SYS_QX_JSXX t1\n         where t1.yxx = \'1\'\n           and t1.fjs = t.dm\n        ) parent\n  from SYS_QX_JSXX t\n where t.yxx = \'1\'\n      /*if(!isEmpty(sjdx.fjs)){*/\n   and t.fjs = #{sjdx.fjs}\n      /*}else if(!isEmpty(sjdx.treeRoot)){*/\n   and t.fjs = #{sjdx.treeRoot}\n      /*}else{*/\n   and t.fjs is null\n      /*}*/\n order by px asc\n', '获取角色树的sql', NULL, NULL, NULL, '20200901181851', '20200901182321', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('B5ABEB9A5E2E4F46A5B32F7B7495C55A', 'DEFAULT.swyx', 99999, 'SYS_SJGL_APPCONFIG', 'update ${sql.from} t set ${sjdx.yxxzd}=\'1\'\n/*if(su.isNotBlank(sjdx.zlzd)){*/\n    ,t.${sjdx.zlzd}=#{globalUse(\"util.expDate14\")}\n/*}*/\n-- @ where(){\n/*if(!isEmpty(sys.ids)){*/\nand t.${sjdx.zjzd} in (#{join(sys.ids)})\n/*}else if(!isEmpty(sql.whereStr)){*/\n${sql.whereStr} ${sql.authWhere} \n/*}else{*/\nand 1=2\n/*}*/\n-- @ }', NULL, 'UPDATE ${SQL.FROM} T SET ${SJDX.YXXZD}=\'1\'\n/*IF(SU.ISNOTBLANK(SJDX.ZLZD)){*/\n    ,T.${SJDX.ZLZD}=#{GLOBALUSE(\"UTIL.EXPDATE14\")}\n/*}*/\n-- @ WHERE(){\n/*IF(!ISEMPTY(SYS.IDS)){*/\nAND T.${SJDX.ZJZD} IN (#{JOIN(SYS.IDS)})\n/*}ELSE IF(!ISEMPTY(SQL.WHERESTR)){*/\n${SQL.WHERESTR} ${SQL.AUTHWHERE} \n/*}ELSE{*/\nAND 1=2\n/*}*/\n-- @ }', 'UPDATE ${SQL.FROM} T SET ${SJDX.YXXZD}=\'1\'\n/*IF(SU.ISNOTBLANK(SJDX.ZLZD)){*/\n    ,T.${SJDX.ZLZD}=#{GLOBALUSE(\"UTIL.EXPDATE14\")}\n/*}*/\n-- @ WHERE(){\n/*IF(!ISEMPTY(SYS.IDS)){*/\nAND T.${SJDX.ZJZD} IN (#{JOIN(SYS.IDS)})\n/*}ELSE IF(!ISEMPTY(SQL.WHERESTR)){*/\n${SQL.WHERESTR} ${SQL.AUTHWHERE} \n/*}ELSE{*/\nAND 1=2\n/*}*/\n-- @ }', NULL, '20190125150406', '20240131151215', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('BA7C7A29CDF742AE8858239B52A4747C', 'SYS_SJGL_SJDX.kzxx', 99999, 'SYS_SJGL_APPCONFIG', '{\n	//系统参数\n  \"sys\": {\n		\"dcwjm\": \"数据对象导出文件名称自定义\",\n    \"fields\": {\n      \"sszzd\": {\n        \"zddm\": \"dxmc\",\n        \"zdms\": \"搜索主字段\"\n      },\n      \"pyjp\": {\n        \"zdms\": \"拼音简拼\",\n        \"zddm\": \"dxjp\"\n      },\n      \"pyqp\": {\n        \"zdms\": \"拼音全拼\",\n        \"zddm\": \"dxqp\"\n      },\n      \"sszdlb\": {\n        \"zdms\": \"搜索字段列表\",\n        \"zddm\": \"dxms\',\'t.dxdm\"\n      }\n    }\n  },\n	\"zhgz\":{\n		\"yobj.cjrxm\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.yhxm}\"\n				}\n			}\n		},\n		\"yobj.cjrdm\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.id}\"\n				}\n			}\n		},\n		\"yobj.cjrdwmc\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.jgxx.jgmc}\"\n				}\n			}\n		},\n		\"yobj.cjrdwdm\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.jgxx.id}\"\n				}\n			}\n		}\n	},\n	\"cllxkz\": {\n		\"select\": {\n			\"myHelp\": \"42F03A5FE3B9425E98E46B52298485A2\",\n			//页面扩展：这里设置的参数会合并到页面参数的根节点中\n			\"pagekz\": {\n				gridOptions:{\n					showFooter: true,\n					\"pagerConfig\": {\n						\"pageSize\": 20\n					}\n				},\n				//定时刷新，120秒\n				\"dssx\":300,\n				//报警声音，值为声音文件的id，走文件下载接口获取，配置了页面查询查询有数据时则报警\n				\"bjsy\":\"5835E452395A429C85BC836E92415B53\"\n			},\n			\"qxpz\": {\n				\"plclLeft\": {\n					\"insert\": {\n						\"px\": 10,\n						\"content\": \"导入对象\"\n					},\n					\"plsc\": {\n						\"px\": 20\n					},\n          \"pldr\": {\n						\"px\": 25,\n            \"type\": \"primary\",\n            \"content\": \"批量导入\",\n            \"buttonOptions\": {\n              \"clfs\": \"tcck\",\n              //是否需要选择记录\n              sfxyxzjl: false,\n              tcqp: true,\n              \"dxjcxx\": {\n                \"sjdx\": {\n                  \"dxdm\": \"SYS_SJGL_SJDX_PLDR\"\n                },\n                \"sys\": {\n                  \"cllx\": \"insert\"\n                }\n              },\n              //基础信息扩展，可以把当前页面参数取出来设置到dxjcxx中\n              \"jcxxkz\": {\n                // <设置到obj中的key，从myData中取的只路径>\n                // \"sys.ids\": \"dxjcxx.sys.ids\"\n              }\n            }\n          },\n          \"scdxst\": {\n						\"px\": 30,\n            \"type\": \"primary\",\n            \"content\": \"生成实体\",\n            \"buttonOptions\": {\n              \"clfs\": \"tcck\",\n							\"tckz\":{\n								\"width\":\"400px\",\n								\"height\":\"200px\"\n							},\n              //是否需要选择记录\n              sfxyxzjl: true,\n              tcqp: false,\n              \"dxjcxx\": {\n                \"sjdx\": {\n                  \"dxdm\": \"SYS_SJGL_SJDX_SCDXST\"\n                },\n                \"sys\": {\n                  \"cllx\": \"insert\"\n                }\n              },\n              //基础信息扩展，可以把当前页面参数取出来设置到dxjcxx中\n              \"jcxxkz\": {\n                //<设置到obj中的key，从myData中取的只路径>\n                \"sys.ids\": \"dxjcxx.sys.ids\"\n              }\n            }\n          }\n				},\n				\"plclRight\": {\n          \"dcsj\": {\n            \"content\": \"Export all\",\n            \"buttonOptions\": {\n							//允许分页导出全部，否则只允许导出第一页\n							\"yxfydc\": true,\n              \"params\": {\n                \"page\": {\n                  //默认导出50000条记录\n                  \"pageSize\": 50,\n                  //导出全部默认只允许导出第一页\n                  \"pageNumber\": 1\n                }\n              }\n            }\n          }\n				}\n			}\n		}\n	},\n  \"fields\": {\n    \"dxdm\": {\n			\"tails\":{\n				\"xxxx\":\"xxx\"\n			},\n			//导出表头背景色\n			\"dcbtbjs\":\"RED1\",\n			//导出默认背景色\n			\"dcmrbjs\":\"BLUE1\",\n			//导出数据定制颜色，具体设置每一行\n			\"dcdzbjs\":{\n				1:\"BRIGHT_GREEN\",\n				3:\"DARK_RED\"\n			}\n		},\n    \"dxmc\": {\n			//导出默认背景色\n			\"dcmrbjs\":\"GREY_25_PERCENT\"\n		},\n    \"dxms\": {\n			//导出默认背景色\n			\"dcbtbjs\":\"ORCHID\"\n		}\n	}\n}', '扩展信息-数据对象', '{\n	//XTCS\n  \"SYS\": {\n		\"DCWJM\": \"SJDXDCWJMCZDY\",\n    \"FIELDS\": {\n      \"SSZZD\": {\n        \"ZDDM\": \"DXMC\",\n        \"ZDMS\": \"SSZZD\"\n      },\n      \"PYJP\": {\n        \"ZDMS\": \"PYJP\",\n        \"ZDDM\": \"DXJP\"\n      },\n      \"PYQP\": {\n        \"ZDMS\": \"PYQP\",\n        \"ZDDM\": \"DXQP\"\n      },\n      \"SSZDLB\": {\n        \"ZDMS\": \"SSZDLB\",\n        \"ZDDM\": \"DXMS\',\'T.DXDM\"\n      }\n    }\n  },\n	\"ZHGZ\":{\n		\"YOBJ.C', '{\n	//XITONGCANSHU\n  \"SYS\": {\n		\"DCWJM\": \"SHUJUDUIXIANGDAOCHUWENJIANMINGCHENGZIDINGYI\",\n    \"FIELDS\": {\n      \"SSZZD\": {\n        \"ZDDM\": \"DXMC\",\n        \"ZDMS\": \"SOUSUOZHUZIDUAN\"\n      },\n      \"PYJP\": {\n        \"ZDMS\": \"PINYINJIANPIN\",\n        \"ZDDM\": \"DXJP\"\n      },\n      \"PYQP\": {\n        \"ZDMS\": \"PINYINQUANPIN\",\n        \"ZDDM\": \"DXQP\"\n      },\n      \"SSZDLB\": {\n        \"ZDMS\": \"SOUSUOZIDUANL', NULL, '20221129151045', '20240709232758', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('BE42BE57470146F9A5F945CC88BB6E29', 'SYS_QX_QXXX.cds.oracle', 99999, 'SYS_SJGL_APPCONFIG', 'SELECT\n  t.id,\n	t.mc NAME,\n	t.tb icon,\n	t.tptb,\n	t.mc,\n	t.dm,\n	t.ms,\n	t.DZLX,\n	t.DKFS,\n	t.FQX,\n	t.KZXX,\n	t.LX,\n	( CASE  WHEN t.dzlx=\'05\' THEN  #{globalUse(\'util.expConcatWs\',{\"list\":[\"app.dz\",\"t.dz\"]\\})} ELSE t.dz END) dz,\n/*if(!isEmpty(yobj.dqjs)){*/\n	(\n	SELECT\n		count( 1 ) \n	FROM\n		sys_qx_jsqxgl jq\n		INNER JOIN sys_qx_jsxx js ON js.id = jq.js \n	WHERE\n		js.id = #{yobj.dqjs}\n		\n		AND js.yxx = \'1\' \n		AND jq.yxx = \'1\' \n		AND jq.qx = t.id \n	) checked,\n/*}*/\n	(\n	SELECT\n		count( 1 ) \n	FROM\n		SYS_QX_QXXX t1 \n	WHERE\n		t1.yxx = \'1\' \n		AND t1.fqx = t.id \n		/*if(yobj.treeModel==\'cds\'){*/\n		AND t1.lx != \'03\' \n		/*}*/\n		\n	) parent ,\n  dx.dxdm\nFROM\n	SYS_QX_QXXX t\n	LEFT JOIN sys_qx_app app ON app.dm = t.SSYY \n	left join sys_sjgl_sjdx dx on dx.id = t.sjdx\nWHERE\n	t.yxx = \'1\' \n	-- @if(sys.zdlb!=\"PC\"){\n	  and t.zcsjd = \'1\'\n	-- @}\n	/*if(!isEmpty(yobj.fqx)){*/\n	AND (t.dm LIKE #{yobj.fqx+\"\\\\_%\"} escape \'\\\' or t.dm = #{yobj.fqx})\n/*}else if(!isEmpty(yobj.treeRoot)){*/\n	AND (t.dm LIKE #{yobj.treeRoot+\"\\\\_%\"} escape \'\\\' or t.dm = #{yobj.treeRoot})\n/*}else{*/\n			AND t.fqx IS NULL \n			/*}*/\n/*if(yobj.treeModel==\'cds\'){*/\n			AND (t.lx != \'03\' or t.dz is not null)\n/*}*/\n/*if(yobj.treeModel==\'cds\'){*/\n			AND EXISTS (\n			SELECT\n				qx.dm \n			FROM\n				sys_qx_qxxx qx\n				INNER JOIN sys_qx_jsqxgl jq ON qx.id = jq.qx \n				AND jq.yxx = \'1\'\n				INNER JOIN sys_qx_jsxx js ON js.id = jq.js \n				AND js.yxx = \'1\' \n			WHERE\n				qx.yxx = \'1\' \n				AND ( js.dm IN ( \'ADMIN_DLYH_LSYH\' \n-- @if(user.yhdm != \'lsyh\') {\n						, \'ADMIN_DLYH\' \n-- @}\n						) \n-- @for(e in user.jsMap) {\n					OR js.dm LIKE #{e.key+\"%\"}\n-- @}\n				) \n			AND qx.id = t.id \n	) \n/*}*/\n order by t.px asc', '获取菜单树的全部数据，然后代码中组建为树形结构', 'SELECT\n  T.ID,\n	T.MC NAME,\n	T.TB ICON,\n	T.TPTB,\n	T.MC,\n	T.DM,\n	T.MS,\n	T.DZLX,\n	T.DKFS,\n	T.FQX,\n	T.KZXX,\n	T.LX,\n	( CASE  WHEN T.DZLX=\'05\' THEN  #{GLOBALUSE(\'UTIL.EXPCONCATWS\',{\"LIST\":[\"APP.DZ\",\"T.DZ\"]\\})} ELSE T.DZ END) DZ,\n/*IF(!ISEMPTY(YOBJ.DQJS)){*/\n	(\n	SELECT\n		COUNT( 1 ) \n	FROM\n		SYS_QX_JSQXGL JQ\n		INNER JOIN SYS_QX_JSXX JS ON JS.ID = JQ.JS \n	WHERE\n		JS.ID = #{YOBJ.DQJS}\n		\n		AND JS.YXX = \'1\' ', 'SELECT\n  T.ID,\n	T.MC NAME,\n	T.TB ICON,\n	T.TPTB,\n	T.MC,\n	T.DM,\n	T.MS,\n	T.DZLX,\n	T.DKFS,\n	T.FQX,\n	T.KZXX,\n	T.LX,\n	( CASE  WHEN T.DZLX=\'05\' THEN  #{GLOBALUSE(\'UTIL.EXPCONCATWS\',{\"LIST\":[\"APP.DZ\",\"T.DZ\"]\\})} ELSE T.DZ END) DZ,\n/*IF(!ISEMPTY(YOBJ.DQJS)){*/\n	(\n	SELECT\n		COUNT( 1 ) \n	FROM\n		SYS_QX_JSQXGL JQ\n		INNER JOIN SYS_QX_JSXX JS ON JS.ID = JQ.JS \n	WHERE\n		JS.ID = #{YOBJ.DQJS}\n		\n		AND JS.YXX = \'1\' ', NULL, '20220411142801', '20231009153545', NULL, NULL, '1', '系统管理员', 'sys', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('C2C3F609CC6F4AAABC46455821F60140', 'DEFAULT.dis.greenplum', 99999, 'SYS_SJGL_APPCONFIG', 'select T.col_name AS zddm,\n       z.zdms AS zdms,\n       T.col_type AS zdlx,\n       CASE\n         WHEN T.col_len IS NOT NULL THEN\n          T.col_len\n         ELSE\n          T.col_prec\n       END AS zdcd\n  FROM (SELECT aa.*, bb.zdms\n          FROM (SELECT A.ordinal_position         AS col_num,\n                       A                          . COLUMN_NAME AS col_name,\n                       A.data_type                AS col_type,\n                       A.character_maximum_length AS col_len,\n                       A.numeric_precision        AS col_prec\n                  FROM information_schema. COLUMNS A\n                 WHERE A . TABLE_NAME = LOWER(\'${tableName}\')\n                      /* if(!isEmpty(yobj.dxgs)){*/\n                   AND table_schema = \'${yobj.dxgs}\'\n                      /* }else  if(!isEmpty(owner)){*/\n                   AND table_schema = \'${owner}\'\n                /* }*/\n                ) AS aa\n          LEFT JOIN (SELECT objsubid, description AS zdms\n                      FROM pg_description\n                     WHERE objoid = (SELECT relid\n                                       FROM pg_stat_all_tables\n                                      WHERE relname = LOWER(\'${tableName}\')\n                                           /* if(!isEmpty(yobj.dxgs)){*/\n                                        AND schemaname= \'${yobj.dxgs}\'\n                                           /* }else  if(!isEmpty(owner)){*/\n                                        AND schemaname = \'${owner}\'\n                                     /* }*/\n                                     )) AS bb\n            ON aa.col_num = bb.objsubid\n         ORDER BY aa.col_num) T\n  LEFT JOIN (SELECT attr.attname AS zddm,\n                    col_description(attr.attrelid, attr.attnum) AS zdms\n               FROM pg_attribute attr\n               LEFT JOIN pg_class clazz\n                 ON attr.attrelid = clazz.oid\n               LEFT JOIN pg_type C\n                 ON attr.attrelid = C.oid\n              WHERE clazz.relname = LOWER(\'${tableName}\')\n                AND attr.attnum > 0) z\n    ON T.col_name = z.zddm', NULL, NULL, NULL, NULL, '20181223155302', '20220608142851', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('CC291F6C42F04098A740DCBCC11A260C', 'SYS_QX_FWQ.scjkrw', 99999, 'SYS_SJGL_APPCONFIG', 'select id jtrw,ip rwdm,mc rwmc,\'4\' rwlx,\'99\' rwlb,\'1\' rwdj \n   from SYS_QX_FWQ t \n   where 1=1 \n   /*if (!isEmpty(sys.ids)){*/\n   	and t.id in (#{join(sys.ids)})\n   /*}*/', NULL, 'SELECT ID JTRW,IP RWDM,MC RWMC,\'4\' RWLX,\'99\' RWLB,\'1\' RWDJ \n   FROM SYS_QX_FWQ T \n   WHERE 1=1 \n   /*IF (!ISEMPTY(SYS.IDS)){*/\n   	AND T.ID IN (#{JOIN(SYS.IDS)})\n   /*}*/', 'SELECT ID JTRW,IP RWDM,MC RWMC,\'4\' RWLX,\'99\' RWLB,\'1\' RWDJ \n   FROM SYS_QX_FWQ T \n   WHERE 1=1 \n   /*IF (!ISEMPTY(SYS.IDS)){*/\n   	AND T.ID IN (#{JOIN(SYS.IDS)})\n   /*}*/', NULL, '20190925185138', '20211205140420', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('CC5CE903871048AFA91791CF34FEE6FF', 'zd.SYS_COMMON_ORG.mysql', 99999, 'SYS_SJGL_APPCONFIG', 'select id dm,jgmc as mc,sjjg upnode,px,\nCONCAT(jgjc,jgdm,jgbm,jcjp) as search_key \nfrom  sys_qx_jgxx org where org.yxx=\'1\'', NULL, 'SELECT ID DM,JGMC AS MC,SJJG UPNODE,PX,\nCONCAT(JGJC,JGDM,JGBM,JCJP) AS SEARCH_KEY \nFROM  SYS_QX_JGXX ORG WHERE ORG.YXX=\'1\'', 'SELECT ID DM,JGMC AS MC,SJJG UPNODE,PX,\nCONCAT(JGJC,JGDM,JGBM,JCJP) AS SEARCH_KEY \nFROM  SYS_QX_JGXX ORG WHERE ORG.YXX=\'1\'', NULL, '20220313173115', '20220912205501', NULL, NULL, '0', '系统管理员', 'sys', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('ce8d3ee61b5611ee912d000c29f304ac', 'DEFAULT.select.elastic_search', 99999, 'SYS_SJGL_APPCONFIG', '/*\n//查询字段列表\nvar selectField = \"\";\n//查询条件\nvar whereStr = \"\";\n//搜索字段列表\nvar sszdlb = null;\n//设置查询的字段列表\nfor(e in fields){\n   var field = e.value;\n	 if(!isEmpty(sys.fwdm)){\n	     if((field.lbzs==\"1\"&&!su.contains(field.zdywlb,\"99\"))||(sys.cllx==\"hcfw\"&&\"99\"!=field.zdywlb)||(sys.fwfs==\"2\"&&\"99\"!=field.zdywlb)){\n       	   selectField = selectField + \",t.\\\"\" + field.yszddm+\"\\\"\";\n			}\n	 }else if(!su.contains(field.zdywlb,\"99\")&&(field.xqzs==\"1\"||field.bjzs==\"1\"||field.lbzs==\"1\"||field.zddm==sjdx.zjzd)){\n       selectField = selectField + \",t.\\\"\" + field.yszddm+\"\\\"\";\n   }\n}\n//树形结构处理\nif(null!=cllxkz[\'select\'].tree.hasChild!){\n   var tree = cllxkz[\'select\'].tree;\n   //查询该节点是否有子节点\n   selectField = selectField + \",(select (case when count(1)>0 then \'true\' else \'false\' end) from \"+sql.from+\" tree where tree.\"+tree.parentField+\"=t.\"+tree.rowField+\")\" + tree.hasChild;\n}\n\nif(!isEmpty(sql.qczd)){\n    //去重时只要去重字段和主键\n    selectField = \",t.\"+sql.qczd;\n		if(sql.qczd!=sjdx.zjzd){\n		  selectField = selectField+\",t.\"+sjdx.zjzd;\n		}\n    //去重查询\n    whereStr = \" and (\";\n		for(var i=0;i<sql.qcList.~size;i++){\n    	whereStr += \" t.\"+sql.qczd+\" in (#{join(sql.qcList[\"+i+\"])}) or\";\n		}\n		whereStr = su.substring(whereStr,0,su.length(whereStr)-3)+\")\";\n}else if(!isEmpty(sys.ids)){\n    //id列表场景：不再处理其他查询条件\n    whereStr = \" and t.\"+sjdx.zjzd+\" in (#{join(sys.ids)})\";\n}else if(!isEmpty(sjdx.zjzd)&&!isEmpty(yobj[sjdx.zjzd])){\n   //主键存在，则只查询主键\n   whereStr = \" and t.\"+sjdx.zjzd+\" =#{yobj.\"+sjdx.zjzd+\"}\";\n}else{\n  if(null!=cllxkz[\'select\'].tree.hasChild!){\n     //树形结构查询场景\n     var tree = cllxkz[\'select\'].tree;\n      //是否树形结构查询条件\n      var sfsxjgField = tree.sfsxjgField!;\n     if(isEmpty(yobj[tree.parentField])&&(sfsxjgField==null||!(yobj[sfsxjgField]==\'0\'))){\n         //若是没有传父节点，且没有要求不按树形结构查询，则默认查所有根节点\n         whereStr = \" and t.\"+tree.parentField+\"  is null\";\n     }\n  }\n  //简拼全拼支持\n  if(!isEmpty(sys.fields.sszzd)){\n     var value = yobj[sys.fields.sszzd.zddm];\n     if(isEmpty(value)){\n         value = sys.searchKey;\n         mu.safeAddToMap(yobj,sys.fields.sszzd.zddm,value);\n     }\n     if(!isEmpty(value)){\n       sszdlb = \"\'t.\"+sys.fields.sszzd.zddm+\"\'\";\n       if(!isEmpty(sys.fields.pyjp)){\n            sszdlb = sszdlb+\",\'t.\"+sys.fields.pyjp.zddm+\"\'\";\n       }\n       if(!isEmpty(sys.fields.pyqp)){\n            sszdlb = sszdlb+\",\'t.\"+sys.fields.pyqp.zddm+\"\'\";\n       }\n       if(!isEmpty(sys.fields.sszdlb)){\n            sszdlb = sszdlb+\",\'t.\"+sys.fields.sszdlb.zddm+\"\'\";\n       }\n       whereStr = whereStr + \" and upper(#{globalUse(\'util.expConcatWs\',{\'list\':[\"+sszdlb+\"]\\\\})}) like upper(#{\'%\'+yobj.\"+sys.fields.sszzd.zddm+\"+\'%\'})\";\n     }\n  }\n  //循环生成字段\n  for(e in fields){\n   var field = e.value;\n     if(su.contains(field.zdywlb,\"99\")){\n          //虚拟字段\n          continue;\n     }\n     if((sszdlb!=null&&sys.fields.sszzd.zddm==field.zddm)||isEmpty(yobj[field.zddm])){\n          //搜索主字段或该字段值为空\n          continue;\n     }\n     if(yobj[field.zddm]==\'my-null\'){\n           whereStr = whereStr + \" and t.\\\"\"+field.yszddm+\"\\\" is null\";\n     }else if(yobj[field.zddm]==\'my-not-null\'){\n           whereStr = whereStr + \" and t.\\\"\"+field.yszddm+\"\\\" is not null\";\n     }else if((\"$select\"==field.kjlx&&field.zddx==\'1\')||\"$checkbox\"==field.kjlx){\n          //字典多选支持\n         var arr = su.split(yobj[field.zddm], \",\");\n         mu.safeAddToMap(yobj,field.zddm+\"_arr\",arr);\n         var idx=0;\n         for(var a=0;a<arr.~size;a++){\n             if(idx==0){\n               if(a==\'my-null\'){\n                 whereStr = whereStr + \" and (t.\\\"\"+field.yszddm+\"\\\" is null \";\n               }else{\n                 whereStr = whereStr + \" and (t.\\\"\"+field.yszddm+\"\\\" like #{\'%\'+yobj.\"+field.zddm+\"_arr[\"+a+\"]+\'%\'} \";\n               }\n             }else{\n               if(a==\'my-null\'){\n                 whereStr = whereStr + \" or t.\\\"\"+field.yszddm+\"\\\"  is null\";\n               }else{\n                 whereStr = whereStr + \" or t.\\\"\"+field.yszddm+\"\\\" like #{\'%\'+yobj.\"+field.zddm+\"_arr[\"+a+\"]+\'%\'} \";\n               }\n             }\n             idx=idx+1;\n         }\n         whereStr = whereStr + \")\";\n     }else if(\"$select\"==field.kjlx||\"$radio\"==field.kjlx||\"ElCascader\"==field.kjlx\n		 		||\"$switch\"==field.kjlx){\n           whereStr = whereStr + \" and t.\\\"\"+field.yszddm+\"\\\"\"+ su.addInput(field.zddm,yobj[field.zddm]);\n     }else if(\"suggest\"==field.kjlx){\n           mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm+\"_text\"]+\"%\");\n           whereStr = whereStr + \" and t.\\\"\"+field.yszddm+\"\\\"\"+ su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n     }else if(\"ElDatePicker\"==field.kjlx){\n           su.clEqDate(field,yobj);\n           if(field.hdgs==\'date\'){\n                    //支持date类型的时间\n                    if(!isEmpty(yobj[field.zddm+\"_start\"])){\n                      whereStr = whereStr + \" and t.\\\"\"+field.yszddm+\"\\\" >=to_date(\'\"+yobj[field.zddm+\"_start\"]+\"\',\'YYYYMMDDHH24MISS\')\";\n                    }\n                    if(!isEmpty(yobj[field.zddm+\"_end\"])){\n                      whereStr = whereStr + \" and t.\\\"\"+field.yszddm+\"\\\" <=to_date(\'\"+yobj[field.zddm+\"_end\"]+\"\',\'YYYYMMDDHH24MISS\')\";\n                    }\n           }else{\n                    if(!isEmpty(yobj[field.zddm+\"_start\"])){\n                      whereStr = whereStr + \" and t.\\\"\"+field.yszddm+\"\\\" >=#{yobj.\"+field.zddm+\"_start}\";\n                    }\n                    if(!isEmpty(yobj[field.zddm+\"_end\"])){\n                      whereStr = whereStr + \" and t.\\\"\"+field.yszddm+\"\\\" <=#{yobj.\"+field.zddm+\"_end}\";\n                    }\n           }\n     }else if(\"ElInputNumber\"==field.kjlx){\n					if(yobj[field.zddm].~size>0&&!isEmpty(yobj[field.zddm][0])){\n						whereStr = whereStr + \" and t.\\\"\"+field.yszddm+\"\\\" >=#{\"+yobj[field.zddm][0]+\"}\";\n					}\n					if(yobj[field.zddm].~size>1&&!isEmpty(yobj[field.zddm][1])){\n						whereStr = whereStr + \" and t.\\\"\"+field.yszddm+\"\\\" <=#{\"+yobj[field.zddm][1]+\"}\";\n					}\n     }else{\n		     whereStr = whereStr + \" and t.\\\"\"+field.yszddm+\"\\\"\";\n          //默认处理方式\n         if(!isEmpty(yobj[field.zddm])){\n             if(su.indexOf(yobj[field.zddm]+\"\", \"%\")>-1){\n                //用户输入有%，则按用户输入进行模糊即可\n                mu.safeAddToMap(yobj,field.zddm+\"_like\",yobj[field.zddm]);\n                whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n             }else if(field.cxms==\'1\'){\n                //模糊搜索\n                mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm]+\"%\");\n                whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n             }else if(field.cxms==\'2\'){\n                //右模糊搜索\n                mu.safeAddToMap(yobj,field.zddm+\"_like\",yobj[field.zddm]+\"%\");\n                whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n             }else if(field.cxms==\'3\'){\n                //左模糊搜索\n                mu.safeAddToMap(yobj,field.zddm+\"_like\",\"%\"+yobj[field.zddm]);\n                whereStr = whereStr + su.addInput(field.zddm,yobj[field.zddm+\"_like\"]);\n             }else{\n                //精确搜索\n                whereStr = whereStr + \" =#{yobj[\'\"+field.zddm+\"\']}\";\n             }\n          }\n     }\n  }\n}\n\n//权限过滤条件\nvar authWhere = \"\";\nif(!has(user)){\n    //用户为空，初进系统\n}else if(user.qxMap[\'KFZFW_GLY\']!=null){\n    //管理员，不能查看系统管理员(sys)创建的数据。\n    if(!isEmpty(sys.fields.cjrdm)){\n        authWhere = \" and t.\"+sys.fields.cjrdm.zddm+\"<>\'BC5D77315CA84C6C807988E3CD17E70D\'\";\n    }\n}else if(user.qxMap[\'KFZFW_DWGLY\']!=null){\n    //单位管理员，只能管理本单位\n    if(!isEmpty(sys.fields.cjrdwdm)&&has(user)){\n        authWhere = \" and t.\"+sys.fields.cjrdwdm.zddm+\"=\'\"+user.jgxx.id+\"\'\";\n    }\n    if(user.qxMap[\'KFZFW_GLZDW\']!=null){\n        //管理子单位\n    \n    }\n}else if(user.qxMap[\'KFZFW_GLZDW\']!=null){\n    //管理子单位\n    \n}\n\nif(!has(user)){\n    //用户为空，初进系统\n}else if(user.qxMap[\'KFZFW_SYS\']!=null){\n    //系统管理员，无权限过滤\n    authWhere = \"\";\n}else if(isEmpty(authWhere)){\n    //普通用户,或上述权限没有生效只能查看本人数据\n    if(!isEmpty(sys.fields.cjrdm)&&has(user)&&user!=null){\n        authWhere = \" and t.\"+sys.fields.cjrdm.zddm+\"=\'\"+user.id+\"\'\";\n    }\n}\n\n//处理排序\nvar orderBy = page.orderBy;\nif(isEmpty(orderBy)){\n    orderBy = sjdx.mrpx;\n}\nif(!isEmpty(orderBy)){\n    orderBy = \"order by \"+orderBy;\n}\n\nselectField = su.substring(selectField,1);\n\n//设置变量，备用\nmu.safeAddToMap(sql,\"selectField\",selectField);\nmu.safeAddToMap(sql,\"whereStr\",whereStr);\nmu.safeAddToMap(sql,\"authWhere\",authWhere);\nmu.safeAddToMap(sql,\"orderBy\",orderBy);\n//要上天，逆天的操作\n//mydb.update(mydb.use(),\"insert into test_sjgl_1(xm) select to_char(sysdate,\'yyyymmddhh24miss\') from dual\",null);\n*/\nselect\n-- @pageTag(){\n ${sql.selectField}\n-- @}\n  from ${sjdx.jtdx} t\n-- @where(){\n        ${sql.whereStr}\n-- @}\n-- @pageIgnoreTag(){\n	${sql.orderBy}\n-- @}', '生成es查询语句', '/*\n//CXZDLB\nVAR SELECTFIELD = \"\";\n//CXTJ\nVAR WHERESTR = \"\";\n//SSZDLB\nVAR SSZDLB = NULL;\n//SZCXDZDLB\nFOR(E IN FIELDS){\n   VAR FIELD = E.VALUE;\n	 IF(!ISEMPTY(SYS.FWDM)){\n	     IF((FIELD.LBZS==\"1\"&&!SU.CONTAINS(FIELD.ZDYWLB,\"99\"))||(SYS.CLLX==\"HCFW\"&&\"99\"!=FIELD.ZDYWLB)||(SYS.FWFS==\"2\"&&\"99\"!=FIELD.ZDYWLB)){\n       	   SELECTFIELD = SELECTFIELD + \",T.\\\"\" + FIELD.YSZDDM+\"\\\"\";\n			}\n	 }ELSE IF(!SU.CON', '/*\n//CHAXUNZIDUANLIEBIAO\nVAR SELECTFIELD = \"\";\n//CHAXUNTIAOJIAN\nVAR WHERESTR = \"\";\n//SOUSUOZIDUANLIEBIAO\nVAR SSZDLB = NULL;\n//SHEZHICHAXUNDEZIDUANLIEBIAO\nFOR(E IN FIELDS){\n   VAR FIELD = E.VALUE;\n	 IF(!ISEMPTY(SYS.FWDM)){\n	     IF((FIELD.LBZS==\"1\"&&!SU.CONTAINS(FIELD.ZDYWLB,\"99\"))||(SYS.CLLX==\"HCFW\"&&\"99\"!=FIELD.ZDYWLB)||(SYS.FWFS==\"2\"&&\"99\"!=FIELD.ZDYWLB)){\n       	   SELECTFIELD = SELECTFIELD ', NULL, '20230706011014', '20230706194536', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('D77F3FED4D674652AC804F874FC751F8', 'SYS_ZNJH_JHRW.insert', 99999, 'SYS_SJGL_APPCONFIG', '/*\ndict.clearDict(\"SYS_ZNJH_JHRW\");\n*/\n${sql.defaultSql}', NULL, NULL, '/*\nDICT.CLEARDICT(\"SYS_ZNJH_JHRW\");\n*/\n${SQL.DEFAULTSQL}', NULL, '20221106230136', '20221106230136', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('D8173C7BB62F4FBD8C97D666A5F10FC6', 'sjdx.jcxx2', 99999, 'SYS_SJGL_APPCONFIG', '//本默认配置优先级高于用户前端传参，避免系统入侵\n{\n  //系统参数\n  \"sys\": {\n    //已找到记录，传入主键是否能查询到对应的记录\n    \"yzdjl\": false,\n    //事务提交量，主要用于批量上传时，多少条数据提交一次事务，默认5000\n    \"swtjl\": 5000,\n    //物理删除，默认false，配置该数据对象是否允许物理删除\n    \"wlsc\": false\n  },\n	\"znjh\":{\n		//直接传入sql代替源sql，只允许内部采用\n		\"sql\":\"\"\n	}\n}', '数据对象基础信息2，优先级高于前端请求参数，低于数据对象等后端配置，避免前端入侵', '//BMRPZYXJGYYHQDCC，BMXTRQ\n{\n  //XTCS\n  \"SYS\": {\n    //YZDJL，CRZJSFNCXDDYDJL\n    \"YZDJL\": FALSE,\n    //SWTJL，ZYYYPLSCS，DSTSJTJYCSW，MR5000\n    \"SWTJL\": 5000,\n    //WLSC，MRFALSE，PZGSJDXSFYXWLSC\n    \"WLSC\": FALSE\n  },\n	\"ZNJH\":{\n		//ZJCRSQLDTYSQL，ZYXNBCY\n		\"SQL\":\"\"\n	}\n}', '//BENMORENPEIZHIYOUXIANJIGAOYUYONGHUQIANDUANCHUANCAN，BIMIANXITONGRUQIN\n{\n  //XITONGCANSHU\n  \"SYS\": {\n    //YIZHAODAOJILU，CHUANRUZHUJIANSHIFOUNENGCHAXUNDAODUIYINGDEJILU\n    \"YZDJL\": FALSE,\n    //SHIWUTIJIAOLIANG，ZHUYAOYONGYUPILIANGSHANGCHUANSHI，DUOSHAOTIAOSHUJUTIJIAOYICISHIWU，MOREN5000\n    \"SWTJL\": 5000,\n    //WULISHANCHU，MORENFALSE，PEIZHIGAISHUJUDUIXIANGSHIFOUYUNXUWULISHANCHU\n    \"WL', NULL, '20220108190909', '20221104105523', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('D8308E0D3CCF4DA5B6A24208F38D68A9', 'DEFAULT.wlplsc', 99999, 'SYS_SJGL_APPCONFIG', '/*\nif(su.isBlank(sjdx.yxxzd)){\n*/\ndelete from ${sql.from} t where 1=1 \n/*if(!su.isBlank(sys.ids)){*/\nand t.${sjdx.zjzd} in (#{join(sys.ids)})\n/*}else if(!su.isBlank(sql.whereStr)){*/\n${sql.whereStr} ${sql.authWhere} \n/*}else{*/\nand 1=2\n/*}*/\n/*}else{*/\ndelete from ${sql.from} t where ${sjdx.yxxzd}=\'0\' \n/*if(!su.isBlank(sys.ids)){*/\nand t.${sjdx.zjzd} in (#{join(sys.ids)})\n/*}else if(!su.isBlank(sql.whereStr)){*/\n${sql.whereStr} ${sql.authWhere} \n/*}else{*/\nand 1=2\n/*}*/\n/*}*/', '物理删除，没有设置有效性字段则直接删除，否则只物理删除无效的', '/*\nIF(SU.ISBLANK(SJDX.YXXZD)){\n*/\nDELETE FROM ${SQL.FROM} T WHERE 1=1 \n/*IF(!SU.ISBLANK(SYS.IDS)){*/\nAND T.${SJDX.ZJZD} IN (#{JOIN(SYS.IDS)})\n/*}ELSE IF(!SU.ISBLANK(SQL.WHERESTR)){*/\n${SQL.WHERESTR} ${SQL.AUTHWHERE} \n/*}ELSE{*/\nAND 1=2\n/*}*/\n/*}ELSE{*/\nDELETE FROM ${SQL.FROM} T WHERE ${SJDX.YXXZD}=\'0\' \n/*IF(!SU.ISBLANK(SYS.IDS)){*/\nAND T.${SJDX.ZJZD} IN (#{JOIN(SYS.IDS)})\n/*}ELSE IF(!SU.ISBLANK(SQ', '/*\nIF(SU.ISBLANK(SJDX.YXXZD)){\n*/\nDELETE FROM ${SQL.FROM} T WHERE 1=1 \n/*IF(!SU.ISBLANK(SYS.IDS)){*/\nAND T.${SJDX.ZJZD} IN (#{JOIN(SYS.IDS)})\n/*}ELSE IF(!SU.ISBLANK(SQL.WHERESTR)){*/\n${SQL.WHERESTR} ${SQL.AUTHWHERE} \n/*}ELSE{*/\nAND 1=2\n/*}*/\n/*}ELSE{*/\nDELETE FROM ${SQL.FROM} T WHERE ${SJDX.YXXZD}=\'0\' \n/*IF(!SU.ISBLANK(SYS.IDS)){*/\nAND T.${SJDX.ZJZD} IN (#{JOIN(SYS.IDS)})\n/*}ELSE IF(!SU.ISBLANK(SQ', NULL, '20181219103306', '20231122224558', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('d8a68c97fab644e2858b101ce31e1676', 'zd.SYS_YXJK_JKRW.oracle', 99999, 'SYS_SJGL_APPCONFIG', 'select id dm,\n       (case\n         when rwlx = \'3\' then\n          (select dxmc\n             from sys_sjgl_sjdx tt\n            where substr(jtrw, 1, instr(jtrw, \'#\') - 1) = tt.dxdm) || \'-\'\n         else\n          \'\'\n       end) || rw.rwmc as mc,\n       px,\n       \'\' as search_key\n  from sys_yxjk_jkrw rw\n where rw.yxx = \'1\'', NULL, 'SELECT ID DM,\n       (CASE\n         WHEN RWLX = \'3\' THEN\n          (SELECT DXMC\n             FROM SYS_SJGL_SJDX TT\n            WHERE SUBSTR(JTRW, 1, INSTR(JTRW, \'#\') - 1) = TT.DXDM) || \'-\'\n         ELSE\n          \'\'\n       END) || RW.RWMC AS MC,\n       PX,\n       \'\' AS SEARCH_KEY\n  FROM SYS_YXJK_JKRW RW\n WHERE RW.YXX = \'1\'', 'SELECT ID DM,\n       (CASE\n         WHEN RWLX = \'3\' THEN\n          (SELECT DXMC\n             FROM SYS_SJGL_SJDX TT\n            WHERE SUBSTR(JTRW, 1, INSTR(JTRW, \'#\') - 1) = TT.DXDM) || \'-\'\n         ELSE\n          \'\'\n       END) || RW.RWMC AS MC,\n       PX,\n       \'\' AS SEARCH_KEY\n  FROM SYS_YXJK_JKRW RW\n WHERE RW.YXX = \'1\'', NULL, '20240606161134', '20240606161134', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('D9BAF7A5150C49E98A169E4991C24FF9', 'DEFAULT.dis.hwmpp', 99999, 'SYS_SJGL_APPCONFIG', 'select T.col_name AS zddm,\n       z.zdms AS zdms,\n       T.col_type AS zdlx,\n       CASE\n         WHEN T.col_len IS NOT NULL THEN\n          T.col_len\n         ELSE\n          T.col_prec\n       END AS zdcd\n  FROM (SELECT aa.*, bb.zdms\n          FROM (SELECT A.ordinal_position         AS col_num,\n                       A                          . COLUMN_NAME AS col_name,\n                       A.data_type                AS col_type,\n                       A.character_maximum_length AS col_len,\n                       A.numeric_precision        AS col_prec\n                  FROM information_schema. COLUMNS A\n                 WHERE A . TABLE_NAME = LOWER(\'${tableName}\')\n                      /* if(!isEmpty(yobj.dxgs)){*/\n                   AND table_schema = \'${yobj.dxgs}\'\n                      /* }else  if(!isEmpty(owner)){*/\n                   AND table_schema = \'${owner}\'\n                /* }*/\n                ) AS aa\n          LEFT JOIN (SELECT objsubid, description AS zdms\n                      FROM pg_description\n                     WHERE objoid = (SELECT relid\n                                       FROM pg_stat_all_tables\n                                      WHERE relname = LOWER(\'${tableName}\')\n                                           /* if(!isEmpty(yobj.dxgs)){*/\n                                        AND schemaname= \'${yobj.dxgs}\'\n                                           /* }else  if(!isEmpty(owner)){*/\n                                        AND schemaname = \'${owner}\'\n                                     /* }*/\n                                     )) AS bb\n            ON aa.col_num = bb.objsubid\n         ORDER BY aa.col_num) T\n  LEFT JOIN (SELECT attr.attname AS zddm,\n                    col_description(attr.attrelid, attr.attnum) AS zdms\n               FROM pg_attribute attr\n               LEFT JOIN pg_class clazz\n                 ON attr.attrelid = clazz.oid\n               LEFT JOIN pg_type C\n                 ON attr.attrelid = C.oid\n              WHERE clazz.relname = LOWER(\'${tableName}\')\n                AND attr.attnum > 0) z\n    ON T.col_name = z.zddm\n', NULL, NULL, NULL, NULL, '20200403103335', '20200617160733', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('D9F69E531C474042A0B84B1F52C6C90F', 'SYS_YXJK_JKRW.getKettleAppID', 99999, 'SYS_SJGL_APPCONFIG', 'select to_char(sysdate,\'yyyymmddhh24miss\') curr_date from dual', NULL, 'SELECT TO_CHAR(SYSDATE,\'YYYYMMDDHH24MISS\') CURR_DATE FROM DUAL', 'SELECT TO_CHAR(SYSDATE,\'YYYYMMDDHH24MISS\') CURR_DATE FROM DUAL', NULL, '20190315200414', '20190315200414', NULL, NULL, '0', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
