INSERT INTO `sys_sjgl_dzd` VALUES ('dbedcfbaf6f711edb4ad000c29f304ac', 'zd.KETTLE_DEFAULT_JOB.oracle', 99999, 'SYS_SJGL_APPCONFIG', 'select id_job dm,\n       to_char(#{globalUse(\'util.expConcatWs\',{\'list\':[\'name\',\"\'[\'\",\'t.description\',\"\']\'\"]\\})}) as mc,\n       id_job px,\n       t.extended_description as search_key\n  from r_job t;ds=kettle_default', NULL, 'SELECT ID_JOB DM,\n       TO_CHAR(#{GLOBALUSE(\'UTIL.EXPCONCATWS\',{\'LIST\':[\'NAME\',\"\'[\'\",\'T.DESCRIPTION\',\"\']\'\"]\\})}) AS MC,\n       ID_JOB PX,\n       T.EXTENDED_DESCRIPTION AS SEARCH_KEY\n  FROM R_JOB T;DS=KETTLE_DEFAULT', 'SELECT ID_JOB DM,\n       TO_CHAR(#{GLOBALUSE(\'UTIL.EXPCONCATWS\',{\'LIST\':[\'NAME\',\"\'[\'\",\'T.DESCRIPTION\',\"\']\'\"]\\})}) AS MC,\n       ID_JOB PX,\n       T.EXTENDED_DESCRIPTION AS SEARCH_KEY\n  FROM R_JOB T;DS=KETTLE_DEFAULT', NULL, '20230520181952', '20230520182014', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
