INSERT INTO `sys_sjgl_dzd` VALUES ('E5516EB85FE640AAAB194A34658E6365', 'get.sjdx.params', 99999, 'SYS_SJGL_APPCONFIG', '{\n    \"sjdx\":{\n        \"id\":\"SYS_SJGL_SJDX\"\n    },\n    \"yobj\": {\n    },\n    \"sys\":{\n        \"cllx\":\"select\",\n        \"token\":\"权限key\",\n        \"userInfo\":\"用户信息，用于跨系统自动登陆\",\n        \"clientIp\":\"客户端ip\",\n        \"authCode\":\"SYS_SJGL_SJDX\"\n    },\n    \"user\":{\n\n    },\n    \"page\":{\n    \"totalRequired\":false\n\n    },\n    \"sql\":{\n        \"defaultSql\":\"默认sql\"\n    },\n    \"kzxx\":{\n\n    },\n    \"fields\":{\n\n    },\n    \"czrz\":{\n\n    }\n}                     ', '获取数据对象的基础参数', NULL, NULL, NULL, '20210915205731', '20231023184059', NULL, NULL, '0', '系统管理员', 'sys', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('E9099A6294AE4268B80BF7D15BA1BDF7', 'SYS_LOG_FWRZ_FWLTJ.getdata', 99999, 'SYS_SJGL_APPCONFIG', 'select *\n  from (select t.cjrdm, max(t.cjrxm) cjrxm, count(1) fwcs\n          from sys_log_fwzr t\n         group by t.cjrdm\n         order by count(1) desc)\n where rownum < 10\n', NULL, 'SELECT *\n  FROM (SELECT T.CJRDM, MAX(T.CJRXM) CJRXM, COUNT(1) FWCS\n          FROM SYS_LOG_FWZR T\n         GROUP BY T.CJRDM\n         ORDER BY COUNT(1) DESC)\n WHERE ROWNUM < 10\n', 'SELECT *\n  FROM (SELECT T.CJRDM, MAX(T.CJRXM) CJRXM, COUNT(1) FWCS\n          FROM SYS_LOG_FWZR T\n         GROUP BY T.CJRDM\n         ORDER BY COUNT(1) DESC)\n WHERE ROWNUM < 10\n', NULL, '20190506175842', '20190511172013', NULL, NULL, '0', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('ee055fd95de311ed8f08000c29f304ac', 'SYS_ZNJH_JHRW.update', 99999, 'SYS_SJGL_APPCONFIG', '/*\ndict.clearDict(\"SYS_ZNJH_JHRW\");\n*/\n${sql.defaultSql}', NULL, NULL, NULL, NULL, '20221106230145', '20221106230207', NULL, NULL, '1', '系统管理员', 'sys', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('EE3187B646AC47DF8E2E3BDD941CD1DC', 'DEFAULT.insert', 99999, 'SYS_SJGL_APPCONFIG', '/*\nvar insertf = \"\";\nvar values = \"\";\n//设置主键\nif(isEmpty(yobj[sjdx.zjzd])){\n        yobj[sjdx.zjzd]=su.getUUIDUpperStr();\n}\n//循环生成字段\nfor(ent in fields){\n     field = ent.value;\n     if(!su.contains(field.zdywlb,\"99\")&&!isEmpty(yobj[field.zddm])){\n          insertf = insertf+\",#{globalUse(\'util.expField\',{\'field\':\'\"+field.yszddm+\"\'\\\\})}\";\n          if(!sys.sjjy){\n             values = values+\",#{yobj.\"+field.zddm+\"}\";\n          }else if(field.kjlx==\'password\'){\n             values = values+\",\'\"+su.desEnByField(yobj[field.zddm],field)+\"\'\";\n          }else if(field.zdlx==\'DATE\'){\n             values = values+\",#{globalUse(\'util.expStr14ToDate\',{\'dateStr\':\'\"+yobj[field.zddm]+\"\'\\\\})}\";\n          }else{\n             values = values+\",#{yobj.\"+field.zddm+\"}\";\n          }\n     }\n}\nif(!isEmpty(sys.fields.sszzd.zddm!)&&!isEmpty(yobj[sys.fields.sszzd.zddm!])){\n     //设置简拼和全拼\n     if(!isEmpty(sys.fields.pyjp.zddm!)&&isEmpty(yobj[sys.fields.pyjp.zddm!])){\n          insertf = insertf+\",#{globalUse(\'util.expField\',{\'field\':\'\"+sys.fields.pyjp.zddm+\"\'\\\\})}\";\n          values = values+\",#{yobj[sys.fields.pyjp.zddm]}\";\n					classUtil.setVal(sys.fields.pyjp.zddm,su.substrByByte(su.getSimpleSpell(yobj[sys.fields.sszzd.zddm]),fields[sys.fields.pyjp.zddm].zdcd),yobj,null);\n     }\n     if(!isEmpty(sys.fields.pyjp.zddm!)&&isEmpty(yobj[sys.fields.pyqp.zddm!])){\n          insertf = insertf+\",#{globalUse(\'util.expField\',{\'field\':\'\"+sys.fields.pyqp.zddm+\"\'\\\\})}\";\n          values = values+\",#{yobj[sys.fields.pyqp.zddm]}\";\n					classUtil.setVal(sys.fields.pyqp.zddm,su.substrByByte(su.getFullSpell(yobj[sys.fields.sszzd.zddm]),fields[sys.fields.pyqp.zddm].zdcd),yobj,null);\n     }\n}\nif(has(user)){\n		if(!isEmpty(sys.fields.cjrdm.zddm!)&&isEmpty(yobj[sys.fields.cjrdm.zddm!])){\n          insertf = insertf+\",#{globalUse(\'util.expField\',{\'field\':\'\"+sys.fields.cjrdm.zddm+\"\'\\\\})}\";\n				values = values+\",#{user.id}\";\n		}\n		if(!isEmpty(sys.fields.cjrxm.zddm!)&&isEmpty(yobj[sys.fields.cjrxm.zddm!])){\n          insertf = insertf+\",#{globalUse(\'util.expField\',{\'field\':\'\"+sys.fields.cjrxm.zddm+\"\'\\\\})}\";\n				values = values+\",#{user.yhxm}\";\n		}\n		if(!isEmpty(sys.fields.cjrdwdm.zddm!)&&isEmpty(yobj[sys.fields.cjrdwdm.zddm!])){\n          insertf = insertf+\",#{globalUse(\'util.expField\',{\'field\':\'\"+sys.fields.cjrdwdm.zddm+\"\'\\\\})}\";\n				values = values+\",#{user.jgxx.id}\";\n		}\n		if(!isEmpty(sys.fields.cjrdwmc.zddm!)&&isEmpty(yobj[sys.fields.cjrdwmc.zddm!])){\n          insertf = insertf+\",#{globalUse(\'util.expField\',{\'field\':\'\"+sys.fields.cjrdwmc.zddm+\"\'\\\\})}\";\n				values = values+\",#{user.jgxx.jgmc}\";\n		}\n}\ninsertf = su.substring(insertf, 1);\nvalues = su.substring(values, 1);\n//mu.safeAddToMap(sql,\"insertf\",insertf);\n//mu.safeAddToMap(sql,\"values\",values);\nclassUtil.setVal(\"insertf\",insertf,sql,null);\nclassUtil.setVal(\"values\",values,sql,null);\n*/\ninsert into ${sql.from}\n  (${sql.insertf})\nvalues\n  (${sql.values})', NULL, '/*\nVAR INSERTF = \"\";\nVAR VALUES = \"\";\n//SZZJ\nIF(ISEMPTY(YOBJ[SJDX.ZJZD])){\n        YOBJ[SJDX.ZJZD]=SU.GETUUIDUPPERSTR();\n}\n//XHSCZD\nFOR(ENT IN FIELDS){\n     FIELD = ENT.VALUE;\n     IF(!SU.CONTAINS(FIELD.ZDYWLB,\"99\")&&!ISEMPTY(YOBJ[FIELD.ZDDM])){\n          INSERTF = INSERTF+\",#{GLOBALUSE(\'UTIL.EXPFIELD\',{\'FIELD\':\'\"+FIELD.YSZDDM+\"\'\\\\})}\";\n          IF(!SYS.SJJY){\n             VALUES = VALUES+\",#{YOB', '/*\nVAR INSERTF = \"\";\nVAR VALUES = \"\";\n//SHEZHIZHUJIAN\nIF(ISEMPTY(YOBJ[SJDX.ZJZD])){\n        YOBJ[SJDX.ZJZD]=SU.GETUUIDUPPERSTR();\n}\n//XUNHUANSHENGCHENGZIDUAN\nFOR(ENT IN FIELDS){\n     FIELD = ENT.VALUE;\n     IF(!SU.CONTAINS(FIELD.ZDYWLB,\"99\")&&!ISEMPTY(YOBJ[FIELD.ZDDM])){\n          INSERTF = INSERTF+\",#{GLOBALUSE(\'UTIL.EXPFIELD\',{\'FIELD\':\'\"+FIELD.YSZDDM+\"\'\\\\})}\";\n          IF(!SYS.SJJY){\n          ', NULL, '20181213112333', '20240709224914', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('F12D45A55F5D4134967D2422DB8E41A6', 'SYS_QX_JGXX1.xtdx', 99999, 'SYS_SJGL_APPCONFIG', 'SYS_QX_JGXX1,SYS_QX_JGXX2', '机构信息的协同对象，用于分表跨库', 'SYS_QX_JGXX1,SYS_QX_JGXX2', 'SYS_QX_JGXX1,SYS_QX_JGXX2', NULL, '20200721120004', '20200721120004', NULL, NULL, '1', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{}', '06');
INSERT INTO `sys_sjgl_dzd` VALUES ('F856A11EACB94BFAB410AB2DA1E143AF', 'SYS_ZNBK_RWSH_SHTC.update', 99999, 'SYS_SJGL_APPCONFIG', '/*\nvar setf = \",shrxm=#{user.yhxm},shrzjhm=#{user.id},shdw=#{user.jgxx.jgmc},shsj=#{globalUse(\"util.expDate14\")}\";\nif(su.isNotBlank(sjdx.zlzd)){\n    setf = setf+\",\"+sjdx.zlzd+\"=#{globalUse(\"util.expDate14\")}\";\n}\nvar whereStr = sjdx.zjzd+\"=#{yobj.\"+sjdx.zddmZjzd+\"}\";\n//循环生成字段\nfor(field in fieldList){\n     if(yobj[field.zddm]!=null&&field.zddm!=sjdx.zjzd&&!su.contains(field.zdywlb,\"99\")){\n          if(field.kjlx==\'password\'){\n             setf = setf+\",\"+field.zddm+\"=\'\"+su.desEnByField(yobj[field.zddm],field)+\"\'\";\n          }else{\n             setf = setf+\",\"+field.zddm+\"=#{yobj.\"+field.zddm+\"}\";\n          }\n     }\n }\n if(!isEmpty(kzxx.fields.sszzd)&&!isEmpty(yobj[kzxx.fields.sszzd.zddm])){\n     //设置简拼和全拼\n     if(!isEmpty(kzxx.fields.pyjp)&&su.length(yobj[kzxx.fields.sszzd.zddm])<200){\n          setf = setf+\",\"+kzxx.fields.pyjp.zddm+\"=#{yobj.pyjp}\";\n          mu.safeAddToMap(yobj,\"pyjp\",su.getSimpleSpell(yobj[kzxx.fields.sszzd.zddm]));\n     }\n     if(!isEmpty(kzxx.fields.pyqp)&&su.length(yobj[kzxx.fields.sszzd.zddm])<200){\n          setf = setf+\",\"+kzxx.fields.pyqp.zddm+\"=#{yobj.pyqp}\";\n          mu.safeAddToMap(yobj,\"pyqp\",su.getFullSpell(yobj[kzxx.fields.sszzd.zddm]));\n     }\n }\n setf = su.substring(setf, 1);\n*/\n/*if(myYzdjl!=true){*/\nerror:没有找到要修改的记录\n/*}else if(isEmpty(setf)){*/\nerror:没有要修改的信息\n/*}else{*/\nupdate /*if(!isEmpty(sjdx.dxgs)){*/ ${sjdx.dxgs}.${tableName}\n       /*}else{*/ ${tableName}\n/*}*/\n   set ${setf}\n where ${whereStr}\n/*}*/', '默认更新语句生成逻辑', '/*\nVAR SETF = \",SHRXM=#{USER.YHXM},SHRZJHM=#{USER.ID},SHDW=#{USER.JGXX.JGMC},SHSJ=#{GLOBALUSE(\"UTIL.EXPDATE14\")}\";\nIF(SU.ISNOTBLANK(SJDX.ZLZD)){\n    SETF = SETF+\",\"+SJDX.ZLZD+\"=#{GLOBALUSE(\"UTIL.EXPDATE14\")}\";\n}\nVAR WHERESTR = SJDX.ZJZD+\"=#{YOBJ.\"+SJDX.ZDDMZJZD+\"}\";\n//XHSCZD\nFOR(FIELD IN FIELDLIST){\n     IF(YOBJ[FIELD.ZDDM]!=NULL&&FIELD.ZDDM!=SJDX.ZJZD&&!SU.CONTAINS(FIELD.ZDYWLB,\"99\")){\n          ', '/*\nVAR SETF = \",SHRXM=#{USER.YHXM},SHRZJHM=#{USER.ID},SHDW=#{USER.JGXX.JGMC},SHSJ=#{GLOBALUSE(\"UTIL.EXPDATE14\")}\";\nIF(SU.ISNOTBLANK(SJDX.ZLZD)){\n    SETF = SETF+\",\"+SJDX.ZLZD+\"=#{GLOBALUSE(\"UTIL.EXPDATE14\")}\";\n}\nVAR WHERESTR = SJDX.ZJZD+\"=#{YOBJ.\"+SJDX.ZDDMZJZD+\"}\";\n//XUNHUANSHENGCHENGZIDUAN\nFOR(FIELD IN FIELDLIST){\n     IF(YOBJ[FIELD.ZDDM]!=NULL&&FIELD.ZDDM!=SJDX.ZJZD&&!SU.CONTAINS(FIELD.ZDYWLB,\"', NULL, '20210823164720', '20240523154205', NULL, NULL, '1', '系统管理员', 'sys', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', '{\n  \n}', '06');
