INSERT INTO `sys_sjgl_grbj` VALUES ('01', '系统参数', NULL, '9B5A99E235634E03976F347E023C3883', '99', '01', '1', 99999, '02', '# 系统参数\n\n如下为本系统全部参数信息，数据对象的扩展信息（kzxx）会合并到该信息中，就是说可以通过数据对象的扩展信息修改任何允许修改的系统参数。\n\n配置优先级：具体代码实现>数据对象中配置>默认配置2>前端传入>默认配置1。\n\n不是所有参数都支持前端传入，这个需要做权限控制，避免系统风险。\n\n```json\n{\n  //数据对象\n  \"sjdx\": {\n    \"id\": \"对象id\",\n    \"dxdm\": \"对象代码\",\n    \"dxmc\": \"对象名称\",\n    //对象的扩展信息会合并到系统参数的根对象下\n    \"kzxx\": {\n    },\n    //数据对象扩展，从对象扩展信息合并进来\n    \"tails\": {\n      ///////文本文件扩展//////////\n      //分隔符\n      \"fgf\":\"|\",\n      //文本限定符\n      \"wbxdf\":\"\",\n      //头部行数\n      \"tbhs\":1,\n      //编码方式\n      \"bmfs\":\"UTF-8\",\n      ///////文本文件扩展//////////\n//      //Excel场景 start\n        //sheet名称\n        \"sheet\":\"Sheet1\",\n        //起始行\n        \"startRow\":0,\n        //起始列\n        \"startColumn\":0\n//      //Excel场景 start\n    },\n  },\n  //原对象，一般是前端的表单数据，与对应表字段对应\n  \"yobj\": {\n    \"id\": \"数据主键;将根据该主键获取具体记录\",\n    \"cjsj\": \"创建时间\",\n    \"gxsj\": \"更新时间\",\n    \"yxx\": \"有效性\"\n  },\n  //根据yobj中的主键从数据库中读取的完整记录信息\n  \"obj\": {\n  },\n  //-------------按处理类型扩展 start-------------\n  \"cllxkz\": {\n    //处理类型：查询页面扩展\n    \"select\": {\n      //权限配置:参考系统中的：系统参数功能\n      \"qxpz\": {},\n      //树形列表：支持vxe树形配置的各种属性\n      \"tree\": {\n        \"transform\": true,\n        \"rowField\": \"树字段\",\n        \"parentField\": \"父节点对应的字段\",\n        \"hasChild\": \"是否有子节点的字段\",\n        //是否树形结构条件字段，不配置默认树形结构\n        \"sfsxjgField\": \"sfsxjg\",\n        //树形结构请求数据扩展\n        \"treeQqsjkz\":{\n          \"yobj.js\":\"formData.js\"\n        }\n      },\n      //表格的复选框相关配置，支持vxe的各复选框配置\n      \"checkboxConfig\": {\n\n      },\n      //页面扩展：这里设置的参数会合并到页面参数的根节点中\n      \"pagekz\": {\n        \"pagerConfig\": {\n          \"pageSize\": 1000\n        },\n        //定时刷新，120秒\n        \"dssx\":120,\n        //报警声音，值为声音文件的id，走文件下载接口获取，配置了页面查询查询有数据时则报警\n        \"bjsy\":\"XXXXXXXX\"\n      }\n    },\n    //处理类型：编辑页面页面扩展\n    \"update\": {\n      //是否显示关闭按钮，默认显示\n      \"xsgban\": true,\n      //确定不提示，默认要提示\n      \"qdbts\": true\n    },\n    //处理类型：图表扩展\n    \"echarts\": {\n      \"title\": {\n        \"text\": \"同名数量统计-对象自定义\",\n        \"subtext\": \"测试子标题\"\n      },\n      \"series\": {\n        \"roseType\": \"angle\"\n      }\n    }\n  },\n  //系统参数\n  \"sys\": {\n    \"cllx\": \"处理类型;必填\",\n    \"authCode\": \"权限代码;不传时只提供最基础功能\",\n    \"dlsjdxdm\": \"代理数据对象代码，配置了则优先使用该数据对象，一些场景需要代理原数据对象\",\n    \"fsjdxdm\": \"父数据对象代码，一些数据对象时基于另一个数据对象复制而来，而我们在大字典中配置sql等场景需要依赖对象代码，为避免重复配置，此处支持配置父对象代码，系统会读取父对象代码相关大字典\",\n    \"token\": \"权限key\",\n    \"zxcz\": \"执行操作;设置执行什么操作，默认getdata，可选项：getdata获取数据，plcl执行新增修改操作，getfile获取文件\",\n    \"clearCache\": \"请求时清除缓存，默认false，重新加载对象、字段等信息\",\n    \"dataCache\": \"数据是否使用缓存，部分功能数据存在缓存会用到，如字典等，默认true\",\n    \"ids\": \"页面批量操作选择的记录id列表，为数组\",\n    \"xzms\": \"下载模式，1：按文件类型下载、2：二进制文件下载、3：base64、4：转为base64后作为data以json对象返回，针对代理下载文件场景。默认：1\",\n    //编辑表格数据：列表编辑的数据\n    \"editTableData\": [],\n    //参数体处理，调用接口时，需要一起执行的其他操作\n    \"cstcl\":{\n        //key一般为字段名称，值为参数对象\n        \"key\":{\n        }\n    },\n    //可以是实现了接口HdInterface的对象或请求参数体，系统会自动采用该参数体进行回调。\n    \"hdcst\":{\n    },\n    //任何内容\n    \"context\": \"\",\n    //穿透调用\n    \"ctdy\": \"可以实现将请求生成文件，传到其他地方调用后结果返回\",\n    //穿透前应用\n    \"ctqapp\": \"可以实现自动将请求条件和用户信息转发到另一个应用，相当于代理功能，在穿透调用前执行\",\n    //穿透应用\n    \"ctapp\": \"可以实现自动将请求条件和用户信息转发到另一个应用，相当于代理功能\",\n    //穿透url\n    \"cturl\": \"穿透应用的相对地址\",\n    //穿透调用和穿透app场景都会用到，毫秒\n    \"timeout\": \"超时时长\",\n    //不执行更新，默认false，主要针对批量保存场景\n    \"bzxgx\":false,\n    //不执行新增，默认false，主要针对批量保存场景\n    \"bzxxz\":false,\n    //穿透调用结果\n    \"ctdyjg\": \"控制是否需要穿透调用的结果，默认true，数据推送类就可以不需要，感觉有结果当然还是更完美哈\",\n    //变化的列表选择数据\n    \"changeCheckData\": {\n      //记录主键\n      \"主键\": {\n        \"checked\": \"是否选中状态\",\n        \"expand\": \"树形节点是否展开\",\n        //该行数据\n        \"obj\":{}\n      }\n    },\n    //存储树形结构展开情况\n    \"treeExpandData\":{\n        \"主键\":\"树形节点是否展开\"\n    },\n    \"files\": \"文件数组，当我们需要上传文件时，需要先调用upload文件上传接口，文件上传后，接口会返回一个文件对象列表，后续的使用都基于该文件列表进行\",\n    \"userInfo\": \"用户信息;用于跨系统自动登陆\",\n    \"clientIp\": \"客户端ip;系统会自动获取\",\n    \"dcwjm\": \"用于自定义导出文件名，不设置则采用数据对象名称\",\n    \"dcpczdlb\":\"导出排除字段列表\",\n    \"dczdlb\":\"导出字段列表\",\n    \"qqkssj\": \"收到请求开始的时间\",\n    \"qqid\":\"每次请求系统会自动生成一个请求id与日志id一致\",\n    \"hdqqid\":\"回调请求id，异步请求时，会将请求id带回，使调用方知道是对应的哪一次请求\",\n    \"hdjs\":\"回调结束，告知调用方法回调完成\",\n    \"searchKey\": \"通用搜索信息\",\n    \"language\": \"国际化语言切换,如：zh_CN、en_US等\",\n    \"yzdjl\": \"已找到记录，传入主键是否能查询到对应的记录\",\n    \"swtjl\": \"事务提交量，主要用于批量上传时，多少条数据提交一次事务，默认5000\",\n    \"wlsc\": \"物理删除，默认false，配置该数据对象是否允许物理删除\",\n    \"scywj\": \"删除源文件，默认不删除\",\n    \"zddm\": \"是否包含字段代码，默认true，导出下载模板时会用到\",\n    \"sjyz\": \"是否数据校验，1验证，0不验证，默认1，数据同步场景生效\",\n    \"fileType\": \"文件类型，下载数据模板格式等\",\n    \"zdlb\":\"终端类别，默认：PC，PC（电脑）、Android、IOS、Wx、Zfb、H5\",\n    //-------------按处理类型扩展 end-------------\n    //系统字段相关配置\n    \"fields\": {\n      //-------------查询相关字段 start-------------\n      //用于综合搜索的字段\n      \"sszzd\": {\n        \"zddm\": \"dxmc\",\n        \"zdms\": \"搜索主字段\"\n      },\n      //系统会自动生成主字段的简拼进行赋值\n      \"pyjp\": {\n        \"zdms\": \"拼音简拼\",\n        \"zddm\": \"dxjp\"\n      },\n      //系统会自动生成主字段的全拼进行赋值\n      \"pyqp\": {\n        \"zdms\": \"拼音全拼\",\n        \"zddm\": \"dxqp\"\n      },\n      //综合搜索需要包含的字段\n      \"sszdlb\": {\n        \"zdms\": \"搜索字段列表\",\n        \"zddm\": \"dxms||dxdm\"\n      },\n      //对于移动端或字典下拉等场景只能展示较少信息时，展示在头部的信息，在前端实现\n      \"my_header\": {\n        \"zddm\": \"mc\"\n      },\n      //对于移动端或字典下拉等场景只能展示较少信息时，展示在尾部的信息，在前端实现\n      \"my_footer\": {\n        \"zddm\": \"dm\"\n      },\n      //-------------查询相关字段 end-------------\n    }\n  },\n  //用户信息\n  \"user\": {\n    //用户主键\n    \"id\": \"141B1AFC7E634176BDA7DB7F491A9004\",\n    \"yhdm\": \"用户代码;用户登陆账户\",\n    \"yhxm\": \"用户姓名\",\n    //身份证号\n    \"sfzh\": \"10002\",\n    //头像信息\n    \"tx\": \"94BB29C705AE4B849853917C876AE86B\",\n    //人员所属机构信息\n    \"jgxx\": {\n      //机构主键\n      \"id\": \"141B1AFC7E634176BDA7DB7F491A9004\",\n      //机构代码\n      \"jgdm\": \"9900000000\",\n      //机构名称\n      \"jgmc\": \"临时机构\"\n    },\n    //当前用户的权限信息集合\n    \"qxMap\": {\n      //权限完整路径\n      \"KFZFW_PTGL_SJZD_sjplsc\": {\n        \"mc\": \"批量上传\",\n        \"dm\": \"KFZFW_PTGL_SJZD_sjplsc\"\n      }\n    }\n  },\n  //分页对象\n  \"page\": {\n    \"totalRequired\": \"是否进行总数统计;默认true\",\n    \"listRequired\": \"是否进行列表查询;默认true\",\n    \"pageNumber\": \"查询页号\",\n    \"pageSize\": \"页大小，默认10\",\n    \"orderBy\": \"排序\"\n  },\n  //sql相关参数\n  \"sql\": {\n    \"defaultSql\": \"默认sql\",\n    \"from\": \"查询的表，含对象归属\",\n    \"selectField\": \"查询的字段列表\",\n    \"whereStr\": \"查询条件\",\n    \"authWhere\": \"权限条件\",\n    \"orderBy\": \"排序信息\",\n    //更新相关\n    \"setf\": \"更新的字段，如：xm=\'dsds\',age=2\",\n    //新增相关\n    \"insertf\": \"要插入的字段列表\",\n    \"values\": \"要插入的数据列表\"\n  },\n  //对象的字段信息，可以在对象中配置字段，但一般不这么做，专门的字段配置优先级最高，全局配置文件中可以配置所有对象的通用字段\n  \"fields\": {\n    //字段代码\n    \"zddm\": {\n      \"zddm\": \"字段代码\",\n      \"zdmc\": \"字段名称\",\n      //导出表头背景色\n      \"dcbtbjs\":\"RED1\",\n      //导出默认背景色\n      \"dcmrbjs\":\"BLUE1\",\n      //导出数据定制颜色，具体设置每一行\n      \"dcdzbjs\":{\n        \"1\":\"BRIGHT_GREEN\",\n        \"3\":\"DARK_RED\"\n      },\n      //字段扩展信息都存在每个字段中，各自独立，可以通过$.fields[字段代码].kzxx从myParams中获取\n      \"kzxx\": {\n        //验证规则，会合并到$.yzgz[\'yobj.zddm\']中，进行全局校验，计划不存在的时默认采用insert的规则\n        \"yzgz\": {\n          \"insert\": {\n            //按顺序继承哪些处理类型的验证规则，后面覆盖前面的规则\n            \"extends\": [\n              \"xxx\",\n              \"xxx\"\n            ],\n            //\"不能为空，会根据是否编辑必填添加该规则\"\n            \"notNull\": {\n            },\n            //必须是某个值\n            \"mustBe\": {\n              //必须为123，必须设置\n              \"value\": \"123\"\n            },\n            //长度校验，若没有人工配置则会自动根据字段长度的75%添加该规则\n            \"length\": {\n              //最长10，不设置没限制\n              \"max\": 10,\n              //最长2，不设置没限制\n              \"min\": 2\n            },\n            //正则表达式\n            \"zzbds\": {\n              //校验的正则表达式，必须设置\n              \"value\": \"[0-9]{8}\",\n              //验证没通过时的提示信息\n              \"ts\": \"必须是8位的数字\"\n            },\n            //必须是数字\n            \"number\": {\n              //最小2，不设置没限制\n              \"min\": 2,\n              //最大10，不设置没限制\n              \"max\": 10\n            },\n            //必须为空\n            \"null\": {\n            },\n            //必须是时间，系统会自动转为14位字符串时间，也可自定义转为的时间格式。\n            \"date\": {\n              //指定时间格式，默认YYYYMMDDHHmmss\n              \"value\": \"YYYYMMDDHHmmss\"\n            },\n            //身份证格式校验，系统会自定将15位转为18位\n            \"sfzh\": {\n            },\n            //邮箱格式校验\n            \"email\": {\n            },\n            //字典校验，值必须是设置字典的字典项\n            \"zd\": {\n              //字典类别，必须设置\n              \"value\": \"SYS_COMMON_LJPD\",\n              //展示字典项，默认true\n              \"zszdx\": true,\n              //字典多选，默认false\n              \"zddx\": false\n            },\n            //字典判断，通过字典机制实现后台校验，需要在字典中进行校验逻辑配置，参考：JCGA_JCYG_SFZHCQ\n            \"zdpd\": {\n              //对应的字典类别\n              \"value\": \"JCGA_JCYG_SFZHCQ\",\n              //验证没通过的提示\n              \"ts\": \"身份证号不能重复\"\n            },\n            //基于模板验证，只有后端实现，前端不支持\n            \"tmpl\": {\n              //可以写beetl表达式，可以取myParams中的所有数据\n              \"value\": \"${yobj.xxx==\'xx\'}\",\n              //验证没通过的提示\n              \"ts\": \"XXXX\"\n            }\n          }\n        },\n        //转换规则\n        \"zhgz\": {\n          //转换为空\n          \"null\": {\n          },\n          //转换为18位身份证号\n          \"sfzh\": {\n          },\n          //时间格式转换，系统会自动转为14位字符串时间，也可自定义转为的时间格式。\n          \"date\": {\n            //设置要转换的格式，不设置默认：YYYYMMDDHHmmss\n            \"value\": \"YYYYMMDDHHmmss\"\n          },\n          //转为大写\n          \"zwdx\": {\n          },\n          //转为小写\n          \"zwxx\": {\n          },\n          //去掉前后空格\n          \"qdqhkg\": {\n          },\n          //字符替换\n          \"zfth\": {\n            //原字符串\n            \"yzfc\": \"x\",\n            //新字符串\n            \"xzfc\": \"X\"\n          },\n          //字典替换\n          \"zdzh\": {\n            //对应的字典类别\n            \"value\": \"SYS_COMMON_LJPD\"\n          },\n          //基于beetl模板，如创建人信息、简拼全拼啥的都可以走该规则\n          \"tmpl\": {\n            //设置的值，可以取myParams中的所有值，只在后端实现\n            \"value\": \"${user.id}\"\n          }\n        },\n        //处理类型扩展\n        \"cllxkz\": {\n          \"insert\": {\n			//弹窗关闭提示，默认false\n			\"tcgbts\":true,\n            //该处理类型是否展示：\n            \"show\": true,\n            //默认值\n            \"default\": \"默认值\",\n            //是否禁用，默认false\n            \"disabled\": false,\n            //是否只读，默认true\n            \"readonly\": true,\n            //字段宽度\n            \"zdkd\": \"\"\n          },\n          \"update\": {\n            //该处理类型是否展示\n            \"show\": true,\n            \"default\": \"默认值\",\n            //在获取对象基础信息时，根据主键进行数据库记录获取\n            \"putobj\":true\n          },\n          \"select\": {\n			//展示查询项数量\n			\"zscxxsl\":6,\n            \"myHelp\": \"系统帮助文档id，配置了则会显示帮助文档入口\",\n            //该处理类型是否展示：这个配置的是表单页面生效，\n            \"show\": false,\n            \"default\": \"默认值\"\n          },\n        },\n        //针对控件类型的配置，vxe的from-intm中的参数基本都可以设置，系统会自动合并进行展示\n        \"kjkz\": {\n          //可以给该行增加多个class，用空格分割，modalStickyBottom：该行沾在下发，modalStickyTop：该行沾在上方\n          \"className\":\"modalStickyBottom\",\n          //密码控件-密码\n          \"mm\": \"xxxxxxxx\",\n          //时间控件-存储格式\n          \"ccgs\": \"yyyyMMddHHmmss\",\n          //时间控件-展示格式\n          \"zsgs\": \"yyyy-MM-dd HH:mm:ss\",\n          //最大按钮数，列表操作中默认最大显示3个按钮\n          \"zdans\": 3,\n          //控件类型是$buttons时，会读取该配置展示按钮\n          \"btns\": [\n            {\n              \"type\": \"button\",\n              \"content\": \"确定\",\n              \"status\": \"primary\",\n              \"name\": \"qd\",\n              //按钮参数，列表批量操作按钮和列表操作按钮都是此规则\n              \"buttonOptions\": {\n                //是否关闭弹窗，针对进行一些操作后配置是否关闭弹窗\n                \"sfgbtc\":true,\n                //基础信息扩展，属性复制\n                \"jcxxkz\":{\n                },\n                //基础信息请求参数扩展，属性复制\n                \"jcxxqqcskz\":{\n                },\n                //参数，会与默认参数进行合并\n                \"params\":{\n                },\n                //参数2，主要针对批量上传时，params会被上传文件接口使用，此处再加一个\n                \"params2\":{\n                }\n              }\n            },\n            {\n              \"type\": \"button\",\n              \"content\": \"关闭\",\n              \"name\": \"gb\"\n            }\n          ],\n          //树形结构展示的字段设置为true,默认false\n          \"treeNode\": false,\n          //控件位置\n          \"align\": \"center\",\n          //控件占一行比例，整行24\n          \"span\": 24,\n          //渲染器设置\n          \"itemRender\": {\n            \"props\": {\n            }\n          }\n        },\n        //属性扩展，从页面参数对象myData中复制属性到字段配置中\n        \"sxkz\": {\n          //<设置到字段配置中的key，从myData中取的只路径>\n          \"obj\": \"dxjcxx.sjdx\",\n          \"fields.sjdx.cxmrz\": \"dxjcxx.sjdx.id\"\n        },\n      }\n    }\n  },\n  //请求的操作日志\n  \"czrz\": {\n  },\n  //验证规则，可以对全局参数进行验证规则定制，字段的默认验证规则和用户在字段上配置的验证规则和自动合并进来\n  \"yzgz\": {\n    //参数jsonpath路径\n    \"yobj.zddm\": {\n      //处理类型\n      \"insert\": {\n        //按顺序继承哪些处理类型的验证规则，后面覆盖前面的规则\n        \"extends\": [\n          \"xxx\",\n          \"xxx\"\n        ],\n        \"xxms\": \"信息描述;作为提示的主体\",\n        //任意系统支持的规则\n        \"xxx\": {\n          //规则参数\n          \"value\": \"xxx\"\n        }\n      }\n    }\n  },\n  //转换规则，\n  \"zhgz\": {\n    //参数jsonpath路径\n    \"yobj.zddm\": {\n      //处理类型\n      \"insert\": {\n        //按顺序继承哪些处理类型的转换规则，后面覆盖前面的规则\n        \"extends\": [\n          \"xxx\",\n          \"xxx\"\n        ],\n        //任意系统支持的规则\n        \"xxx\": {\n          //规则参数\n          \"value\": \"xxx\"\n        }\n      }\n    }\n  },\n  //其他一些信息，特殊场景使用，参数对象序列化时会移除该信息\n  \"other\": {\n    \"request\": \"http请求对象\",\n    \"response\": \"http返回对象\",\n    \"ysParams\": \"原始请求参数,将原始请求参数克隆备份一份，可能会用到，如：跨网请求需要原始请求参数\",\n    \"yobj\": \"原始表单参数备份信息，校验时用到\"\n  },\n  //智能交换相关参数\n  \"znjh\":{\n    \"sql\":\"要执行的sql\",\n    \"start\":\"开始\",\n    \"end\":\"结束\"\n  }\n}\n```\n\n# 请求状态码表\n- 优先采用：https://www.runoob.com/http/http-status-codes.html\n- 超过510的状态不会反应在http响应头中，会统一转为400，具体状态码可以从返回内容中获取\n\n状态码|说明\n---|---\n200|请求成功\n301|资源（网页等）被永久转移到其它URL\n400|业务错误，错误详情参考返回消息\n403|没权限，服务器理解请求客户端的请求，但是拒绝执行此请求\n404|请求的资源（网页等）不存在\n412|数据校验未通过，通过msg可以了解具体不通过原因\n500|内部服务器错误\n1000|穿透调用超时\n1001|批量上传数据校验不通过\n1002|等待回调超时\n9999|框不统一处理返回结果，该状态不会到达前端\n\n# 数据同步配置\n\n```json\n{\n  \"jcsr\": {\n    \"sjdx\": {\n      \"zlzd\": \"gxsj\"\n    },\n    \"page\": {\n      \"pageSize\": 10\n    },\n    \"znjh\": {\n      \"start\": \"20220101010101\",\n      \"sql\": \"select * from sys_log_fwzr where gxsj>=#{znjh.start} and gxsj<#{znjh.end}\"\n    }\n  },\n  \"jcsc\": {\n    \"sjdx\": {\n      \"dxdm\": \"SYS_LOG_FWZR\"\n    },\n    \"sys\": {\n      \"ctdy\": \"A_B\",\n      \"cllx\": \"plbc\"\n    },\n    \"znjh\": {\n      \"app\": \"sjsj\"\n    }\n  }\n}\n```\n\n# 流程处理配置\n\n```json\n{\n  \"clq\": {\n    \"jcsr\": {\n      \"sjdx\": {\n        \"zlzd\": \"gxsj\"\n      },\n      \"page\": {\n        \"pageSize\": 10\n      },\n      \"znjh\": {\n        \"clq\":\"jcsr\",\n        \"ljq\":{\n        	\"success\":[\"jcsc\"]\n        },\n        \"start\": \"20220101010101\",\n        \"sql\": \"select * from sys_log_fwzr where gxsj>=#{znjh.start} and gxsj<#{znjh.end}\"\n      }\n    },\n    \"jcsc\": {\n      \"sjdx\": {\n        \"dxdm\": \"SYS_LOG_FWZR\"\n      },\n      \"sys\": {\n        \"ctdy\": \"A_B\",\n        \"cllx\": \"plbc\"\n      },\n      \"znjh\": {\n        \"clq\":\"jcsc\",\n        \"app\": \"sjsj\"\n      }\n    }\n  },\n  \"jcxx\":{\n  	\"startClq\":[\"jcsr\"]\n  }\n}\n```', NULL, 4, '20230604121601', '20230604121601', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', NULL, 'XITONGCANSHU', '00E457AB76B64D85B7DE4321EA3C3054', '{\n  \n}', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446_9B5A99E235634E03976F347E023C3883_00E457AB76B64D85B7DE4321EA3C3054', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', '平台简介', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446', '99', '09', '1', 1010, '02', '# 平台简介\n本系统是的基础思想是“万物皆对象”。\n支持常规的数据库表、视图、excel等数据形式的管理，主要功能有：基础的增删改查、运行监控、数据流转、对外数据接入、数据共享、比对核查、后台任务的设计及运行管理、数据统计、图表展示等。\n专注于服务于开发者，将全部公共服务集中在本项目中，本项目不涉及业务需求（也存在一些以样例的形式存在），提供各个项目都能用到的通用服务。\n主要优势为表单操作类的后台管理系统可以很快的配置出来，同时还具有非常好的扩展性，能应对各种定制需求，本系统中所有功能包括登陆、菜单等都是配置出来的。\n\n# 安全性\n\n本系统采用当前业界普遍使用的https安全协议进行通信，目前互联网大部分网站已经采用该协议，从而实现了通信渠道的安全传输。\n同时本系统具有完善的账户体系，每个接入方都需要进行用户认证，从而确保了接入方的身份认证。\n\n', '0BC90099033B45018A49891E6F280CB8', 392, '20200624115238', '20200707162324', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'PTJJ', 'PINGTAIJIANJIE', '034EA2309FEF44B988785417D943AB91', '{\"markdown\":{\"显示目录\":false,\"标题样式\":\"\"}}', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446_034EA2309FEF44B988785417D943AB91', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', 'myservice-README.md', NULL, NULL, '99', '01', '0', 99999, '01', '# 开发者服务\n\n本项目专注于服务于开发者，将全部公共服务集中在本项目中，本项目不涉及业务需求，提供各个项目都能用到的通用服务。\n\n## 字典服务\n\n提供字典管理功能，对外字典接口。\n\n## UI服务\n\n各种通用样式都统一从此项目维护。\n\n## 文件服务\n\n提供文件上传、下载服务。\n\n## 数据对象管理\n\n当前支持对数据库中的表和视图进行配置查询，具有卓越的扩展性，可以完整的配置出表的增删改查，并支持高度定制。\n\n# 项目部署\n\n## 初次部署\n\n1. 创建数据库用户。\n1. 执行数据库脚本时一定要谨慎，删错了很忧伤。\n1. 通过Navicat执行数据库初始化脚本\n1. 修改其中的数据库表中的全部数据库连接信息。\n1. 复制配置文件到：/bengma666/config目录。\n1. 修改myservice.properties中服务地址和配置读取数据库连接信息。\n1. 修改优化tomcat配置，调整内存、编码等参数。\n1. 拷贝war包到tomcat中。\n1. 修改index.jsp中的默认登录页\n1. 启动项目并访问。\n\n## 项目升级1（换用户名）\n\n1. 安照初次部署流程重新部署一个项目，数据库重新创建个用户，其他信息可以复用。\n1. 打开upscript.sql升级脚本，根据实际情况替换用户名等信息，并执行。\n1. 查看初始部署流程，根据情况在升级中对应调整。\n\n## 项目升级2（不换用户名）\n\n1. 新建一个用户，原封不动的将本地数据库备份还原进去。\n1. 根据记录将数据库表结构变化更新到线上库中。\n1. 打开“upscript不换用户.sql”升级脚本，根据实际情况替换用户名等信息，并执行。\n1. 更换应用部署包测试功能是否正常。\n\n# 更新记录\n\n## 2019-1-15\n\n1. 表和视图的的增删改查基本完成。\n1. 实现了字典、数据库、日志、应用的基础管理。\n1. 建立了用户和机构的表结构，进行了两种基础的权限控制，以后完善权限体系。\n\n## 2019-11-14\n\n1. 笔记功能基本完成，将来可以基于此改进实现公告功能。\n1. 开始编写系统使用文档。\n\n\n', NULL, 411, '20191114112519', '20191118165705', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'MYSERVICE-README.MD', 'MYSERVICE-README.MD', '0E30E262DA484652AC684E1A001FE303', '{}', NULL, '0E30E262DA484652AC684E1A001FE303', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', '文档资料', NULL, '4D87975B09344CC5ADDA4D3DC37D3312', '99', '01', '1', 100, '01', '# 功能简介\n\n用于平台公告、个人笔记、系统帮助文档或者写一本书。\n\n# markdown编辑器\n\n该编辑器的语法请多参考其他文档，或者在网上简单的学习了解下，只需要先了解基础的，慢慢有需求在具体了解。\n\n# 扩展信息\n\n```json\n{\n	//标题是否显示，默认显示\n	\"titleShow\":false\n}\n```\n\n# 大文档编写原则\n\n1. 大文档建议根据功能进行拆分为每个小章节一个文档，然后通过目录结构进行组装，最终形成完整的文档。\n1. 每个拆分的最小章节应该控制在一篇博客的大小内，因为一篇文章字数太多，不便于编辑维护。\n1. 每篇具体章节的标题都按一级标题开始，将来在做整个文档导出时，会结合目录层级，对标题转换。\n\n# 帮助文档\n\n1. 采用本系统编写帮助文档的一个好处是，首先它是有多层结构的一本帮助手册，结构清晰，维护简单，基于markdown的优势，可以很方便的展示代码、编号等。\n2. 其次帮助文档主要就是帮助用户使用系统，虽然提供一本帮助手册用户可以按目录去查看对应的章节，但还是有点繁琐，本系统可以直接将每个功能的帮助手册直接与对应的功能关联，用户可以在使用每个功能时，方便的直达对应的帮助手册，然后每个独立的帮助文档采用目录整合后就是完整的帮助文档。\n3. 后续还将提供机制，实现将一本帮助手册直接导出为word等线下文档。', NULL, 45, '20200709004832', '20240201113916', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'WDZL', 'WENDANGZILIAO', '1610D01D97EF44E4AD9EE4E2F4382459', '{\n  \"markdown\":{\n    \"显示目录\":true,\n    \"标题样式\":\"\"\n  }\n}', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446_4D87975B09344CC5ADDA4D3DC37D3312_1610D01D97EF44E4AD9EE4E2F4382459', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', 'php学习笔记', 'php', '4EB2166D5077430283980676A2772A80', '99', '01', '1', 99999, '01', '# 基础工具\n\n## 开发框架laravel\n\n### 官方地址\nhttps://learnku.com/docs/laravel/7.x\n\n### 安装说明\n\n> composer global require laravel/installer 很慢，这一步采用如下方式进行\n\n在这里下载最新的包：\n\n> https://github.com/laravel/laravel/tags\n\n在解压后的文件夹根目录执行如下命令安装：\n\n`composer install -vvv`\n\n加参数 -vvv，这样就能看到具体的报错\n\n## 包管理工具composer\n\nhttps://pkg.phpcomposer.com/#how-to-install-composer\n\n设置全局国内镜像：\n\n`composer config -g repo.packagist composer https://packagist.phpcomposer.com`\n\n\n## php的环境集成包\n\nhttps://www.apachefriends.org/index.html\n\n## phpstorm\n\nhttps://www.jb51.net/softs/720592.html\nhttps://www.zdfans.com/html/26005.html\n\n破解操作：\n\n编辑系统hosts文件：\n```\n127.0.0.1 www.account.jetbrains.com\n127.0.0.1 account.jetbrains.com\n127.0.0.1 www.jetbrains.com\n127.0.0.1 https://account.jetbrains.com:443\n```\n在Activation code输入激活码：\n```\n45RJNQXN3G---\n6ZUMD7WWWU---\n```\n```c\n6K9R0MTCDN---\n\n```\n## 技术日志\n\n### 日志输出\n\n```php        \nvar_dump($validator);\nLog::info(\"测试日志\");\n```\n\n# testMall\n\n## 环境搭建\n\n### 下载代码\n> http://47.96.22.18:8078/ 版本管理，mj::5398551\n`git clone http://47.96.22.18:8078/se/amall.git`\n\n### 工具包\n\n下载工具包：http://47.96.22.18/vendor.rar\n解压后放在amall项目根目录。\n\n### httpd配置\n\nhttpd.conf目录：\n![](/myservice/common/download.do?xzms=false&id=26C1D112E2C64ED38134D0DF6F8E735B)\nhttpd.conf-端口：\n![](/myservice/common/download.do?xzms=false&id=FF4A7547D98D473791B46DAAAE09E049)\n\n1. 配一个端口，用于这个项目的访问，就是把原有的屏掉，不要用。\n1. Directory />搜这句，他默认的配置，只能127.0.0.1访问，这样配置的话，就可以192.168.x.x访问了\n```\nAllowOverride All\nRequire all granted\n```\n\n配虚拟主机：\n![](/myservice/common/download.do?xzms=false&id=D41F30168991438A9B1890FABD712011)\n![](/myservice/common/download.do?xzms=false&id=CBBF54570BAA4D76958960A05AEE27F1)\n```\nListen 83\n<VirtualHost *:83>\n    DocumentRoot \"D:/NIS/Laravel/amall/public\"\n</VirtualHost>\n```\n重启Apache：\n![](/myservice/common/download.do?xzms=false&id=A8A83E8841C44833934C73A0BCCBD622)\n\n### 项目目录下执行\n\n```\ncopy .env.example .env\n# 将应用程序的密钥设置为随机字符串\nphp artisan key:generate\n```\n\n### 数据库初始化\n\n在mysql中执行如下脚本：\n![](/myservice/common/download.do?xzms=false&id=A141A61C37F243E193C1C4AD5156154B)\n\n### 配置数据信息\n\n![](/myservice/common/download.do?xzms=false&id=44FAE6479DAF467FA8CB7856CD3A5751)\n```\nDB_CONNECTION=mysql\nDB_HOST=127.0.0.1\nDB_PORT=3306\nDB_DATABASE=testmall\nDB_USERNAME=root\nDB_PASSWORD=123\n```\n### 系统访问\n\nhttp://127.0.0.1:83/ 访问正常就ok\n\n\n', NULL, 43, '20200704114532', '20200716232709', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'PHPXXBJ', 'PHPXUEXIBIJI', '20B0C88EDEEC4AD7920675FCE185A423', '{\"markdown\":{\"显示目录\":true,\"标题样式\":\"\"}}', NULL, '4EB2166D5077430283980676A2772A80_20B0C88EDEEC4AD7920675FCE185A423', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', '对外服务', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446', '99', '01', '1', 1060, '01', '## 功能简介\n\n用于开发者通过调用接口的形式与本系统对接，可以实现前端用户通过页面操作系统相同的效果，从而实现自动化系统对接需求。\n\n## 接口规范\n\n每个请求接口都会返回如下信息：\n\n|  参数名称 | 参数描述  |  备注 |\n| :------------ | :------------ | :------------ |\n| status  | 状态  |  首先根据该值判断请求是否成功。失败时请通过msg查看失败原因 |\n|  msg |  消息 |  请求返回的消息，失败时会说明失败原因 |\n\n例如：\n```json\n{\n    \"msg\": \"密码不正确\",\n    \"status\": false\n}\n{\n    \"msg\": \"数据处理异常：null\",\n    \"status\": false\n}\n{\n    \"code\": \"403\",\n    \"msg\": \"权限过滤未通过，请重新登陆\",\n    \"status\": false\n}\n```\n## 系统跳转\n\n此部分为可信任的内部系统对接采用的方式，第三方系统可以传入登录人证件号码，实现自动登陆，可以实现系统任何用户的自动登陆，可以实现以任何用户进行任何操作，因为安全问题，不能对外部系统开放。\n\n### 本系统跳转\n\n此部分讲解本系统跳转外部系统的场景，本系统会将用户信息加密传给外部系统，外部系统参考如下用户信息解密代码对用户信息进行解密，然后实行自动登录。从而实现本系统自动跳转登录外部系统。\n\n用户信息解密代码片段：\n```java\n    public static JsonResult zddl(HttpServletRequest req) {\n		//从请求中获取用户信息加密串\n        String userInfo = req.getParameter(\"userInfo\");\n		//约定\n        String pwd = \"XXXX\";\n		try {\n			//用户时间加密模式，用户信息解密\n			userInfo = DesUtil.decrypt(userInfo, pwd);\n			int idx = userInfo.indexOf(\"@\");\n			Date urlDate = DateUtil.parseDate(userInfo.substring(0, idx));\n			//时间判断，五分钟内有效\n			if(Math.abs(urlDate.getTime()-new Date().getTime())>1000*60*5){\n				return error(\"用户信息过期：\"+userInfo);\n			}\n		}\n		//得到用户的身份号\n		String u = userInfo.substring(idx+1);\n		//TODO 根据身份证号实现自己系统的用户自动登录\n        return success(\"自动登陆成功\",user);\n    }\n```\n\n### 跳转本系统\n\n此部分讲解外部系统跳转本系统的场景，外部系统需要参考如下代码将用户信息加密传给本系统，本系统会对用户信息进行解密，然后实行自动登录。从而实现外部系统自动跳转登录本系统。\n\n用户信息加密代码片段：\n```java\npublic static String doDesEncryptUrl(String userid) \n            throws UnsupportedEncodingException {\n	//当前时间加用户身份证号\n	String userInfo = db.getCurrentDateStr14()+\"@\"+userid;\n	//约定的密码\n	String pwd = \"XXXXXXXXXX\";\n	//本系统地址\n	String url = \"http://xxxxxx\";\n	userInfo = DesUtil.encrypt(userInfo, pwd).replace(\"\\n\",\"\").replace(\"\\r\", \"\");\n	url += \"userInfo=\"+URLEncoder.encode(userInfo,\"utf8\");\n	//重定向到该地址\n	return url;\n}\n```\n\n### 加密工具\n\n加密工具类：\n\n## APP系统认证\n\n本模式主要适用于手机app场景及其他类似的对外提供接口的场景。\n\n### 系统操作\n\n在登录获取token后，后续在操作中带上token参数系统即可识别出请求方的身份，进行权限控制。\n因为token类似浏览器的会话，所以它有会话时长，本系统会话时长是10小时，超过10小时没有访问系统则会话过期，过期后进行系统操作将返回无权限，所以使用时需要判断结果是否为无权限，若无权限则需要重新登陆。\n\n无权限请求结果样例：\n\n```json\n{\n    \"code\": \"403\",\n    \"msg\": \"权限过滤未通过，请重新登陆\",\n    \"status\": false\n}\n```\n\n## 数据接入\n\n### 接口地址\n\n> ${系统地址} /sjdx/save.do\n\n### 请求样例1\n\n简单模式，当请求参数较少时采用此方式会比较便捷。\n\n> http://127.0.0.1:88/myservice/sjdx/save.do?dxdm=SYS_QX_XXX&token=XXXX&e_zd1=xxx&e_zd2=xxx&e_zdn=xxx\n\n### 请求样例2\n\n\n### 参数说明\n\n\n\n## 数据共享\n\n### 接口地址\n\n> ${系统地址} /sjdx/page.do\n\n### 请求样例\n\n> http://127.0.0.1:88/myservice/sjdx/page.do?dxdm=SYS_LOG_XXX&token=XXXX&pageSize=1&pageIndex=1\n\n### 接口参数\n\n\n\n### 结果样例\n\n```json\n{\n}\n```\n\n### 结果说明\n\n|参数名称|参数描述|备注  |\n| :------------ | :------------ | :------------ |\n|status|状态|首先根据该值判断请求是否成功。失败时请通过msg查看失败原因  |\n|msg|消息|请求返回的消息，失败时会说明失败原因  |\n|data.totalRow|数据总量|若请求了数据统计，统计结果就在该字段中  |\n|data.totalPage|分页页数|只有统计了数据总量才能计算页数  |\n|data.list|具体数据列表|为数组，数组中的每个对象的字段信息会在系统对接时提供  |\n\n## 条件字段\n| 字段名 | 类型 | 字段描述 | 是否必填 |\n| :---: | :-: | :-----: | :----: |\n<%for( i in srcs){%>\n|${i.zddm}|${i.zddm==\'px\'?\'Long\':\'String\'}|${i.zdmc}|${i.cxbt==\'1\'?\'是\':\'否\'}|\n<%}}%>\n\n<%if(sczdcd>=1){%>\n## 结果字段\n| 字段名 | 类型 | 字段描述 |\n| :---: | :-: | :-----: |\n<%for( i in sccs){%>\n|${i.zddm}|${i.zddm==\'px\'?\'Long\':\'String\'}|${i.zdmc}|\n<%}}%>\n\n## 请求规范\n### 1 服务地址\n```\n${htdz}\n```\n\n### 2 请求头\n\n```json\n{\n    \"Content-Type\":\"application/json\"\n}\n```\n\n### 3 登录参数\n- 注意：登录接口不允许在每次调用接口时反复调用，调用一次登录接口获取的token有效期一般有几个小时，每当调用接口返回403时再重新调用一次登录接口获取token即可\n```json\n{\n  \"sjdx\":{\n    \"dxdm\":\"SYS_QX_YHXX_MRDL\"\n  },\n  \"yobj\": {\n    \"yhdm\":\"xxx\",\n    \"yhmm\":\"xxxx\"\n  },\n  \"sys\":{\n    \"cllx\":\"yhdl\",\n    //SM2公钥，测试期间可以暂时不传，传了该参数请求结果会采用该公钥进行加密，加密传输详细说明请参考文档最后章节\n    \"publicKey\":\"您生成的公钥\"\n  }\n}\n```\n\n### 4 请求参数\n```json\n${qqcs}\n```\n\n### 5 请求结果\n```json\n{\n}\n```\n\n### 8 异步请求结果\n```json\n{\n    \"code\": 200,\n    \"dateType\": \"application/json\",\n    \"data\": \"qqid\", \n    \"msg\": \"操作成功\",\n    \"status\": true,\n	  \"sys\":{\n			\"qqid\":\"请求id，与发起请求获取的值一致，用于对应请求和结果关系\"\n		}\n}\n```\n\n### 9 服务状态码\n| 代码 | 描述 |\n| :---: | :------------: |\n| 200 | 请求成功！ |\n| 400 | 业务错误，错误详情参考返回消息 |\n| 403 | 无操作权限或会话过期 |\n| 999 | 未知错误！ |\n\n### 10 接口加密传输说明\n1. 如上为明文请求接口说明，基于安全考虑，在前述接口的基础上对请求条件及请求结果采用SM2进行加密传输（SM2参考：https://blog.csdn.net/Wei_96/article/details/127637395）。\n2. 请求参数请通过SM2的方式进行加密为文本,采用加密的参数时请求头需要由application/json改为text/plain\n3. 请求参数加密公钥：${publicKey}，请求方需要采用该公钥对请求json串加密为密文请求参数。\n4. 请求参数中sys.publicKey为调用方自己生成的公钥（生成密钥：https://webencrypt.org/sm2samplecryptjs/）,当参数中包含sys.publicKey时返回的结果会以SM2的方式使用该公钥加密。\n\n## 对接提供信息\n\n这里将说明具体与外单位进行对接时，除提供本文档外，需要在对接时根据实际情况提供的信息。\n\n### 信息列举\n\n1. 系统地址信息。如：https://trimdata.cn:2000/sjsj-ht\n1. App模式：提供用户名和密码\n1. 后台模式：系统代码和系统密码\n1. 对接相关数据对象代码及数据对象字段信息，字段信息包括字段的字典、验证要求等信息。', NULL, 65, '20200707150351', '20230602153642', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'DWFW', 'DUIWAIFUWU', '23764DE618BF43C98BFB4F636CED207A', '{\n  \"markdown\":{\n    \"显示目录\":true,\n    \"标题样式\":\"\"\n  }\n}', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446_23764DE618BF43C98BFB4F636CED207A', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('01', 'mysql笔记', NULL, '9B5A99E235634E03976F347E023C3883', '99', '01', '1', 99999, '01', '## 系统参数\n```sql\n-- 查询设置mysql参数\nshow global variables like \'%time%\';\n-- set global connect_timeout=20;\n-- flush privileges;\n```\n\n## 时间操作\n\n```sql\nselect date_format(DATE_SUB(str_to_date(\'20221005092822\',\'%Y%m%d%H%i%s\'), INTERVAL -40 MINUTE),\'%Y%m%d%H%i%s\')\n```\n\n## 表被锁\n\n```sql\n-- 常规处理\n-- 查询进程\nshow PROCESSLIST\n-- 杀进程\nkill 324844\n\n-- 未查询到被锁进程\n-- 目前分析该场景是开启了事务，事务一直未提交导致该表一直被锁着。\n-- 1.查询锁 找到表对应字段object_name 取出 engine_transaction_id字段结果\nselect * from  PERFORMANCE_SCHEMA.data_locks\n-- 2.将thread_id拿到事务表中查询 取出trx_mysql_thread_id字段结果\nselect * from  information_schema.innodb_trx where trx_id =\'486861643\'\n-- 3. 通过kill trx_mysql_thread_id杀掉进程\nkill 324844\n-- 查询锁等待\nselect * from  PERFORMANCE_SCHEMA.data_lock_waits\n```\n\n## 列转行\n```sql\nwith lx as (\n    select * from lxgl lx\n    where lx.yxx=1 and lx.ssxm = #{obj.ssxm}\n),\n     lxd as (\n         SELECT \'tjd\' wllx, TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(lx.tjdid, \',\', t.n), \',\', -1)) AS id\n         FROM lx\n                  JOIN (\n             SELECT 1 AS n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4\n             UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7\n             -- 根据最大科目数调整\n         ) AS t ON CHAR_LENGTH(lx.tjdid) - CHAR_LENGTH(REPLACE(lx.tjdid, \',\', \'\')) >= t.n - 1\n         union all\n         select \'czc\' wllx,lx.czcid id\n         FROM lx\n         union all\n         select \'xnc\' wllx,lx.xncid id\n         FROM lx\n     )\nselect lxd.*,wl.wlmc,wl.wlbj,wl.zbdsz,wl.lng,wl.lat from lxd\n    INNER JOIN dzwlgl wl on lxd.id=wl.id and wl.yxx=1\n```\n\n## 行转列\n```sql\nSELECT id, GROUP_CONCAT(value SEPARATOR \',\') AS concatenated_values  \nFROM table_name  \nGROUP BY id;\n```', NULL, 12, '20230515153235', '20231221213947', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', NULL, 'MYSQLBIJI', '24DF9480E6B34C54B40A5B2B1B362592', '{\n  \n}', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446_9B5A99E235634E03976F347E023C3883_24DF9480E6B34C54B40A5B2B1B362592', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', '日志预警', NULL, '33FC64D3885C46BEA2BAACF74BBCBD82', '99', '09', '1', 20, '02', NULL, NULL, 0, '20210511173149', '20230602222125', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'RZYJ', 'RIZHIYUJING', '26D76B9507254066991543442CE5DC0A', '{\"markdown\":{\"显示目录\":true,\"标题样式\":\"\"}}', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446_33FC64D3885C46BEA2BAACF74BBCBD82_26D76B9507254066991543442CE5DC0A', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', '数据大师', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446', '99', '09', '1', 1080, '02', '# 平台简介\n\n基于kettle的数据流转平台，依托kettle的灵活性及丰富的组件生态，能灵活的实现各类复杂需求，本平台可以单纯作为一个kettle的调度平台，也可以作为一个灵活的数据流转平台，二者将是最完美的组合。\n\n平台创建的作业最终都是生成kettle作业，有特殊需求可以在kettle中直接进行修改以满足特殊需求，灵活才是长期存活的基础。\n\n其他非常规作业可以直接在kettle中设计后在本平台内进行统一调度管理。\n\n本平台足够灵活，所谓有容乃大如是也，自身虽然已经足够强大，但仍具备不可比拟的包容性，任何外部优秀的东西都可以集成进来，因此本平台也是很完美的所有后台任务的统一管理平台。\n\nkettle作为非常优秀的开源ETL工具得到了非常广泛的使用，一般的使用都是使用客户端操作管理，但问题是当投入生产环境使用时，动辄几百上千个job需要管理，这时在使用客户端管理已经很难完成了。我所知道的解决方案有用命令行的调用的，操作极其麻烦，难以维护，总之还是很难用啦，还有就是开发web端管理工具，kettle自带了一个web端管理工具，界面极其简陋不说，还很难用，基本无法投入生产环境使用，其他没留意到还有没有较好对众多job进行管理的工具。\n\n基于以上情况和我多年的kettle定制开发与使用经验。我设计并开发了数据大师，在kettle的基础上，将常用的场景迁移到web端，使运维人员甚至普通客户都能实现常见需求，我的目标是web端能实现70%的需求，剩余一些特殊少见的需求则由数据人员在kettle中直接实现，然后统一在本平台调度管理。\n\n本平台的具体优势请参考“平台特性”章节。\n\n# 平台界面\n\n![作业管理](https://trimdata.cn:2000/sjsj-zs-ht/default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=2CBD8CA826F34DB880B27B25EDE721C8)\n\n# 新版体验地址\n\nhttps://trimdata.cn:2001/sjds/#/login   sys/sys_123\n\n# 平台特性\n\n1. 【新】支持在一个调度中同时调度多个资源库的任务，也支持一个资源库的任务在多个调度节点上执行，同时支持在一个管理系统中同时管理多个调度节点。\n1. 新增支持设置作业启动时执行，支持cron定时，使定时设置更加灵活。\n1. 平台内支持创建：数据流转作业（暂时取消，设计有点复杂不太实用，目前有数据同步任务）、KM作业、javascript作业、shell作业、sql作业。\n1. 本平台能自动检测作业运行异常信息，便于平台运行状况跟踪，当作业量很大时，很难逐个作业查看运行情况。\n1. 本平台提供基础的运行日志，作为作业运行情况的回溯依据，便于事后问题排查。\n1. 平台提供设计好的数据流转日志功能，更接近业务层，用户可以根据需要使用。\n1. 平台提供转换管理，当前转换管理只提供查看、删除、查看转换图功能，将来根据需要提供导入功能。\n1. 数据库管理是管理kettle中配置的数据库信息，若是完全深入采用数据世界平台，那么这里的数据库都将采用jndi的形式关联使用数据世界中的数据载体管理，一处配置全平台通用，若是直接在kettle中配置的数据库，此处可以进行密码解密。\n\n# 一些说明\n1.	本平台2015年投入使用，我们公司已经在多地部署使用，开源以来，外部也有大量用户，所有基础的作业调度功能已经稳定，新添加的功能基本属于锦上添花，有些小bug也难免，欢迎反馈，让我们一起让他变得更好。\n2.	本系统是基于数据库资源库设计的，暂时不考虑支持文件资源库，当前支持oracle和mysql。\n3.	关于kettle版本的问题，当前版本开发使用的是8.3版，之前版本采用5.4开发，目前建议使用8.3版\n\n# 关键信息\n1.	[项目文档地址](https://trimdata.cn:2000/sjsj2/#/singleHome/sjdx?sjdx.dxdm=SYS_SJGL_GRBJ&sys.cllx=ckwd&yobj.ckwd=33FC64D3885C46BEA2BAACF74BBCBD82&)\n1.  [部署文档](https://trimdata.cn:2000/sjsj2/#/singleHome/sjdx?sjdx.dxdm=SYS_SJGL_GRBJ&sys.cllx=ckwd&yobj.ckwd=A4EBC2AF226447DBA18FD56CB12BD40D&)\n1.  项目源码\n	1. https://gitee.com/majinju/kettle-manager.git 之前的kettle-manager仓库，针对数据大师项目的web项目。\n	1. https://gitee.com/majinju/myutils-kettle.git 我的工具集kettle相关子项目\n	2. 有些依赖没有上传到maven仓库，建议直接采用项目中doc/lib中的依赖包。\n	3. 数据库脚本请从部署包中获取。\n1.	问题反馈邮箱：jinjuma@yeah.net。\n1.	项目交流qq群：320302530(已满勿加)，交流2群：142104962(已满勿加)，交流3群：142105082。\n\n\n# 常见问题\n\n## 作业添加\n1. 本平台是直接读取你数据库资源的v_job视图，这个视图包装了一下r_job表，你可以通过修改视图达到隐藏一些作业的目的。\n2. R_job是kettle资源库的系统表，只要你连接这个资源库设计的作业，都会记录在这个表中，所以你只需按照平常的习惯，连接与本平台配置的相同的资源库设计作业即可，因为读取的是同一张表，所以不需要额外的操作，直接就可以在本平台中看到你的作业并进行调度。\n3. 有外部作业需要添加到本平台，你只需直接使用kettle的Spoon工具，连接同一个资源库进行导入操作，这个数据人员都很熟悉。\n4. 我觉得没必要在页面支持作业导入功能，不知是否有这样的需求，这个暂时不开发。\n\n## 查看转换\n\n1. 关于这个问题，我一直很困惑，为毛要直接查询运行转换，作业和转换可谓各司其职，我认为要运行转换就需要在其上包装一个作业，不管是否有其他流程依赖的需求。\n2. 当前新版本已经提供转换查看功能，支持直接在调度中将转换包装为作业进行运行。\n\n# 注意事项\n1. 不要使用系统自带的记事本编辑配置文件，否则会导致系统无法正常读取你修改的配置文件，可以使用editpuls或notepad++。当出现奇葩问题时要想起这个提示。\n1. 相关文件最好不要存放在有空格或中文的目录下，避免不必要的麻烦。\n\n# 后续计划\n\n1.	任务管理在设置定时时可能需要人为分散定时，考虑生成时间-运行任务数的分析图辅助进行分散定时。\n8.	权限管理，不同用户看到自己的作业，管理员看所有作业。\n9.	分布式、集群支持，考虑增加容灾机制。\n10. 根据日志加入一些统计功能', NULL, 311, '20191114124844', '20240529150008', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'SJDS', 'SHUJUDASHI', '33FC64D3885C46BEA2BAACF74BBCBD82', '{\n  \"markdown\":{\n    \"显示目录\":true,\n    \"标题样式\":\"\"\n  }\n}', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446_33FC64D3885C46BEA2BAACF74BBCBD82', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', '资源智用', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446', '99', '01', '1', 1070, '01', '支持配置各类数据库的表或视图的增删改查，并且支持深度定制。\n\n现有相关产品\n智能检索:全文检索，快\n智能检索-批量比对:号码比对任务，个性化导出。\n实时检索:等级、时效性\n实时检索-一键搜:根据配置查询全部资源。\n档案:主线\n模型:页面拖拉进行关联运算\n\n资源智用\n比对核查:增量比对和全量比对，开发易用布控系统，数据量大的，慢的，都改为走本系统。\n全域智搜:支持资源级各类条件汇集单表搜索，展现形式参考一键搜（覆盖一键搜功能，覆盖智能检索，只要查询es的资源就差不多），也要参考档案和智能检索的展现形式，因为可能资源会很多，一键搜形式就不太好了\n批量比对:基于全域智搜，通用条件证件号码为大文本框，支持放入一批号码，一行一个，考虑保留证件类型，生成任务，直接拉取数据，不用统计，结果缓存。批量比对走实时核查模式，及时比对，若确实数据量大，速度慢，则走比对核查布控模式。\n全域摸排:全域智搜的交集，每类资源去重得到号码，内存再交集，得到交集号码，结合人工资源可以实现上传一批人进行摸排，添加功能“获取数据”，自动根据摸排出的号码，及条件调用批量比对功能生成任务，提示到批量比对查看结果。\n人工资源:支持用户上传任意数据（资源名称，证件号码，备用信息，前三个建立索引），纳入资源管理\n资源管理:统一资源管理，兼顾各类资源需求，资源添加数据量，便于摸排时优先核查数据量较小的表，然后依次缩小范围。\n\n证件号码考虑\n暂不考虑证件类型\n一表多证件:考虑拆分为多个资源\n', NULL, 32, '20200707150512', '20200721092042', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'ZYZY', 'ZIYUANZHIYONG', '3CFDB25669784E748EB7316AFC080E8D', '{\"markdown\":{\"显示目录\":true,\"标题样式\":\"\"}}', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446_3CFDB25669784E748EB7316AFC080E8D', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', '基础日志', NULL, '26D76B9507254066991543442CE5DC0A', '99', '09', '1', 1030, '02', '# 功能简介\n\n一般好的作业设计都会记录自己的日志，详细记录作业运行状况，本平台提供了平台级日志功能，不涉及业务，记录了作业的开始停止时间，最终运行结果（捕获了的预知的异常不算）及详细的日志文件。\n\n# 日志查看\n\n![数据大师-基础日志](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=69B6D36F8F224B5FA5DD927858EC148B)\n\n# 机制简介\n\n日志文件按天分文件夹存放，日志文件大小可以配置，若觉得占用空间，可以设计一个作业进行定时清理以前的日志文件，后续会提供该作业。也可以配置为不写日志文件。\n该功能也是由cn.benma666.kettle.job.JobManager作业实现，与运行状态更新是同一个作业。\n日志相关配置在字典类别“系统-kettle加-应用配置”中进行配置。', NULL, 43, '20200707213217', '20230602223258', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'JCRZ', 'JICHURIZHI', '3D7401FB3D9743A18008EC2A329679D8', '{\n  \"markdown\":{\n    \"显示目录\":true,\n    \"标题样式\":\"\"\n  }\n}', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446_33FC64D3885C46BEA2BAACF74BBCBD82_26D76B9507254066991543442CE5DC0A_3D7401FB3D9743A18008EC2A329679D8', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', '作业预警', NULL, '26D76B9507254066991543442CE5DC0A', '99', '09', '1', 1020, '02', '# 功能简介\n\n当我们调度的作业达几百个时，各个作业内部是否运行正常，其实是不知道的，每天人工逐个查看作业运行情况也是不现实的。\n\n本系统会自动进行异常检测，将匹配上设定的关键字的日志独立记录作为异常日志，同时作业本身输出的error级别的日志也会作为异常日志单独记录。\n\n# 预警查看\n\n![数据大师-作业预警](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=60754159D5DC4C26A5D75575E2C4BB31)\n\n# 消息通知\n\n基于以上生成的预警，我们可以增量将该预警推送到邮件、短信等消息平台进行消息通知，及时发现作业异常情况。', NULL, 73, '20200707213128', '20230602223202', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'ZYYJ', 'ZUOYEYUJING', '3F4BC62C57F245C7A4D3BA4BFCDCE877', '{\n  \"markdown\":{\n    \"显示目录\":true,\n    \"标题样式\":\"\"\n  }\n}', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446_33FC64D3885C46BEA2BAACF74BBCBD82_26D76B9507254066991543442CE5DC0A_3F4BC62C57F245C7A4D3BA4BFCDCE877', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', '数据对象', NULL, '4D87975B09344CC5ADDA4D3DC37D3312', '99', '01', '1', 10, '01', '# 功能简介\n\n所有数据，如oracle等数据库中的表或视图、excel文件数据、文本文件数据、文件、ES中的数据、GP中的数据等都抽象为数据对象，正如编程从面向过程编程升级为面向对象编程。\n\n一个数据对象的创建最基础的需要定义代码、名称、对象载体、具体对象等基础信息，就像一个人出生就会获得一个身份证号、姓名、所在行政区划、详细地址。\n\n目前支持：表、视图。\n\n# 新建\n\n【通】新建为所有数据对象通用功能，当然本新建因为业务需求，所有定制。\n\n新建数据对象，目前主要数据对象都是从数据库中导入表作为数据对象，后续可以导入excel、文本文件、ES等各类数据对象。也可以直接新建数据对象，通过“生成实体”功能生成对应的数据库表等。\n\n后续中通用功能将标记【通】。\n\n## 对象代码\n\n需要是唯一的。\n\n## 对象作用\n\n主要用于配置该数据对象的创建用于上面用途。\n\n## 对象归属\n\n在oracle类数据库中就代表用户，在mysql中就代表数据库。\n\n## 字段导入SQL\n\n一般不需要配置，导入对象时系统会自动生成导入字段的sql。\n\n系统会根据用户配置，自动生成获取字段的sql语句，用户可以在此基础上进行修改，最终以前端设置的导入sql为准。\n\n支持如下方式导入字段信息：\n1. 获取默认sql或自定义sql导入字段信息。\n2. 直接按如下格式配置字段信息,一行一个字段，依次为：字段代码,字段描述,字段类型,字段长度：\n```\nxm|姓名|VARCHAR2|100\nzjhm|证件号码|VARCHAR2|100\nzjlx|证件类型@SYS_COMMON_ZJLX|VARCHAR2|100\n```\n\n## SQL模板\n\n此处采用的是beetle模板工具，很优秀，具体用法可以参考官方文档。\n\n模板支持的参数：\n1. 样例：\n```sql\nselect\n-- @pageTag(){\n    ${sql.selectField}\n-- @}\nfrom ${sql.from} t\n-- @ where(){\n   ${sql.whereStr} ${sql.authWhere}\n-- @}\n-- @pageIgnoreTag(){\n	${sql.orderBy}\n-- @}\n```\n1. sql.defaultSql：当在数据对象配置中设置了sql模板时，可以通过此参数获取字典中配置的sql模板渲染出的sql语句。\n1. sql.selectField：默认查询字段\n2. sql.from：要查询的表，带对象归属的\n1. sql.whereStr：默认查询条件\n1. sql.authWhere：权限过滤条件\n1. sql.orderBy：默认排序\n5. sjdx：即当前操作的数据对象，是通过对象代码或id从数据库中加载的完整的数据对象的信息。\n7. fields：当前操作的数据对象的字段信息，为map结构，<字段代码，字段对象>可以通过字段代码获取到该字段完整的配置信息。\n9. yobj：前端通过myparams参数传入的json字符串解析出来的json对象，即获取前端传入的参数基本通过此获取。\n10. obj：通过当前操作的数据对象的主键从数据库中加载的完整的当前操作的记录信息，即与数据库中的信息一致。\n11. user：当前登录人的完整信息，字段信息与SYS_QX_YHXX表一致。\n12. user.jgxx：当前登录人的所属机构信息，字段信息与SYS_QX_JGXX表一致。\n13. user.qxMap：拥有的权限。\n1. czrz：操作日志对象，里面包含czip、url等信息。\n\n模板支持的方法：\n\n- 字符串工具\nFNP.su = cn.benma666.myutils.StringUtil\n- 时间工具\nFNP.du = cn.benma666.myutils.DateUtil\n- map工具\nFNP.mu = org.apache.commons.collections.MapUtils\n- 数据库工具\nFNP.mydb = cn.benma666.sjzt.Db\n- JSON工具\nFNP.json = com.alibaba.fastjson.JSON\n- jdbc工具\nFNP.ju = com.alibaba.druid.util.JdbcUtils\n- 用户管理工具，可进行权限判断\nFNP.um = cn.benma666.sjsj.web.UserManager\n- 系统配置工具，可以获取系统配置参数\nFNP.conf = cn.benma666.iframe.Conf\n- 字典工具\nFNP.dict = cn.benma666.iframe.DictManager\n- 身份证工具\nFNP.sfzh = cn.benma666.myutils.SfzhUtil\n- 类型工具，可以进行各种类型转换\nFNP.typeu = com.alibaba.fastjson.util.TypeUtils\n- 经纬度转换工具\nFNP.jdw = cn.benma666.myutils.JWDUtil\n\n## 扩展信息\n\n该扩展信息会合并到根参数，可以配置所有参数。\n\n因为kzxx字段长度限制为4000，若扩展信息过多，则可以采用在大字典中配置“对象代码.kzxx”的形式在大字典中进行配置，大字典的名称字段类型是大文本，可以参考数据对象的配置。\n\n### 当前用户信息设置\n```json\n{\n	\"zhgz\":{\n		\"yobj.cjrxm\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.yhxm}\"\n				}\n			}\n		},\n		\"yobj.cjrdm\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.id}\"\n				}\n			}\n		},\n		\"yobj.cjrdwmc\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.jgxx.jgmc}\"\n				}\n			}\n		},\n		\"yobj.cjrdwdm\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.jgxx.id}\"\n				}\n			}\n		}\n	}\n}\n```\n\n# 编辑\n\n【通】编辑功能是作用于每条记录的，在哪条记录中点击编辑则编辑哪条记录，可以对允许修改的信息进行修改。\n\n# 删除\n\n【通】此为单条记录删除功能，删除前将会有确认提示，确认删除将删除对应行的记录。\n\n# 详情\n\n【通】详情为也不可编辑的模式查询记录详情，将更全面的展示该记录的各数据项。\n\n# 查询\n\n【通】支持查询某项查询项为空的数据记录的功能，在输入框中输入my-null则可查询该项为空的数据，下拉字典类的查询项的字典最后一项为“为空的值”，选择该选项则查询为空的值。\n\n# 批量删除\n\n【通】支持批量删除选中的数据记录，删除前将会有确认提示，确认删除将删除选中行的记录。\n\n# 编辑模式\n\n【通】将以列表的形式进行数据编辑，便于对比修改多条记录。\n\n# 批量上传\n\n【通】基于设定的数据模板，按要求填充数据后，批量上传数据。\n\n# 模板下载\n\n【通】数据上传模板下载，模板中展示了模板的表头，每个字段的验证要求等，请不要修改下载的模板的格式。\n\n# 配置对象\n\n【通】将跳转到该数据对象的配置页面。\n\n# 配置字段\n\n【通】将跳转到该数据对象的字段配置页面。\n\n# 复制\n\n【通】通用的数据对象是参考新增字段进行的单条记录复制。\n\n数据对象中的复制是进行了定制的，支持复制数据对象的同时会复制该对象的所有字段信息，这个功能也是很实用的，因为我们经常会遇到需要配置两个或多个比较类似的数据对象。\n\n# 查看对象\n\n将弹出新页面展示对应记录的数据对象的列表页面。\n\n# 刷新对象\n\n若该数据对象的字段信息发生了变化，已经存在的字段不会被修改，这是避免人工配置的信息丢失，新增的字段将自动导入，删除的字段请人工在配置字段中删除。', NULL, 253, '20200709002411', '20230602150343', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'SJDX', 'SHUJUDUIXIANG', '42F03A5FE3B9425E98E46B52298485A2', '{\n  \"markdown\":{\n    \"显示目录\":true,\n    \"标题样式\":\"\"\n  }\n}', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446_4D87975B09344CC5ADDA4D3DC37D3312_42F03A5FE3B9425E98E46B52298485A2', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', '作业管理', NULL, 'A093B44916BF4D679E1BE2974BE79B9F', '99', '09', '1', 1010, '02', '# 功能简介\n\n提供了非常完善的作业管理功能，支持作业增删改查、参数设置、启动、停止、结束、目录查看、运行日志查看、作业图查看、定时设置、作业复制、作业重置等功能。\n\n# 主界面\n\n![image.png](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=4E3F385F335A48B3B09C46A1F4AB95DB)\n\n# 作业操作\n\n## 定时设置\n\n操作界面与kettle中的开始控件界面一致，这个是最有用的功能之一。\n本平台对定时控件进行了改进，支持设置作业初始执行，支持cron定时方式，使定时设置更加灵活。\n辅助生成cron表达式：[数据世界》辅助工具》cron表达式工具]\n\n![数据大师-作业管理-定时设置](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=AB969A67C8C94BDCB7032E916B005B3A)\n\n## 启动与停止\n\n在列表中批量选择需要操作的作业，点击“启动”按钮或“停止”按钮可以批量操作选中的作业。\n也可以在每个作业的操作列中进行单个作业的启停\n\n## 运行日志\n\n查看作业运行日志，掌握作业最新的运行情况，这个功能看起来不起眼，实际是非常有用的，当前已经实现自动实时刷新日志。\n因为实时日志在内存中保存是有时效性的，若需要更早的日志信息，请使用“基础日志”功能，可以下载查看所有历史日志信息。\n\n![数据大师-作业管理-运行日志](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=66DB2E02A5994CE4AF1D18A5612BBDBB)\n \n## 运行状态\n\n作业的运行状态会定时反映到管理界面，我们可以通过多种条件筛选我们需要的作业进行批量运行或停止。\n完成作业状态更新，日志文件记录的类：cn.benma666.kettle.job.JobManager，使用方式与按顺序运行的作业类似，请参考使用，该作业默认已经创建好“JobManager”，请不要删除他，并保证他正常运行。\n\n![数据大师-作业管理-运行状态](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=3DF5F8CCBAAD4160BAC96AE35C34B283)\n\n## 作业复制\n\n支持给某个作业复制出多个副本，结合“参数设置”功能，可以避免大量重复工作。\n一行一个作业，最后一级为作业名称，前面层级为目录。如：/test/xxx\n![image.png](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=B80F991FF43D4DB1A8134754CE285A37)\n\n## 参数设置\n\njob运行参数设置，可以在页面上设置作业运行参数，每次运行作业时会用设置的参数覆盖默认值，设置了参数需要重启作业。\n\n参数设置是非常重要的功能，在本系统中大量运用，可以将一些类似的需求由数据人员做成通用模型，然后由运维人员通过“作业复制”功能快速复制出很多的作业，再根据需要调整对应的参数即可。\n\n![image.png](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=5DF6D991E745478CAA2468C0913A27B6)\n![image.png](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=66D0EEFB906645DCA6F773F2C1BF7068)\n \n## 作业目录\n\n获取作业所在目录，因为我们有很多作业，很难记得每个作业在资源库中的目录位置，即使你记得，其他参与维护的人也是不知道的。\n当我们需要查看作业具体实现逻辑或进行修改时就需要知道作业做在的目录，便于快速定位作业进行工作，也是很实用的功能。\n\n![数据大师-作业管理-获取目录](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=C96781C111EB4690BCD1154ADB49303B)\n \n## 删除作业\n\n支持批量删除作业，这个很危险哦，请小心使用，不会删除子转换和作业。\n删除操作系统会进行确认提示，用户确认后将真实删除作业。\n\n## 作业图\n\n可以查看某个作业的流程图，与kettle中打开作业一致，只是此处无法编辑，为一张图片。\n![image.png](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=E84CE1849C9B4D9D94339394507E6914)\n\n## 强制结束\n\n强制结束等待的作业，针对正常停止无效的情况可以尝试这个功能，强制结束将直接结束作业的线程，是比较粗暴的操作，使用前建议先尝试“停止”功能。\n\n但本功能也不是很好使，因为很多时候卡死的线程不是作业本身这个线程，很多时候都是转换的某个步骤线程卡死，此时可以尝试本平台杀手锏级功能[数据世界》辅助工具》线程管理]，在线程管理中直接搜索作业名称，选中全部搜索出来的线程进行中断或结束，此功能要慎用哦。\n\n## 重新生成\n\n一般用于“对象流转”类型的作业，对象流转的配置相比较为复杂，有时需要完整的重新生成。\n此处支持批量重新生成。\n\n## 导入作业\n\n暂时没有实现，后续考虑实现与直接在kettle中导入作业类似的功能。\n\n## 作业重置\n\n当“强制结束”都不行的时候，线程管理理论上一定能结束，此功能是在线程管理之前设计实现的，有了线程管理按理说应该是用不到了，为备不时之需还是保留本功能。\n本功能就是舍弃该作业的本次运行对象的引用，就是说卡死就让他卡在那里不管他了，重置作业后，我们就可以重新运行该作业了。\n\n# 新建作业\n\n目前支持在web端新建五类作业，基于这五类作业可以实现大部分常见需求。\n\n![数据大师-作业管理-新建作业-类型选择](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=01A27C83C64843DB9693314C28715B6F)\n\n## 通用配置项\n\n此处以“JS作业”为例对新建作业的基本配置进行讲解，后续作业将只讲特殊配置项。\n1. 作业目录：为必填项，为该作业在资源库中的目录，便于分类管理，类似文件管理，自己根据情况设置即可。\n1. 作业名称：为必填项，比如日志等都会用到作业名称，作业名称为后续对该作业管理的主要依据，请不要设置重复的作业名称，建议每个系统根据情况事先规定好命名规则，便于后期维护，例如：DXLZ_OTHER_TEST1，采用这样的三段命名规则，一般为描述的简拼，后续一般不进行修改。\n1. 作业描述：为必填项，与作业名称对应，例如：对象流转-其他-测试1，描述一般用于人工识别，系统本身一般不使用它，后续可以根据需要进行修改。\n1. 作业类型：首先根据需要选择作业类型为“JS作业”。\n1. 作业类别：为人工对作业的分类便于后期系统维护，根据实际需求选择即可，不影响系统运行，该字典可以根据需要调整。\n1. 日志级别：非必填，默认“Basic”级别，一般保持默认即可，当有特殊需求可以根据需要调整。\n1. 扩展描述：实际是一个JSON对象，一般不用管它，可以用于记录该作业相关的扩展信息。\n2. 备注：用于针对该作业进行更详细的说明\n\n## JS作业\n\nJS作业就是用户可以编写一段javascript代码作为定时任务进行调度。\nJS脚本参考：\n```javascript\n//创建一个java对象，后续就可以通过和这个对应调用其内置方法。\nvar str1 = new Packages.java.lang.String(\"new字符串\");\n//打印一条基础日志。\n_entry_.logBasic(\"测试JS作业-基础日志：\"+str1);\n//打印一条调试日志\n_entry_.logBasic(\"测试JS作业-调试日志：\"+str1);\n```\nJS脚本内置对象：\n1. \\_entry_：为作业对象引用，可以通过它调用作业很多内置方法以实现我们的业务需求。\n1. 后续在根据需要进行梳理。\n\n![数据大师-作业管理-新建JS作业](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=7CF1005707054113B156967077B4308A)\n\n## SQL作业\n\n就是编写一个SQL脚本作为定时任务，比如定时执行一个更新操作等。\n1. 数据载体：就是选择要在哪个数据库中执行，数据载体管理在“数据世界-平台管理-数据载体”中进行管理配置。\n1. SQL脚本：就是我们要定时执行的脚本，根据不同的数据库对应的语法也不太相同。\n\n![数据大师-作业管理-新建SQL作业](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=484C6551E6584F72883AAF6384BCF43A)\n\n## shell作业\n\n就是编写一个系统Shell脚本作为定时任务进行调度，脚本语法需要根据平台所在操作系统决定，一般就是windows或linux。\n1. 工作路径：就是该脚本以哪个目录作为基础目录执行。\n1. Shell脚本：一般是windows的cmd命令或linux的Shell命令集，需要自行了解对应的语法。\n![数据大师-作业管理-新建Shell作业]\n![image.png](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=A5314B8D78DB4042A7B85CE14CB111F1)\n\n## KM作业\n\nKM作业是基于我的插件开发的作业，作业继承cn.benma666.km.job.AbsJob类，在java中实现自己的业务需求，然后打包放到本平台中，以这种方式进行调度。\n一些复杂的工作不能在上述的JS作业、Sql作业等中实现，此时就可以采用KM作业的形式，java中实现你就可以放飞自我了，理论上可以实现任何需求。\n一个实现类可以设置一些配置参数，使其更加灵活，该类也可以重复使用，通过配置不同参数实现各种类似需求。\n1. KM类名：此处填写完整的类名称（就是继承cn.benma666.km.job.AbsJob类的实现类），然后点击“获取默认配置”按钮，获取该作业支持的配置参数。\n1. KM配置：上述获取的默认配置将自动填充到此处，用户可以根据需要修改。\n![数据大师-作业管理-新建KM作业](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=AF80770478054471B4191A30AC6F6CB9)\n\n## 对象流转作业\n\n- 本版本暂未实现，考虑还是觉得有点复杂不太实用\n\n对象流转是建立在“数据对象”的基础上的，也是本平台的基础。\n数据对象添加到本平台中后，可以在很多地方使用，比如：作为输出目标接收数据，作为输入源提供数据，可以在web端实现增删改查等业务需求还支持提供各类http接口等。\n1. 来源对象：数据输入源配置，已经存在可以直接选择，不存在则可以根据需要创建，“配置字段”就是对该对象的字段进行配置，因支持的配置项比较多，对应的配置说明请参考具体功能。\n1. 目标对象：数据接收目标对象配置，配置与“来源对象”基本一致。\n1. 流转模板：平台提供了一些默认的对象流转模板，也是可以满足大部分常见场景的，当具体到一些特殊的业务场景，用户也可以创建自己的模板，调整下字典配置就可以像默认模板一样使用了（模板配置也是比较高层次的使用了，一般用户不用深入）。\n1. 获取默认配置：当选择好流转对象和流转模板后，点击“获取默认配置”后可以获取该模板对应的默认配置信息，基于默认的配置信息，用户可以根据需要修改以满足自己的需求。\n1. 输入组件：根据不同的业务需求选择不同的组件。\n1. 输出组件：跟输入组件类似选择。\n1. 字段映射：用户可以在notepad++、excel等功能强大的编辑器中编辑好后粘贴进来，基于已有的字段信息可以快速完成字段映射配置。\n1. 扩展描述：因不同对象类型、组件类型有很多特殊的配置信息，这些配置信息都将存储在扩展描述中，用户可以基于默认配置根据需要修改即可。\n\n## 按顺序运行\n\n我已经开发好了一个上面的KM作业：cn.benma666.kettle.job.KettleJobRunner，这样的作业可以作为“KM作业”使用，具体使用请参考对应的使用说明。\n这个作业已经包含在项目中了，可以直接使用。\n用户可以在KM配置-作业id列表中配置要按顺序执行的作业id，作业的id请在作业查询列表中查看，配置好后，系统将根据用户配置的作业顺序执行，前一个作业执行成功才会执行下一个作业，其中一个作业执行失败则不再执行后续作业。\n\n\n# 作业修改\n\n支持在web端对作业一些常见的属性进行设置，简化用户操作。\n![数据大师-作业管理-作业修改](##urlRoot##default?sjdx.dxdm=SYS_QX_QTQX&sys.cllx=download&yobj.id=2314B4ED05C24E7ABEBE4BC54243C844)\n\n## 作业描述\n\n作业的中文描述，随着业务的变化，可能需要修改该描述以更精确的对作业进行描述。\n\n## 自动重启次数\n\n支持配置失败自动重启。\n\n## 作业分类\n\n将job_version字段作为作业类别使用，便于分类管理。\n\n## 增量时间戳\n\n为增量抽取的时间戳，对象流转的增量抽取每次都会读取该时间戳，只读取大于等于该时间戳的数据，抽取完成后会更新为最新的时间戳。\n当我们需要全部重新抽取或重新抽取指定时间范围内的数据时，我们只需要修改该时间戳即可。\n\n## 日志级别\n\n当我们需要详细研究一个作业时，我们可以将作业的日志级别调整为“Debug”等级别，就可以输出更详细的日志，或者作业日志量太大，我们想日志少一点，那就可以将日志级别改为“Error”等级别减少日志输出。\n\n## 作业状态\n\n本平台默认查看作业状态为“产品”的作业，本平台建议只有产品状态的作业才需要纳入作业管理，这样就可以屏蔽还在开发中的、过期的、一些公共作业等，放在意外误操作。\n所有我们可以根据需要将作业状态改为草稿或产品状态。\n\n## 扩展描述\n\n可以用于记录一些作业相关信息。\n\n## 重新生成\n\n一般用于“对象流转”类型的作业，对象流转的配置相比较为复杂，有时需要完整的重新生成。\n\n## 备注\n\n用于针对该作业进行更详细的说明', NULL, 226, '20200707192012', '20240603163041', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'ZYGL', 'ZUOYEGUANLI', '43947035D9F546C291B82369C9479313', '{\n  \"markdown\":{\n    \"显示目录\":true,\n    \"标题样式\":\"\"\n  }\n}', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446_33FC64D3885C46BEA2BAACF74BBCBD82_A093B44916BF4D679E1BE2974BE79B9F_43947035D9F546C291B82369C9479313', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', '已实现功能', NULL, '9B5A99E235634E03976F347E023C3883', '99', '01', '1', 99999, '01', '1. 笔记支持图片、文件上传，添加uediter控件。\n2. 文档怎么写，自己结合ztree和markdown开发文档管理系统\n3. 解决查询功能中，修改了前端传来的原始数据的问题，以后都不能修改原始数据。\n4. 对象配置的查询模板时无法使用详情，需要将详情改为调用分页查询\n5. 拆分出大字典项的字典，新增大字典管理，mc为clob类型。\n6. 文件控件支持清除文件。\n7. 笔记的权限机制实现。\n8. 新增操作全部的功能。\n9. 通用文件存数据库，结构还是之前的方式，数据才有dmp方式。\n10. 文件上传支持控制是否按日期分文件夹。\n11. 数据库支持配置连接池参数\n12. 把对象监控配置改到字典中去\n13. 优化时间控件，支持灵活的时间格式。\n14. 同一个service的项目间面登陆，右上角系统导航能跳转对应的应用。\n15. 加一各前端执行sql的功能，先选择数据库，sql文本框，确定后，执行sql，返回结果放入json控件中。\n16. 添加通用对应复制功能。\n17. 支持数据库：greenplum、华为mpp\n18. 实现json框控件、密码控件\n19. eova的图标集导入文件管理中供选择，数据载体用本地文件。\n20. 图标选择控件，图标控件弹出图标查询页面进行图标选择（common/icon），图标查询页列表添加选择按钮，选择后关闭图标查询页面，回传选择的图标信息，selectpage是不是也支持展示图标。\n21. 文字图标的名称，去重码都只保留class内的内容，将翻译结果存入描述字段。\n22. 数据库中建立图标表（就使用文件表，图片类型为icon时为文字图标），从网页中取出全部图标，对该表配置一个查询页面，格式化一个虚拟字段展示出图标。\n23. 文件管理支持存储在数据库和ftp，url，其他某个库中某个表的某个大字段。\n24. 改进密码控件，密码还是加密存储，密码控件可以不止用于密码字段，还可以用于任何想加密的字段，作为通用的字段加密机制，密码字段扩展信息中设置字段密码，后台设置二次加密密码，用后台密码对字段密码加密，取前20位作为真正密码，用des进行加密，如此知道前端密码没用，后台密码必须严格保密，密码控件支持输入后台密码查看真正解密的信息，当需要将某个密码字段给第三方时，将后台密码解密后的字段密码的前20位提供给他即可，这样其他字段不会因此泄露，也能保证传输安全，系统对密码字段提供批量更新机制，加密机制以工具类的形式实现，便于更换字段密码和后台密码，字段支持配置加密方式（md5，des，自己设计一个快速的加密方式，用于大数据量加密）。\n25. 关于权限码，父节点增删改时，需对子节点做对应调整，新建时先选择父节点，当权限码为空时，自动填写权限码前缀。\n26. 在common中类似字典添加清理缓存接口。\n27. json控件在列表页面按普通文本处理。\n28. 字段修改自动清空数据对象缓存。\n29. 字段排序功能实现。\n30. 分页：支持配置默认不统计总量，不统计时，只展示：首页，上一页，下一页。\n31. 展示数据对象组件，添加柱状图，通用性调整，支持自定义列表展示模板（使用tmpl，或组件路线），默认还是列表模式，不支持选择，通过扩展信息配置才展示。\n32. 改进list组件（不动原组件，不要影响现有功能，复制一份修改），列表可以渲染为列表，各种图形，个性化列表，支持在各种模式间切换。\n33. 添加访问日志统计，操作次数排行榜，登陆次数排行、柱状图、饼状图（统计图表功能，先搞几个常用的图表控件）。\n34. 校验机制不用外部组件，自己按自己规则重新实现，在设值时就进行校验，前后台端统一校验规则。\n35. 查询表单的校验需要额外处理，不进行常规校验，需要进行查询时校验的，在字段扩展信息中配置。\n36. 表单提交时进行统一校验，新增编辑页面，查询表单，编辑列表都需要对应调整，输入控件添加一个参数fromid，由外层告知当前输入控件属于哪个表单，在_root中存储frommap<fromid，<name，输入控件对象>>。\n37. 调整编号生成规则，减短编号长度，autoid支持选择如下方式：在数据库中建立sys_sjgl_bhsc，字段为通用字段和编号类别，当前值，递增量，初始值，最大值，当前周期，重置周期（天，月，年），配置对应管理功能。\n38. 字段管理中添加：模板展示，字段，记录是否在批量上传模板中展示该字段。\n39. 缓存机制，默认内存缓存，支持扩展redis，支持指定为内存机制，默认机制支持配置，添加清除缓存接口。\n40. 员工身份证号重复判断：走字典接口，在字典中配置字典类别：JCGA_JCYG_SFZHCQ，代码为待查身份证号，不能走缓存，连字典项都不能缓存，在字典翻译接口添加参数，判断是否走缓存，前端同样区分缓存和非缓存方法。\n41. 批量上报时，后端字段校验中也可拿到用户进行相关校验，如字典相关判断。\n42. 字典支持根据用户进行权限过滤，将用户信息和前端参数传入进行模板渲染，这类字典请设置为不缓存。\n43. 单位代码改为id和用户代码改为id，全球唯一码机制。\n44. 简拼全拼生成添加限制，超过两百字则不生成简拼全拼。\n45. 文件下载接口支持参数控制是否根据文件名后缀写头信息，从而浏览器直接识别展示，而非下载。\n46. 文件控件\n47. 文件上传控件实现，然后修改文件管理新增功能，支持上传配置，文件管理详情，支持图片展示。\n48. 文件管理添加拦截器，物理删除时同时删除文件。\n49. 文件管理模块支持上传，在文件管理上方加文件上传按钮，上传到common/other目录，默认上传到数据库，上传后可以编辑修改文件名等。\n50. 改进字典接口，不用map参数，好用些。\n51. 字典需要改进，字典类别中配置，避免较大的字典一次性加载，大字典在字典缓存中标记为大字典，在获取字典项处改为直接查询数据库并缓存，支持单个和多个，查询前先检查缓存，之前的清理缓存等机制迁入以替换原字典管理，接口支持一次查询多个接口，前端按类别请求大字典时返回大字典标记，后续字典翻译逐个请求并缓存，仍然先监测缓存，不存在则请求后台，机制基本与后台一致。\n52. 具体权限控制：没有配置权限则按无权限处理，新增对象权限菜单时，自动生成默认权限，初始化和后续批量维护暂时就直接操作数据库，然后前端和后端根据配置的权限进行控制。\n53. 菜单：左侧树形结构，右侧列表页面开发。\n54. 登陆、菜单支持简单配置出多个。\n55. 新建数据对象权限时，自动生成默认子权限，插入查询语句，就以数据对象的权限为基础，过滤掉特有权限。\n56. 建议框：就是字典框，但他搜索的是名称，就是前端当字典框，后端当文本框。\n57. 登陆，菜单框架，放到模板中便于配置多个页面。\n58. 数据对象的页面参数，如按钮名称等，支持在对象扩展中设置。\n59. 把关系图改为走数据对象模式，图片，js，css等都可以走文件管理上传，然后在代码中引用，神操作。\n60. 导出全部：怎么支持更大量的导出，考虑支持分页控制，这样就能持续导出大量数据。方案：页大小添加5、1000、2000、5000，默认任然10，通过调整页大小然后导出当前页，再在后台实现一个通用导出全部，导出数量限制支持对象级配置，默认值走字典，需要支持按页导出全部。\n61. 数据库管理升级为数据载体管理（文件，ftp，数据库等都可以抽象出地址，用户名，密码，额外信息走扩展信息）。\n62. 字段描述规范：展示名称@字典代码;扩展描述。系统支持自动识别。\n63. 分页查询：初始查询、异步统计、默认不统计。\n64. 已经支持控件：输入框、字典框（单选，搜索，多选）、时间框、大文本框\n65. 系统自动根据字段描述、类型等信息对长度、控件类型等进行默认设置，减少人工配置\n66. 支持配置增删改查功能\n67. 字段，对象信息可走jsp变量或ajax请求，ajax优先。\n68. 加入虚字段的概念，操作作为默认虚字段。\n69. 支持对搜索字段进行搜索方式选择，模糊、精确、左模糊、右模糊，并支持为字段配置默认值，也可配置某个字段不支持搜索方式选择，不支持选择时，就只能使用设置的默认搜索方式。支持用户保存自定义。考虑改为采用%通配符的模式，更易用。\n70. 拦截器：可以像写kettle插件一样单独编写，放一个jar进去，前端到后端都可以完全重新定制，串联好，可以终止在某个环节直接返回，拦截点考虑全面，所有功能都基于此进行开发，做几个功能后就比较完备了，多实现几个常用的拦截器，不同对象类型的支持等都可以改为拦截器实现方案。\n71. 对象扩展（是不是考虑还是走字典的配置，比json好管理呢，前者依附对象是一个整体，后者集中配置，数据结构好一些，或者一起使用，需进一步考虑）作为拦截器参数机制，从而提升拦截器的通用性，把不常用的配置都放在这个字段中，避免表字段过分扩张。\n72. sql模板的支持定制，列表、编辑详情参考sql模板形式。\n73. 编辑页面改为精确控制修改了的字段，标记出修改了的字段。\n74. 配置的方式实现导入对象。\n75. 支持多选字段的搜索。\n76. 支持列表编辑模式切换。\n77. 支持自定义页面组件。\n78. 字段简拼全拼自动设置，查询自动支持简拼全拼，在默认拦截器中实现，通过扩展字段配置相关字段信息，配置主字段，简拼全拼字段，搜索字段列表。\n79. 走批量处理的接口：复制对象，刷新对象，删除，批量删除，拦截器实现功能。\n80. 逻辑删除支持：设置了有效性的对象支持进行逻辑删除，同时支持对已经无效的数据进一步进行物理删除。\n81. 标准化排序（重新按10的间隔排序，方便穿插）\n82. 支持在sql模板中调用db工具类进行数据库操作。\n83. 列表序号和复选框列都改为虚拟字段机制实现。\n84. 日志体系：web过滤器维度，将数据对象map中的信息也存入相关参数中。\n85. 设计用户单位结构，实现filter拦截，即使是service也要有用户体系，可以提供默认用户，支持后续的权限体系，参考之前的认证机制，实现免登陆，考虑app的场景，支持取会话id作为权限码，，uaac登陆使用cqqb2的转发服务，只有这个服务集成uaac，通过http交互，将用户信息映射到我的用户体系实现衔接，我的所有功能全部走自己的用户体系，免得将来切换麻烦，将来与任何系统集成都可以建立对应的转换服务即可对接。\n86. 复选框控件支持（列表编辑支持全选或全部取消），就统一使用编辑列表那个对象吧。\n87. 各sql模板优先读取该对象自己的模板，sjdx的作为默认模板。\n88. 加入项目代码：创建应用管理表，管理项目基本信息，地址，分类，默认数据源（目前走spring的事务机制，只有默认数据支持事务，事务只有注入的类上才有用，他是通过代理实现的，可以看一下这部分代码，实现人工调用，还是需要此项，每个项目主要操作的数据库可能不一样，在此处配置项目主数据库），状态，描述等，各项目配置中需要配置自己的项目代码，根据代码获取项目具体信息，包含项目名称，sconf支持配置是否需要初始加载临时数据库信息供读取配置，默认不需要，其他项目都直接走service的配置中心，这样所有项目就只需要一个配置文件，包含service地址，和临时数据库配置信息。\n89. 数据库管理：支持状态检查，动态添加进系统（db改进后，可使用时加载），管理其中数据，需要获取每个数据源的用户，一切支持jdbc的数据源，考虑连接池参数的配置（通用配置的基础上支持在数据库配置的扩展信息中进行个性定制，通用配置要设置小一点），默认数据库配置还是加入到数据库配置表吧，考虑还需不需要km那种支持配置文件中进行多数据源配置的方式（就以配置表为主吧那，只有service中配置一个临时数据库信息供初始配置加载，在sconf中加载数据库配置表中的默认数据库的配置供spring数据库注入需要，之后清除，全部以数据库配置表的数据为准，因为可以对连接池进行定制），改进db工具类，use数据库不存在时，支持主动从数据库配置中读取相关配置创建数据源，这样可以按需加载，避免浪费，postgresql、gp、h2、mysql的支持。\n90. 支持gp元数据导入及相关查询功能。\n91. 各类型数据库的测试sql和驱动等可以在通用配置中统一设置，这样就可以把gp这些通用化处理，当成一般库对待。\n92. 整个页面默认应该极简（通过包装组件打到目标），对象中可以自定义vue模板以替换默认模板', NULL, 9, '20200709010553', '20230602232858', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'YSXGN', 'YISHIXIANGONGNENG', '43F07C73E192435697F9950CFC8C55DC', '{\n  \"markdown\":{\n    \"显示目录\":true,\n    \"标题样式\":\"\"\n  }\n}', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446_9B5A99E235634E03976F347E023C3883_43F07C73E192435697F9950CFC8C55DC', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', '测试', NULL, '4EB2166D5077430283980676A2772A80', '01', '09', '1', 99999, '01', '<h1 style=\"text-align: center; font-size: 2em;\">测试富文本</h1>\n<p>测试普通文字</p>\n<!--恶意脚本植入-->\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"sjsj-ht/default?sjdx.dxdm=SYS_QX_QTQX&amp;sys.cllx=download&amp;yobj.id=F7D3CCA2587D4FA696C331AD20F3E1F3\" width=\"480\" height=\"640\"></p>\n<h2 style=\"font-size: 1.5em;\">附件</h2>\n<p><a href=\"sjsj-ht/default?sjdx.dxdm=SYS_QX_QTQX&amp;sys.cllx=download&amp;yobj.id=5835E452395A429C85BC836E92415B53\">notice.mp3</a></p>', NULL, 502, '20211227142436', '20240625093324', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'CS', 'CESHI', '46C58B01399E4A0AB1D319351D66141C', '{\n	//标题是否显示\n	titleShow:false\n}', NULL, '4EB2166D5077430283980676A2772A80_46C58B01399E4A0AB1D319351D66141C', '0', '0', '0');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', '员工数据上报说明', NULL, '4EB2166D5077430283980676A2772A80', '99', '09', '1', 99999, '02', '# 注意事项\n\n1. 请不要修改数据模板表头信息，否则系统无法识别。\n1. 上传过程中提示的错误信息，都说明了问题的处理方式，请仔细阅读。\n1. excel数据建议所有单元格全部调整为文本格式，特别是身份证、时间等数据。\n1. 社会关系中，若是父母去世了,可以这样填写。比如父亲去世，社会关系填：“父亲”，备注：“已经去世”其他项空着即可。再如配偶离婚的场景，备注这么写就行：“无法获取证件号码其他情况：已经离异无联系”。\n\n# 上传后说明\n\n1. 只有“申办隔离区证”为“是”的数据才会传输到安检站。\n1. 数据上传成功后，需要经过较多环节才能到安检站，所有请二十分钟后再确认数据传输情况。\n1. 当收到短信提示：证件号码或姓名错误时，请核查本人，还有社会关系是否正确，录入系统的社会关系可以点击人员列表最后的第三个按钮查看。\n1. 半小时后数据若是没有到达安检站，可以咨询机场公安电话：67156307，看是否核查未通过。', NULL, 56, '20191127113216', '20200701182454', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'YGSJSBSM', 'YUANGONGSHUJUSHANGBAOSHUOMING', '4AE60B823BA549F89C15B15C8E2635A7', '{\"markdown\":{\"显示目录\":false,\"标题样式\":\"\"}}', NULL, '4EB2166D5077430283980676A2772A80_4AE60B823BA549F89C15B15C8E2635A7', '1', '1', '1');
INSERT INTO `sys_sjgl_grbj` VALUES ('02', '平台管理', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446', '99', '01', '1', 1020, '01', '\n# 平台管理\n\n平台管理类功能。\n\n## 数据字段\n\n\n\n## 数据字典\n\n## 数据载体\n\n## 应用管理\n\n目前推荐只维护此一个项目，不要进行复制等操作，便于升级。\n\n若有新功能需要开发，但又不是通用的，且引入了其他不必要的东西，则建议以开发扩展包的形式实现，引入相关包即可集成相关功能，不需要时移除即可，保持主项目的简洁性，过于复杂的项目是不好维护推广的。\n\n按如上建议开发，线上部署时可以相关配置，部署为多个项目，即一套源码部署多套，避免附加功能影响常规功能。\n\n新部署的项目在应用管理中添加进行管理，还可以生成监控任务进行系统运行情况监控。\n\n所有web应用都可以添加到此处管理。\n\n## 服务器管理\n\n## 文件管理\n\n## 访问日志\n\n## 后台日志\n\n## 编号管理\n\n## 个人笔记\n\n## SQL执行\n\n## 清空缓存\n', NULL, 41, '20200707150101', '20200709002507', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'PTGL', 'PINGTAIGUANLI', '4D87975B09344CC5ADDA4D3DC37D3312', '{\"markdown\":{\"显示目录\":true,\"标题样式\":\"\"}}', NULL, 'A3FEC59BDBE0476B857E0D007B4D5446_4D87975B09344CC5ADDA4D3DC37D3312', '1', '1', '1');
