INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_ZNJH_CTDY', '系统-智能交换-穿透调用', 99999, NULL, NULL, '02', 'table', 'default', NULL, 'sys_znjh_ctdy', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px,gxsj desc', '1', '1', '1', NULL, NULL, NULL, '20221012160125', '20221012160125', '06', '1', '{\n  \"sys\":{\n    \"fields\": {\n      \"cjrdm\": {\n        \"zdms\": \"创建人代码\",\n        \"zddm\": \"cjrdm\"\n      },\n      \"cjrxm\": {\n        \"zdms\": \"创建人名称\",\n        \"zddm\": \"cjrxm\"\n      },\n      \"cjrdwdm\": {\n        \"zdms\": \"创建人单位代码\",\n        \"zddm\": \"cjrdwdm\"\n      },\n      \"cjrdwmc\": {\n        \"zdms\": \"创建人单位名称\",\n        \"zddm\": \"cjrdwmc\"\n      }\n    }\n  }\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', NULL, 'XITONG-ZHINENGJIAOHUAN-CHUANTOUTIAOYONG', '03F5C599950C4C2A9253A6CC0133A161');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_LOG_FWRZ_MKTJ', '系统-日志-访问日志-模块统计', 99999, NULL, NULL, '02', 'xndx', 'default', NULL, 'v_xndx', 'id', NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, '1', '1', '1', NULL, NULL, '/*\nvar whereStr  = \"\";\nif(!isEmpty(yobj.tjzb)){\n   whereStr  = whereStr + \"and dxmc like #{\'%\'+yobj.tjzb+\'%\'}\";\n}\nvar field = fields.cjsj;\nsu.clEqDate(field , yobj);\nif(!isEmpty(yobj[field.zddm+\"_start\"])){\n	whereStr = whereStr + \" and \"+field.zddm+\" >=#{yobj[\'\"+field.zddm+\"_start\']}\";\n}\nif(!isEmpty(yobj[field.zddm+\"_end\"])){\n	whereStr = whereStr + \" and \"+field.zddm+\" <=#{yobj[\'\"+field.zddm+\"_end\']}\";\n}\n*/\nselect\n-- @pageTag(){\n    ${sql.selectField}\n-- @}\nfrom (\nselect sjdx id, max(dxmc) tjzb, count(1) cs\n  from (select t.*, dx.dxmc dxmc\n          from sys_log_fwzr t\n          left join sys_sjgl_sjdx dx\n            on dx.id = t.sjdx) t\n-- @ where(){\n   				${whereStr}\n-- @}\n group by sjdx\n) t\n-- @pageIgnoreTag(){\n   order by cs desc\n-- @}', '20190506182549', '20221205210455', '06', '1', '{\n  \"lbymkz\":{\n    \"my-lbms\":\"ba\",\n    \"列表模式字典数据\":[{\n      \"dm\":\"list\",\n      \"mc\":\"列表\"\n    },\n    {\n      \"dm\":\"pie\",\n      \"mc\":\"饼图\",\n      \"optios\":{\n        \n      }\n    },\n    {\n      \"dm\":\"txt\",\n      \"mc\":\"条形图\",\n      \"type\":\"ba\",\n      \"optios\":{\n        \"visualMap\":{\n          \"oiet\":\"vetical\",\n          \"top\":\"cete\",\n          \"left\":\"ight\"\n        },\n        \"leged\":\"\",\n        \"seies\":{\n          \"label\":{\n            \"positio\":\"ight\"\n          }\n        },\n        \"xAxis\":{\n          \"type\":\"value\",\n          \"axisLabel\":{\n            \"otate\":0\n          }\n        },\n        \"yAxis\":{\n          \"type\":\"categoy\"\n        }\n      },\n      \"fuOptios\":{\n        \"_this.epaams.seies.label.fomatte\":\"labelZh\"\n      }\n    },\n    {\n      \"dm\":\"ba\",\n      \"mc\":\"柱图\",\n      \"optios\":{\n        \"leged\":\"\"\n      }\n    },\n    {\n      \"dm\":\"lie\",\n      \"mc\":\"折线图\"\n    },\n    {\n      \"dm\":\"zdy\",\n      \"mc\":\"自定义\"\n    }]\n  }\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-RZ-FWRZ-MKTJ', 'XITONG-RIZHI-FANGWENRIZHI-MOKUAITONGJI', '05405FB19362440DB7B6763DB18536F0');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_LOG_FWZR', '系统-日志-访问日志', 99999, NULL, NULL, '01', 'table', 'default', NULL, 'SYS_LOG_FWZR', 'id', NULL, 'gxsj', NULL, NULL, NULL, NULL, '3', 'gxsj desc', '1', '1', '1', NULL, NULL, '', '20181220215058', '20221117085354', '06', '1', '{\n	\"fields\":{\n		\"czip\":{\n			\"dcmrbjs\":\"RED\"\n		}\n	},\n  \"sys\":{\n    \"fields\":{\n      \"cjrdm\":{\n        \"zdms\":\"创建人代码\",\n        \"zddm\":\"cjrdm\"\n      },\n      \"cjrxm\":{\n        \"zdms\":\"创建人名称\",\n        \"zddm\":\"cjrxm\"\n      },\n      \"cjrdwdm\":{\n        \"zdms\":\"创建人单位代码\",\n        \"zddm\":\"cjrdwdm\"\n      },\n      \"cjrdwmc\":{\n        \"zdms\":\"创建人单位名称\",\n        \"zddm\":\"cjrdwmc\"\n      }\n    }\n  }\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-RZ-FWRZ', 'XITONG-RIZHI-FANGWENRIZHI', '07DCAFB42634494C85B1F90A442489F1');
INSERT INTO `sys_sjgl_sjdx` VALUES ('QT_DCXT_CZ', '其他-点餐系统-餐桌', 99999, NULL, NULL, '01', 'table', 'default', NULL, 'QT_DCXT_CZ', 'id', NULL, 'gxsj', '', NULL, NULL, 'yxx', '1', 'px,gxsj desc', '1', '1', '1', NULL, '', 'select \n-- @ pageTag(){\n${sql.selectField},\n(case when krry>10 then 0 else 1 end) update_show\n-- @}\nfrom ${sql.from} t where 1 = 1 ${sql.whereStr} ${sql.authWhere} \nand t.cjrdm=\'${user.id}\'\n${sql.orderBy }', '20200714100544', '20231221215838', '06', '1', '{\n  \"sys\":{\n    \"fields\":{\n      \"cjrdm\":{\n        \"zdms\":\"创建人代码\",\n        \"zddm\":\"cjrdm\"\n      },\n      \"cjrxm\":{\n        \"zdms\":\"创建人名称\",\n        \"zddm\":\"cjrxm\"\n      },\n      \"cjrdwdm\":{\n        \"zdms\":\"创建人单位代码\",\n        \"zddm\":\"cjrdwdm\"\n      },\n      \"cjrdwmc\":{\n        \"zdms\":\"创建人单位名称\",\n        \"zddm\":\"cjrdwmc\"\n      }\n    }\n  }\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'QT-DCXT-CZ', 'QITA-DIANCANXITONG-CANZHUO', '0A95157EDA474FE68CAEA1C13DE51B0D');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SHRMYY_HLB_ZLJC_AZBTJ_LSVC', '射洪人民医院-护理部-质量检查-按指标统计-落实率较差', 99999, NULL, NULL, '02', 'view', 'sjsj_yw', NULL, 'v_xndx', 'id', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'dbl', '1', '1', '1', NULL, NULL, '/*\r\nvar whereStr  = sys_sjgl_sjdx;\r\nvar whereStr1  = sys_sjgl_sjdx;\r\nif(!isEmpty(yobj.tjzb)){\r\n   whereStr  = whereStr + and t.zbmc like \'%\'||#yobj.tjzb#||\'%\';\r\n}\r\nif(!isEmpty(yobj.zblb)){\r\n   whereStr  = whereStr + and zblb = #yobj.zblb#;\r\n}\r\nvar field = fields.cjsj;\r\nsu.addEqDate(field , yobj);\r\nif(!isEmpty(yobj[cjsj_start])){\r\n	whereStr = whereStr +  and jl_cjsj >=\'+yobj[cjsj_start]+\';\r\n}\r\nif(!isEmpty(yobj[cjsj_end])){\r\n	whereStr = whereStr +  and jl_cjsj <=\'+yobj[cjsj_end]+\';\r\n}\r\nif(!isEmpty(yobj[dbl_start])){\r\n	whereStr1 = whereStr1 +  and dbl >=\'+yobj[dbl_start]+\';\r\n}\r\nif(!isEmpty(yobj[dbl_end])){\r\n	whereStr1 = whereStr1+  and dbl <=\'+yobj[dbl_end]+\';\r\n}\r\nvar orderby  = obj.orderBy;\r\nif(isEmpty(orderby )){\r\n     orderby = order by dbl asc;\r\n}\r\n*/\r\nselect t.*  from (\r\nwith a as\r\n (select t.*, k.mc ksmc\r\n    from V_SHRMYY_HLB_ZLJCX t\r\n   inner join shrmyy_jcxx_ksxx k\r\n      on k.id = t.ks\r\n   where k.YXX = \'1\' ${whereStr})\r\nselect t.*,\r\n       (select wm_concat(distinct t1.ksmc)\r\n          from a t1\r\n         where t1.z_id = t.z_id\r\n           and t1.sfdb <> \'1\') wdbks,\r\n       dbl score\r\n  from (select nvl(max(t.tjmc),t.zbmc) zbmc,\r\n               max(t.z_id) z_id,\r\n               max(t.z_px) z_px,\r\n               max(t.ssdl) ssdl,\r\n               max(t.zblb) zblb,\r\n               sum(sfdb),\r\n               count(1),\r\n               ROUND((sum(sfdb) / count(1)) * 100, 1) dbl\r\n          from a t\r\n         group by t.zbmc) t\r\nwhere 1=1 ${whereStr1}\r\n ${orderby }\r\n) t', '20191114113437', '20230814225254', '06', '1', '{\n  \n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'SHRMYY-HLB-ZLJC-AZBTJ-LSLJC', 'SHEHONGRENMINYIYUAN-HULIBU-ZHILIANGJIANCHA-ANZHIBIAOTONGJI-LUOSHILVJIAOCHA', '0B6D6C3523C4454E927D3F3FF0221C86');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_ZNBK_JG', '系统-智能布控-结果', 99999, '正式环境请采用分区表', NULL, '02', 'table', 'bdhc_default', NULL, 'V_SYS_BDHC_JG', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '3', 'gxsj desc,hdfssj desc', '0', '1', '1', NULL, NULL, 'select\n-- @pageTag(){\n    ${sql.selectField}\n-- @}\nfrom ${sql.from} t\n-- @ where(){\n   t.rw_ssxm=\'D465CAAEA8E34BF9955367337D1A7979\' and yxx=\'1\' ${sql.whereStr} ${sql.authWhere}\n-- @}\n-- @pageIgnoreTag(){\n	${sql.orderBy}\n-- @}', '20200427173229', '20220120095149', '06', '1', '{\"lbymkz\":{\"pagePath\":\"zbk/bkjgList\"},\"sys\":{\"fields\":{\"cjrdm\":{\"zdms\":\"创建人代码\",\"zddm\":\"cjrdm\"},\"cjrxm\":{\"zdms\":\"创建人名称\",\"zddm\":\"cjrxm\"},\"cjrdwdm\":{\"zdms\":\"创建人单位代码\",\"zddm\":\"cjrdwdm\"},\"cjrdwmc\":{\"zdms\":\"创建人单位名称\",\"zddm\":\"cjrdwmc\"}}}}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-ZNBK-JG', 'XITONG-ZHINENGBUKONG-JIEGUO', '115348A1FF4F4F7591E96BB9F757F7BA');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_YXJK_JKRW_GXT', '系统-运行监控-监控任务-关系图', 99999, NULL, NULL, '02', 'table', 'default', NULL, 'SYS_YXJK_JKRW', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px', '1', '1', '1', NULL, NULL, NULL, '20181225212709', '20190505185158', '06', '1', '{}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-YXJK-JKRW-GXT', 'XITONG-YUNXINGJIANKONG-JIANKONGRENWU-GUANXITU', '1186CA50965541EFA177F49A57A25A14');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_QX_QXXX_JSSQ', '系统-权限-权限信息-角色授权', 99999, NULL, NULL, '02', 'table', 'default', NULL, 'SYS_QX_QXXX', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px,gxsj desc', '1', '1', '1', 'cn.benma666.sjsj.ljq.qxgl.QxxxLjq', '', 'select\n-- @pageTag(){\n    ${sql.selectField}\n-- @if(!isEmpty(yobj.js)){\n		,(select (case when count(1)>0 then 1 else 0 end) from sys_qx_jsqxgl jq where jq.yxx=\'1\' and jq.js=#{yobj.js} and jq.qx=t.id) checked\n-- @}\n-- @}\nfrom ${sql.from} t\n-- @ where(){\n   ${sql.whereStr} ${sql.authWhere} and yxx=\'1\'\n-- @}\n-- @pageIgnoreTag(){\n	${sql.orderBy}\n-- @}', '20190330161317', '20240704154635', '06', '1', '{\n  \"sys\": {\n    \"fields\": {\n      \"cjrdm\": {\n        \"zdms\": \"创建人代码\",\n        \"zddm\": \"cjrdm\"\n      },\n      \"cjrxm\": {\n        \"zdms\": \"创建人姓名\",\n        \"zddm\": \"cjrxm\"\n      },\n      \"cjrdwdm\": {\n        \"zdms\": \"创建人单位代码\",\n        \"zddm\": \"cjrdwdm\"\n      },\n      \"cjrdwmc\": {\n        \"zdms\": \"创建人单位名称\",\n        \"zddm\": \"cjrdwmc\"\n      },\n			\"sszzd\": {\n				\"zddm\": \"mc\",\n				\"zdms\": \"搜索主字段\"\n			},\n			\"pyjp\": {\n				\"zdms\": \"拼音简拼\",\n				\"zddm\": \"mcjp\"\n			},\n			\"pyqp\": {\n				\"zdms\": \"拼音全拼\",\n				\"zddm\": \"mcqp\"\n			},\n			\"sszdlb\": {\n				\"zdms\": \"搜索字段列表\",\n				\"zddm\": \"mc||dm\"\n			}\n    }\n  },\n	\"cllxkz\": {\n		\"select\": {\n			\"tree\": {\n				\"lazy\": false,\n				\"transform\": true,\n				\"rowField\": \"id\",\n				\"parentField\": \"fqx\",\n				\"hasChild\": \"myhaschild\",\n				\"sfsxjgField\": \"sfsxjg\",\n				//树形结构请求数据扩展\n				\"treeQqsjkz\":{\n					\"yobj.js\":\"formData.js\"\n				}\n			},\n			\"qxpz\": {\n				\"plclLeft\": {\n					\"bcsq\": {\n						\"type\": \"primary\",\n						\"content\": \"保存授权\",\n						\"buttonOptions\": {\n							\"clfs\": \"htqq\",\n							\"sfxyxzjl\": false,\n							\"htqqts\": true,\n							\"jcxxkz\":{\n								\"yobj.js\":\"formData.js\"\n							}\n						}\n					}\n				},\n				\"plclRight\": {}\n			},\n			\"checkboxConfig\":{\n				\"checkFieldOld\":\"checked\"\n			},\n			\"pagekz\":{\n				\"selectReqData\":{\n					\"page\":{\n						\"pageSize\": 50000\n					}\n				},\n				gridOptions:{\n					\"pagerConfig\":{\n						\"pageSize\": 50000\n					}\n				}\n			}\n		}\n	}\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-QX-QXXX-JSSQ', 'XITONG-QUANXIAN-QUANXIANXINXI-JIAOSESHOUQUAN', '11E3EB1BF4074852966B5872209D1A1C');
INSERT INTO `sys_sjgl_sjdx` VALUES ('KETTLE_GLPT_ZYGL', 'kettle-管理平台-作业管理', 99999, 'cn.benma666.kettle.ljq.JobLjq', NULL, '02', 'table', 'kettle_default', NULL, 'V_JOB', 'id_job', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'px,zhgxsj desc', '1', '1', '0', 'cn.benma666.kettle.ljq.JobLjq', NULL, 'select\n-- @pageTag(){\n    ${sql.selectField},\'${sjdx.dxzt}\' zyk,#{globalUse(\'util.expConcatWs\',{\"list\":[\"\'${sjdx.dxzt}\'\",\"\'&\'\",\"t.id_job\"]\\})} zyk_job\n-- @}\nfrom ${sql.from} t\n-- @ where(){\n   ${sql.whereStr} ${sql.authWhere}\n	 -- @if(!um.hasAuth(user,\"KFZFW_GLY\")){\n	 and job_version<>\'01\'\n	 -- @}\n-- @}\n-- @pageIgnoreTag(){\n	${sql.orderBy}\n-- @}', '20181225130731', '20230601172352', '06', '1', '{\n  \"fields\": {\n    //编辑按钮字段\n    \"myBjan\": {\n      \"kzxxObj\": {\n        \"kjkz\": {\n          //vxe的按钮\n          \"btns\": {\n            \"update\": {\n              \"buttonOptions\": {\n								\"jcxxkz\":{\n									\"yobj.zyk\":\"initFormData.zyk\"\n								}\n              }\n            }\n          }\n        }\n      }\n    }\n	},\n	\"cllxkz\": {\n		\"select\": {\n			\"qxpz\": {\n				\"plclLeft\": {\n					\"fzjl\":\">delete\",\n					\"qd\": {\n						\"px\":10,\n						\"type\": \"primary\",\n						\"content\": \"启动\",\n						\"buttonOptions\": {\n							\"clfs\": \"htqq\",\n							\"sfxyxzjl\": true,\n							\"htqqts\": false,\n							\"jcxxkz\":{\n								\"sys.ctapp\":\"selectReqData.yobj.ddjd\"\n							}\n						}\n					},\n					\"tz\": {\n						\"px\":20,\n						\"type\": \"primary\",\n						\"content\": \"停止\",\n						\"buttonOptions\": {\n							\"clfs\": \"htqq\",\n							\"sfxyxzjl\": true,\n							\"htqqts\": false,\n							\"jcxxkz\":{\n								\"sys.ctapp\":\"selectReqData.yobj.ddjd\"\n							}\n						}\n					},\n					\"js\": {\n						\"px\":30,\n						\"type\": \"primary\",\n						\"content\": \"结束\",\n						\"buttonOptions\": {\n							\"clfs\": \"htqq\",\n							\"sfxyxzjl\": true,\n							\"htqqts\": false,\n							\"jcxxkz\":{\n								\"sys.ctapp\":\"selectReqData.yobj.ddjd\"\n							}\n						}\n					},\n					\"cxsc\": {\n						\"type\": \"primary\",\n						\"content\": \"重新生成\",\n						\"buttonOptions\": {\n							\"clfs\": \"htqq\",\n							\"sfxyxzjl\": true,\n							\"htqqts\": false\n						}\n					},\n					\"drzy\": {\n						\"type\": \"primary\",\n						\"content\": \"导入作业\",\n						\"buttonOptions\": {\n							\"clfs\": \"htqq\",\n							\"sfxyxzjl\": false,\n							\"htqqts\": false\n						}\n					}\n				}\n			}\n		}\n	}\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'KETTLE-GLPT-ZYGL', 'KETTLE-GUANLIPINGTAI-ZUOYEGUANLI', '123190AB67534D9A93A54BA2114B1D67');
