INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_SJGL_BHSC', '系统-数据管理-编号生成', 99999, NULL, NULL, '01', 'table', 'default', NULL, 'SYS_SJGL_BHSC', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', NULL, '1', '1', '1', NULL, NULL, NULL, '20190423214009', '20220825015621', '06', '1', '{\"sys\":{\"fields\":{\"cjrdm\":{\"zdms\":\"创建人代码\",\"zddm\":\"cjrdm\"},\"cjrxm\":{\"zdms\":\"创建人名称\",\"zddm\":\"cjrxm\"},\"cjrdwdm\":{\"zdms\":\"创建人单位代码\",\"zddm\":\"cjrdwdm\"},\"cjrdwmc\":{\"zdms\":\"创建人单位名称\",\"zddm\":\"cjrdwmc\"}}},\"lbymkz\":{\"pagePath\":\"syskz/bhglList\"}}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-SJGL-BHSC', 'XITONG-SHUJUGUANLI-BIANHAOSHENGCHENG', '15C79300FF5B474A917F578E89572FD4');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_QX_YHXX_GRSZ', '系统-权限-用户信息-个人设置', 99999, NULL, NULL, '02', 'table', 'default', NULL, 'SYS_QX_YHXX', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', NULL, '1', '1', '0', NULL, NULL, 'select * from ${owner}.${tableName} t where 1 = 1 ${obj.whereStr} and id=#user.id# and yxx=\'1\' ${obj.orderBy }', '20181219195237', '20200909001946', '06', '1', '{\"sys\":{\"fields\":{\"cjrdm\":{\"zdms\":\"创建人代码\",\"zddm\":\"cjrdm\"},\"cjrxm\":{\"zdms\":\"创建人名称\",\"zddm\":\"cjrxm\"},\"cjrdwdm\":{\"zdms\":\"创建人单位代码\",\"zddm\":\"cjrdwdm\"},\"cjrdwmc\":{\"zdms\":\"创建人单位名称\",\"zddm\":\"cjrdwmc\"}}}}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-QX-YHXX-GRSZ', 'XITONG-QUANXIAN-YONGHUXINXI-GERENSHEZHI', '16BE2D68868C490E829D4AD95535D9A4');
