INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_SJGL_TYZD_DEMO', '系统-数据管理-统一字典-开发样例', 99999, NULL, NULL, '01', 'table', 'default', NULL, 'SYS_SJGL_TYZD_DEMO', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'zdlb,px asc,dm asc', '1', '1', '1', 'cn.benma666.sjsj.demo.XxxxLjq', NULL, NULL, '20181222190746', '20221117160606', '06', '1', '{\n  \"sys\":{\n		\"wlsc\":true,\n    \"fields\":{\n      \"sszzd\":{\n        \"zddm\":\"mc\",\n        \"zdms\":\"搜索主字段\"\n      },\n      \"pyjp\":{\n        \"zdms\":\"拼音简拼\",\n        \"zddm\":\"jp\"\n      },\n      \"pyqp\":{\n        \"zdms\":\"拼音全拼\",\n        \"zddm\":\"qp\"\n      },\n      \"sszdlb\":{\n        \"zdms\":\"搜索字段列表\",\n        \"zddm\":\"ms\"\n      }\n    }\n  },\n	\"zhgz\":{\n		\"yobj.cjrxm\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.yhxm}\"\n				}\n			}\n		},\n		\"yobj.cjrdm\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.id}\"\n				}\n			}\n		},\n		\"yobj.cjrdwmc\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.jgxx.jgmc}\"\n				}\n			}\n		},\n		\"yobj.cjrdwdm\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.jgxx.id}\"\n				}\n			}\n		}\n	}\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-SJGL-TYZD-KFYL', 'XITONG-SHUJUGUANLI-TONGYIZIDIAN-KAIFAYANGLI', '49E9790BC45B42499725FABB2F6D2BB3');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SHRMYY_HLB_ZLJCX', '射洪人民医院-护理部-质量检查项', 99999, NULL, NULL, '02', 'table', 'sjsj_yw', NULL, 'SHRMYY_HLB_ZLJCX', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px,gxsj desc', '1', '0', '1', NULL, NULL, '/*\nvar whereStr = \"\";\nvar whereStr1 = \"\";\n//默认处理方式\nif(!isEmpty(yobj.ssjl)){\n    whereStr = whereStr +  \" and jl.id= #{yobj.ssjl}\" ;\n}\nif(!isEmpty(yobj.zblb)){\n    whereStr1 = whereStr1 + \" and z.zblb= #{yobj.zblb}\" ;\n}\nif(!isEmpty(yobj.id)){\n    whereStr1 = whereStr1 + \" and x.id = #{yobj.id}\" ;\n}\n*/\nselect\n-- @pageTag(){\n    ${sql.selectField}\n-- @}\nfrom (\nselect z.ssdl,\n       z.ssxl,\n       z.zblb,\n       z.zbmc,\n       z.zbms,\n       z.id z_id,\n       x.id,\n       x.cjsj,\n       x.gxsj,\n       x.yxx,\n       x.px,\n       x.ssjl,\n       x.sszb,\n       #{globalUse(\'util.expNvl\',{\'val1\':\'x.sfdb\',\'val2\':\"\'1\'\"\\})} sfdb,\n       x.qksm\n  from SHRMYY_HLB_ZLJCZB z\n  inner join shrmyy_hlb_zljcjl jl\n    on jl.zblb = z.zblb ${whereStr}\n  left join SHRMYY_HLB_ZLJCX x\n    on z.id = x.sszb\n   and jl.id = x.ssjl\n where z.yxx = \'1\' and jl.yxx=\'1\' ${whereStr1}\n) t\n-- @ where(){\n   ${sql.whereStr} ${sql.authWhere}\n-- @}\n-- @pageIgnoreTag(){\n	${sql.orderBy}\n-- @}', '20210329232911', '20230814225254', '06', '1', '{\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'SHRMYY-HLB-ZLJCX', 'SHEHONGRENMINYIYUAN-HULIBU-ZHILIANGJIANCHAXIANG', '4A3D4236CE9547F8AF9E84716D2EFD5C');
