INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_QX_JSXX', '系统-权限-角色信息', 99999, NULL, NULL, '01', 'table', 'default', NULL, 'SYS_QX_JSXX', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px,dm,gxsj desc', '1', '1', '1', 'cn.benma666.sjsj.ljq.qxgl.JsxxLjq', '', 'select\n-- @pageTag(){\n    ${sql.selectField},t.id my_glj,yj.id my_id\n-- @}\nfrom ${sql.from} t\nleft join sys_qx_yhjsgl yj on yj.js=t.id and yj.yh = #{yobj.keyIn!yobj.keyNot} and yj.yxx=\'1\'\n-- @ where(){\n   ${sql.whereStr} ${sql.authWhere}\n	 -- @if(!su.isBlank(yobj.keyIn)){\n	   and EXISTS (\nselect 1 from sys_qx_yhjsgl yj where yj.yh = #{yobj.keyIn} and yj.js=t.id and yj.yxx=\'1\'\n)\n	 -- @}\n	 -- @if(!su.isBlank(yobj.keyNot)){\n	   and not EXISTS (\nselect 1 from sys_qx_yhjsgl yj where yj.yh = #{yobj.keyNot} and yj.js=t.id and yj.yxx=\'1\'\n)\n	 -- @}\n-- @}\n-- @pageIgnoreTag(){\n	${sql.orderBy}\n-- @}', '20190330161240', '20240704174653', '06', '1', '{\n  \"sys\": {\n		\"wlsc\": true,\n    \"fields\": {\n      \"sszzd\": {\n        \"zddm\": \"mc\",\n        \"zdms\": \"搜索主字段\"\n      },\n      \"sszdlb\": {\n        \"zdms\": \"搜索字段列表\",\n        \"zddm\": \"dm\',\'t.ms\"\n      },\n      \"cjrdm\": {\n        \"zdms\": \"创建人代码\",\n        \"zddm\": \"cjrdm\"\n      },\n      \"cjrxm\": {\n        \"zdms\": \"创建人名称\",\n        \"zddm\": \"cjrxm\"\n      },\n      \"cjrdwdm\": {\n        \"zdms\": \"创建人单位代码\",\n        \"zddm\": \"cjrdwdm\"\n      },\n      \"cjrdwmc\": {\n        \"zdms\": \"创建人单位名称\",\n        \"zddm\": \"cjrdwmc\"\n      }\n    }\n  },\n	\"cllxkz\": {\n		\"select\": {\n			\"tree\": {\n				\"lazy\": false,\n				\"transform\": true,\n				\"rowField\": \"id\",\n				\"parentField\": \"fjs\",\n				\"hasChild\": \"myhaschild\",\n				\"sfsxjgField\": \"sfsxjg\"\n			},\n			\"pagekz\":{\n				\"selectReqData\":{\n					\"page\":{\n						\"pageSize\": 50000\n					}\n				},\n				gridOptions:{\n					\"pagerConfig\":{\n						\"pageSize\": 50000\n					}\n				}\n			},\n			\"qxpz\": {\n				\"plclLeft\": {\n					\"sxyhqx\": {\n						\"px\":10,\n						\"type\": \"primary\",\n						\"content\": \"刷新用户权限\",\n						\"buttonOptions\": {\n							\"clfs\": \"htqq\",\n							\"htqqts\": false,\n							\"sfxyxzjl\": false\n						}\n					}\n				}\n			}\n		}\n	}\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-QX-JSXX', 'XITONG-QUANXIAN-JIAOSEXINXI', '599C8A36A5B54AF283E6339D8179C720');
