INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_SJGL_SJZT', '系统-数据管理-数据载体', 99999, NULL, NULL, '01', 'table', 'default', NULL, 'SYS_SJGL_SJZT', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px,gxsj desc', '1', '1', '1', 'cn.benma666.sjsj.ljq.sjgl.SjztLjq', NULL, NULL, '20181222180901', '20220825015621', '06', '1', '{\n  \"sys\": {\n    \"fields\": {\n      \"sszzd\": {\n        \"zddm\": \"mc\",\n        \"zdms\": \"搜索主字段\"\n      },\n      \"pyjp\": {\n        \"zdms\": \"拼音简拼\",\n        \"zddm\": \"jp\"\n      },\n      \"pyqp\": {\n        \"zdms\": \"拼音全拼\",\n        \"zddm\": \"qp\"\n      },\n      \"sszdlb\": {\n        \"zdms\": \"搜索字段列表\",\n        \"zddm\": \"ms\"\n      },\n      \"cjrdm\": {\n        \"zdms\": \"创建人代码\",\n        \"zddm\": \"cjrdm\"\n      },\n      \"cjrxm\": {\n        \"zdms\": \"创建人名称\",\n        \"zddm\": \"cjrxm\"\n      },\n      \"cjrdwdm\": {\n        \"zdms\": \"创建人单位代码\",\n        \"zddm\": \"cjrdwdm\"\n      },\n      \"cjrdwmc\": {\n        \"zdms\": \"创建人单位名称\",\n        \"zddm\": \"cjrdwmc\"\n      }\n    }\n  },\n	\"cllxkz\": {\n		\"select\": {\n			\"qxpz\": {\n				\"plclLeft\": {\n					\"cszt\": {\n						\"type\": \"primary\",\n						\"content\": \"测试载体\",\n						\"buttonOptions\": {\n							\"clfs\": \"htqq\",\n							\"sfxyxzjl\": false,\n							\"htqqts\": false\n						}\n					},\n					\"scjkrw\": {\n						\"type\": \"primary\",\n						\"content\": \"生成监控任务\",\n						\"buttonOptions\": {\n							\"clfs\": \"htqq\",\n							\"sfxyxzjl\": true,\n							\"htqqts\": true\n						}\n					}\n				}\n			}\n		}\n	}\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-SJGL-SJZT', 'XITONG-SHUJUGUANLI-SHUJUZAITI', '7C53F02FC43043FEAD8653541617710F');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_SJGL_XTCS', '系统-数据管理-系统参数', 99999, NULL, NULL, '01', 'table', 'default', NULL, 'SYS_SJGL_XTCS', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px,gxsj desc', '1', '1', '1', NULL, NULL, NULL, '20211125151823', '20220825015621', '06', '1', '{\n	\"cllxkz\": {\n		\"select\": {\n			\"tree\": {\n				\"lazy\": false,\n				\"transform\": true,\n				\"rowField\": \"dm\",\n				\"parentField\": \"upnode\",\n				\"hasChild\": \"myhaschild\",\n				\"sfsxjgField\": \"sfsxjg\"\n			},\n			\"pagekz\":{\n				\"selectReqData\":{\n					\"page\":{\n						\"pageSize\": 5000\n					}\n				},\n				\"pagerConfig\":{\n					\"pageSizes\":[10, 100, 1000, 5000],\n					\"pageSize\": 5000\n				}\n			}\n		}\n	},\n	\"sys\":{\n		\"fields\": {\n			\"cjrdm\": {\n				\"zdms\": \"创建人代码\",\n				\"zddm\": \"cjrdm\"\n			},\n			\"cjrxm\": {\n				\"zdms\": \"创建人名称\",\n				\"zddm\": \"cjrxm\"\n			},\n			\"cjrdwdm\": {\n				\"zdms\": \"创建人单位代码\",\n				\"zddm\": \"cjrdwdm\"\n			},\n			\"cjrdwmc\": {\n				\"zdms\": \"创建人单位名称\",\n				\"zddm\": \"cjrdwmc\"\n			}\n		}\n	}\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-SJGL-XTCS', 'XITONG-SHUJUGUANLI-XITONGCANSHU', '7DA1F7ABF71943B6B2FBA82FA900B978');
