INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_TYGJ_SQLZX', '系统-通用工具-SQL执行', 99999, NULL, NULL, '02', 'xndx', 'default', NULL, 'v_xndx', 'id', NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, '1', '1', '0', 'cn.benma666.sjsj.ljq.sjgl.SqlzxLjq', NULL, NULL, '20190927180711', '20221030230211', '06', '1', '{\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-TYGJ-SQLZX', 'XITONG-TONGYONGGONGJU-SQLZHIXING', '91DB930CB66C42B6B5CBB9D3FA2B748A');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SHRMYY_HLB_ZLJC_AZBTJ', '射洪人民医院-护理部-质量检查-按指标统计', 99999, NULL, NULL, '02', 'view', 'sjsj_yw', NULL, 'v_xndx', 'id', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'dbl', '1', '1', '1', NULL, NULL, '/*\r\nvar whereStr  = sys_sjgl_sjdx;\r\nvar whereStr1  = sys_sjgl_sjdx;\r\nif(!isEmpty(yobj.tjzb)){\r\n   whereStr  = whereStr + and t.zbmc like \'%\'||#yobj.tjzb#||\'%\';\r\n}\r\nif(!isEmpty(yobj.zblb)){\r\n   whereStr  = whereStr + and zblb = #yobj.zblb#;\r\n}\r\nvar field = fields.cjsj;\r\nsu.addEqDate(field , yobj);\r\nif(!isEmpty(yobj[cjsj_start])){\r\n	whereStr = whereStr +  and jl_cjsj >=\'+yobj[cjsj_start]+\';\r\n}\r\nif(!isEmpty(yobj[cjsj_end])){\r\n	whereStr = whereStr +  and jl_cjsj <=\'+yobj[cjsj_end]+\';\r\n}\r\nif(!isEmpty(yobj[dbl_start])){\r\n	whereStr1 = whereStr1 +  and dbl >=\'+yobj[dbl_start]+\';\r\n}\r\nif(!isEmpty(yobj[dbl_end])){\r\n	whereStr1 = whereStr1+  and dbl <=\'+yobj[dbl_end]+\';\r\n}\r\nvar orderby  = obj.orderBy;\r\nif(isEmpty(orderby )){\r\n     orderby = order by z_px asc;\r\n}\r\n*/\r\nselect t.*  from (\r\nwith a as\r\n (select t.*, k.mc ksmc\r\n    from V_SHRMYY_HLB_ZLJCX t\r\n   inner join shrmyy_jcxx_ksxx k\r\n      on k.id = t.ks\r\n   where k.yxx=\'1\' ${whereStr})\r\nselect t.*,\r\n       (select wm_concat(distinct t1.ksmc)\r\n          from a t1\r\n         where t1.z_id = t.z_id\r\n           and t1.sfdb <> \'1\') wdbks\r\n  from (select t.zbmc,\r\n               max(t.z_id) z_id,\r\n               max(t.z_px) z_px,\r\n               max(t.ssdl) ssdl,\r\n               max(t.zblb) zblb,\r\n               sum(sfdb),\r\n               count(1),\r\n               ROUND((sum(sfdb) / count(1)) * 100, 1) dbl\r\n          from a t\r\n         group by t.zbmc) t\r\nwhere 1=1 ${whereStr1}\r\n ${orderby }\r\n) t', '20191114113437', '20230814225254', '06', '1', '{\n  \n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'SHRMYY-HLB-ZLJC-AZBTJ', 'SHEHONGRENMINYIYUAN-HULIBU-ZHILIANGJIANCHA-ANZHIBIAOTONGJI', '9E13D6BFE1394090AB00E3D638AD19D5');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_QX_QTQX', '系统-权限-其他权限', 99999, NULL, NULL, '02', 'table', 'default', NULL, 'SYS_QX_QXXX', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px,gxsj desc', '1', '1', '1', NULL, NULL, NULL, '20190330174526', '20211102145413', '06', '1', '{\"sys\":{\"fields\":{\"cjrdm\":{\"zdms\":\"创建人代码\",\"zddm\":\"cjrdm\"},\"cjrxm\":{\"zdms\":\"创建人名称\",\"zddm\":\"cjrxm\"},\"cjrdwdm\":{\"zdms\":\"创建人单位代码\",\"zddm\":\"cjrdwdm\"},\"cjrdwmc\":{\"zdms\":\"创建人单位名称\",\"zddm\":\"cjrdwmc\"}}}}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-QX-QTQX', 'XITONG-QUANXIAN-QITAQUANXIAN', '9E46CBF1B34E458E9E24E9DA88F5ABA9');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_SJGL_FILE', '系统-数据管理-文件', 99999, NULL, NULL, '01', 'table', 'default', NULL, 'SYS_SJGL_FILE', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'gxsj desc', '1', '1', '1', 'cn.benma666.sjsj.ljq.sjgl.FileLjq', NULL, NULL, '20181217164122', '20231023183303', '06', '1', '{\n  \"sys\": {\n    \"fields\": {\n      \"cjrdm\": {\n        \"zdms\": \"创建人代码\",\n        \"zddm\": \"cjrdm\"\n      },\n      \"cjrxm\": {\n        \"zdms\": \"创建人名称\",\n        \"zddm\": \"cjrxm\"\n      },\n      \"cjrdwdm\": {\n        \"zdms\": \"创建人单位代码\",\n        \"zddm\": \"cjrdwdm\"\n      },\n      \"cjrdwmc\": {\n        \"zdms\": \"创建人单位名称\",\n        \"zddm\": \"cjrdwmc\"\n      }\n    },\n  	\"wlsc\": true\n  },\n	\"cllxkz\": {\n		\"select\": {\n			\"qxpz\": {\n				\"plclLeft\": {\n					\"uploadWjj\": {\n						\"type\": \"primary\",\n						\"content\": \"上传到文件夹\",\n						\"buttonOptions\": {\n							\"clfs\": \"upload\",\n							\"sfxyxzjl\": false,\n							\"htqqts\": false,\n							\"schqq\": false,\n							\"params\":{\n								\"yobj.sjzt\":\"\"\n							}\n						}\n					},\n					\"uploadSjk\": {\n						\"type\": \"primary\",\n						\"content\": \"上传到数据库\",\n						\"buttonOptions\": {\n							\"clfs\": \"upload\",\n							\"sfxyxzjl\": false,\n							\"htqqts\": false,\n							\"schqq\": false,\n							\"params\":{\n								\"yobj.sjzt\":\"default\"\n							}\n						}\n					}\n				}\n			}\n		}\n	},\n	\"fields\":{\n		\"myLbcz\":{\n			\"kzxxObj\":{\n				\"kjkz\":{\n					\"btns\":{\n            \"download\": {\n              \"type\": \"text\",\n              \"content\": \"文件下载\",\n              \"status\": \"primary\",\n              \"buttonOptions\": {\n                \"clfs\": \"download\",\n                \"htqqts\": false\n              }\n            }\n					}\n				}\n			}\n		}\n	}\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-SJGL-WJ', 'XITONG-SHUJUGUANLI-WENJIAN', 'A0AB3007C2D04BA3B8A58EC24F5550C5');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_LOG_HTRZ', '系统-日志-后台日志', 99999, NULL, NULL, '01', 'table', 'default', NULL, 'SYS_LOG_HTRZ', 'id', NULL, 'gxsj', NULL, NULL, NULL, NULL, '1', 'cjsj desc', '1', '1', '1', NULL, NULL, NULL, '20190120170000', '20221030100545', '06', '1', '{\n	\"cllxkz\": {\n		\"select\": {\n			//页面扩展：这里设置的参数会合并到页面参数的根节点中\n			\"pagekz\": {\n				\"pagerConfig\": {\n					\"pageSize\": 20\n				},\n				//定时刷新，120秒\n				\"dssx\":300,\n				//报警声音，值为声音文件的id，走文件下载接口获取，配置了页面查询查询有数据时则报警\n				\"bjsy\":\"5835E452395A429C85BC836E92415B53\"\n			},\n			\"qxpz\": {\n				\"plclLeft\": {\n          \"ssrz\": {\n						\"px\": 30,\n            \"type\": \"primary\",\n            \"content\": \"实时日志\",\n            \"buttonOptions\": {\n              \"clfs\": \"tcck\",\n              //是否需要选择记录\n              sfxyxzjl: false,\n              tcqp: true,\n              \"dxjcxx\": {\n                \"sjdx\": {\n                  \"dxdm\": \"SYS_LOG_HTRZ\"\n                },\n                \"sys\": {\n                  \"cllx\": \"ssrz\"\n                }\n              }\n            }\n          }\n				},\n				\"plclRight\": {}\n			}\n		}\n	}\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-RZ-HTRZ', 'XITONG-RIZHI-HOUTAIRIZHI', 'A1ABCD9F2CAD4BB9B212380FD90E4C12');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SHRMYY_JCXX_KSXX', '射洪人员医院-基础信息-科室信息', 99999, NULL, NULL, '02', 'table', 'sjsj_yw', NULL, 'SHRMYY_JCXX_KSXX', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px,gxsj desc', '1', '1', '1', NULL, NULL, NULL, '20200413160310', '20230814225254', '06', '1', '{\n	\"zhgz\":{\n		\"yobj.cjrxm\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.yhxm}\"\n				}\n			}\n		},\n		\"yobj.cjrdm\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.id}\"\n				}\n			}\n		},\n		\"yobj.cjrdwmc\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.jgxx.jgmc}\"\n				}\n			}\n		},\n		\"yobj.cjrdwdm\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.jgxx.id}\"\n				}\n			}\n		}\n	}\n}', '管理员', '116EF03719B74690BB8FBFB0DD6D229A', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'SHRYYY-JCXX-KSXX', 'SHEHONGRENYUANYIYUAN-JICHUXINXI-KESHIXINXI', 'A374CF9E691B4051930910120EA52B96');
