INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_BDHC_XM', '系统-比对核查-项目', 99999, NULL, NULL, '02', 'table', 'bdhc_default', NULL, 'SYS_BDHC_XM', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px,gxsj desc', '1', '1', '1', NULL, NULL, NULL, '20200427165601', '20200521165917', '06', '1', '{\"sys\":{\"fields\":{\"cjrdm\":{\"zdms\":\"创建人代码\",\"zddm\":\"cjrdm\"},\"cjrxm\":{\"zdms\":\"创建人名称\",\"zddm\":\"cjrxm\"},\"cjrdwdm\":{\"zdms\":\"创建人单位代码\",\"zddm\":\"cjrdwdm\"},\"cjrdwmc\":{\"zdms\":\"创建人单位名称\",\"zddm\":\"cjrdwmc\"}}}}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-BDHC-XM', 'XITONG-BIDUIHECHA-XIANGMU', 'ACEC5423E7AF47AA9488F13674E9919D');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_QX_YHXX', '系统-权限-用户信息', 99999, NULL, NULL, '01', 'table', 'default', NULL, 'SYS_QX_YHXX', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'gxsj desc', '1', '1', '1', NULL, NULL, 'select\n-- @pageTag(){\n    ${sql.selectField},t.id my_glj,yj.id my_id\n-- @}\nfrom ${sql.from} t\nleft join sys_qx_yhjsgl yj on yj.yh=t.id and yj.js = #{yobj.keyIn}\n-- @ where(){\n   ${sql.whereStr} ${sql.authWhere}\n	 -- @if(!isEmpty(yobj.keyIn)){\n	   and EXISTS (\nselect 1 from sys_qx_yhjsgl yj where yj.js = #{yobj.keyIn} and yj.yh=t.id and yj.yxx=\'1\'\n)\n	 -- @}\n	 -- @if(!isEmpty(yobj.keyNot)){\n	   and not EXISTS (\nselect 1 from sys_qx_yhjsgl yj where yj.js = #{yobj.keyNot} and yj.yh=t.id and yj.yxx=\'1\'\n)\n	 -- @}\n-- @}\n-- @pageIgnoreTag(){\n	${sql.orderBy}\n-- @}', '20181219195237', '20221115211756', '06', '1', '{\n  \"sys\":{\n    \"fields\":{\n      \"sszzd\": {\n        \"zddm\": \"yhxm\",\n        \"zdms\": \"搜索主字段\"\n      },\n      \"sszdlb\": {\n        \"zdms\": \"搜索字段列表\",\n        \"zddm\": \"yhdm\',\'t.sfzh\"\n      },\n      \"cjrdm\":{\n        \"zdms\":\"创建人代码\",\n        \"zddm\":\"cjrdm\"\n      },\n      \"cjrxm\":{\n        \"zdms\":\"创建人名称\",\n        \"zddm\":\"cjrxm\"\n      },\n      \"cjrdwdm\":{\n        \"zdms\":\"创建人单位代码\",\n        \"zddm\":\"cjrdwdm\"\n      },\n      \"cjrdwmc\":{\n        \"zdms\":\"创建人单位名称\",\n        \"zddm\":\"cjrdwmc\"\n      }\n    },\n		\"wlsc\":true\n  },\n	\"cllxkz\":{\n		\"select\":{\n			\"pagekz\":{\n				\"gridOptions\":{\n					\"showOverflow\":false\n				}\n			}\n		}\n	}\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-QX-YHXX', 'XITONG-QUANXIAN-YONGHUXINXI', 'AD6FF4C358284A8DB3954B3E32A51E86');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_LOG_FWZR_FTP_TEXT', '系统-日志-访问日志-FTP-文本文件', 99999, NULL, NULL, '02', 'txt', 'ZNJH_SJY_YHY_WBTD', 'log/fwrz', 'SYS_LOG_FWZR', 'id', NULL, NULL, NULL, NULL, NULL, 'yxx', '3', NULL, '1', '1', '1', NULL, NULL, NULL, '20181220215058', '20221102231715', '06', '1', '{\n	\"sjdx\":{\n		//数据对象扩展\n		\"tails\":{\n			//分隔符\n			\"fgf\":\"|\",\n			//文本限定符\n			\"wbxdf\":\"\",\n			//头部行数\n			\"tbhs\":1,\n			//编码方式\n			\"bmfs\":\"UTF-8\"\n		}\n	}\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-RZ-FWRZ-FTP-WBWJ', 'XITONG-RIZHI-FANGWENRIZHI-FTP-WENBENWENJIAN', 'AE53A3D268F840C8AD5CD8BD54748853');
INSERT INTO `sys_sjgl_sjdx` VALUES ('QT_GJZQ_ZHMX', '其他-国金证券-账户明细', 99999, NULL, NULL, '01', 'table', 'sjsj_yw', NULL, 'QT_GJZQ_ZHMX', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'rq desc', '1', '1', '1', NULL, NULL, NULL, '20210311093240', '20230814225409', '06', '1', '{\"sys\":{\"fields\":{\"cjrdm\":{\"zdms\":\"创建人代码\",\"zddm\":\"cjrdm\"},\"cjrxm\":{\"zdms\":\"创建人名称\",\"zddm\":\"cjrxm\"},\"cjrdwdm\":{\"zdms\":\"创建人单位代码\",\"zddm\":\"cjrdwdm\"},\"cjrdwmc\":{\"zdms\":\"创建人单位名称\",\"zddm\":\"cjrdwmc\"}}}}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'QT-GJZQ-ZHMX', 'QITA-GUOJINZHENGQUAN-ZHANGHUMINGXI', 'AF26B80944F9403E9EEB3582F0AA21BB');
INSERT INTO `sys_sjgl_sjdx` VALUES ('JCGA_JCYG_JCXX_LZZY', '机场公安-机场用工-基础信息-离职专用', 99999, NULL, NULL, '02', 'table', 'default', NULL, 'JCGA_JCYG_JCXX', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'gxsj desc', '1', '1', '0', 'cn.benma666.other.ljq.JcygLzLjq', NULL, 'select *\n  from ${owner}.${tableName} t\n where 1 = 1 ${obj.whereStr} ${obj.authWhere}\n   and yxx = \'1\' \n/*if(!QxManager.hasAuthCode(user,\'CQJC_XTGLY\')){*/\n  and t.cjrdwdm = #user.jgxx.id#\n/*}*/\n${obj.orderBy }', '20190418202237', '20190918185558', '06', '1', '{\"sys\":{\"fields\":{\"cjrdm\":{\"zdms\":\"创建人代码\",\"zddm\":\"cjrdm\"},\"cjrxm\":{\"zdms\":\"创建人名称\",\"zddm\":\"cjrxm\"},\"cjrdwdm\":{\"zdms\":\"创建人单位代码\",\"zddm\":\"cjrdwdm\"},\"cjrdwmc\":{\"zdms\":\"创建人单位名称\",\"zddm\":\"cjrdwmc\"}}},\"lbymkz\":{\"my-plscamc\":\"设为无效\"}}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'JCGA-JCYG-JCXX-LZZY', 'JICHANGGONGAN-JICHANGYONGGONG-JICHUXINXI-LIZHIZHUANYONG', 'B0C1988A3086427CBDAE38817BEA7F70');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_WDGL_PL', '系统-文档管理-评论', 99999, NULL, NULL, '02', 'table', 'default', NULL, 'sys_wdgl_pl', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px,gxsj desc', '1', '1', '1', NULL, '', 'select\n-- @pageTag(){\n				(select count(1) from sys_wdgl_pl t1 where t1.xgpl=t.id and t1.yxx=\'1\' and t1.czlb=\'02\') zan_sl,\n				(select count(1) from sys_wdgl_pl t1 where t1.xgpl=t.id and t1.yxx=\'1\' and t1.czlb=\'03\') cai_sl,\n				(select count(1) from sys_wdgl_pl t1 where t1.xgpl=t.id and t1.yxx=\'1\' and t1.czlb=\'01\') pl_sl,\n				(select id from sys_wdgl_pl t1 where t1.xgpl=t.id and t1.yxx=\'1\' and t1.czlb=\'02\' and t1.cjrdm=#{user.id}) zan_dqyh,\n				(select id from sys_wdgl_pl t1 where t1.xgpl=t.id and t1.yxx=\'1\' and t1.czlb=\'03\' and t1.cjrdm=#{user.id}) cai_dqyh,\n				(select to_base64(t1.nr) from sys_sjgl_blob t1 inner join sys_qx_yhxx t2 on t2.tx=t1.id where t1.yxx=\'1\' and t2.id=t.cjrdm) yhtx,\n    ${sql.selectField}\n-- @}\nfrom ${sql.from} t\n-- @ where(){\n   ${sql.whereStr} \n	 -- @if(yobj.ckwd!=\'1\'){\n	 ${sql.authWhere}\n	 -- @}\n-- @}\n-- @pageIgnoreTag(){\n	${sql.orderBy}\n-- @}', '20221118163606', '20231028002420', '06', '1', '{\n  \"sys\":{\n    \"fields\": {\n      \"cjrdm\": {\n        \"zdms\": \"创建人代码\",\n        \"zddm\": \"cjrdm\"\n      },\n      \"cjrxm\": {\n        \"zdms\": \"创建人名称\",\n        \"zddm\": \"cjrxm\"\n      },\n      \"cjrdwdm\": {\n        \"zdms\": \"创建人单位代码\",\n        \"zddm\": \"cjrdwdm\"\n      },\n      \"cjrdwmc\": {\n        \"zdms\": \"创建人单位名称\",\n        \"zddm\": \"cjrdwmc\"\n      }\n    }\n  }\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', NULL, 'XITONG-WENDANGGUANLI-PINGLUN', 'B182F81FAD5747088CB98E7F0990DB4B');
