INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_SJGL_HTRW', '系统-数据管理-后台任务', 99999, NULL, NULL, '01', 'table', 'default', NULL, 'SYS_SJGL_HTRW', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px,gxsj desc', '1', '1', '1', NULL, NULL, NULL, '20220725102547', '20220825015621', '06', '1', '{\n  \"sys\":{\n    \"fields\": {\n      \"cjrdm\": {\n        \"zdms\": \"创建人代码\",\n        \"zddm\": \"cjrdm\"\n      },\n      \"cjrxm\": {\n        \"zdms\": \"创建人名称\",\n        \"zddm\": \"cjrxm\"\n      },\n      \"cjrdwdm\": {\n        \"zdms\": \"创建人单位代码\",\n        \"zddm\": \"cjrdwdm\"\n      },\n      \"cjrdwmc\": {\n        \"zdms\": \"创建人单位名称\",\n        \"zddm\": \"cjrdwmc\"\n      }\n    }\n  }\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-SJGL-HTRW', 'XITONG-SHUJUGUANLI-HOUTAIRENWU', 'BC869DBAA78344AFAA39491051394165');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_QX_QXXX', '系统-权限-权限信息', 99999, NULL, NULL, '01', 'table', 'default', NULL, 'SYS_QX_QXXX', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px,gxsj desc', '1', '1', '1', 'cn.benma666.sjsj.ljq.qxgl.QxxxLjq', NULL, NULL, '20190330161317', '20230602180858', '06', '1', '{\n  \"sys\": {\n    \"fields\": {\n      \"cjrdm\": {\n        \"zdms\": \"创建人代码\",\n        \"zddm\": \"cjrdm\"\n      },\n      \"cjrxm\": {\n        \"zdms\": \"创建人姓名\",\n        \"zddm\": \"cjrxm\"\n      },\n      \"cjrdwdm\": {\n        \"zdms\": \"创建人单位代码\",\n        \"zddm\": \"cjrdwdm\"\n      },\n      \"cjrdwmc\": {\n        \"zdms\": \"创建人单位名称\",\n        \"zddm\": \"cjrdwmc\"\n      },\n			\"sszzd\": {\n				\"zddm\": \"mc\",\n				\"zdms\": \"搜索主字段\"\n			},\n			\"pyjp\": {\n				\"zdms\": \"拼音简拼\",\n				\"zddm\": \"mcjp\"\n			},\n			\"pyqp\": {\n				\"zdms\": \"拼音全拼\",\n				\"zddm\": \"mcqp\"\n			},\n			\"sszdlb\": {\n				\"zdms\": \"搜索字段列表\",\n				\"zddm\": \"mc||dm\"\n			}\n    }\n  },\n	\"cllxkz\": {\n		\"select\": {\n			\"qxpz\": {\n				\"plclLeft\": {\n					\"fzjl\":\">delete\"\n				}\n			},\n			\"tree\": {\n				\"transform\": true,\n				\"rowField\": \"id\",\n				\"parentField\": \"fqx\",\n				\"hasChild\": \"myhaschild\",\n				\"sfsxjgField\": \"sfsxjg\"\n			}\n		}\n	}\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-QX-QXXX', 'XITONG-QUANXIAN-QUANXIANXINXI', 'BCE46453CE814322A355A65189A6538E');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_LOG_FWRZ_FWLTJ', '系统-日志-访问日志-访问量统计', 99999, NULL, NULL, '02', 'xndx', 'default', NULL, 'v_xndx', 'id', NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, '1', '1', '1', NULL, NULL, 'select\n-- @pageTag(){\n    ${sql.selectField}\n-- @}\nfrom (\nselect t.cjrdm id, max(t.cjrxm) tjzb, count(1) cs\n          from sys_log_fwzr t\n-- @ where(){\n          /*if(!isEmpty(yobj.cjrxm)){*/\n          and t.cjrxm like #{yobj.cjrxm}\n          /*}*/\n   				${sql.authWhere}\n-- @}\n         group by t.cjrdm\n) t\n-- @ where(){\n   				${sql.whereStr} \n-- @}\n-- @pageIgnoreTag(){\n   order by cs desc\n-- @}', '20190506182549', '20221205214604', '06', '1', '{\n  \"cllxkz\": {\n    \"select\": {\n      \"lbmskz\": {\n        \"myLbms\": \"pie\",\n        \"lbmsList\": [\n          {\n            \"dm\": \"list\",\n            \"mc\": \"列表\"\n          },\n          {\n            \"dm\": \"pie\",\n            \"mc\": \"饼图\",\n            \"option\": {\n              \"legend\": {},\n              \"tooltip\": {},\n              \"dataset\": {\n                \"dimensions\": [\n                  \"tjzb\",\n                  \"cs\"\n                ]\n              },\n              \"series\": {\n                \"name\": \"访问量统计\",\n                \"type\": \"pie\"\n              }\n            }\n          },\n          {\n            \"dm\": \"ba\",\n            \"mc\": \"柱图\",\n            \"option\": {\n              \"legend\": {},\n              \"tooltip\": {},\n              \"dataset\": {\n                \"dimensions\": [\n                  \"tjzb\",\n                  \"cs\"\n                ]\n              },\n              \"xAxis\": {\n                \"type\": \"category\"\n              },\n              \"yAxis\": {},\n              \"series\": {\n                \"name\": \"访问量统计\",\n                \"type\": \"bar\"\n              }\n            }\n          }\n        ]\n      }\n    }\n  }\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', NULL, NULL, 'C379D106C9DF49408628266184B229B8');
INSERT INTO `sys_sjgl_sjdx` VALUES ('KETTLE_GLPT_ZYGL_FZZY', 'kettle-管理平台-作业管理-复制作业', 99999, '通用的，部署多套时不需要复制该对象', NULL, '02', 'xndx', 'default', NULL, 'v_xndx', 'id', NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, '1', '1', '0', 'cn.benma666.kettle.ljq.JobFzzyLjq', NULL, NULL, '20191014150759', '20191119102336', '06', '1', '{\"bjymkz\":{\"my-qda\":\"确定\",\"my-xsgba\":1,\"my-qdbts\":0}}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'KETTLE-GLPT-ZYGL-FZZY', 'KETTLE-GUANLIPINGTAI-ZUOYEGUANLI-FUZHIZUOYE', 'C890209D1738409DAE4898182D6FD466');
INSERT INTO `sys_sjgl_sjdx` VALUES ('V_SHRMYY_HLB_ZLJC_KS_DBL', '射洪人民医院-护理部-质量检查-科室-达标率', 99999, NULL, NULL, '02', 'view', 'sjsj_yw', NULL, 'v_xndx', 'id', NULL, NULL, NULL, NULL, NULL, NULL, '1', 'cs', '1', '1', '1', NULL, NULL, '/*\r\nvar whereStr  = sys_sjgl_sjdx;\r\nif(!isEmpty(yobj.tjzb)){\r\n   whereStr  = whereStr + and k.mc like \'%\'||#yobj.tjzb#||\'%\';\r\n}\r\nif(!isEmpty(yobj.zblb)){\r\n   whereStr  = whereStr + and t.zblb = #yobj.zblb#;\r\n}\r\nvar field = fields.cjsj;\r\nsu.addEqDate(field , yobj);\r\nif(!isEmpty(yobj[cjsj_start])){\r\n  whereStr = whereStr +  and jl_cjsj >=\'+yobj[cjsj_start]+\';\r\n}\r\nif(!isEmpty(yobj[cjsj_end])){\r\n  whereStr = whereStr +  and jl_cjsj <=\'+yobj[cjsj_end]+\';\r\n}\r\n*/\r\nselect *\r\n  from (select k.mc tjzb,\r\n               sum(sfdb),\r\n               count(1),\r\n               ROUND((sum(sfdb) / count(1)) * 100, 1) cs\r\n          from V_SHRMYY_HLB_ZLJCX t\r\n         inner join shrmyy_jcxx_ksxx k\r\n            on k.id = t.ks\r\n         where k.yxx=\'1\' ${whereStr }\r\n         group by k.mc) t\r\n order by cs asc\r\n', '20190506182549', '20230814225254', '06', '1', '{\n  \n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'SHRMYY-HLB-ZLJC-KS-DBL', 'SHEHONGRENMINYIYUAN-HULIBU-ZHILIANGJIANCHA-KESHI-DABIAOLV', 'C9F4C1A4ECE54CB0B8D770F8D4DC331A');
