INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_BDHC_FK', '系统-比对核查-反馈', 99999, NULL, NULL, '02', 'table', 'bdhc_default', NULL, 'SYS_BDHC_FK', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px,gxsj desc', '1', '1', '1', NULL, NULL, 'select\n-- @pageTag(){\n    ${sql.selectField}\n-- @}\nfrom ${sql.from} t\n-- @ where(){\n   t.yxx=\'1\' ${sql.whereStr} ${sql.authWhere}\n-- @}\n-- @pageIgnoreTag(){\n	${sql.orderBy}\n-- @}', '20210723112735', '20221120104013', '06', '1', '{\n  \"sys\":{\n    \"fields\":{\n      \"cjrdm\":{\n        \"zdms\":\"创建人代码\",\n        \"zddm\":\"cjrdm\"\n      },\n      \"cjrxm\":{\n        \"zdms\":\"创建人名称\",\n        \"zddm\":\"cjrxm\"\n      },\n      \"cjrdwdm\":{\n        \"zdms\":\"创建人单位代码\",\n        \"zddm\":\"cjrdwdm\"\n      },\n      \"cjrdwmc\":{\n        \"zdms\":\"创建人单位名称\",\n        \"zddm\":\"cjrdwmc\"\n      }\n    }\n  }\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-BDHC-FK', 'XITONG-BIDUIHECHA-FANKUI', 'D59DEEBF1DB64A0DB47AEBF5049B4213');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_SJGL_MMCK', '系统-数据管理-密码查看', 99999, NULL, NULL, '02', 'xndx', 'default', NULL, 'v_xndx', 'id', NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, '1', '1', '0', 'cn.benma666.sjsj.ljq.sjgl.MmcxLjq', NULL, NULL, '20190511191347', '20211204212925', '06', '1', '{\n  \"bjymkz\":{\n    \"my-qdbts\":1,\n    \"my-xsgba\":0\n  }\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-SJGL-MMCK', 'XITONG-SHUJUGUANLI-MIMACHAKAN', 'D739F41EBDFE4F7389114338309745E4');
INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_SJGL_GRBJ', '系统-数据管理-文档资料', 99999, NULL, NULL, '01', 'table', 'default', NULL, 'SYS_SJGL_GRBJ', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px,gxsj desc', '1', '1', '1', NULL, '', 'select\n-- @pageTag(){\n	 -- @if(yobj.ckwd==\'1\'&&yobj.wdxq!=\'1\'){\n	 (select \n	       count(1) from SYS_SJGL_GRBJ t1\n         where t1.yxx = \'1\'\n           and t1.sjbj = t.id\n        ) parent,\n	 	t.id,t.bt,t.sjbj,t.zt,t.cjrdm,t.cjrdwdm,t.kjx\n	 -- @}else{\n     (select \n	       count(1) from SYS_SJGL_GRBJ t1\n         where t1.yxx = \'1\'\n           and t1.sjbj = t.id\n        ) parent,t.id ckwd,\n				(select count(1) from sys_wdgl_pl t1 where t1.xgwd=t.id and t1.yxx=\'1\' and t1.czlb=\'02\' and t1.xgpl is null) zan_sl,\n				(select count(1) from sys_wdgl_pl t1 where t1.xgwd=t.id and t1.yxx=\'1\' and t1.czlb=\'03\' and t1.xgpl is null) cai_sl,\n				(select count(1) from sys_wdgl_pl t1 where t1.xgwd=t.id and t1.yxx=\'1\' and t1.czlb=\'01\' and t1.xgpl is null) pl_sl,\n				(select id from sys_wdgl_pl t1 where t1.xgwd=t.id and t1.yxx=\'1\' and t1.czlb=\'02\' and t1.xgpl is null and t1.cjrdm=#{user.id}) zan_dqyh,\n				(select id from sys_wdgl_pl t1 where t1.xgwd=t.id and t1.yxx=\'1\' and t1.czlb=\'03\' and t1.xgpl is null and t1.cjrdm=#{user.id}) cai_dqyh,\n    ${sql.selectField}\n	 -- @}\n-- @}\nfrom ${sql.from} t\n-- @ where(){\n   ${sql.whereStr} \n	 -- @if(isEmpty(yobj.id)){\n	 -- @if(isNotEmpty(yobj.sjbj)&&isNotEmpty(sys.searchKey)){\n	 and t.dm like #{\"%\"+yobj.sjbj+\"%\"}\n	 -- @}else if(isNotEmpty(yobj.sjbj)){\n	 and t.sjbj = #{yobj.sjbj}\n	 -- @}\n	 -- @}\n	 -- @if(yobj.ckwd!=\'1\'){\n	 ${sql.authWhere}\n	 -- @}\n-- @}\n-- @pageIgnoreTag(){\n	${sql.orderBy}\n-- @}', '20191028231903', '20231028002503', '06', '1', '{\n	\"sys\":{\n		\"fields\": {\n			\"sszzd\": {\n				\"zddm\": \"bt\",\n				\"zdms\": \"搜索主字段\"\n			},\n			\"pyjp\": {\n				\"zdms\": \"拼音简拼\",\n				\"zddm\": \"jp\"\n			},\n			\"pyqp\": {\n				\"zdms\": \"拼音全拼\",\n				\"zddm\": \"qp\"\n			},\n      \"sszdlb\": {\n        \"zdms\": \"搜索字段列表\",\n        \"zddm\": \"nr\',\'bq\"\n      },\n			\"cjrdm\": {\n				\"zdms\": \"创建人代码\",\n				\"zddm\": \"cjrdm\"\n			},\n			\"cjrxm\": {\n				\"zdms\": \"创建人名称\",\n				\"zddm\": \"cjrxm\"\n			},\n			\"cjrdwdm\": {\n				\"zdms\": \"创建人单位代码\",\n				\"zddm\": \"cjrdwdm\"\n			},\n			\"cjrdwmc\": {\n				\"zdms\": \"创建人单位名称\",\n				\"zddm\": \"cjrdwmc\"\n			}\n		}\n	},\n	\"cllxkz\": {\n		\"select\": {\n			\"tree\": {\n				\"transform\": true,\n				\"rowField\": \"id\",\n				\"label\":\"bt\",\n				\"parentField\": \"sjbj\",\n				\"hasChild\": \"myhaschild\",\n				\"sfsxjgField\": \"sfsxjg\"\n			}\n		}\n	}\n}', '系统管理员', 'BC5D77315CA84C6C807988E3CD17E70D', '临时机构', '141B1AFC7E634176BDA7DB7F491A9004', 'XT-SJGL-WDZL', 'XITONG-SHUJUGUANLI-WENDANGZILIAO', 'DB7A417A3AC74ED9A0B41ABEF10C03C0');
