INSERT INTO `sys_sjgl_sjdx` VALUES ('SYS_SJGL_SJDX_PLDR', '系统-数据管理-数据对象-批量导入', 99999, NULL, NULL, '01', 'table', 'default', NULL, 'SYS_SJGL_SJDX', 'id', NULL, 'gxsj', NULL, NULL, NULL, 'yxx', '1', 'px asc,gxsj desc', '0', '1', '1', 'cn.benma666.sjsj.ljq.sjgl.SjdxLjq', NULL, '/*if(yobj.ztlx==\'oracle\'){*/\nselect \n-- @pageTag(){\nt.TABLE_NAME jtdx,t.TABLE_NAME dxdm,t.COMMENTS as dxmc\n-- @}\nfrom  all_tab_comments t where t.owner=\'${yobj.owner}\'\n-- @if(!isEmpty(yobj.dxmc)){\nand (t.TABLE_NAME like #{\"%\"+yobj.dxmc+\"%\"} or t.COMMENTS like #{\"%\"+yobj.dxmc+\"%\"})\n-- @}\n;ds=${yobj.sjzt}\n/* }else if(yobj.ztlx==\'mysql\'){*/\nselect \n-- @pageTag(){\nt.table_name jtdx,t.table_name dxdm,t.table_comment as dxmc\n-- @}\nfrom information_schema.tables t where table_schema=\'${yobj.owner}\'\n-- @if(!isEmpty(yobj.dxmc)){\nand (t.table_name like #{\"%\"+yobj.dxmc+\"%\"} or t.table_comment like #{\"%\"+yobj.dxmc+\"%\"})\n-- @}\n;ds=${yobj.sjzt}\n/*}else if(yobj.ztlx==\'vertica\'){*/\nSELECT \n-- @pageTag(){\ntable_name jtdx,t.table_name dxdm,\nCASE when remarks is null \nthen table_name else remarks\nend dxmc\n-- @}\nFROM v_catalog.all_tables t where schema_name = \'${yobj.owner}\'\n-- @if(!isEmpty(yobj.dxmc)){\nand (t.table_name like #{\"%\"+yobj.dxmc+\"%\"} or t.remarks like #{\"%\"+yobj.dxmc+\"%\"})\n-- @}\n;ds=${yobj.sjzt}\n/*}else {*/\n${sql.defaultSql}\n/* }*/', '20181210203129', '20221125211603', '06', '1', '{\n	\"sys\":{\n		\"batch\":false,\n		\"fields\":{\n			\"sszzd\":{\n				\"zddm\":\"dxmc\",\n				\"zdms\":\"搜索主字段\"\n			},\n			\"pyjp\":{\n				\"zdms\":\"拼音简拼\",\n				\"zddm\":\"dxjp\"\n			},\n			\"pyqp\":{\n				\"zdms\":\"拼音全拼\",\n				\"zddm\":\"dxqp\"\n			},\n			\"sszdlb\":{\n				\"zdms\":\"搜索字段列表\",\n				\"zddm\":\"dxms||dxdm\"\n			}\n		},\n		\"fsjdxdm\":\"SYS_SJGL_SJDX\"\n	},\n	\"zhgz\":{\n		\"yobj.cjrxm\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"value\":\"${user.yhxm}\"\n				}\n			}\n		},\n		\"yobj.cjrdm\":{\n			\"insert\":{\n				\"tmpl\":{\n					\"va