-- ----------------------------
-- Table structure for sys_bdhc_zy
-- ----------------------------
DROP TABLE IF EXISTS `sys_bdhc_zy`;
CREATE TABLE `sys_bdhc_zy`  (
  `sjzy` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '上级资源@SYS_BDHC_ZY;上级资源',
  `sjl` bigint NULL DEFAULT NULL COMMENT '数据量;便于摸排时优先核查数据量较小的表，然后依次缩小范围',
  `xiaolv` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '效率;记录每类资源历史每次查询的耗时，每天综合计算效率，给用户进行资源选择做参考，同时也为系统优化做参考',
  `dj` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '06' COMMENT '等级@SYS_COMMON_DJ;从高到低为1~10，按每三级分为高中低，一些较少使用的资源就设置为10级，10级默认不比对，只有在比对组或比对号码的比对资源中明确设置才生效，系统默认6级',
  `qyhc` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '全域慧查@SYS_COMMON_LJPD;全域慧查',
  `dm` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '代码;动态信息类别',
  `mc` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '名称;名称',
  `ms` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '描述;描述',
  `sjdx` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '数据对象@SYS_SJGL_SJDX;数据对象',
  `sjzt` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '数据载体@SYS_COMMON_SJZT;数据载体',
  `dl` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '大类@SYS_BDHC_ZYDL;大类',
  `xl` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '细类@SYS_BDHC_ZYXL;细类',
  `hcyj` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '核查语句;采用模板形式，参数化满足增量、全量等需求场景',
  `bz` varchar(4000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注;备注',
  `gxpl` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新频率;更新频率',
  `id` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT (REPLACE(UUID(),'-','')) COMMENT '主键;主键',
  `cjsj` varchar(14) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT (date_format(now(), '%Y%m%d%H%i%S')) COMMENT '创建时间;创建时间',
  `gxsj` varchar(14) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT (date_format(now(), '%Y%m%d%H%i%S')) COMMENT '更新时间;更新时间',
  `yxx` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '1' COMMENT '有效性@SYS_COMMON_LJPD;有效性',
  `px` bigint NULL DEFAULT 9999 COMMENT '排序;排序',
  `kzxx` varchar(4000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展信息;JSON格式',
  `cjrxm` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人姓名;创建人姓名',
  `cjrdm` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人代码@SYS_COMMON_USER;创建人代码',
  `cjrdwmc` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人单位名称;创建人单位名称',
  `cjrdwdm` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人单位代码@SYS_COMMON_ORG;创建人单位代码',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统-比对核查-资源' ROW_FORMAT = DYNAMIC;

