-- ----------------------------
-- Table structure for sys_log_jhjl
-- ----------------------------
DROP TABLE IF EXISTS `sys_log_jhjl`;
CREATE TABLE `sys_log_jhjl`  (
  `ID` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT (REPLACE(UUID(),'-','')) COMMENT 'ID',
  `CJSJ` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT (date_format(now(), '%Y%m%d%H%i%S')) COMMENT '创建时间;推送时间',
  `GXSJ` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT (date_format(now(), '%Y%m%d%H%i%S')) COMMENT '更新时间;接收时间',
  `XGJH` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '相关交换@SYS_SJGL_ZNJH',
  `WJBH` bigint NULL DEFAULT NULL COMMENT '文件编号',
  `GZMS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '工作模式@SYS_SJGL_ZNJH_GZMS',
  `WJZT` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '文件状态@SYS_SJGL_ZNJH_WJZT;推送文件时根据情况设置：正常推送、文件名不规范、超出大小限制、推送异常',
  `BZ` varchar(4000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注;如果报错可以报错异常信息',
  `WJZW` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '文件指纹',
  `LYSJZT` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '来源数据载体@SYS_COMMON_SJZT;可能是本地文件或ftp',
  `LYML` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '来源目录',
  `LYWJM` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '来源文件名',
  `LYWJDX` bigint NULL DEFAULT NULL COMMENT '来源文件大小',
  `MBSJZT` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '目标数据载体@SYS_COMMON_SJZT;可能是本地文件或ftp',
  `MBML` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '目标目录',
  `MBWJM` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '目标文件名;规则：当前时间17位字符串_文件编号_文件大小_源文件名',
  `MBWJDX` bigint NULL DEFAULT NULL COMMENT '目标文件大小',
  `BFML` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备份目录;规则：配置的备份目录+年月日时，备份文件名与目标文件名一致',
  `SFBL` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '是否补漏@SYS_COMMON_LJPD',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统-日志-交换记录' ROW_FORMAT = DYNAMIC;

