-- ----------------------------
-- Table structure for sys_sjgl_dzd
-- ----------------------------
DROP TABLE IF EXISTS `sys_sjgl_dzd`;
CREATE TABLE `sys_sjgl_dzd`  (
  `id` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT (REPLACE(UUID(),'-','')) COMMENT '主键;主键',
  `dm` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '代码;代码',
  `px` bigint NOT NULL DEFAULT 99999 COMMENT '排序;建议排序都按10、20、30的方式排序，方便修改穿插',
  `zdlb` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '字典类别@SYS_COMMON_ZDLB;字典类别',
  `mc` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '名称;名称',
  `ms` varchar(400) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '描述;描述',
  `jp` varchar(400) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '简拼;简拼',
  `qp` varchar(400) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '全拼;全拼',
  `bzzd` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '标准字典@SYS_COMMON_QBZDX;用于数据标准化等场景，如性别可以有几套字典，然后关联一个标准字典,进一步通过mc关联',
  `cjsj` varchar(14) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT (date_format(now(), '%Y%m%d%H%i%S')) COMMENT '创建时间;创建时间',
  `gxsj` varchar(14) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT (date_format(now(), '%Y%m%d%H%i%S')) COMMENT '更新时间;更新时间',
  `sjly` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '数据来源;数据来源',
  `upnode` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '父节点@SYS_COMMON_ZDLB;父节点',
  `yxx` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '1' COMMENT '有效性@SYS_COMMON_LJPD;与共享平台一致，所以这里没有采用中文简拼命名',
  `cjrxm` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人姓名;创建人姓名',
  `cjrdm` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人代码@SYS_COMMON_USER;创建人代码@SYS_COMMON_USER',
  `cjrdwmc` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人单位名称;创建人单位名称',
  `cjrdwdm` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人单位代码@SYS_COMMON_ORG;创建人单位代码@SYS_COMMON_ORG',
  `kzxx` varchar(4000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展信息;JSON格式',
  `sjdj` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '3' COMMENT '数据等级;数据等级',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统-数据管理-大字典' ROW_FORMAT = DYNAMIC;

