  `px` bigint NOT NULL DEFAULT 99999 COMMENT '排序;排序',
  `zt` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '01' COMMENT '状态@SYS_SJGL_BJZT;状态',
