  `zan` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '1' COMMENT '赞@SYS_COMMON_LJPD',
  `cai` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '1' COMMENT '踩@SYS_COMMON_LJPD',
  PRIMARY KEY (`id`) USING BTREE
