  `dxzy` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对象作用@SYS_SJGL_DXZY;增量导出、数据插入、数据更新、页面查询、页面新增、页面修改等',
  `dxlb` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '02' COMMENT '对象类别@SYS_SJGL_DXLB;标准对象、临时对象、系统对象等人工分类',
  `dxlx` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'table' COMMENT '对象类型@SYS_SJGL_DXLX;表、视图、excel、txt等',
  `dxzt` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'default' COMMENT '数据载体@SYS_COMMON_SJZT;根据对象载体类型不同，表示不同的具体载体，如具体数据库、ftp等',
  `dxgs` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对象归属;数据库的某个用户、ftp的目录等',
  `jtdx` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '具体对象;数据库的表视图、文件名、文件正则等',
  `zjzd` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'id' COMMENT '主键字段;用于查询详情等',
  `qxzd` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '权限字段;进行权限控制',
  `zlzd` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'gxsj' COMMENT '增量字段;进行增量抽取等',
  `qczd` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '去重字段;用于插入更新',
  `jyzd` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '校验字段;用于存放校验信息',
  `pczd` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '批次字段;用于存放批次号，知道具体数据来自哪次抽取等',
  `yxxzd` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'yxx' COMMENT '有效性字段;忘了',
  `fytjxs` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '1' COMMENT '分页统计形式@SYS_SJGL_FYTJXS;控制分页查询数据量统计形式，如：默认形式、异步统计、默认不统计',
  `mrpx` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'px,gxsj desc' COMMENT '默认排序;查询时的默认排序规则',
  `cscx` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '1' COMMENT '初始查询@SYS_COMMON_LJPD;控制查询页面是否初始化查询',
  `cxtj` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '1' COMMENT '查询条件@SYS_COMMON_LJPD;控制是否展示',
  `bjxh` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '1' COMMENT '编辑序号@SYS_COMMON_LJPD;控制是否显示编辑页面的字段序号',
  `ljq` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '拦截器;后台扩展系统',
  `zddrsql` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '字段导入SQL;用于刷新对象字段',
  `sqlmb` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'SQL模板;用于扩展后端，基于beetl实现',
  `cjsj` varchar(14) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT (date_format(now(), '%Y%m%d%H%i%S')) COMMENT '创建时间;',
  `gxsj` varchar(14) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT (date_format(now(), '%Y%m%d%H%i%S')) COMMENT '更新时间;',
  `zydj` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '06' COMMENT '资源等级@SYS_SJGL_ZYGJ;从高到低为1~10，按每三级分为高中低，一些较少使用的资源就设置为10级，10级默认不使用，需要使用时，需要特殊配置，系统默认6级',
  `yxx` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '1' COMMENT '有效性@SYS_COMMON_LJPD;',
  `kzxx` varchar(4000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '{\r\n  \"sys\":{\r\n    \"fields\": {\r\n      \"cjrdm\": {\r\n        \"zdms\": \"创建人代码\",\r\n        \"zddm\": \"cjrdm\"\r\n      },\r\n      \"cjrxm\": {\r\n        \"zdms\": \"创建人名称\",\r\n        \"zddm\": \"cjrxm\"\r\n      },\r\n      \"cjrdwdm\": {\r\n        \"zdms\": \"创建人单位代码\",\r\n        \"zddm\": \"cjrdwdm\"\r\n      },\r\n      \"cjrdwmc\": {\r\n        \"zdms\": \"创建人单位名称\",\r\n        \"zddm\": \"cjrdwmc\"\r\n      }\r\n    }\r\n  }\r\n}' COMMENT '扩展信息;JSON格式',
  `cjrxm` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人姓名;',
  `cjrdm` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人代码@SYS_COMMON_USER;',
  `cjrdwmc` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人单位名称;',
  `cjrdwdm` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人单位代码@SYS_COMMON_ORG;',
  `dxjp` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对象简拼;',
  `dxqp` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对象全拼;',
  `id` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT (REPLACE(UUID(),'-','')) COMMENT '主键;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统-数据管理-数据对象' ROW_FORMAT = DYNAMIC;

