  `bzzd` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '标准字段@SYS_SJGL_SJZD;',
  `mbzs` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '1' COMMENT '模板展示@SYS_COMMON_LJPD;模板展示@SYS_COMMON_LJPD',
  `yxx` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '1' COMMENT '有效性@SYS_COMMON_LJPD;',
