  `zdjp` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '字段简拼;',
  `zdqp` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '字段全拼;',
  `zdlx` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'VARCHAR2' COMMENT '字段类型;',
  `zdcd` bigint NULL DEFAULT 1024 COMMENT '字段长度;',
  `cxmrz` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '查询默认值;',
  `xzmrz` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '新增默认值;',
  `zdzdlb` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '字段字典类别@SYS_COMMON_ZDLB;',
  `ZDYWLB` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '00' COMMENT '字段业务类别@SYS_SJGL_ZDYWLB',
  `zddx` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '字典多选@SYS_COMMON_LJPD;字典下拉框是否支持多选',
  `zdfy` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '字典分页@SYS_COMMON_LJPD;字典下拉框是否分页展示',
  `yxpx` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '允许排序@SYS_COMMON_LJPD;',
  `cxbt` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '查询必填@SYS_COMMON_LJPD;',
  `zydj` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '06' COMMENT '资源等级@SYS_SJGL_ZYGJ;从高到低为1~10，按每三级分为高中低，一些较少使用的资源就设置为10级，10级默认不使用，需要使用时，需要特殊配置，系统默认6级',
  `zdts` varchar(4000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '字段提示;',
  `cssl` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'CSS类;将填充到class中',
  `qcbh` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '去重编号;',
  `cjsj` varchar(14) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT (date_format(now(), '%Y%m%d%H%i%S')) COMMENT '创建时间;',
