  `yszddm` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原始字段代码;从载体中获取的原始字段代码，不做任何转换，进行载体相关操作时使用，本体系统全部采用驼峰',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统-数据管理-数据字段' ROW_FORMAT = DYNAMIC;

