DROP TABLE IF EXISTS `sys_sjgl_sjzt`;
CREATE TABLE `sys_sjgl_sjzt`  (
  `dm` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '代码;代表唯一数据对象，多处使用，唯一',
  `mc` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '名称;名称',
  `px` bigint NOT NULL DEFAULT 9999 COMMENT '排序;排序',
  `ms` varchar(4000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '描述;描述',
  `lx` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'oracle' COMMENT '类型@SYS_SJGL_DXZTLX;类型',
  `fwfs` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'Native' COMMENT '访问方式@SYS_SJGL_SJKFWFS;访问方式',
  `jndi` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'JNDI名称;JNDI名称',
  `ljc` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '连接串;连接串',
  `yhm` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户名;用户名',
  `mm` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '密码;以后改为加密存储',
  `dxgs` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对象归属;就是该数据库的表所属SCHEMA',
  `zt` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '状态@SYS_COMMON_ZT;状态',
  `sjkqd` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '数据库驱动;数据库驱动',
  `csyj` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '测试语句;测试语句',
  `kzxx` varchar(4000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '{}' COMMENT '扩展信息;JSON格式',
  `gxsj` varchar(14) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT (date_format(now(), '%Y%m%d%H%i%S')) COMMENT '更新时间;更新时间',
  `yxx` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '1' COMMENT '有效性@SYS_COMMON_LJPD;有效性@SYS_COMMON_LJPD',
  `cjsj` varchar(14) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT (date_format(now(), '%Y%m%d%H%i%S')) COMMENT '创建时间;创建时间',
  `cjrxm` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人姓名;创建人姓名',
  `cjrdm` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人代码@SYS_COMMON_USER;创建人代码@SYS_COMMON_USER',
  `cjrdwmc` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人单位名称;创建人单位名称',
  `cjrdwdm` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人单位代码@SYS_COMMON_ORG;创建人单位代码@SYS_COMMON_ORG',
  `jp` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '简拼;简拼',
  `qp` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '全拼;全拼',
  `id` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT (REPLACE(UUID(),'-','')) COMMENT '主键;主键',
  `ssyy` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '所属应用@SYS_QX_APP',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统-数据管理-数据载体' ROW_FORMAT = DYNAMIC;

