  `SCZT` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '输出载体@SYS_COMMON_SJZT;过滤只允许选择该网络空间的数据载体',
  `SCML` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '输出目录',
  `BFZT` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备份载体@SYS_COMMON_SJZT;过滤只允许选择该网络空间的数据载体，不选择则不进行备份。',
  `BFML` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备份目录',
  `JTQLX` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '监听器类型@SYS_SJGL_ZNJH_JTQLX',
  `GZMS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '工作模式@SYS_SJGL_ZNJH_GZMS',
  `JTJG` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '监听间隔;格式nHnMnS',
  `JTWJZZ` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '监听文件正则',
  `BGFWJZZ` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '不规范文件正则;文件记录推送日志，推送日志状态为：忽略，文件不推送到底层网闸，备份到备份目录后删除',
  `JTQZT` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '监听器状态@SYS_SJGL_ZXZT',
  `DXXZ` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '大小限制;单位kb|mb|gb',
  `YXX` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '1' COMMENT '有效性@SYS_COMMON_LJPD',
  `CJSJ` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT (date_format(now(), '%Y%m%d%H%i%S')) COMMENT '创建时间',
  `GXSJ` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT (date_format(now(), '%Y%m%d%H%i%S')) COMMENT '更新时间',
  `CJRXM` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人姓名',
  `CJRDM` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人代码',
  `CJRDWMC` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人单位名称',
  `CJRDWDM` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人单位代码',
  `PX` bigint NULL DEFAULT 9999 COMMENT '排序',
  `KZXX` varchar(4000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展信息',
  `JHJD` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交换节点@SYS_QX_APP;用于设置该任务在哪个交换节点上执行',
  `FHJH` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '返回交换@SYS_SJGL_ZNJH;不选择则没有返回',
  `JLRZ` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '1' COMMENT '记录日志@SYS_COMMON_LJPD',
  `SCYWJ` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '1' COMMENT '删除源文件@SYS_COMMON_LJPD',
  `XWJDD` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0.1s' COMMENT '小文件等待;格式nHnMnS',
  `DWJDD` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '1s' COMMENT '大文件等待;格式nHnMnS',
  `XGSJCXY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '修改时间差小于;与当前时间相比,格式：PnYnMnDTnHnMnS',
  `XGSJCDY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '修改时间差大于;与当前时间相比,格式：PnYnMnDTnHnMnS',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统-数据管理-智能交换' ROW_FORMAT = DYNAMIC;

