  `xxlx` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '消息类型@SYS_YXJK_XXLX;异常、恢复，跟进',
  `xxdj` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '消息等级@SYS_COMMON_JJCD;消息等级@SYS_COMMON_JJCD',
  `jkrw` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '监控任务@SYS_YXJK_JKRW;监控任务',
  `yclx` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '异常类型@SYS_YXJK_YCLX;异常类型',
  `ycyy` varchar(4000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '异常原因;监控系统生成，实际异常信息，具体问题定位',
  `xxnr` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '消息内容;通过消息模板生成',
  `gxsj` varchar(14) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT (date_format(now(), '%Y%m%d%H%i%S')) COMMENT '更新时间;更新时间',
  `yxx` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '有效性@SYS_COMMON_LJPD;无效的消息不发送',
  `px` bigint NULL DEFAULT NULL COMMENT '排序;按顺序监控',
  `id` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT (REPLACE(UUID(),'-','')) COMMENT '主键;主键',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统-运行监控-消息' ROW_FORMAT = DYNAMIC;

